export const part1: Record<string, string[]> = {
  "1:1": ["In the name of Allah, the Rahman, the Raheem", "পরম করুণাময়, পরম দয়ালু আল্লাহর নামে।"],
  "1:2": ["Praise belongs to Allah, Rabb of the worlds", "প্রশংসা আল্লাহর, মহাবিশ্বের প্রভু।"],
  "1:3": ["The Rahman, the Raheem", "পরম করুণাময়, পরম দয়ালু।"],
  "1:4": ["Sovereign of the Day of Judgment", "বিচার দিনের মালিক।"],
  "1:5": ["You alone we worship, and You alone we ask for help", "আমরা একমাত্র আপনার উপাসনা করি; আমরা একমাত্র আপনার কাছেই সাহায্য চাই।"],
  "1:6": ["Guide us to the straight path", "আমাদেরকে সঠিক পথে পরিচালিত করুন;"],
  "1:7": ["The path of those whom You have favored, not of those upon whom wrath has fallen, nor of those who go astray", "তাদের পথে যাদের আপনি অনুগ্রহ করেছেন; তাদের পথে নয় যারা আপনার ক্রোধের উপযুক্ত হয়েছে, তাদের পথেও নয় যারা পথভ্রষ্ট হয়েছে।"],
  "2:1": ["Alif, Lam, Mim.", "অ. ল. ম."],
  "2:2": ["That is the Book: no doubt in it; guidance for the reverent.", "এই ঐশীগ্রন্থটি নির্ভূল; সৎকর্মশীলদের জন্য একটি পথনির্দেশিকা;"],
  "2:3": ["Those who believe in the unseen and keep up the prayer and spend from what We provided them,", "যারা অদৃশ্যে বিশ্বাস করে,সংযোগ প্রার্থণা (সালাত) পালন করে,এবং আমাদের দেয়া জীবিকা থেকে তারা দান করে।"],
  "2:4": ["and those who believe in what was sent down to you and what was sent down before you, and of the Last they are certain —", "এবং তারা বিশ্বাস করে যা তোমার কাছে প্রকাশিত হয়েছে,এবং যা তোমার পূর্বে প্রকাশিত হয়েছে, এবং পরকাল সম্পর্কে তারা সম্পূর্ণ নিশ্চিত।"],
  "2:5": ["those are on guidance from their Rabb, and those are the ones who attain success.", "এরাই তাদের প্রভুর দ্বারা পথ-প্রদর্শিত; এরাই বিজয়ী।"],
  "2:6": ["Indeed those who disbelieve — it is equal to them whether you warn them or do not warn them — they will not believe.", "আর যারা অবিশ্বাস করে,তাদেরকে তুমি সতর্ক করো অথবা সতর্ক না করো,তা তাদের জন্য সমান কথা,তারা বিশ্বাস করতে পারে না।"],
  "2:7": ["Allah has set a seal upon their hearts and upon their hearing, and over their sight is a covering; and for them is a tremendous punishment.", "আল্লাহ তাদের অন্তর এবং শ্রবনশক্তিতে মোহর মেরে দিয়েছেন, এবং তাদের চোখ পর্দাবৃত। তারা নিজেদের উপর টেনে এনেছে কঠিন শাস্তি।"],
  "2:8": ["And among the people are those who say, \"We believe in Allah and in the Last Day,\" yet they are not muminin.", "এরপর রয়েছে তারা,যারা বলে,“আমরা আল্লাহ এবং শেষ দিনে বিশ্বাস করি,”অথচ তারা বিশ্বাসী নয়।"],
  "2:9": ["They try to deceive Allah and those who believe, but they deceive none but themselves, yet they do not perceive.", "আল্লাহ এবং যারা বিশ্বাস করে তাদেরকে ধোঁকা দেয়ার চেষ্টা করতে গিয়ে,তারা না বুঝে শুধু  নিজেদেরকেই ধোঁকা দেয়।"],
  "2:10": ["In their hearts is a sickness, and Allah increased them in sickness; and for them is a painful punishment for what they used to deny.", "তাদের অন্তরে রয়েছে ব্যধি। পরিনামে,আল্লাহ তাদের ব্যধি আরো বাড়িয়ে দেন। তারা তাদের মিথ্যাবাদিতার জন্য নিজেদের উপর টেনে এনেছে যন্ত্রণাদায়ক শাস্তি।"],
  "2:11": ["And when it is said to them, \"Do not corrupt in the earth,\" they say, \"We are only ones who set things right.\"", "যখন তাদেরকে বলা হয়, “মন্দ কাজ করো না,”তারা বলে,“কিন্তু আমরা তো সৎকর্মশীল!”"],
  "2:12": ["Truly, they are the corrupters, but they do not perceive.", "আসলে,তারা মন্দকর্মী,কিন্তু তারা তা বোঝে না।"],
  "2:13": ["And when it is said to them, \"Believe as the people believed,\" they say, \"Shall we believe as the fools believed?\" Truly, they are the fools, but they do not know.", "যখন তাদের বলা হয়, “বিশ্বাস করো সে লোকদের মতো যারা বিশ্বাস করেছে,”তারা বলে,“যারা বিশ্বাস করেছে,সে বোকাদের মত আমরাও কি বিশ্বাস করবো?” আসলে তারাই বোকা,কিন্তু তারা জানে না।"],
  "2:14": ["And when they meet those who believe, they say, \"We believe,\" but when they are alone with their satans, they say, \"We are with you; we were only mocking.\"", "যখন তারা বিশ্বাসীদের সাথে সাক্ষাৎ করে,তারা বলে,“আমরা বিশ্বাস করি,”কিন্তু যখন তারা তাদের শয়তানদের সাথে একান্তে হয়, তারা বলে,“আমরা তোমাদের সাথে আছি;আমরা তো কেবল উপহাস করছিলাম।”"],
  "2:15": ["Allah mocks them and grants them extension in their transgression, wandering blind.", "আল্লাহ তাদের উপহাস করেন, এবং তাদের পরিচালিত করেন তাদের সীমালঙ্ঘনে বিভ্রান্ত অবস্থায়।"],
  "2:16": ["Those are the ones who bought straying in exchange for guidance, and their trade gained nothing, and they were not guided.", "এরা তারাই যারা পথভ্রষ্টতা কিনেছে পথ-নির্দেশনার মূল্যে। এমন ব্যবসা কখনো উন্নতি করে না,না তারা কোনো পথনির্দেশনা পায়।"],
  "2:17": ["Their likeness is the likeness of one who kindled a fire; when it lit up what was around him, Allah took away their light and left them in darkness, unseeing.", "এদের উদাহরণ হলো তাদের মতো যারা আগুন জ্বালালো,আর যখন তা তাদের চারপাশে আলো ছড়াতে আরম্ভ করলো,আল্লাহ তাদের আলো তুলে নিয়ে তাদের অন্ধকারে ছেঁড়ে দেন, তারা দেখতে পায় না।"],
  "2:18": ["Deaf, dumb, unseeing — so they do not return.", "বধির, বোবা এবং অন্ধ; তারা ফিরতে ব্যর্থ।"],
  "2:19": ["Or like a torrent from the sky, in it darkness and thunder and lightning: they put their fingers in their ears against the thunderstrikes, wary of death. And Allah encompasses the kafirin.", "আরেকটি উদাহরণঃ আকাশ থেকে কোন ঝড়োবৃষ্টি যাতে আছে অন্ধকার, বজ্র, এবং বিদ্যুত চমক। তারা মৃত্যু এড়াতে তাদের কানে আঙ্গুল দেয়। আল্লাহ অবিশ্বাসীদের সম্পর্কে সম্পূর্ণ অবগত।"],
  "2:20": ["The lightning nearly snatches their sight: whenever it lights the way for them they walk in it, and when darkness falls on them they stand still. Had Allah willed, Allah would have taken away their hearing and their sight. Indeed Allah is over all things able.", "বিদ্যুত চমক তাদের দৃষ্টিশক্তি প্রায় ছিনিয়ে নেয়। যখন তা তাদের জন্য আলো দেয়, তারা সামনে এগোয়, এবং যখন তা অন্ধকা্রে রুপ নেয়, তারা স্থির দাঁড়িয়ে যায়। যদি আল্লাহ চান, তিনি তাদের শ্রবণ ও দৃষ্টিশক্তি তুলে নিতে পারেন। আল্লাহ সর্বশক্তিমান।"],
  "2:21": ["O people, worship your Rabb, who created you and those before you, so that you may be reverent.", "হে লোকসকল, একমাত্র তোমাদের প্রভুর উপাসনা করো – সেই একজন যিনি সৃষ্টি করেছেন তোমাদেরকে এবং তাদেরকে যারা তোমাদের পূর্বে ছিল – যাতে তোমরা রক্ষা পেতে পারো।"],
  "2:22": ["The one who made the earth a spread for you and the sky a building, and sent down from the sky water, and brought forth with it fruits as provision for you — so do not set up equals to Allah while you know.", "সেই সত্ত্বা,যিনি পৃথিবীকে তোমাদের জন্য বাসযোগ্য করেছেন, এবং আকাশকে করেছেন একটি কাঠামো। তোমাদের জীবিকার জন্য সব ধরণের ফলমূল উৎপন্ন করতে তিনি আকাশ থেকে পানি বর্ষণ করেন। তোমরা আল্লাহর সাথে প্রতিদ্বন্দিতা করতে উপাস্যদের স্থাপন করবে না,এখন যেহেতু তোমরা জানো।"],
  "2:23": ["And if you are in doubt about what We sent down upon Our servant, then bring a chapter like it, and call your witnesses apart from Allah, if you are sadiq.", "যদি তোমাদের কোনো সন্দেহ থাকে সে সম্পর্কে,যা আমরা আমাদের বান্দার কাছে প্রকাশ করেছি,তাহলে এই সুরার মতো একটি সুরা তৈরী করো,এবং ডাকো আল্লাহর বিপক্ষে তোমাদের নিজেদের সাক্ষীদেরকে,যদি তোমরা সত্যবাদী হও।"],
  "2:24": ["But if you do not — and you will not — then beware the Fire whose fuel is people and stones, prepared for the kafirin.", "যদি তোমরা তা করতে না পারো – এবং তোমরা তা কখনোই করতে পারবে না – তাহলে নরকের আগুনের ব্যাপারে সতর্ক হও, যার জ্বালানী হলো মানুষ এবং পাথর; এটা অবিশ্বাসীদের জন্য অপেক্ষা করছে।"],
  "2:25": ["And give glad tidings to those who believe and do the good deeds: that for them are gardens beneath which rivers flow. Whenever they are provided from it with a provision of fruit, they say, \"This is what we were provided before,\" and they are given the like of it. And for them in it are purified spouses, and they abide in it forever.", "সুসংবাদ দাও তাদেরকে,যারা বিশ্বাস করে এবং সৎ জীবনযাপন করে যে,তাদের জন্য থাকবে প্রবাহিত ঝর্নাধারা সহ বাগানসমূহ। যখন সেখানে তাদেরকে কোন ফল খেতে দেয়া হবে,তারা বলবে,“এটা তো তা-ই যা আমাদেরকে পূর্বে দেয়া হয়েছিল।”এভাবে,তাদেরকে রূপকধর্মী বর্ণনা দেয়া হয়েছে। সেখানে তাদের জন্য থাকবে শুদ্ধ সহধর্মী/সহধর্মিণী,এবং সেখানে তারা চিরকাল বসবাস করবে।"],
  "2:26": ["Indeed Allah is not ashamed to strike a likeness — even of a gnat or what is above it. As for those who believe, they know it is the truth from their Rabb; but as for those who disbelieve, they say, \"What did Allah intend by this likeness?\" By it Allah lets many stray and guides many, and by it none are led astray except the transgressors.", "আল্লাহ কোনো ধরণের রূপকের মাধ্যমে উদাহরণ দিতে লজ্জা বোধ করেন না,তা সে হোক ছোট মশা কিংবা এর থেকে বড় কিছু। আর যারা বিশ্বাস করে,তারা জানে যে,এটা তাদের প্রভুর পক্ষ থেকে সত্য। আর যারা অবিশ্বাস করে,তারা বলে,“আল্লাহ এমন রূপক দ্বারা কি বুঝিয়েছেন?”তিনি এর দ্বারা অনেককেই বিপথগামী করেন, এবং এর দ্বারা অনেককেই সঠিক পথে পরিচালিত করেন। কিন্তু,তিনি মন্দ ছাড়া অন্য কাউকে এর দ্বারা বিপথগামী করেন না,"],
  "2:27": ["Those who unbind Allah's pledge after its pact, and sever what Allah commanded to be joined, and corrupt in the earth — those are the khasirin.", "যারা আল্লাহর চুক্তি ভংগ করে,তা মেনে চলার অঙ্গীকার করার পর, বিচ্ছিন্ন হয় তা থেকে,যাতে আল্লাহ যুক্ত হতে আদেশ দিয়েছেন, এবং মন্দ কাজ করে। এরাই হতভাগ্য।"],
  "2:28": ["How can you disbelieve in Allah when you were dead and Allah gave you life, then Allah causes you to die, then Allah brings you to life, then to Allah you will be returned?", "কিভাবে তোমরা আল্লাহতে অবিশ্বাস করতে পারো যখন তোমরা ছিলে মৃত এবং তিনি তোমাদের জীবন দিয়েছেন, তারপর তিনি তোমাদের মৃত্যু দেন, তারপর তিনি আবার তোমাদের জীবিত করেন, তারপর তাঁরই কাছে তোমরা চুড়ান্তভাবে ফিরে যাও?"],
  "2:29": ["It is Allah who created for you all that is in the earth, then turned to the sky and leveled them into seven heavens — and Allah is knowing of all things.", "তিনিই একজন, যিনি তোমাদের জন্য পৃথিবীতে সবকিছু সৃষ্টি করলেন, তারপর তিনি আকাশের দিকে ফিরলেন আর তাতে সাতটি মহাবিশ্ব সুষম করলেন,  এবং তিনি সবকিছু সম্পর্কে সম্পূর্ণ অবগত।"],
  "2:30": ["And when your Rabb said to the malakat, \"I am placing in the earth a successor,\" they said, \"Will You place in it one who will corrupt in it and shed blood, while we glorify with praise of You and sanctify You?\" Allah said, \"I know what you do not know.\"", "স্মরণ করো যে তোমার প্রভু ফেরেশতাদের বললেন, “আমি পৃথিবীতে একজন প্রতিনিধি (একজন অস্থায়ী উপাস্য) প্রতিষ্ঠা করতে যাচ্ছি।”তারা বলল, “আপনি কি সেখানে এমন কাউকে পাঠাবেন, যে সেখানে মন্দের প্রসার ঘটাবে এবং রক্তপাত করবে,যখন কিনা আমরা আপনার গুণগাণ করছি,আপনার মহিমা ঘোষণা করছি,এবং আপনার পূর্ণ কর্তৃত্ব মেনে চলছি?”তিনি বললেন, “আমি জানি যা তোমরা জানো না।”"],
  "2:31": ["And Allah taught Adam the names, all of them, then presented them to the malakat and said, \"Tell Me the names of these, if you are sadiq.\"", "তিনি আদমকে সবকিছুর নাম শেখালেন তারপর সেগুলোকে ফেরেশতাদের কাছে উপস্থাপন করে বললেন, “আমাকে এগুলোর নাম বল, যদি তোমরা সঠিক হও।”"],
  "2:32": ["They said, \"Glory be to You! We have no knowledge except what You taught us. You are the Knowing, the Wise.\"", "তারা বলল, “আপনি মহিমান্বিত, যা আপনি আমাদেরকে শিখিয়েছেন তা ছাড়া আমাদের কোনো জ্ঞান নেই। আপনিই সর্বজ্ঞ, পরম জ্ঞানী।”"],
  "2:33": ["Allah said, \"Adam, tell them their names.\" And when he told them their names, Allah said, \"Did I not tell you that I know the unseen of the heavens and the earth, and I know what you manifest and what you were hiding?\"", "তিনি বললেন, “হে আদম, তাদেরকে এগুলোর নাম বলে দাও।”যখন সে তাদেরকে সেগুলোর নাম বলে দিলো,তিনি বললেন, “আমি কি তোমাদেরকে বলিনি যে আমি আকাশমন্ডলী এবং পৃথিবীর গোপন বিষয়সমূহ জানি? আমি জানি যা তোমরা প্রকাশ করো,এবং যা তোমরা গোপন করো।”"],
  "2:34": ["And when We said to the malakat, \"Prostrate before Adam,\" they prostrated, except Iblis: he refused and was arrogant, and was among the kafirin.", "যখন আমরা ফেরেশতাদের বললাম, “আদমের সামনে সেজদাবনত হও, ”তারা সেজদাবনত হল, শয়তান ছাড়া; সে প্রত্যাখ্যান করল, সে ছিল অত্যন্ত উদ্ধত এবং এক অবিশ্বাসী।"],
  "2:35": ["And We said, \"Adam, dwell, you and your spouse, in the garden, and eat from it freely wherever you wish; but do not approach this tree, or you would be among the wrongdoers.\"", "আমরা বললাম, ”হে আদম, তোমার স্ত্রীর সাথে স্বর্গে বাস করো এবং সেখান থেকে ইচ্ছেমতো খাও, যেমন তোমাদের পছন্দ, কিন্তু এই গাছের কাছে যেও না,পাছে তোমাদের পাপ হয়।"],
  "2:36": ["Then the satan made them slip from it and brought them out of what they were in. And We said, \"Descend, some of you an enemy to some; and for you in the earth is a settlement and enjoyment until a time.\"", "কিন্তু শয়তান তাদেরকে ধোঁকা দিল, এবং সেখান থেকে তাদের বহিষ্কারের কারণ হল। আমরা বললাম, “একে অপরের শত্রু হিসেবে নেমে যাও। পৃথিবীতে হবে তোমাদের কিছু সময়ের জন্য বসবাস এবং জীবিকা।”"],
  "2:37": ["Then Adam received from his Rabb some words, and Allah turned to him in forgiveness. Indeed, Allah is the Turning, the Raheem.", "তারপর, আদম তার প্রভুর কাছ থেকে শব্দাবলী গ্রহন করলো,যার দ্বারা তিনি তাকে উদ্ধার করলেন। তিনিই উদ্ধারকারী,পরম দয়ালু।"],
  "2:38": ["We said, \"Descend from it, all of you. Then if guidance comes to you from Me, whoever follows My guidance — no fear upon them, nor will they grieve.\"", "আমরা বললাম, “এখান থেকে নেমে যাও, তোমরা সবাই। যখন আমার কাছ থেকে তোমাদের কাছে পথনির্দেশনা আসে,তখন যারা আমার পথনির্দেশনা অনুসরণ করে তাদের কোনো ভয় থাকবে না,না তারা শোক করবে।"],
  "2:39": ["And those who disbelieve and deny Our signs — those are the companions of the Fire; they abide in it forever.", "“আর যারা অবিশ্বাস করে এবং আমাদের প্রত্যাদেশসমূহ প্রত্যাখ্যান করে,তারা হবে নরকের বাসিন্দা,যেখানে তারা চিরকাল থাকবে।”"],
  "2:40": ["Children of Israel, remember My favor that I favored upon you, and fulfill My pledge — I will fulfill your pledge — and of Me be in awe.", "হে ইসরাঈলের সন্তানেরা,স্মরণ করো আমার অনুগ্রহ, যা আমি তোমাদের উপর অর্পণ করেছি এবং পূর্ণ করো তোমাদের অঙ্গীকারকৃত অংশ, যাতে আমি পূর্ণ করি আমার অঙ্গীকারকৃত অংশ, এবং আমাকে ভক্তি-শ্রদ্ধা করো।"],
  "2:41": ["And believe in what I sent down, confirming what is with you, and do not be the first to disbelieve in it, and do not buy with My signs a small price; and of Me be reverent.", "তোমরা বিশ্বাস করবে তাতে যা আমি এখানে প্রকাশ করেছি,যা তোমাদের কাছে আছে তা সুনিশ্চিত করে; এটাকে প্রত্যাখ্যানে প্রথম হইও না। আমার প্রত্যাদেশনাবলীকে সামান্য মূল্যে বিক্রি করো না এবং আমার প্রতি মনোযোগ দাও।"],
  "2:42": ["And do not clothe truth with falsehood and hide the truth while you know.", "সত্যকে মিথ্যার সাথে মিশ্রিত করো না,আর জেনে-শুনে সত্যকে গোপন করো না"],
  "2:43": ["And keep up the prayer and give the alms and bow with those who bow.", "তোমরা সংযোগ প্রার্থণা (সালাত) পালন করবে এবং বাধ্যতামূলক দান (যাকাত) প্রদান করবে,এবং অবনত হবে (রুকু করবে) তাদের সাথে যারা অবনত হয় (রুকু করে)।"],
  "2:44": ["Do you command people to goodness and forget yourselves while you recite the Book? Will you not understand?", "তোমরা কি মানুষকে সৎকর্মশীল হতে উদবুদ্ধ করো,অথচ নিজেদেরকেই ভুলে যাও, যদিও তোমরা ঐশীগ্রন্থ পড়ো? তোমরা কি বুঝো না?"],
  "2:45": ["And seek help in steadfastness and prayer; and it is indeed hard, except on the humbled,", "তোমরা সাহায্য প্রার্থণা করবে ধৈর্য্য এবং সংযোগ প্রার্থণা (সালাতের) মাধ্যমে। এটা প্রকৃতপক্ষে কঠিন, কিন্তু ভক্তদের জন্য নয়।"],
  "2:46": ["those who consider that they will meet their Rabb and that to Allah they will return.", "যারা বিশ্বাস করে যে তারা তাদের প্রভুর সাথে সাক্ষাত করবে আর তাঁর কাছে তারা অবশেষে ফিরে যাবে।"],
  "2:47": ["Children of Israel, remember My favor that I favored upon you, and that I favored you above the worlds.", "হে ইসরাইলের সন্তানেরা,স্মরণ করো আমার অনুগ্রহ যা আমি তোমাদের উপর প্রদান করেছি,এবং যে আমি তোমাদেরকে অন্য যেকোন লোকের চেয়ে বেশি সৌভাগ্যশালী করেছি।"],
  "2:48": ["And beware a day when no self will avail another self anything, and no intercession will be accepted from it, and no compensation will be taken from it, and they will not be helped.", "সেদিনের ব্যাপারে সাবধান হও যখন না কেউ কারো উপকারে আসতে পারে,না কোনো সুপারিশ গ্রহণ করা হবে,না কোনো মুক্তিপণ দেয়া যাবে,না কেউ সাহায্যপ্রাপ্ত হতে পারবে।"],
  "2:49": ["And when We saved you from the family of Fir'awn, who afflicted you with the evil of punishment, slaughtering your sons and letting your nisa live — and in that was a great test from your Rabb.", "স্মরণ করো যে আমরা তোমাদেরকে ফেরাউনের লোকদের থেকে রক্ষা করেছিলাম যারা তোমাদের উপর নির্মম অত্যাচার চালিয়েছিল, তোমাদের পুত্রদের হত্যা করতো আর কন্যাদের ছেড়ে দিতো। তোমাদের প্রভুর পক্ষ থেকে সেটা ছিল এক কঠোর পরীক্ষা।"],
  "2:50": ["And when We split the sea for you and saved you, and drowned the family of Fir'awn while you watched.", "স্মরণ করো যে,আমরা তোমাদের জন্য সাগরকে বিভক্ত করেছিলাম; আমরা তোমাদের রক্ষা করেছিলাম এবং তোমাদের চোখের সামনে ফিরাউনের লোকদের ডুবিয়ে দিয়েছিলাম।"],
  "2:51": ["And when We appointed with Musa forty nights, then you took the calf after him, and you were wrongdoers.", "এরপরও, যখন আমরা মুসাকে চল্লিশ রাতের জন্য ডেকেছিলাম, তোমরা তার অনুপস্থিতিতে বাছুর পূজা করেছিলে এবং পাপপূর্ন হয়ে পড়েছিলে।"],
  "2:52": ["Then We passed over you after that, so that you might be grateful.", "তবুও, এসবের পরে আমরা তোমাদেরকে ক্ষমা করেছিলাম যাতে তোমরা কৃতজ্ঞ হও।"],
  "2:53": ["And when We gave Musa the Book and the criterion, so that you might be guided.", "স্মরণ করো যে,আমরা মুসাকে দিয়েছিলাম ঐশীগ্রন্থ এবং বিধিবদ্ধ আইনগ্রন্থ, যাতে তোমরা সুপথপ্রাপ্ত হতে পারো।"],
  "2:54": ["And when Musa said to his people, \"My people, you have wronged yourselves by taking the calf, so turn in repentance to your Maker and kill your selves; that is better for you with your Maker.\" So Allah turned to you in forgiveness. Indeed, Allah is the Turning, the Raheem.", "স্মরণ করো যে,মুসা তার লোকদের বলেছিল, “হে আমার লোকেরা,বাছুর পূজা করে তোমরা তোমাদের আত্মার ক্ষতি করেছ। তোমরা অবশ্যই তোমাদের স্রষ্টার কাছে অনুশোচনা করবে। তোমরা তোমাদের ‘আমিত্ব’কে (অহংবোধকে) হত্যা করবে। তোমাদের স্রষ্টার দৃষ্টিতে এটা তোমাদের জন্য উত্তম।”তিনি  তোমাদের উদ্ধার করেছিলেন। তিনি উদ্ধারকর্তা,পরম দয়ালু।"],
  "2:55": ["And when you said, \"Musa, we will not believe you until we see Allah openly,\" so the thunderstrike seized you while you watched.", "স্মরণ করো যে,তোমরা বলেছিলে,“হে মুসা,আমরা বিশ্বাস করবো না যতক্ষণ না আমরা আল্লাহকে স্বশরীরে দেখছি।”ফলস্বরুপ, বজ্র তোমাদের আঘাত করলো,যখন তোমরা তাকিয়েছিলে।"],
  "2:56": ["Then We raised you after your death, so that you might be grateful.", "তারপর, তোমরা মরে যাবার পর, আমরা তোমাদের পূনর্জীবিত করলাম, যাতে তোমরা কৃতজ্ঞ হও।"],
  "2:57": ["And We shaded over you the cloud, and sent down upon you the unstinting favor and the solace: \"Eat of the good of what We provided you.\" And they did not wrong Us, but they were wronging themselves.", "আমরা তোমাদেরকে (সিনাইয়ে) মেঘমালা দিয়ে ছায়া দান করেছিলাম এবং তোমাদের কাছে অবতীর্ণ করেছিলাম ‘মান্না’ এবং কোয়েলঃ “তোমাদের জন্য আমাদের দেয়া ভালো জিনিস থেকে খাও।”তারা (বিদ্রোহ করে) আমাদের ক্ষতি করেনি; তারা শুধু নিজেদের আত্মারই ক্ষতি করেছিল।"],
  "2:58": ["And when We said, \"Enter this town and eat from it freely wherever you wish, and enter the gate bowing and say, 'Remit' — We will forgive you your errors, and We will increase the doers of good.\"", "স্মরন করো যে আমরা বলেছিলাম, \"এই শহরে প্রবেশ করো, যেখানে তোমাদের পছন্দমতো অনেক জীবিকা পাবে। শুধু নম্রভাবে দরজা দিয়ে প্রবেশ করো, এবং লোকদের সাথে সুন্দর ব্যবহার করো। তাহলে আমরা তোমাদের পাপসমূহ ক্ষমা করে দেব, এবং সৎকর্মশীলদের জন্য পুরষ্কার বাড়িয়ে দেব।"],
  "2:59": ["But those who wronged substituted a word other than what was said to them, so We sent down upon those who wronged an affliction from the sky for what they used to transgress.", "কিন্তু,তাদের মধ্যকার মন্দ লোকেরা তাদেরকে দেয়া নির্দেশ অনুসরণ না করে অন্য নির্দেশ অনুসরন করলো। ফলস্বরূপ, আকাশ থেকে আমরা সীমালঙ্গনকারীদের উপর শাস্তি অবতীর্ণ করলাম, তাদের অপকর্মের জন্য।"],
  "2:60": ["And when Musa asked for drink for his people, We said, \"Strike the stone with your staff,\" and twelve springs burst forth from it. Every people already knew their drinking place. \"Eat and drink from Allah's provision, and do not ravage in the earth as corrupters.\"", "স্মরন করো যে,মুসা তার লোকদের জন্য পানি খুঁজেছিল, আমরা বলেছিলাম, \"তোমার লাঠি দিয়ে পাথরটিতে আঘাত করো\"। যার ফলে,সেখান থেকে বারটি ঝর্না প্রবলবেগে বের হয়ে আসলো। প্রত্যেক গোত্রের সদস্যরা তাদের নিজ নিজ পানি চিনতো। আল্লাহর দেয়া জীবিকা থেকে খাও এবং পান করো,এবং পৃথিবীতে দূর্নীতি করে বেড়িও না।"],
  "2:61": ["And when you said, \"Musa, we cannot endure one food; call your Rabb for us to bring forth for us of what the earth grows — its herbs, its gourds, its garlic, its lentils, and its onions.\" He said, \"Would you substitute what is lower for what is better? Descend to Riverland; you will have what you asked for.\" And abasement and want were struck upon them, and they met with wrath from Allah. That is because they used to disbelieve in Allah's signs and kill the nabis without right. That is because they disobeyed and used to transgress.", "স্মরন করো যে তোমরা বলেছিলে,\"হে মুসা,আমরা এক রকমের খাদ্য আর সহ্য করতে পারছি না। তোমার প্রভুর কাছে আহবান করো তিনি যেন আমাদের জন্য ভূমিজাত শস্য যেমন শীম, শসা,রসূন, ডাল এবং পেঁয়াজ উৎপন্ন করেন। সে বলল, \"তোমরা কি ভাল জিনিসের পরিবর্তে এর চেয়ে নিম্নমানের জিনিস চাও? মিশরে গিয়ে অধঃপতিত হও, সেখানে তোমরা যা চাচ্ছ তা পাবে\"। তারা নিজেদের উপর টেনে আনলো নিন্দা,লাঞ্ছনা এবং অসম্মান, এবং নিজেদের উপর নিয়ে আসলো আল্লাহর ক্রোধ। এটা এ কারনে যে তারা আল্লাহর প্রকাশণাবলী প্রত্যাখান করেছিল, এবং নবীদেরকে অন্যায়ভাবে হত্যা করেছিল। এটা এ কারনে যে,তারা অমান্য করেছিল এবং সীমালঙ্ঘন করেছিল।"],
  "2:62": ["Indeed those who believe, and the Jews, and the Nazarenes, and the Sabians — whoever believes in Allah and the Last Day and does good, their reward is with their Rabb, and no fear upon them, nor will they grieve.", "নিশ্চয়ই, যারা বিশ্বাস করে,যারা ইহুদী,খ্রীস্টান, এবং ধর্মান্তরিত; যে কেউই (১) বিশ্বাস করে আল্লাহতে,এবং (২) বিশ্বাস করে শেষ দিনে,এবং (৩) সৎ জীবন-যাপন করে,তারা তাদের প্রভুর কাছ থেকে প্রতিদান পাবে। তাদের ভয়ের কিছু নেই, না তারা শোক করবে।"],
  "2:63": ["And when We took your pact and raised the Mount above you: \"Take what We gave you with strength, and remember what is in it, so that you may be reverent.\"", "আমরা যখন তোমাদের উপর সিনাই পর্বত তুলে ধরে তোমাদের সাথে অঙ্গীকার করেছিলাম যে,“তোমরা দৃঢভাবে মেনে চলবে যা আমরা তোমাদের দিয়েছি,এবং এর বিষয়বস্তু স্মরণ রাখবে,যাতে তোমরা রক্ষা পেতে পার।”"],
  "2:64": ["Then you turned away after that; had it not been for Allah's favor upon you and Allah's mercy, you would have been among the khasirin.", "কিন্তু তোমরা এরপর মুখ ফিরিয়ে নিলে এবং যদি তোমাদের প্রতি আল্লাহর অনুগ্রহ ও কৃপা না থাকতো,তোমরা ধ্বংস হয়ে যেতে।"],
  "2:65": ["And you already knew those of you who transgressed in the sabbath; We said to them, \"Be apes, despised.\"", "তোমাদের মধ্যে যারা সাব্বাথকে অপবিত্র করেছিল তোমরা তাদের সম্পর্কে জেনেছো। আমরা তাদেরকে বললাম, “তোমরা বানরের মতো ঘৃণ্য হয়ে যাও।”"],
  "2:66": ["And We made it a warning to what was before it and what was after it, and an admonition for the reverent.", "আমরা তাদেরকে তাদের, এবং তাদের পরবর্তী প্রজন্মদের জন্য উদাহরণস্বরুপ করেছি,এবং সৎকর্মশীলদের জন্য করেছি একটি জ্ঞানালোক।"],
  "2:67": ["And when Musa said to his people, \"Allah commands you to slaughter a cow.\" They said, \"Do you take us in mockery?\" He said, \"I seek refuge with Allah from being among the ignorant.\"", "মুসা তার লোকদের বলল, “আল্লাহ তোমাদেরকে একটি অপক্ব-গাভী উৎসর্গ করতে আদেশ করেন।” তারা বলল, “তুমি কি আমাদের উপহাস করছো?” সে বলল, “আল্লাহ না করুন, যে আমি অজ্ঞদের মতো আচরণ করি।”"],
  "2:68": ["They said, \"Call your Rabb for us to make clear to us what she is.\" He said, \"Allah says she is a cow neither worn out nor young, middling between that; so do what you are commanded.\"", "তারা বলল, “তোমার প্রভুকে আহবান করো যেন তিনি আমাদের দেখান কোনটি।”সে বলল, “তিনি বলেছেন যে,সেটা একটি বকনা বাছুর যেটা খুব বেশি বয়ষ্ক নয়, কিংবা অল্প বয়ষ্কও নয়; মাঝামাঝি বয়সের। এবার, তোমাদেরকে যা আদেশ করা হয়েছে তা পালন করো।”"],
  "2:69": ["They said, \"Call your Rabb for us to make clear to us her color.\" He said, \"Allah says she is a yellow cow, intense in color, gladdening the beholders.\"", "তারা বলল, “তোমার প্রভুকে আহবান করো আমাদেকে যেন এর রং দেখান।”সে বলল, “তিনি বলেছেন যে,সেটা একটি হলুদ বকনা বাছুর, উজ্জ্বল রংয়ের, দর্শকদের মুগ্ধ করে।”"],
  "2:70": ["They said, \"Call your Rabb for us to make clear to us what she is, for the cows look alike to us, and if Allah wills we will be guided.\"", "তারা বলল, “তোমার প্রভুকে আহবান করো যেন তিনি আমাদের দেখান তা কোনটি। বকনা বাছুরগুলো আমাদের কাছে দেখতে একই রকম মনে হয়, আল্লাহ যদি চান, আমরা সুপথে পরিচালিত হবো।”"],
  "2:71": ["He said, \"Allah says she is a cow not subdued, that does not stir the earth nor water the tillage, sound, with no blemish in her.\" They said, \"Now you have come with the truth,\" and they slaughtered her, though they barely did it.", "সে বলল, “তিনি বলেন যে,এটি এমন বকনা বাছুর যেটা কখনো জমি চাষে অথবা শস্য ক্ষেতে পানি দেয়ার কাজে ব্যবহৃত হয়নি; কোনো প্রকার খুঁত মুক্ত।”তারা বলল, “এখন তুমি সত্যটা এনেছ।”তারা অবশেষে এটি উৎসর্গ করলো,এই দীর্ঘ অনীহার পর।"],
  "2:72": ["And when you killed a person and disputed over it — and Allah brings out what you were hiding.", "তোমরা একজনকে হত্যা করেছিলে,এরপর নিজেদের মধ্যে বিবাদ করলে। আল্লাহ তা প্রকাশ করতে চেয়েছিলেন যা তোমরা গোপন করার চেষ্টা করছিলে।"],
  "2:73": ["So We said, \"Strike him with part of it.\" Thus Allah brings the dead to life and shows you Allah's signs, so that you may understand.", "আমরা বললাম, “(অপক্ব-গাভীর) অংশ দিয়ে (মৃত ব্যক্তিটিকে) আঘাত করো।”তখনই আল্লাহ মৃত ব্যক্তিটির জীবন ফিরিয়ে দিলেন, এবং তোমাদেরকে তাঁর নিদর্শনসমূহ দেখালেন, যাতে তোমরা বুঝতে পারো।"],
  "2:74": ["Then your hearts hardened after that, so they are like stones, or harder; yet from some stones rivers burst forth, and some of them split so water comes out of them, and some of them descend in awe of Allah. And Allah is not unmindful of what you do.", "তা সত্ত্বেও, তোমাদের হৃদয় পাথরের মতো কঠিন হয়ে গেল, বা তার চেয়েও কঠিন। কারণ এমন পাথরও আছে যেগুলো থেকে নদী প্রবল বেগে বের হয়ে আসে। অন্যগুলো ফেঁটে যায় এবং শান্ত ঝর্ণা নির্গত হয়, এবং অন্য পাথরগুলো আল্লাহর ভয়ে খসে পড়ে। আল্লাহ কখনোই অসচেতন নন যা কিছু তোমরা করো।"],
  "2:75": ["Do you hope that they will believe for you when a party of them used to hear Allah's word and then distort it after they had understood it, while they knew?", "তোমরা কি আশা করো যে তারা তোমাদের মতো বিশ্বাস করবে,যখন তাদের মধ্যে কিছু লোক আল্লাহর কথা শুনতো,তারপর তা বিকৃত করতো,সম্পূর্ণ বুঝে-শুনে এবং ইচ্ছাকৃতভাবে?"],
  "2:76": ["And when they meet those who believe, they say, \"We believe,\" but when some of them are alone with others, they say, \"Do you tell them what Allah has opened for you, so that they may argue with you by it before your Rabb? Do you not understand?\"", "এবং যখন তারা বিশ্বাসীদের সাথে সাক্ষাত করে,তারা বলে,“আমরা বিশ্বাস করি,”কিন্তু যখন তারা একে অপরের সাথে মিলিত হয়, তারা বলে,“তোমাদেরকে দেয়া আল্লাহর তথ্য (বিশ্বাসীদেরকে) জানিয়ে দিয়ো না,পাছে তোমরা তোমাদের প্রভুর সম্পর্কে তাদের যুক্তিতে সমর্থন যোগাবে। তোমরা কি বোঝ না?”"],
  "2:77": ["Do they not know that Allah knows what they hide and what they openly declare?", "তারা কি জানে না যে,আল্লাহ জানেন যা কিছু তারা গোপন করে,এবং যা কিছু তারা প্রকাশ করে?"],
  "2:78": ["And among them are unlettered ones who do not know the Book except as wishes, and they do nothing but conjecture.", "তাদের মধ্যে রয়েছে ঐশীগ্রন্থ অনুসরণ না করা (উম্মী) লোক, যারা ঐশীগ্রন্থ সম্পর্কে জানে না; লোক মুখে শোনা কথা ছাড়া,তারপর তারা ধরে নেয় যে তারা তা জানে।"],
  "2:79": ["Woe to those who write the book with their own hands and then say, \"This is from Allah,\" to buy with it a small price. Woe to them for what their hands have written, and woe to them for what they earn.", "কাজেই, দুর্ভোগ তাদের প্রতি যারা নিজেদের হাতে ঐশীগ্রন্থ বিকৃত করে,এরপর বলে,“এটাই আল্লাহ অবতীর্ণ করেছেন, ”সস্তা পার্থিব মুনাফা খোঁজে। দূর্ভোগ তাদের প্রতি এরুপ বিকৃতির জন্য, এবং দূর্ভোগ তাদের প্রতি তাদের এই অবৈধ অর্জনের জন্য।"],
  "2:80": ["And they said, \"The Fire will not touch us except for counted days.\" Say, \"Have you taken a pledge with Allah? Then Allah will never break Allah's pledge. Or do you say of Allah what you do not know?\"", "কেউ কেউ বলেছে,“নরক আমাদের স্পর্শ করবে না নির্দিষ্ট সংখ্যক কিছু দিন ছাড়া।”বল, “তোমরা কি আল্লাহর কাছ থেকে এমন কোন অঙ্গীকার নিয়েছ – আল্লাহ কখনোই তাঁর অঙ্গীকার ভঙ্গ করেন না – নাকি তোমরা আল্লাহ সম্পর্কে এমন কিছু বলছো যা তোমরা জানো না?”"],
  "2:81": ["Yes — whoever earns an evil and is encompassed by their sin, those are the companions of the Fire; they abide in it forever.", "নিশ্চয়ই, যারা পাপ অর্জন করে এবং তাদের অসৎ কর্ম দ্বারা পরিবেষ্টিত হয়ে যায়, তারাই হবে নরকের বাসিন্দা; তারা সেখানে চিরকাল বসবাস করে।"],
  "2:82": ["And those who believe and do the good deeds — those are the companions of the garden; they abide in it forever.", "আর যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে,তারা হবে স্বর্গের বাসিন্দা; তারা সেখানে চিরকাল বসবাস করে।"],
  "2:83": ["And when We took the pact of the Children of Israel: worship none but Allah, and goodness to parents and to the near kin, and to orphans and the needy, and speak good to the people, and keep up the prayer and give the alms. Then you turned away — except a few of you — and you are turning aside.", "আমরা ইসরাইলের সন্তানদের সাথে একটি অঙ্গীকার করেছিলামঃ “তোমরা আল্লাহ ছাড়া আর কারো উপাসনা করবে না। তোমরা পিতামাতাকে সম্মান করবে এবং আত্মীয়-স্বজন, এতীম এবং গরীবদের প্রতি খেয়াল রাখবে। তোমরা লোকদের সাথে সুন্দর ব্যবহার করবে। তোমরা সংযোগ প্রার্থণা (সালাত) পালন করবে এবং বাধ্যতামূলক দান (যাকাত) প্রদান করবে।”কিন্তু সামান্য কয়েকজন ছাড়া,তোমরা মুখ ফিরিয়ে নিলে,এবং তোমরা বিরোধী হয়ে পড়লে।"],
  "2:84": ["And when We took your pact: do not shed your blood nor drive yourselves out from your homes; then you affirmed, and you were witnesses.", "আমরা তোমাদের সাথে একটি অঙ্গীকার করেছিলাম যে,তোমরা নিজেদের মধ্যে রক্তপাত করবে না,না তোমরা পরস্পরকে তোমাদের ঘর-বাড়ি থেকে উচ্ছেদ করবে। তোমরা সম্মত হয়েছিলে এবং স্বাক্ষ্য দিয়েছিলে।"],
  "2:85": ["Yet here you are, killing yourselves and driving out a party of you from their homes, backing one another against them in sin and aggression; and if they come to you as captives, you ransom them, though their driving out was forbidden to you. Do you believe in part of the Book and disbelieve in part? Then what is the recompense for whoever does that among you except disgrace in the nearer life? And on the Day of Rising they will be returned to the hardest punishment. And Allah is not unmindful of what you do.", "এরপরও, তোমরা একে অন্যকে হত্যা করছো এবং তোমাদের কাউকে কাউকে তাদের বাড়ি-ঘর থেকে উচ্ছেদ করছো,তাদের বিরুদ্ধে পাপ এবং বিদ্বেষের সাথে একত্রিত হয়ে। এমনকি তারা আত্ম-সমর্পণ করার পরও তোমরা তাদের কাছে মুক্তিপণ দাবী করেছো। তাদের উচ্ছেদ করাটাই প্রথমত তোমাদের জন্য নিষিদ্ধ ছিল। তোমরা কি ঐশীগ্রন্থের কিছু অংশে বিশ্বাস করো আর কিছু অংশে অবিশ্বাস করো? তোমাদের মধ্যে যারা এরুপ করে তাদের শাস্তি কি হওয়া উচিত, এই জীবনে অপদস্থতা এবং পুনুরুত্থান দিবসে আরোও নিকৃষ্ট শাস্তি ছাড়া? তোমরা যা কিছু করো তা সম্পর্কে আল্লাহ কখনোই অসচেতন নন।"],
  "2:86": ["Those are the ones who bought the nearer life for the Last; so the punishment will not be lightened for them, nor will they be helped.", "এরা তারাই যারা পরকালের বিনিময়ে এই তুচ্ছ জীবন ক্রয় করেছে। ফলস্বরুপ, তাদের জন্য শাস্তি কখনোই কমানো হয় না,না তারা সাহায্যপ্রাপ্ত হতে পারে।"],
  "2:87": ["And We gave Musa the Book and followed him up with the Rasuls afterward, and We gave Isa son of Maryam clear proofs and strengthened him with the Holy Spirit. Then is it that whenever a Rasul comes to you with what your souls do not desire, you are arrogant: a party you deny, and a party you kill?", "আমরা মুসাকে ঐশীগ্রন্থ দিয়েছিলাম এবং তার পরে আমরা অন্যান্য বার্তাবাহকদের পাঠিয়েছিলাম এবং আমরা মরিয়মের পুত্র যীশুকে সুস্পষ্ট অলৌকিক নিদর্শনাবলি দিয়েছিলাম আর পবিত্র আত্মার মাধ্যমে তাকে সমর্থণ করেছিলাম। এটাই কি বাস্তব সত্য নয় যে,যখনই কোন বার্তাবাহক তোমাদের কাছে যেতো এমন কোনকিছু নিয়ে যা তোমরা অপছন্দ করতে,তোমাদের আমিত্ব তোমাদেরকে উদ্ধত করে তুলতো? তাদের কাউকে তোমরা প্রত্যাখ্যান করতে,এবং কাউকে হত্যা করতে।"],
  "2:88": ["And they said, \"Our hearts are wrapped.\" No — Allah has cursed them for their disbelief, so little do they believe.", "কেউ কেউ বলে, “পূর্ব থেকে আমাদের মন স্থির হয়ে আছে!” বরং,এটা আল্লাহর পক্ষ থেকে এক অভিশাপ, তাদের অবিশ্বাসের ফলে, যা তাদেরকে বিশ্বাস করা থেকে বিরত রাখে, তাদের অল্প কিছু সংখ্যক ছাড়া।"],
  "2:89": ["And when a book came to them from Allah confirming what was with them — while before they used to seek triumph over those who kafara — then when there came to them what they recognized, they kafara in it. So Allah's curse is upon the kafirin.", "যখন এই ঐশীগ্রন্থ আল্লাহর পক্ষ থেকে তাদের কাছে আসলো, এবং এমনকি যদিও এটি তাদের নিকট যা আছে তার সাথে একমত হয়, এবং তা সুনিশ্চিত করে,এবং এমনকি যদিও অবিশ্বাসীদের সাথে কথা বলার সময় তারা এর আগমনের ভবিষ্যদ্বানী করতো, যখন তাদের নিজেদের ভবিষ্যদ্বানী পূর্ণ হলো, তারা তা অবিশ্বাস করলো। আল্লাহর অভিসম্পাত এভাবেই অবিশ্বাসীদের উপর পতিত হয়।"],
  "2:90": ["Miserable is what they bought their souls with: that they disbelieve in what Allah sent down, grudging that Allah should send down of Allah's favor upon whomever Allah wills of Allah's servants. So they met wrath upon wrath, and for the kafirin is a humiliating punishment.", "নিশ্চয়  শোচনীয় যার বিনিময়ে তারা তাদের আত্মা বিক্রি করেছে – আল্লাহর এই প্রকাশণাবলি প্রত্যাখ্যান করে,নিছক এই বিদ্বেষে যে আল্লাহ তাঁর দাসদের মধ্যে যার উপর ইচ্ছা অনুগ্রহ প্রদান করেন। ফলস্বরুপ, তারা ক্রোধের উপর ক্রোধ অর্জন করেছে। অবিশ্বাসীরা নিজেদের উপর টেনে এনেছে লাঞ্ছনাকর শাস্তি।"],
  "2:91": ["And when it is said to them, \"Believe in what Allah sent down,\" they say, \"We believe in what was sent down on us,\" and they disbelieve in what is beyond it — though it is the truth confirming what is with them. Say, \"Then why did you kill the nabis of Allah before, if you are muminin?\"", "যখন তাদেরকে বলা হয়, “তোমরা আল্লাহর এই প্রকাশণাবলিতে বিশ্বাস করবে,”তারা বলে,“আমরা শুধু তাতে বিশ্বাস করি যা আমাদের উপর অবতীর্ণ হয়েছে।”এরুপে,তারা অবিশ্বাস করে পরবর্তী প্রকাশণাবলিতে,যদিও এটা তাদের প্রভুর পক্ষ থেকে সত্য এবং যদিও এটা নিশ্চিত করে যা তাদের কাছে আছে! বল, “তাহলে কেন তোমরা আল্লাহর নবীদের হত্যা করেছো,যদি তোমরা বিশ্বাসীই ছিলে?”"],
  "2:92": ["And Musa came to you with clear proofs, then you took the calf after him, and you were wrongdoers.", "মুসা তোমাদের কাছে গিয়েছিল সুস্পষ্ট অলৌকিক নিদর্শনবলি নিয়ে, তারপরও তোমরা তার অনুপস্থিতিতে বাছুর পূজা করেছিলে এবং পাপপূর্ন হয়েছিলে।"],
  "2:93": ["And when We took your pact and raised the Mount above you: \"Take what We gave you with strength, and listen.\" They said, \"We hear and we disobey,\" and the calf was drunk into their hearts for their disbelief. Say, \"Miserable is what your faith commands you, if you are muminin.\"", "আমরা তোমাদের সাথে একটি অঙ্গীকার করেছিলাম, যখন আমরা তোমাদের উপর সিনাই পর্বত তুলে ধরেছিলাম, এই বলে,“আমরা তোমাদেরকে যে প্রত্যাদেশাবলি দিয়েছি তা মেনে চলবে,দৃঢভাবে এবং মন দিয়ে শোন।”তারা বলল, “আমরা শুনি,কিন্তু অমান্য করি।”তাদের হৃদয় বাছুর পূজায় পূর্ণ ছিল, তাদের অবিশ্বাসের কারণে। বল, “সত্যিই শোচনীয় যা তোমাদের বিশ্বাস তোমাদের নির্দেশ দেয়, যদি আদৌ তোমাদের কোন বিশ্বাস থেকে থাকে।”"],
  "2:94": ["Say, \"If the Last Abode with Allah is yours exclusively, apart from the people, then wish for death, if you are sadiq.\"", "বল, “যদি আল্লাহর নিকট পরকালের আবাস শুধুমাত্র তোমাদের জন্যই সংরক্ষিত থাকে,অন্য সকল মানুষকে বাদ দিয়ে,তবে তোমাদের মৃত্যু আকাঙ্ক্ষা করা উচিত, যদি তোমরা সত্যবাদী হয়ে থাক।”"],
  "2:95": ["And they will never wish it, for what their hands sent forth. And Allah is knowing of the wrongdoers.", "তারা কখনোই তা আকাঙ্ক্ষা করে না,তা-র জন্য যা তাদের হাত ইতিপূর্বে পাঠিয়েছে। আল্লাহ পাপীদের সম্পর্কে পূর্ণ সচেতন।"],
  "2:96": ["And you will surely find them the most ardently wanting of people for life, more than the associators: each one of them would like to be given a thousand years of life, and it would not move them away from the punishment to be given life so long. And Allah is all-seeing of what they do.", "প্রকৃতপক্ষে,তোমরা দেখবে,তারা জীবনের প্রতি সবচেয়ে বেশি লোভী; এমনকি প্রতিমা উপাসকদের চেয়েও বেশি। তাদের একেক জন হাজার বছর বেঁচে থাকতে চায়। কিন্তু এটা তাদেরকে কোন শাস্তি থেকে রেহাই দেবে না,যত দিনই তারা বাঁচুক না কেন। তারা যা কিছু করে আল্লাহ সবই দেখেন।"],
  "2:97": ["Say, \"Whoever is an enemy to Jibril — indeed, it is he who sent it down upon your heart by Allah's leave, confirming what was before it, and guidance and glad tidings for the muminin.\"", "বল, “যে কেউ জিবরাইলের বিরোধীতা করে তার জানা উচিত যে,সে এটি (কুরআন) তোমার হৃদয়ে অবতীর্ণ করেছে আল্লাহর ইচ্ছানুসারে,যা নিশ্চিত করে পুর্ববর্তী ঐশীগ্রন্থসমূহ এবং বিশ্বাসীদের জন্য পথনির্দেশ ও সুসংবাদ দেয়।”"],
  "2:98": ["Whoever is an enemy to Allah, and to Allah's malakat, and to Allah's rusul, and to Jibril and Mikail — then indeed Allah is an enemy to the kafirin.", "যে কেউ আল্লাহ, এবং তাঁর ফেরেশতাদের, এবং তাঁর বার্তাবাহকদের, আর জিবরাইল ও মিকাইলের বিরোধিতা করে,তার জানা উচিত যে,আল্লাহ অবিশ্বাসীদের বিরোধিতা করেন।"],
  "2:99": ["And We sent down upon you clear signs, and none disbelieve in them except the transgressors.", "আমরা তোমার প্রতি অবতীর্ণ করেছি এমন সুস্পষ্ট প্রকাশণাবলি এবং শুধুমাত্র পাপীরাই তা প্রত্যাখ্যান করবে।"],
  "2:100": ["Is it that whenever they pledged a pledge, a party of them cast it away? No — most of them do not believe.", "এটাই কি বাস্তব সত্য নয় যে যখন তারা কোন অঙ্গীকার করে এবং সেটা রক্ষা করার প্রতিজ্ঞা করে,তাদের মধ্যে কেউ কেউ তা সবসময় উপেক্ষা করে? বস্তুত, তাদের অধিকাংশ বিশ্বাস করে না।"],
  "2:101": ["And when a Rasul from Allah came to them confirming what was with them, a party of those given the Book cast the Book of Allah behind their backs, as if they did not know.", "এখন যেহেতু আল্লাহর পক্ষ থেকে তাদের কাছে একজন বার্তাবাহক এসেছে এবং যদিও সে তাদের নিজেদের ঐশীগ্রন্থটি প্রমাণ করে এবং সুনিশ্চিত করে,ঐশীগ্রন্থের কিছু অনুসারীরা (ইহুদী,খ্রীস্টান এবং মুসলিমরা) তাদের অগোচরে আল্লাহর গ্রন্থ উপেক্ষা করে,যেন তাদের কখনো কোন ঐশীগ্রন্থ ছিল না।"],
  "2:102": ["And they followed what the satans recited over Sulayman's kingdom — and Sulayman did not disbelieve, but the satans kafara, teaching people magic, and what was sent down upon the two malakat at Babel, Harut and Marut. And they taught no one without first saying, \"We are only a test, so do not disbelieve.\" Yet from the two they learned what they use to divide between a person and their spouse. And by it they harm no one except by Allah's leave. And they learn what harms them and does not benefit them. And they have surely known that whoever buys it has no share in the Last. And miserable is what they bought their souls with, if only they knew.", "তারা অনুসরণ করলো যা শয়তানরা সোলায়মানের রাজত্ব সম্পর্কে শিখিয়েছিল। তবে,সোলায়মান অবিশ্বাসী ছিল না,অবিশ্বাসী ছিল শয়তানরা। তারা লোকদের শেখাতো কালো যাদু এবং যা বাবেল নগরীর দু’জন ফেরেশতা হারুত ও মারুতের মাধ্যমে অবতীর্ণ হয়েছিল। এই দু’জন এরকম জ্ঞান ফাঁস করতো না,এটা না বলে যেঃ “এটা একটা পরীক্ষা। তোমরা এমন জ্ঞানের অপব্যবহার করবে না।”কিন্তু লোকেরা এটি ব্যবহার করলো বিয়ে ভেঙ্গে দেয়ার মতো মন্দ ষড়যন্ত্রে। তারা কখনো আল্লাহর ইচ্ছার বিরুদ্ধে কারো ক্ষতি করতে পারে না। এভাবে তারা শেখে যা তাদেরকে কষ্ট দেয়, তা নয় যা তাদের উপকার করে এবং তারা খুব ভালোভাবে জানে যে,যেকেউ কালো যাদু চর্চা করে তার জন্য পরকালে কোন অংশ নেই। সত্যিই শোচনীয় যার জন্য তারা তাদের আত্মা বিক্রি করে,যদি শুধু তারা জানতো।"],
  "2:103": ["If only they had believed and been reverent — a recompense from Allah would have been better, if only they knew.", "যদি তারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে,তাহলে আল্লাহর পক্ষ থেকে পুরষ্কার অনেক উত্তম, যদি শুধু তারা জানতো।"],
  "2:104": ["O you who believe, do not say \"keep us,\" but say \"look upon us,\" and listen. And for the kafirin is a painful punishment.", "হে তোমরা যারা বিশ্বাস করো,“রা’য়েনা (আমাদের রাখাল হও)” বলো না। বরং বল, “উনযুরনা (আমাদের প্রতি লক্ষ্য রাখো)”এবং মনোযোগ সহকারে শোনো। অবিশ্বাসীরা নিজেদের উপর কষ্টদায়ক শাস্তি টেনে এনেছে।"],
  "2:105": ["Neither those who kafara among the people of the Book nor the associators wish that any good be sent down upon you from your Rabb. But Allah singles out for Allah's mercy whomever Allah wills, and Allah is possessor of the tremendous favor.", "না ঐশীগ্রন্থের অনুসারীদের মধ্যকার অবিশ্বাসীরা,না অংশীদার উপসাকরা,দেখতে চায় যে তোমাদের কাছে তোমাদের প্রভুর পক্ষ থেকে কোন আশীর্বাদ নেমে আসুক। যদিও, আল্লাহ তাঁর আশীর্বাদ তার প্রতি বর্ষণ করেন যাকে তিনি পছন্দ করেন। আল্লাহ অসীম অনুগ্রহের অধিকারী।"],
  "2:106": ["Whatever verse We abrogate or cause to be forgotten, We bring better than it or its like. Do you not know that Allah is over all things able?", "যখন আমরা কোন অলৌকিক নিদর্শন রহিত করি কিংবা তা বিস্মৃত করে দেই, আমরা এর চেয়েও উত্তম, বা অন্ততপক্ষে এর সমতুল্য কোন অলৌকিক নিদর্শন উপস্থিত করি। তোমরা কি এই বাস্তব সত্যটা উপলব্ধি করো না যে আল্লাহ সর্বশক্তিমান?"],
  "2:107": ["Do you not know that to Allah belongs the kingdom of the heavens and the earth, and that you have, apart from Allah, no protecting friend and no helper?", "তোমরা কি এই বাস্তব সত্যটা উপলব্ধি করো না যে আল্লাহর অধীনে রয়েছে আকাশমন্ডলী ও পৃথিবীর রাজত্ব; আর আল্লাহ ব্যতীত তোমাদের কোন প্রভু ও মালিক নেই?"],
  "2:108": ["Or do you wish to ask your Rasul as Musa was asked before? And whoever exchanges disbelief for belief has strayed from the even way.", "তোমরা কি তোমাদের বার্তাবাহকের কাছে এমন কিছু দাবী করতে চাও যেমন অতীতে মুসার কাছে দাবী করা হয়েছিল? যে কেউ অবিশ্বাসকে বেছে নেয়, বিশ্বাসের পরিবর্তে,সত্যিই সে সঠিক পথ থেকে বিচ্যুত হয়েছে।"],
  "2:109": ["Many of the people of the Book wish they could return you to disbelief after your belief, out of envy from themselves, after the truth was made clear to them. So pass over and pardon, until Allah brings Allah's command. Indeed Allah is over all things able.", "এখন যেহেতু তোমরা বিশ্বাস করেছ, ঐশীগ্রন্থের অনেক অনুসারী দেখতে চাইবে যে তোমরা পুনরায় অবিশ্বাস করো। এটা তাদের পক্ষ থেকে হিংসার ফল, সত্য তাদের কাছে সুস্পষ্ট হবার পর। তোমরা তাদেরকে ক্ষমা করো,তাদেরকে তাদের মতো ছেঁড়ে দাও, যতক্ষণ না আল্লাহ তাঁর রায় দেন। আল্লাহ সর্বশক্তিমান।"],
  "2:110": ["And keep up the prayer and give the alms. Whatever good you send ahead for yourselves, you will find it with Allah. Indeed Allah is all-seeing of what you do.", "তোমরা সংযোগ প্রার্থণা (সালাত) পালন করো এবং বাধ্যতামূলক দান (যাকাত) দাও। তোমাদের আত্মার পক্ষে ভালো যা কিছু তোমরা অগ্রে প্রেরণ করো,তা তোমরা আল্লাহর কাছে পাবে। তোমরা যা কিছু করো আল্লাহ তা দেখেন।"],
  "2:111": ["And they said, \"None will enter the garden except who is a Jew or a Nazarene.\" Those are their wishes. Say, \"Bring your proof, if you are sadiq.\"", "কেউ কেউ বলেছে,\"ইহুদী বা খ্রিষ্টান ছাড়া কেউই স্বর্গে প্রবেশ করবে না!”এমনই তাদের মনগড়া চিন্তাধারা। বল, “আমাদেরকে তোমাদের প্রমাণ দেখাও, যদি তোমরা সঠিক হও।”"],
  "2:112": ["Rather, whoever surrenders their face to Allah while doing good — their reward is with their Rabb, and no fear upon them, nor will they grieve.", "নিশ্চয়ই, যারা নিজেদেরকে সম্পূর্ণরুপে শুধুমাত্র আল্লাহর কাছে সমর্পণ করে,সেই সাথে সৎজীবন যাপন করে,তারা তাদের প্রভুর কাছ থেকে প্রতিদান পাবে; তাদের ভয়ের কিছু নেই, না তারা কোন শোক করবে।"],
  "2:113": ["The Jews said, \"The Nazarenes stand on nothing,\" and the Nazarenes said, \"The Jews stand on nothing,\" while they recite the Book. Likewise said those who do not know, the like of their saying. So Allah will judge between them on the Day of Rising in what they used to differ.", "ইহুদিরা বলল, “খ্রীস্টানদের কোন ভিত্তি নেই, ”আবার অন্যদিকে খ্রীস্টানরা বলল, “ইহুদিদের কোনো ভিত্তি নেই।”অথচ তারা উভয়ই ঐশীগ্রন্থ পাঠ করে। এমন কথাবার্তা তাদেরই হয় যারা কোন জ্ঞান রাখে না। আল্লাহ পুনঃরুত্থান দিবসে তাদের বিচার করবেন, তাদের মতবিরোধ সম্পর্কে।"],
  "2:114": ["And who is more unjust than one who bars the places of prostration of Allah, that Allah's name be remembered in them, and strives for their ruin? Those — it was not for them to enter them except in fear. For them in the nearer life is disgrace, and for them in the Last is a tremendous punishment.", "তাদের চেয়ে কারা বেশি মন্দ যারা আল্লাহর মসজিদগুলো বর্জন করে,যেখানে তাঁর নাম স্মরণ করা হয়, এবং সেগুলোকে পরিত্যক্ত করতে ভূমিকা রাখে? ভয়-বিহবল অবস্থায় ছাড়া সেখানে তাদের প্রবেশ কাঙ্খিত নয়। তারা এই জীবনে লাঞ্ছনা ভোগ করবে এবং পরকালে ভোগ করবে এক ভয়ানক প্রতিফল।"],
  "2:115": ["And to Allah belong the east and the west; so wherever you turn, there is the face of Allah. Indeed Allah is all-ample, knowing.", "পূর্ব ও পশ্চিম আল্লাহরই; তোমরা যেখানেই যাও সেখানেই আল্লাহর উপস্থিতি থাকবে। আল্লাহ সর্বত্র বিরাজমান, সর্বজ্ঞ।"],
  "2:116": ["And they said, \"Allah has taken a child.\" Glory be to Allah! No — to Allah belongs whatever is in the heavens and the earth; all are devoutly obedient to Allah.", "তারা বলেছে,“আল্লাহ পুত্র জন্ম দিয়েছেন!”তিনি মহিমান্বিত; কখনই নয়! তাঁর অধীনে রয়েছে আকাশমন্ডলী ও পৃথিবীর সবকিছু।; সবাই তাঁর আজ্ঞাধীন।"],
  "2:117": ["Originator of the heavens and the earth — and when Allah decides a matter, Allah only says to it, \"Be,\" and it is.", "আকাশমন্ডলী ও পৃথিবীর সূচনাকারীঃ কোন কিছু সম্পন্ন করতে তিনি শুধু একে বলেন, “হও”এবং তা হয়ে যায়।"],
  "2:118": ["And those who do not know said, \"If only Allah would speak to us, or a sign would come to us.\" Likewise said those before them, the like of their saying. Their hearts are alike. We have made the signs clear for a people who are certain.", "যারা কোন জ্ঞান রাখে না তারা বলে,“শুধু যদি আল্লাহ আমাদের সাথে কথা বলতেন, অথবা কোন অলৌকিক নিদর্শন আমাদের কাছে আসতো”তাদের পূর্বে অন্যরা একই ধরণের কথা বলেছে; তাদের মানসিকতা একই ধরণের। আমরা তাদের জন্য অলৌকিক নিদর্শন সুস্পষ্ট করি যারা নিশ্চিত বিশ্বাস অর্জন করেছে।"],
  "2:119": ["Indeed We sent you with the truth, as a bringer of glad tidings and a warner, and you will not be asked about the companions of the blazing fire.", "আমরা তোমাকে সত্য সহকারে পাঠিয়েছি সুসংবাদবহনকারী,সেই সাথে সতর্ককারী হিসেবে। তোমাকে তাদের সম্পর্কে জিজ্ঞাসা করা হবে না যারা নিজেদের উপর নরক টেনে এনেছে।"],
  "2:120": ["And the Jews will never be pleased with you, nor the Nazarenes, until you follow their way. Say, \"The guidance of Allah — that is the guidance.\" And if you follow their desires after the knowledge that came to you, you will have from Allah no protecting friend and no helper.", "ইহুদি বা খ্রীস্টানরা তোমাকে গ্রহণ করবে না,যদি না তুমি তাদের ধর্ম অনুসরণ করো। বল, “আল্লাহর পথনির্দেশনাই সত্য পথনির্দেশনা।”তুমি যে জ্ঞান প্রাপ্ত হয়েছো তা সত্ত্বেও যদি তুমি তাদের ইচ্ছায় সম্মত হও, তবে আল্লাহর বিরুদ্ধে তোমাকে সাহায্য করার জন্য তুমি কোন মিত্র বা সমর্থণকারী পাবে না।"],
  "2:121": ["Those to whom We gave the Book recite it as it should be recited — those believe in it. And whoever disbelieves in it, those are the khasirin.", "যারা ঐশীগ্রন্থ পেয়েছে এবং এটা সম্বন্ধে জানে যেভাবে জানা উচিত, তারা এতে বিশ্বাস করবে। আর যারা অবিশ্বাস করে,তারাই ক্ষতিগ্রস্থ।"],
  "2:122": ["Children of Israel, remember My favor that I favored upon you, and that I favored you above the worlds.", "হে ইসরাঈলের সন্তানেরা,স্মরণ করো আমার অনুগ্রহ যা আমি তোমাদের দান করেছি,এবং আমি তোমাদেরকে অন্য সকল লোকদের চেয়ে বেশি সৌভাগ্যশালী করেছিলাম।"],
  "2:123": ["And beware a day when no self will avail another self anything, and no compensation will be accepted from it, and no intercession will benefit it, and they will not be helped.", "সে দিন সম্পর্কে সতর্ক হও যখন কোন আত্মা অন্য আত্মাকে সাহায্য করবে না,কোন মুক্তিপণ গ্রহণ করা হবে না,কোন সুপারিশ ফলপ্রসু হবে না এবং কেউ সাহায্য পাবে না।"],
  "2:124": ["And when Ibrahim's Rabb tested him with words and he completed them, Allah said, \"I am making you an imam for the people.\" He said, \"And from my offspring?\" Allah said, \"My pledge does not reach the wrongdoers.\"", "স্মরণ করো যে,ইব্রাহিম তার প্রভুর দ্বারা নির্দিষ্ট কিছু আদেশের মাধ্যমে পরীক্ষিত হয়েছিল এবং সে সেগুলো পূর্ণ করেছিল। (আল্লাহ) বলেছিলেন, “আমি তোমাকে মানুষের জন্য ইমাম নিযুক্ত করছি।”সে বলেছিল, “আর আমার বংশধর থেকেও কি?”তিনি বলেছিলেন, “আমার অঙ্গীকার সীমালঙ্ঘনকারীদের অন্তর্ভুক্ত করে না”।"],
  "2:125": ["And when We made the House a resort for people and a sanctuary: \"And take from the standing-place of Ibrahim a place of prayer.\" And We charged Ibrahim and Ismail: \"Purify My House for those who go around it, and those who cleave to it, and those who bow and prostrate.\"", "আমরা পবিত্র ঘর (কাবা)-কে করেছি লোকদের জন্য কেন্দ্রবিন্দুতে এবং একটি নিরাপদ পূন্যস্থানে। তোমরা ইব্রাহিমের অবস্থান স্থলকে প্রার্থণা ঘর হিসেবে ব্যবহার করো। আমরা ইব্রাহিম ও ইসমাঈলকে নিযুক্ত করেছিলামঃ “তোমরা আমার ঘরকে তাদের জন্য পবিত্র রাখবে যারা দর্শন করতে আসে,যারা সেখানে বসবাস করে,এবং যারা রুকু এবং সেজদা করে।”"],
  "2:126": ["And when Ibrahim said, \"Rabb, make this a secure town and provide its people with fruits — whoever among them believes in Allah and the Last Day.\" Allah said, \"And whoever disbelieves, I will give them enjoyment a little, then force them to the punishment of the Fire — and miserable is the arrival.\"", "ইব্রাহিম প্রার্থণা করেছিল, “আমার প্রভু,এই স্থানটিকে শান্তিময় করুন এবং এর অধিবাসীদের ফলের যোগান দিন। যোগান দিন তাদের জন্য যারা আল্লাহ এবং শেষ দিবসে বিশ্বাস করে।”(আল্লাহ) বললেন, “আমি তাদের জন্যও যোগান দিব যারা অবিশ্বাস করে। আমি তাদেরকে উপভোগ করতে দেব, সাময়িকভাবে,তারপর তাদেরকে পতিত করবো নরকের শাস্তিতে,এবং এক শোচনীয় নিয়তিতে।”"],
  "2:127": ["And when Ibrahim, with Ismail, was raising up the foundations of the House: \"Our Rabb, accept from us; indeed You are the Hearing, the Knowing.\"", "যখন ইব্রাহিম ইসমাঈলকে সাথে নিয়ে পবিত্র ঘরের ভিত্তি গড়ে তুলেছিল (তারা প্রার্থণা করলো):“আমাদের প্রভু,এটি আমাদের কাছ থেকে গ্রহণ করুন। আপনি সর্বশ্রোতা,সর্বজ্ঞ।"],
  "2:128": ["\"Our Rabb, make us submissive to You, and from our offspring a community submissive to You, and show us our rites, and turn to us in forgiveness. Indeed You are the Turning, the Raheem.\"", "“আমাদের প্রভু,আমাদেরকে আপনার কাছে আত্ম-সমর্পণকারী করুন এবং আমাদের বংশধর থেকে আপনার কাছে একটি আত্ম-সমর্পণকারী সম্প্রদায় গড়ে তুলুন। আমাদেরকে ধর্মের রীতিনীতি শিক্ষা দিন এবং আমাদের পাপ মোচন করুন। আপনি পাপ মোচনকারী,পরম দয়ালু।"],
  "2:129": ["\"Our Rabb, and raise up among them a Rasul from them who will recite to them Your signs and teach them the Book and the wisdom and purify them. Indeed You are the Mighty, the Wise.\"", "“আমাদের প্রভু,আর তাদের মধ্য থেকে একজন বার্তাবাহকের উত্থান ঘটান তাদের কাছে আপনার প্রকাশণাবলি পড়ে শোনানোর জন্য, তাদেরকে ঐশীগ্রন্থ ও প্রজ্ঞা শিক্ষা দেবার জন্য এবং তাদেরকে পরিশুদ্ধ করার জন্য। আপনি সর্বশক্তিমান, সবচেয়ে জ্ঞানী।”"],
  "2:130": ["And who would turn away from the way of Ibrahim except one who fools themselves? And We chose him in the nearer life, and in the Last he is among the good ones.", "সে ছাড়া কে ইব্রাহিমের ধর্ম পরিত্যাগ করে,যে তার নিজ আত্মাকেই বোকা বানায়? আমরা এই দুনিয়াতে তাকে পছন্দ করেছি,এবং পরকালে সে সৎকর্মশীলদের সাথে থাকবে।"],
  "2:131": ["When Allah said to him, \"Surrender,\" he said, \"I surrender to the Rabb of the worlds.\"", "যখন তার প্রভু তাকে বললেন, \"আত্মসমর্পণ করো\",সে বলল, \"আমি বিশ্বজগতের প্রভুর কাছে আত্মসমর্পণ করলাম।"],
  "2:132": ["And Ibrahim enjoined it upon his sons, and Yaqub: \"My sons, Allah has chosen the way for you, so do not die except as ones submissive.\"", "উপরন্তু,ইব্রাহিম তার সন্তানদেরও অনুরূপ করতে উপদেশ দিয়েছিল, এবং ইয়াকুবও এমনটি করেছিল: \"হে আমার সন্তানেরা,আল্লাহ তোমাদের জন্য ধর্মকে নির্দিষ্ট করে দিয়েছেন; আত্মসমর্পণকারী না হয়ে মরো না।\""],
  "2:133": ["Or were you witnesses when death attended Yaqub, when he said to his sons, \"What will you worship after me?\" They said, \"We will worship your ilah and the ilah of your fathers, Ibrahim and Ismail and Ishaq — one ilah — and to Allah we are submissive.\"", "যদি তোমরা ইয়াকুবকে তার মৃত্যু শয্যায় দেখতে ; সে তার সন্তানদের বলেছিল, \"আমার মৃত্যুর পর তোমরা কিসের উপাসনা করবে?”তারা বলেছিল, \"আমরা উপাসনা করবো আপনার  উপাস্যের; আপনার পিতৃপুরুষ ইব্রাহিম, ইসমাইল, এবং ইসহাকের উপাস্যের; সেই একক উপাস্যের। তাঁর নিকট আমরা আত্ম-সমর্পণকারী।"],
  "2:134": ["That is a community that has passed on: theirs is what they earned, and yours is what you earn, and you will not be asked about what they used to do.", "এমনই হচ্ছে অতীতের একটি সম্প্রদায়। তারা যা অর্জন করেছে তার জন্য তারা দায়ী এবং তোমরা যা অর্জন করেছ তার জন্য তোমরা দায়ী। তারা যা কিছু করেছে তার জন্য তোমরা কৈফিয়ত দিবে না।"],
  "2:135": ["And they said, \"Be Jews or Nazarenes and you will be guided.\" Say, \"No — the way of Ibrahim, the upright, and he was not among the associators.\"", "তারা বলে,“পথ-নির্দেশনা পেতে হলে,তোমাদেরকে ইহুদী অথবা খ্রীস্টান হতে হবে।”বল, “আমরা অনুসরণ করি ইব্রাহিমের ধর্ম- একেশ্বরবাদ– সে কখনোই প্রতিমা উপাসক ছিল না”।"],
  "2:136": ["Say, \"We believe in Allah and what was sent down to us, and what was sent down to Ibrahim and Ismail and Ishaq and Yaqub and the tribes, and what was given to Musa and Isa, and what was given to the nabis from their Rabb. We make no division between any of them, and to Allah we are submissive.\"", "বল, “আমরা বিশ্বাস করি আল্লাহতে,এবং যা আমাদের উপর অবতীর্ণ হয়েছে,এবং যা অবতীর্ণ হয়েছে ইব্রাহিম, ইসমাঈল, ইসহাক, ইয়াকুব এবং গোত্রপ্রধানদের উপর; এবং যা দেয়া হয়েছে মুসা ও ঈসাকে,এবং সকল নবীদেরকে তাদের প্রভুর কাছ থেকে। আমরা তাদের কারো মধ্যে কোন রকম পার্থক্য করি না। আমরা একমাত্র তাঁর কাছে আত্ম-সমর্পণকারী।”"],
  "2:137": ["So if they believe in the like of what you believe in, they are guided; but if they turn away, they are only in opposition, and Allah will shield you from them. And Allah is the Hearing, the Knowing.", "যদি তারা তোমাদের মতই বিশ্বাস করে,তাহলে তারা সুপথপ্রাপ্ত। কিন্তু,যদি তারা মুখ ফিরিয়ে নেয়, তাহলে তারা বিপক্ষে অবস্থান নিয়েছে। আল্লাহ তাদের বিরোধিতা থেকে তোমাকে রক্ষা করবেন; তিনি সর্বশ্রোতা,সর্বজ্ঞ।"],
  "2:138": ["The coloring of Allah — and who is better than Allah at coloring? And to Allah we are worshipers.", "এমনই হচ্ছে আল্লাহর নিয়ম, এবং আল্লাহর নিয়মের চেয়ে কার নিয়ম উত্তম? \"আমরা একমাত্র তাঁরই উপাসনা করি\"।"],
  "2:139": ["Say, \"Do you argue with us about Allah when Allah is our Rabb and your Rabb? Ours are our deeds and yours are your deeds, and to Allah we are devoted.\"", "বল, “তোমরা কি আমাদের সাথে আল্লাহ সম্বন্ধে তর্ক করো,যখন তিনি আমাদের প্রভু এবং তোমাদের প্রভু? আমরা আমাদের কাজের জন্য দায়ী এবং তোমরা তোমাদের কাজের জন্য দায়ী। আমরা একমাত্র তাঁর প্রতি নিবেদিত।”"],
  "2:140": ["Or do you say that Ibrahim and Ismail and Ishaq and Yaqub and the tribes were Jews or Nazarenes? Say, \"Are you more knowing, or Allah?\" And who is more unjust than one who hides a testimony in their possession from Allah? And Allah is not unmindful of what you do.", "তোমরা কি বল যে ইব্রাহিম, ইসমাঈল, ইসহাক, ইয়াকুব, এবং গোত্রপ্রধানরা ইহুদী বা খ্রিষ্টান ছিল? বল, \"তোমরা কি আল্লাহর চেয়ে ভালো জান? কে তার চেয়ে অধিক মন্দ যে আল্লাহ থেকে শেখা এক সাক্ষ্য গোপন করে? তোমরা যা কিছু করো আল্লাহ সে সম্পর্কে কখনোই অসচেতন নন।\""],
  "2:141": ["That is a community that has passed on: theirs is what they earned, and yours is what you earn, and you will not be asked about what they used to do.", "সেটা ছিল অতীতের একটি সম্প্রদায়। তারা যা অর্জন করেছে তার জন্য তারা দায়ী এবং তোমরা যা অর্জন করেছ তার জন্য তোমরা দায়ী। যা কিছু তারা করেছিল তার জন্য তোমরা কৈফিয়ত দিবে না।"],
  "2:142": ["The fools among the people will say, \"What turned them from their direction of prayer that they were upon?\" Say, \"To Allah belong the east and the west; Allah guides whomever Allah wills to a straight path.\"", "লোকেদের মধ্যকার নির্বোধরা বলবে, “কেন তারা তাদের ক্বিবলার দিক পরিবর্তন করলো?”বল, “পূর্ব এবং পশ্চিম আল্লাহর; তিনি যাকে ইচ্ছা সরল পথে পরিচালিত করেন।”"],
  "2:143": ["And thus We made you a middle community, so that you may be witnesses over the people and the Rasul may be a witness over you. And We did not make the direction of prayer that you were upon except to know who follows the Rasul from who turns back on their heels — and it was indeed hard except on those Allah guided. And Allah was not to lose your faith. Indeed Allah is to people gentle-merciful, merciful.", "আমরা এভাবে তোমাদেরকে একটি নিরপেক্ষ সম্প্রদায় করেছি,যাতে তোমরা লোকদের মাঝে সাক্ষী হও এবং বার্তাবাহক তোমাদের মাঝে সাক্ষী হয়। আমরা তোমাদের মূল কিবলার দিক পরিবর্তন করেছিলাম শুধু তোমাদের মধ্যে যারা নির্দ্বিধায় বার্তাবাহকের অনুসরণ করে তাদের থেকে যারা পিছু হটে যায় তাদেরকে আলাদা করার জন্য। এটি একটি কঠিন পরীক্ষা ছিল, কিন্তু তাদের জন্য নয় যারা আল্লাহ দ্বারা পথ প্রদর্শিত। আল্লাহ কখনোই তোমাদের উপাসনা বৃথা যেতে দেন না। আল্লাহ মানুষের প্রতি সহানুভূতিশীল, পরম দয়ালু।"],
  "2:144": ["We see you turning your face about in the sky, so We will turn you to a direction of prayer you will be pleased with: turn your face toward the Sacred Mosque; and wherever you are, turn your faces toward it. And those given the Book surely know that it is the truth from their Rabb, and Allah is not unmindful of what they do.", "আমরা তোমাকে দেখেছি (সঠিক দিকের সন্ধানে) আকাশের দিকে ইতঃস্তত মুখ ফেরাতে। আমরা এখন একটি কিবলা নির্দিষ্ট করছি যা তোমাকে সন্তুষ্ট করে। এখন থেকে,তুমি পবিত্র মসজিদের দিকে তোমার মুখ ফেরাবে। তোমরা যেখানে থাক না কেন, তোমরা সকলে তোমাদের মুখ এর দিকে ফেরাবে। যারা পূর্বে ঐশীগ্রন্থ প্রাপ্ত হয়েছিল তারা জানে যে,এটা তাদের প্রভুর পক্ষ থেকে সত্য। তারা যা কিছু করে আল্লাহ সে সম্পর্কে কখনই অসচেতন নন।"],
  "2:145": ["And even if you brought those given the Book every sign, they would not follow your direction of prayer, and you are not to follow their direction of prayer, and some of them are not followers of each other's direction of prayer. And if you followed their desires after the knowledge that came to you, you would surely be among the wrongdoers.", "এমনকি তুমি যদি ঐশীগ্রন্থের অনুসারীদের সব ধরণের অলৌকিক নিদর্শনও দেখা,তারা তোমার কিবলা অনুসরণ করবে না। না তুমি তাদের কিবলা অনুসরণ করবে। এমনকি তারা নিজেরাই একে অন্যের কিবলা অনুসরণ করে না। তোমার কাছে যে জ্ঞান এসেছে,তারপর যদি তুমি তাদের ইচ্ছা মেনে নাও, তুমি সীমালঙ্ঘনকারীদের অন্তর্ভুক্ত হবে।"],
  "2:146": ["Those to whom We gave the Book recognize it as they recognize their own sons. Yet a party of them surely hide the truth while they know.", "যারা ঐশীগ্রন্থ গ্রহণ করেছে তারা এর মধ্যকার সত্য এমনভাবে চিনে নেয় যেমন তারা আপন সন্তানদের চিনে থাকে। এরপরও, তাদের কেউ কেউ জেনে-শুনে সত্য গোপন করে।"],
  "2:147": ["The truth is from your Rabb, so do not be among the doubters.", "এটা তোমার প্রভুর পক্ষ থেকে আসা সত্য; কোন রুপ সন্দেহ পোষণ করো না।"],
  "2:148": ["And for every direction there is one who turns to it; so race ahead to the good things. Wherever you are, Allah will bring you all together. Indeed Allah is over all things able.", "তোমাদের প্রত্যেকেই অনুসরণের একেক দিক বেছে নাও; তোমাদের উচিত সৎকর্মে প্রতিযোগীতা করা। তোমরা যেখানেই থাক না কেন, আল্লাহ তোমাদের সবাইকে একত্রিত করবেন। আল্লাহ সর্বশক্তিমান।"],
  "2:149": ["And from wherever you set out, turn your face toward the Sacred Mosque — and it is indeed the truth from your Rabb. And Allah is not unmindful of what you do.", "তুমি যেখানেই যাও, (সালাতের সময়) তুমি তোমার মুখ পবিত্র মসজিদের দিকে ফেরাবে। এটা তোমার প্রভুর পক্ষ থেকে সত্য। তোমরা সবাই যা কিছু করো আল্লাহ সে সম্পর্কে কখনই অসচেতন নন।"],
  "2:150": ["And from wherever you set out, turn your face toward the Sacred Mosque; and wherever you are, turn your faces toward it, so that there be no argument from the people against you — except from those of them who wronged. So do not fear them, but fear Me, and so that I may complete My favor upon you and so that you may be guided.", "তুমি যেখানেই যাও, (সালাতের সময়) তুমি তোমাদের মুখ পবিত্র মসজিদের দিকে ফেরাবে; তোমরা যেখানেই থাক না কেন, তোমরা (সালাতের সময়) তোমাদের মুখ এর দিকে ফেরাবে। এতে করে তোমাদের বিরুদ্ধে লোকদের কোন তর্ক থাকবে না,শুধু তাদের মধ্যকার সীমালঙ্ঘনকারীদের ছাড়া। তাদেরকে ভয় করো না,বরং আমাকেই ভয় করো। আমি তখন তোমাদের প্রতি আমার আশীর্বাদ সম্পূর্ণ করবো,যাতে তোমরা পথপ্রাপ্ত হতে পার।"],
  "2:151": ["Just as We sent among you a Rasul from you, who recites to you Our signs and purifies you and teaches you the Book and the wisdom, and teaches you what you did not know.", "(আশীর্বাদ) যেমন তোমাদের মধ্য থেকে একজন বার্তাবাহক পাঠানো– তোমাদের কাছে আমাদের প্রকাশণাবলী পাঠ করার জন্য, তোমাদেরকে পরিশুদ্ধ করার জন্য, তোমাদেরকে ঐশীগ্রন্থ ও প্রজ্ঞা শিক্ষা দেবার জন্য, এবং তোমাদেরকে শিক্ষা দেবার জন্য যা তোমরা কখনো জানতে না।"],
  "2:152": ["So remember Me — I will remember you — and be grateful to Me, and do not disbelieve.", "তোমরা আমাকে স্মরণ করো,যাতে আমিও তোমাদের স্মরণ করি,এবং আমার প্রতি কৃতজ্ঞ হও; অকৃতজ্ঞ হইও না।"],
  "2:153": ["O you who believe, seek help in steadfastness and prayer; indeed Allah is with the steadfast.", "হে তোমরা যারা বিশ্বাস করো,দৃঢ়তা ও সংযোগ প্রার্থণা (সালাতের) মাধ্যমে সাহায্য প্রার্থণা করো। আল্লাহ তাদের সাথে আছেন যারা দৃড়তার সাথে অধ্যবসায়ী।"],
  "2:154": ["And do not say of those killed in Allah's way, \"Dead.\" No — they are alive, but you do not perceive.", "আল্লাহর পথে যারা নিহত হয়, তাদের সম্পর্কে বলো না যে,“তারা মৃত”। তারা তাদের প্রভুর কাছে জীবিত, কিন্তু তোমরা বোঝ না।"],
  "2:155": ["And We will surely test you with something of fear and hunger, and loss of wealth and lives and fruits. And give glad tidings to the steadfast,", "আমরা অবশ্যই তোমাদেরকে পরীক্ষা করবো কিছু ভয়, ক্ষুধা,এবং অর্থ, জীবন ও শস্যের ক্ষয়-ক্ষতির মাধ্যমে। সুসংবাদ দাও অবিচলদের।"],
  "2:156": ["those who, when a calamity strikes them, say, \"Indeed we belong to Allah, and indeed to Allah we are returning.\"", "যখন কোন দুঃখ-কষ্ট তাদের উপর আসে,তারা বলে,“আমরা আল্লাহর এবং তাঁর কাছেই আমরা ফিরে যাচ্ছি।”"],
  "2:157": ["Those — upon them are prayers from their Rabb and mercy, and those are the guided.", "এরা তাদের প্রভুর আশীর্বাদ এবং অনুগ্রহের উপযুক্ত হয়েছে। এরাই সুপথপ্রাপ্ত।"],
  "2:158": ["Indeed Safa and Marwah are among Allah's rites, so whoever makes pilgrimage to the House or performs the visitation, there is no blame on them to go around the two. And whoever volunteers good, then Allah is appreciative, knowing.", "সাফা ও মারওয়া টিলাগুলো আল্লাহর জারি করা ধর্মীয় অনুষ্ঠানাদির অন্তর্ভূক্ত। যে কেউ হজ্জ অথবা উমরাহ পালন করে,এ দু’য়ের মাঝের দুরত্ব অতিক্রম করাতে তাদের কোন ভুল নেই। যদি কেউ স্বেচ্ছায় অধিক সৎকর্ম করে,তবে আল্লাহ যথার্থ মূল্যায়নকারী,সর্বজ্ঞ।"],
  "2:159": ["Indeed those who hide what We sent down of clear proofs and guidance after We made it clear to the people in the Book — those Allah curses, and the cursers curse them.", "যারা আমাদের প্রকাশনাবলী এবং পথ-নির্দেশণা গোপন করে,ঐশীগ্রন্থের সেগুলো মানুষের জন্য প্রকাশ করার পর, তারা আল্লাহ কর্তৃক নিন্দিত; তারা সকল বিবেচক দ্বারা নিন্দিত।"],
  "2:160": ["Except those who repent and set right and make clear — those I turn to in forgiveness, and I am the Turning, the Raheem.", "আর যারা অনুশোচনা করে,সংশোধিত হয় এবং ঘোষনা করে,আমি তাদের উদ্ধার করি। আমিই উদ্ধারকারী,পরম দয়ালু।"],
  "2:161": ["Indeed those who kafara and died while they were kafirin — upon them is the curse of Allah and the malakat and the people, all together,", "যারা অবিশ্বাস করে এবং অবিশ্বাসী অবস্থায় মারা যায়, তারা (বিচার দিবসে) নিজেদের উপর টেনে এনেছে আল্লাহর, ফেরেশতাদের এবং সকল মানুষের নিন্দা।"],
  "2:162": ["abiding in it; the punishment will not be lightened for them, nor will they be looked upon.", "তারা সেখানে চিরস্থায়ীভাবে বসবাস করে। তাদের জন্য শাস্তি কখনোই কমানো হয় না,না তাদেরকে অবকাশ দেয়া হয়।"],
  "2:163": ["Your ilah is one ilah: there is no ilah but Allah, the Rahman, the Raheem.", "তোমাদের উপাস্য এক উপাস্য; তিনি ছাড়া আর কোন উপাস্য নেই, পরম করুণাময়, পরম দয়ালু।"],
  "2:164": ["Indeed in the creation of the heavens and the earth, and the alternation of night and day, and the ships that run in the sea with what benefits people, and what Allah sent down from the sky of water and gave life with it to the earth after its death, and scattered in it of every creature, and the directing of the winds, and the clouds subjected between the sky and the earth — are signs for a people who understand.", "আকাশমন্ডলী ও পৃথিবীর সৃষ্টি,রাত ও দিনের পালাবদল, জাহাজসমূহ যা মানুষের উপকারার্থে সাগরে ঘুরে বেড়ায়, পানি যা আল্লাহ আকাশ থেকে বর্ষণ করেন মৃত ভূমিকে পূনর্জীবিত করানোর জন্য এবং এতে সব ধরণের জীবের বিস্তার করতে,বায়ূপ্রবাহ নিয়ন্ত্রনে,এবং আকাশ ও পৃথিবীর মাঝে অবস্থিত মেঘমালায়, যথেষ্ট প্রমাণ রয়েছে মানুষের জন্য যারা অনুধাবন করে।"],
  "2:165": ["And among the people are those who take equals apart from Allah, loving them as Allah is loved. But those who believe are stronger in love for Allah. And if only those who wronged could see, when they see the punishment, that all strength belongs to Allah, and that Allah is severe in punishment.", "এরপরও, কিছু লোক আল্লাহর প্রতিদ্বন্দী করতে উপাস্য স্থাপন করে এবং তাদেরকে এমনভাবে ভালবাসে যেন তারা আল্লাহ। যারা বিশ্বাস করে তারা আল্লাহকেই সবচেয়ে বেশি ভালবাসে। শুধু যদি সীমালঙ্ঘনকারীরা নিজেদের দেখতে পেত যখন তারা শাস্তি অবলোকন করে! তখন তারা উপলব্ধি করবে যে সকল ক্ষমতা কেবল আল্লাহর, এবং আল্লাহর শাস্তি ভয়ানক।"],
  "2:166": ["When those who were followed disavow those who followed them, and they see the punishment, and the means are cut off from them,", "যাদেরকে অনুসরণ করা হতো তারা তাদের অনুসারীদের পরিত্যাগ করবে। তারা শাস্তি দেখবে,এবং তাদের মধ্যকার সকল বন্ধন ছিন্ন হবে।"],
  "2:167": ["and those who followed say, \"If only we had a return, we would disavow them as they disavowed us.\" Thus Allah shows them their deeds as regrets upon them, and they will not be coming out of the Fire.", "যারা অনুসরণ করতো তারা বলবে,“যদি আমরা আরেকবার সুযোগ পাই, আমরা তাদেরকে পরিত্যাগ করবো,যেভাবে তারা এখন আমাদের পরিত্যাগ করেছে।”আল্লাহ এভাবে তাদের কর্মফলকে অনুশোচনা ছাড়া অন্য কিছু হিসেবে দেখান না; তারা কখনো নরক থেকে বের হবে না।"],
  "2:168": ["O people, eat of what is in the earth, lawful and good, and do not follow the footsteps of the satan; indeed, to you he is an open enemy.", "হে লোকসকল, পৃথিবীর উৎপাদিত সকল আইনসম্মত ও ভাল জিনিস হতে খাও এবং শয়তানের পদাঙ্ক অনুসরণ করো না। সে তোমাদের সবচেয়ে ঘোর শত্রু।"],
  "2:169": ["He commands you only evil and obscenity, and that you say of Allah what you do not know.", "সে তোমাদের আদেশ দেয় শুধুমাত্র মন্দ ও অধর্ম করতে,এবং আল্লাহ সম্পর্কে এমন কথা বলতে যা তোমরা জানো না।"],
  "2:170": ["And when it is said to them, \"Follow what Allah sent down,\" they say, \"No, we follow what we found our fathers upon.\" Even if their fathers understood nothing and were not guided?", "যখন তাদেরকে বলা হয়, “অনুসরণ করো যা আল্লাহ এখানে প্রকাশ করেছেন, ”তারা বলে,“আমরা শুধু অনুসরণ করি যা আমাদের পিতামাতাদের করতে দেখেছি।”আর যদি তাদের পিতামাতারা না বুঝে থাকে,এবং সুপথপ্রাপ্ত না হয়?"],
  "2:171": ["And the likeness of those who disbelieve is the likeness of one who calls out to what hears nothing but a cry and a shout: deaf, dumb, unseeing — so they do not understand.", "এমন অবিশ্বাসীদের উদাহরণ হলো সেই তোতা পাখি,যেগুলো না বুঝে পুনঃরাবৃত্তি করে,যে শব্দ ও ডাক এগুলো শোনে। বধির, বোবা,ও অন্ধ; এরা বুঝতে পারে না।"],
  "2:172": ["O you who believe, eat of the good things We provided you, and be grateful to Allah, if it is Allah you worship.", "হে তোমরা যারা বিশ্বাস করো,তোমাদের জন্য আমাদের দেয়া ভালো জিনিস থেকে খাও এবং আল্লাহর প্রতি কৃতজ্ঞ হও, যদি তোমরা একমাত্র তাঁর উপাসনা করো।"],
  "2:173": ["Forbidden to you are only carrion, and blood, and the flesh of the pig, and what has been dedicated to other than Allah. But whoever is compelled, without craving or transgressing, there is no sin upon them. Indeed Allah is forgiving, merciful.", "তিনি তোমাদের খাওয়ার জন্য নিষিদ্ধ করেন শুধু সে সমস্ত প্রানী যেগুলো নিজে নিজেই মারা যায় (মানুষের হস্তক্ষেপ ছাড়া),রক্ত, শুকরের মাংস এবং আল্লাহ ছাড়া অন্য কারো প্রতি উৎসর্গকৃত প্রানী। যদি কেউ (এগুলো খেতে) বাধ্য হয়, দুষ্টবুদ্ধি বা ইচ্ছার বশবর্তী না হয়ে,সে কোন পাপ করে না। আল্লাহ ক্ষমাকারী,পরম দয়ালু।"],
  "2:174": ["Indeed those who hide what Allah sent down of the Book and buy with it a small price — those eat into their bellies nothing but fire. And Allah will not speak to them on the Day of Rising, nor purify them, and for them is a painful punishment.", "যারা আল্লাহর প্রকাশনাবলী গোপন করে,সস্তা পার্থিব অর্জনের বিনিময়ে,তারা আগুন ছাড়া অন্যকিছু দিয়ে তাদের পেট ভরায় না। আল্লাহ পুনঃরুত্থান দিবসে তাদের সাথে কথা বলবেন না,না তিনি তাদের পরিশুদ্ধ করবেন। তারা নিজেদের উপর এক যন্ত্রনাদায়ক শাস্তি টেনে এনেছে।"],
  "2:175": ["Those are the ones who bought straying for guidance, and punishment for forgiveness. So how sabir they are for the Fire!", "এরা তারা যারা পথ-নির্দেশনার পরিবর্তে পথভ্রষ্টতা,এবং ক্ষমার পরিবর্তে শাস্তি বেছে নিয়েছে। ফলশ্রুতিতে,তাদেরকে সহ্য করতে হবে নরক।"],
  "2:176": ["That is because Allah sent down the Book with the truth, and those who differed about the Book are in far opposition.", "এর কারণ এই যে,আল্লাহ এই ঐশীগ্রন্থ প্রকাশ করেছেন, সত্য সহকারে,এবং যারা ঐশীগ্রন্থে বিবাদ করে তারাই ঘোরতম বিরোধী।"],
  "2:177": ["Goodness is not that you turn your faces toward the east or the west. Rather, goodness is of one who believes in Allah and the Last Day and the malakat and the Book and the nabis, and gives wealth, despite love of it, to near kin and orphans and the needy and the wayfarer and the askers, and for the freeing of necks; and keeps up the prayer and gives the alms; and those who fulfill their pledge when they pledge, and the steadfast in hardship and harm and the time of hardship — those are the ones who are true, and those are the reverent.", "পূর্ব বা পশ্চিমে তোমাদের মুখ ফেরানোই সৎকর্ম নয়। তারা সৎকর্মশীল যারা বিশ্বাস করে আল্লাহতে,শেষ দিনে,ফেরেশতাদের, ঐশীগ্রন্থে এবং নবীদের; এবং তারা সানন্দে অর্থ দান করে আত্মীয়-স্বজনদের, এতীমদের, অভাবীদের, ভ্রমণরত বহিরাগতদের, ভিক্ষুকদের এবং দাস মুক্তির জন্য; এবং তারা সংযোগ প্রার্থণা (সালাত) পালন করে এবং বাধ্যতামূলক দান (যাকাত) দেয়; এবং তারা তাদের কথা রাখে যখন তারা কোন প্রতিশ্রুতি দেয়; এবং তারা নির্যাতন, কষ্ট এবং যুদ্ধের মুখে অবিচলতার সাথে অধ্যবসায়ী থাকে। এরাই সত্যবাদী; এরাই সৎকর্মশীল।"],
  "2:178": ["O you who believe, requital is written upon you for the slain: the free for the free, the slave for the slave, the female for the female. Whoever is pardoned anything by their brother, then follow up with kindness and deliver to him with goodness. That is a lightening from your Rabb and a mercy. Whoever transgresses after that, for them is a painful punishment.", "হে তোমরা যারা বিশ্বাস করো,সমতা হলো আইন যা তোমাদের জন্য জারি করা হলো যখন হত্যার বিচার করো– স্বাধীন ব্যক্তির জন্য স্বাধীন ব্যক্তি,দাসের জন্য দাস, নারীর জন্য নারী। যদি কেউ নিহত ব্যক্তির নিকটতম আত্মীয়ের ক্ষমা পায়, তাদেরকে কৃতজ্ঞতামূলক জবাব দিতে হবে এবং একটি ন্যায্য ক্ষতিপূরণ পরিশোধ করতে হবে। এটি তোমাদের প্রভুর পক্ষ থেকে একটি সহজীকরণ এবং অনুগ্রহ। যে কেউ এর বাইরে সীমালঙ্ঘন করে সে নিজের উপর যন্ত্রণাদায়ক শাস্তি টেনে আনে।"],
  "2:179": ["And in requital for you is life, O people of understanding, so that you may be reverent.", "সমতা হলো তোমাদের জন্য একটি জীবন রক্ষাকারী আইন, হে তোমরা যারা বুদ্ধিমত্তার অধিকারী,যাতে তোমরা সৎকর্মশীল হতে পারো।"],
  "2:180": ["It is written upon you, when death attends any of you, if they leave behind good: a bequest for the parents and the near kin with kindness — a duty upon the reverent.", "এই বিধান জারি করা হলো যে যখন মৃত্যু নিকটবর্তী হয়, তখন তোমরা একটি উইল লিখবে তোমাদের পিতামাতা ও আত্মীয়দের উপকারার্থে,ন্যায়সঙ্গতভাবে। এটা সৎকর্মশীলদের উপর দ্বায়িত্ব।"],
  "2:181": ["Whoever alters it after hearing it, its sin is only upon those who alter it. Indeed Allah is hearing, knowing.", "যদি কেউ কোন উইল পরিবর্তন করে যা সে শুনেছিল, এই পরিবর্তনের পাপ তাদের উপর পড়বে যারা এরুপ পরিবর্তনের জন্য দায়ী। আল্লাহ সর্বশ্রোতা,সবজান্তা।"],
  "2:182": ["Whoever fears from the testator a tilt or a sin and sets things right between them — there is no sin upon them. Indeed Allah is forgiving, merciful.", "যদি কেউ উইলকারীর দিক থেকে ঘোর অন্যায় কিংবা পক্ষপাত লক্ষ্য করে এবং উইলে ন্যায়বিচার ফিরিয়ে আনার লক্ষ্যে সংশোধনমূলক পদক্ষেপ গ্রহণ করে,তবে সে কোনো পাপ করে না। আল্লাহ ক্ষমাশীল, পরম দয়ালু।"],
  "2:183": ["O you who believe, fasting is written upon you as it was written upon those before you, so that you may be reverent.", "হে তোমরা যারা বিশ্বাস করো,তোমাদের জন্য উপবাস পালনের বিধান জারি করা হলো,যেরুপ তোমাদের পূর্ববর্তীদের উপর এই বিধান জারি করা হয়েছিল, যাতে তোমরা পরিত্রাণ লাভ করতে পারো।"],
  "2:184": ["Counted days; but whoever among you is sick or on a journey — a number of other days. And upon those who can bear it, a ransom of feeding a needy person. Whoever volunteers good, it is better for them. And that you fast is better for you, if only you knew.", "নির্দিষ্ট দিনসমূহ (উপবাসের জন্য নির্ধারিত); যদি কেউ অসুস্থ হয় কিংবা ভ্রমণে থাকে,তবে সমান সংখ্যক অন্য দিন প্রতিস্থাপন করতে পারে। যাদের জন্য উপবাস করা অত্যন্ত কষ্টকর, তারা উপবাস ভঙ্গের প্রত্যেক দিনের বদলে একজন গরীব লোক খাওয়াবে। যদি কেউ স্বেচ্ছায় কিছু (অধিক সৎকর্ম) করে,এটা উত্তম। কিন্তু উপবাসই তোমাদের জন্য সর্বোত্তম, যদি শুধু তোমরা জানতে।"],
  "2:185": ["The month of Ramadan, in which the Recitation was sent down, as guidance for people and clear proofs of the guidance and the criterion. So whoever of you witnesses the month, let them fast it; and whoever is sick or on a journey — a number of other days. Allah intends for you ease and does not intend for you hardship, and so that you complete the number and magnify Allah for what Allah guided you to, and so that you may be grateful.", "রমজানই হলো সে মাস যখন কুরআন অবতীর্ণ হয়েছিল, যা মানুষের জন্য প্রদান করে পথ-নির্দেশণা,সুস্পষ্ট শিক্ষা,এবং বিধান গ্রন্থ। তোমাদের মধ্যে যারা এই মাস প্রত্যক্ষ করবে তারা তাতে উপবাস পালন করবে। যারা অসুস্থ কিংবা ভ্রমণে থাকে,তারা এর পরিবর্তে সমান সংখ্যক অন্য দিন প্রতিস্থাপন করতে পারে। আল্লাহ তোমাদের জন্য সহজ করতে চান, কঠিন নয়, যাতে তোমরা তোমাদের দ্বায়িত্বসমূহ সম্পন্ন করতে পারো এবং তোমাদের সুপথে পরিচালনার জন্য আল্লাহর মহিমা ঘোষণা করতে পারো,এবং যাতে তোমাদের কৃতজ্ঞতা প্রকাশ করতে পারো।"],
  "2:186": ["And when My servants ask you about Me — indeed I am near. I answer the call of the caller when they call Me. So let them answer Me and believe in Me, so that they may be guided aright.", "যখন আমার বান্দারা তোমাকে আমার সম্পর্কে জিজ্ঞেস করে,আমি সর্বদাই নিকটে। আমি তাদের প্রার্থণার জবাব দেই যখন তারা আমার কাছে প্রার্থণা করে। লোকেরা আমার প্রতি সাঁড়া দেবে এবং আমাকে বিশ্বাস করবে,সুপথ পাওয়ার জন্য।"],
  "2:187": ["Permitted to you on the night of the fast is intimacy with your nisa: they are a garment for you, and you are a garment for them. Allah knew that you betrayed yourselves, so Allah turned to you in forgiveness and passed over you. So now be intimate with them and seek what Allah wrote for you; and eat and drink until the white thread becomes distinct to you from the black thread of dawn. Then complete the fast until nightfall, and do not be intimate with them while you are cleaving to the mosques. Those are Allah's limits, so do not approach them. Thus Allah makes Allah's signs clear to people, so that they may be reverent.", "উপবাসের রাতে তোমাদের জন্য তোমাদের স্ত্রীদের সাথে সহবাস অনুমোদিত। তারা তোমাদের গোপনীয়তা রক্ষাকারী এবং তোমরা তাদের গোপনীয়তা রক্ষাকারী। আল্লাহ জানতেন যে তোমরা তোমাদের আত্মার সাথে প্রতারণা করতে এবং তিনি তোমাদের পাপমোচন করেছেন ও তোমাদেরকে ক্ষমা করেছেন। এখন থেকে,আল্লাহ তোমাদের জন্য যা অনুমোদন করেছেন তা অন্বেষণ করতে তোমরা তাদের সাথে সহবাস করতে পারো। তোমরা পানাহার করতে পারো যতক্ষণ না রাতের কালো রেখা থেকে আলোর সাদা রেখা পৃথক করা যায় ভোর বেলায়। তারপর, তোমরা সূর্যাস্ত পর্যন্ত উপবাস পালন করবে। (রমজানের শেষ দশ দিনে) সহবাস নিষিদ্ধ যদি তোমরা মসজিদে অবস্থানের সিদ্ধান্ত নাও। এগুলো আল্লাহর আইন; তোমরা এগুলোর সীমালঙ্ঘন করবে না। এভাবে আল্লাহ তাঁর প্রকাশনাবলী লোকদের জন্য সুস্পষ্ট করেন, যাতে তারা পরিত্রাণ লাভ করতে পারে।"],
  "2:188": ["And do not consume your wealth among yourselves in falsehood, and offer it to the judges so as to consume a portion of people's wealth sinfully while you know.", "তোমরা একে অপরের অর্থ অনৈতিকভাবে আত্মসাৎ করবে না,না তোমরা কর্মকর্তাদের ঘুষ দেবে অন্যদেরকে তাদের কিছু অধিকার থেকে অনৈতিকভাবে বঞ্চিত করতে,যখন তোমরা জানো।"],
  "2:189": ["They ask you about the crescents. Say, \"They are appointed times for the people and for the pilgrimage.\" And goodness is not that you come to the houses from their backs; rather, goodness is of the reverent. So come to the houses by their doors, and be reverent to Allah, so that you may attain success.", "তারা তোমাকে চাঁদের পর্যায়সমূহ সম্পর্কে জিজ্ঞেস করে! বল, “এগুলো লোকদের জন্য একটি সময় নিরুপণের পদ্ধতি প্রদান করে এবং হজ্জের সময় নির্ধারণ করে।”কাজের কথায় না এসে কথা ঘুরানোর মধ্যে ন্যায়নিষ্ঠতা নেই,  ন্যায়নিষ্ঠতা অর্জিত হয় ঐশিক আদেশ মেনে চলা এবং সরলতা অবলম্বনের মাধ্যমে। তোমরা আল্লাহকে মান্য করবে,যাতে তোমরা সফল হতে পারো।"],
  "2:190": ["And fight in Allah's way those who fight you, but do not transgress. Indeed Allah does not love the transgressors.", "তোমরা আল্লাহর উদ্দেশ্যে যুদ্ধ করতে পারো তাদের বিরুদ্ধে যারা তোমাদের আক্রমণ করে, কিন্তু প্রথম আক্রমণ করো না। আল্লাহ আগ্রাসনকারীদের ভালোবাসেন না।"],
  "2:191": ["And kill them wherever you overtake them, and drive them out from where they drove you out; for transgression is worse than killing. And do not fight them at the Sacred Mosque until they fight you in it; but if they fight you, then kill them. Such is the recompense of the kafirin.", "তোমরা তাদেরকে হত্যা করতে পারো যারা তোমাদের বিরুদ্ধে যুদ্ধ শুরু করে,এবং তোমরা তাদেরকে উচ্ছেদ করতে পারো,যেখান থেকে তারা তোমাদেরকে উচ্ছেদ করেছিল। অত্যাচার হত্যার চেয়ে অধিকতর মন্দ। পবিত্র মসজিদে (মসজিদ) তাদের সাথে লড়াই করবে না,যদি না তারা তোমাদের সেখানে আক্রমণ করে। যদি তারা তোমাদের আক্রমণ করে,তাদেরকে তোমরা হত্যা করতে পারো। এটা ঐসব অবিশ্বাসীদের জন্য উচিত শাস্তি।"],
  "2:192": ["But if they cease, then Allah is forgiving, merciful.", "যদি তারা বিরত থাকে,তাহলে আল্লাহ ক্ষমাকারী,পরম দয়ালু।"],
  "2:193": ["And fight them until there is no more transgression and the way is for Allah entirely. But if they cease, then there is no aggression except against the wrongdoers.", "এছাড়াও, তোমরা তাদের সাথে লড়াই করতে পারো,অত্যাচার নির্মূল এবং স্বাধীনভাবে আল্লাহর উপাসনা করার জন্য। যদি তারা বিরত থাকে,তোমরা আগ্রাসী হবে না। শুধুমাত্র আগ্রাসনকারীদের বিরুদ্ধে আগ্রাসন অনুমোদিত।"],
  "2:194": ["The sacred month is for the sacred month, and the sacred things are requital. Whoever transgresses against you, transgress against them in the like of what they transgressed against you. And be reverent to Allah, and know that Allah is with the reverent.", "পবিত্র মাসগুলোতে,একটি সমতুল্য জবাবের দ্বারা আগ্রসন মোকাবেলা করা যেতে পারে। যদি তারা তোমাদের আক্রমন করে,একটি ন্যায়সঙ্গত শাস্তি আরোপের দ্বারা তার জবাব দিতে পারো। তোমরা আল্লাহকে মান্য করবে এবং জানো যে আল্লাহ সৎকর্মশীলদের সাথে আছেন।"],
  "2:195": ["And spend in Allah's way, and do not throw yourselves with your own hands into destruction. And do good; indeed Allah loves the doers of good.", "তোমরা আল্লাহর উদ্দেশ্যে ব্যয় করবে; তোমরা নিজেদের হাতে নিজেদেরকে ধ্বংসের মুখে ঠেলে দিও না। তোমরা দানশীল হবে,আল্লাহ দানশীলদের ভালবাসেন।"],
  "2:196": ["And complete the pilgrimage and the visitation for Allah. But if you are confined, then whatever is easy of the offering. And do not shave your heads until the offering reaches its place. Whoever among you is sick or has harm from their head — then a ransom of fasting or charity or a rite. Then when you are secure, whoever enjoys the visitation until the pilgrimage — whatever is easy of the offering. Whoever cannot find it, then a fast of three days during the pilgrimage and seven when you return; that is ten complete. That is for whoever does not have their people present at the Sacred Mosque. And be reverent to Allah, and know that Allah is severe in punishment.", "তোমরা আল্লাহর জন্য হজ্ব এবং ওমরাহের পরিপূর্ণ আনুষ্ঠানিকতা পালন করবে। যদি তোমরা বাধাপ্রাপ্ত হও, তোমরা একটি উৎসর্গ পাঠাবে,এবং তোমাদের উৎসর্গ গন্তব্যে না পৌঁছানো পর্যন্ত মাথা মুন্ডন শুরু করো না। যদি তোমরা অসুস্থ হও, অথবা কোন মাথার আঘাতে ভোগে থাকো (এবং তোমাদের চুল কাটতেই হয়),তোমরা প্রায়শ্চিত্ত করবে উপবাসের মাধ্যমে,অথবা দান করে,অথবা অন্য কোন ধরনের উপাসনার দ্বারা। সাধারণ হজ্বের সময়, তোমরা যদি উমরাহ্‌ এবং হজ্বের মধ্যে ইহরাম (পবিত্রতার) অবস্থা ভঙ্গ করো,তোমরা একটি পশু উৎসর্গের মাধ্যমে প্রায়শ্চিত্ত করবে। যদি তোমাদের এর সামর্থ না থাকে,তাহলে তোমরা হজ্বের সময় তিন (দিন) উপবাস পালন করবে এবং বাড়ি ফিরে সাত (দিন) - এতে দশ (দিন) পূর্ন হয় - যদি না তোমরা পবিত্র মসজিদে বাস করো। তোমরা আল্লাহকে মান্য করবে এবং জানো যে আল্লাহ শাস্তি প্রয়োগে কঠোর।"],
  "2:197": ["The pilgrimage is in well-known months; whoever charges themselves with the pilgrimage in them — no intimacy, and no transgression, and no dispute in the pilgrimage. And whatever good you do, Allah knows it. And take provision, for the best provision is reverence. And be reverent to Me, O people of understanding.", "হজ্জ তীর্থযাত্রা পালন করতে হবে নির্ধারিত মাসগুলোতে। যে কেউ হজ্ব পালনের উদ্দেশে বের হয়, শারীরিক মিলন, খারাপ ব্যবহার এবং তর্ক করা থেকে বিরত থাকবে,হজ্বের পুরো সময় জুঁড়ে। তোমরা যে পূন্যই করো,আল্লাহ সে সম্পর্কে সম্পূর্ণ অবগত। তোমরা যখন (তীর্থ) যাত্রার জন্য পাথেয় প্রস্তুত করো,সবচেয়ে উত্তম পাথেয় হল আল্লাহ ভীতি। তোমরা আমাকে মান্য করবে,ওহে তোমরা যারা জ্ঞানবুদ্ধির অধিকারী।"],
  "2:198": ["There is no blame on you to seek bounty from your Rabb. And when you pour down from Arafat, remember Allah at the sacred landmark, and remember Allah as Allah guided you, though before that you were among the strayers.", "তোমাদের প্রভুর নিকট থেকে (বাণিজ্যের মাধ্যমে) জীবিকা অন্বেষণ করে তোমরা কোন ভুল করো না। তোমরা যখন আরাফাত থেকে সারিবদ্ধভাবে রওয়ানা হবে,তোমরা পবিত্র স্থানে (মুজদালিফাতে) আল্লাহকে স্মরণ করবে,তোমার তাঁকে স্মরণ করবে তোমাদেরকে পথ প্রদর্শণ করার জন্য; এর আগে তোমরা পথভ্রষ্ট হয়ে গিয়েছিলে।‘"],
  "2:199": ["Then pour forth from where the people pour forth, and seek Allah's forgiveness. Indeed Allah is forgiving, merciful.", "তোমরা একত্রে সারিবদ্ধভাবে রওয়ানা হবে বাকী লোকদের সাথে যারা সারিবদ্ধভাবে রওয়ানা হয়, এবং আল্লাহর কাছে ক্ষমা প্রার্থনা করবে। আল্লাহ ক্ষমাশীল, পরম দয়ালু।"],
  "2:200": ["And when you have completed your rites, remember Allah as you remembered your fathers — or with stronger remembrance. Among the people are those who say, \"Our Rabb, give us in the nearer life,\" and for them in the Last there is no share.", "তোমরা তোমাদের আনুষ্ঠানিকতা সম্পূর্ণ করার পর, তোমরা আল্লাহর স্মরণ করতে থাকবে যেভাবে তোমরা তোমাদের নিজেদের পিতামাতাকে স্মরণ করো,বা তার চেয়েও উত্তম রূপে। কিছু লোক বলবে,“আমাদের প্রভু,আমাদেরকে এই দুনিয়াতে দিন\",যখন পরকালে কোন অংশ থাকে না।"],
  "2:201": ["And among them are those who say, \"Our Rabb, give us in the nearer life a good, and in the Last a good, and shield us from the punishment of the Fire.\"", "অন্যরা বলবে,\"আমাদের প্রভু,আমাদেরকে এই দুনিয়াতে কল্যাণ দান করুন, এবং পরকালেও কল্যাণ দান করুন, এবং আমাদেরকে নরকের শাস্তি থেকে রক্ষা করুন।\""],
  "2:202": ["Those — for them is a portion of what they earned, and Allah is swift in reckoning.", "এদের প্রত্যেকেই পাবে সেই অংশ যা তারা অর্জন করেছে। আল্লাহ হিসাব গ্রহণে সবচেয়ে দক্ষ।"],
  "2:203": ["And remember Allah in counted days. Whoever hastens on in two days — no sin upon them; and whoever delays — no sin upon them, for the reverent. And be reverent to Allah, and know that to Allah you will be gathered.", "তোমরা আল্লাহকে স্মরণ করবে কিছু সংখ্যক দিন (মিনাতে); যে কেউ ত্বরা করে তা দুই দিনে সম্পন্ন করে সে কোন পাপ করে না এবং যে কেউ বেশি সময় অবস্থান করে সে কোন পাপ করে না,যতক্ষণ ন্যায়পরায়নতা বজায় রাখা হয়। তোমরা আল্লাহকে মান্য করবে এবং জানো যে তাঁর সামনেই তোমরা একত্রিত হবে।"],
  "2:204": ["And among the people is the one whose speech impresses you in the nearer life, and who calls Allah to witness what is in their heart, while they are the fiercest of contenders.", "লোকদের মধ্যে,কেউ তোমাকে এই দুনিয়া সম্পর্কে তার কথা দিয়ে মোহিত করতে পারে,এবং এমনকি তার গভীরতম চিন্তার সাক্ষী হবার জন্য আল্লাহকে আহবান করতে পারে,যদিও সে একজন সবচেয়ে ঘোর বিরোধী।"],
  "2:205": ["And when they turn away, they strive in the earth to corrupt it and destroy the tillage and the offspring. And Allah does not love corruption.", "সে প্রস্থান করা মাত্রই, পৃথিবীতে ঘুরে বেড়াঁয় দূর্নীতি করে,সম্পত্তি এবং জীবন ধ্বংস করে। আল্লাহ দূর্নীতিকে ভালবাসেন না।"],
  "2:206": ["And when it is said to them, \"Be reverent to Allah,\" arrogance in sin seizes them. So Hell is enough for them — and miserable is the resting place.", "যখন তাকে বলা হয়, \"আল্লাহকে মেনে চল\",সে ঔদ্ধতের সাথে ক্ষুব্ধ হয়। ফলস্বরুপ, তার একমাত্র গন্তব্য নরক, কতই না দুর্বিষহ আবাস।"],
  "2:207": ["And among the people is one who sells their soul, seeking Allah's good pleasure, and Allah is gentle-merciful to the servants.", "অতঃপর রয়েছে তারা,যারা আল্লাহর প্রতি দায়িত্ব পালনে নিজেদের জীবন উৎসর্গ করে। আল্লাহ এরকম উপাসনাকারীদের প্রতি মেহেরবান।"],
  "2:208": ["O you who believe, enter into submission, all together, and do not follow the footsteps of the satan; indeed, to you he is an open enemy.", "হে যারা বিশ্বাস করো,তোমরা পরিপূর্ণভাবে আত্মসমর্পণ করবে; শয়তানের পদাঙ্ক অনুসরণ করো না,কারন সে তোমাদের সবচেয়ে ঘোর শত্রু।"],
  "2:209": ["But if you slip after the clear proofs have come to you, then know that Allah is mighty, wise.", "যদি তোমরা পিছপা হও, তোমাদের কাছে সুস্পষ্ট প্রমাণ আসার পর, তবে জেনে নাও যে আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "2:210": ["Do they wait for anything except that Allah come to them in canopies of cloud, and the malakat, and the matter be decided? And to Allah all matters are returned.", "তারা কি অপেক্ষা করছে যে কখন আল্লাহ নিজে পুঞ্জিভূত মেঘের মাঝে তাদের কাছে আসবেন, ফেরেশতাদের সাথে? যখন তা ঘটবে,পুরো ব্যাপারটাই শেষ হয়ে যাবে,এবং আল্লাহর নিকট সবকিছু ফিরে যাবে।"],
  "2:211": ["Ask the Children of Israel how many a clear sign We gave them. And whoever alters Allah's favor after it came to them — indeed Allah is severe in punishment.", "ইসরাইলের সন্তানদের জিজ্ঞেস করো- তাদেরকে আমরা কতগুলো প্রগাঢ় নিদর্শন দেখিয়েছিলাম! যারা তাদের উপর অর্পিত আল্লাহর আশীর্বাদকে উপেক্ষা করে,আল্লাহ তাদের জন্য শাস্তি আরোপে সবচেয়ে কঠোর।"],
  "2:212": ["Made attractive for those who kafara is the nearer life, and they mock those who believe. But those who were reverent will be above them on the Day of Rising. And Allah provides whomever Allah wills without reckoning.", "অবিশ্বাসীদের চোখে এই পার্থিব জীবন সুসজ্জিত করে দেয়া হয়েছে,এবং তারা তাদেরকে উপহাস করে যারা বিশ্বাস করে। তবে,পুনরুত্থানের দিন সৎকর্মশীলরা তাদের চেয়ে অনেক উপরে থাকবে। আল্লাহ যাকে ইচ্ছা আশীর্বাদ করেন, সীমাহীন ভাবে।"],
  "2:213": ["People were one community; then Allah raised up the nabis as bringers of glad tidings and warners, and sent down with them the Book with the truth, to judge between people in what they differed about it. And none differed about it except those given it, after the clear proofs came to them, out of envy between them. So Allah guided those who believed to the truth of what they differed about it, by Allah's leave. And Allah guides whomever Allah wills to a straight path.", "লোকেরা একই সম্প্রদায়ভূক্ত ছিল যখন আল্লাহ নবীদের পাঠালেন সুসংবাদ বহনকারী,একই সাথে সতর্ককারী হিসেবে। তিনি তাদের সাথে অবতীর্ণ করেছিলেন ঐশীগ্রন্থ, যা সত্য বহনকারী,লোকদের মাঝে তাদের বিতর্কের বিচার করার জন্য। দুঃখজনক ভাবে,যারা ঐশীগ্রন্থ গ্রহণ করেছিল তারাই নতুন কোন ঐশীগ্রন্থ প্রত্যাখ্যান করেছে,তাদেরকে দেয়া সুস্পষ্ট প্রমান সত্তেও। এটা তাদের পক্ষ থেকে হিংসার কারনে। আল্লাহ তাদের পথ-প্রদর্শন করেন যারা বিশ্বাস করে সত্যের দিকে যা অন্য সকলের দ্বারা বিতর্কিত, আল্লাহর ইচ্ছানুসারে। আল্লাহ যাকে ইচ্ছা সরল পথে পথ-প্রদর্শন করেন।"],
  "2:214": ["Or did you suppose you would enter the garden when there had not yet come to you the like of those who passed before you? Hardship and harm touched them, and they were shaken until the Rasul and those who believed with him said, \"When is Allah's help?\" Truly, Allah's help is near.", "তোমরা কি স্বর্গে প্রবেশ করার আশা করো পরিক্ষীত হওয়া ছাড়াই যেমন করা হয়েছিল তোমাদের পূর্ববর্তীদের? তারা পরিক্ষীত হয়েছিল কষ্ট এবং প্রতিকূল পরিস্থিতির মধ্য দিয়ে,এবং শিহরিত হয়েছিল/ধাক্কা খেয়েছিল, যতক্ষণ না বার্তাবাহক এবং তার সঙ্গে যারা বিশ্বাস করেছিল তারা বলেছিল, \"কোথায় আল্লাহর বিজয়?”আল্লাহর বিজয় নিকটেই।"],
  "2:215": ["They ask you what to spend. Say, \"Whatever good you spend is for parents and near kin and orphans and the needy and the wayfarer. And whatever good you do, indeed Allah is knowing of it.\"", "তারা তোমাকে জিজ্ঞেস করে দান সম্পর্কে,বল, \"তোমরা যে দান করো তা যাবে পিতা-মাতা,আত্মীয়-স্বজন, এতিম, গরীব এবং ভ্রমণরত ভীনদেশীদের জন্য।”যেকোন ভাল কাজ তোমরা করো,আল্লাহ সে সম্পর্কে সম্পূর্ণ অবগত।"],
  "2:216": ["Fighting is written upon you though it is hateful to you. And perhaps you hate a thing while it is good for you, and perhaps you love a thing while it is evil for you. And Allah knows, while you do not know.", "যুদ্ধ তোমাদের উপর আরোপিত হতে পারে,যদিও তোমরা তা অপছন্দ করো। কিন্ত হয়তো তোমরা কোন কিছু অপছন্দ করছো যা তোমাদের জন্য ভাল, এবং হয়তো তোমরা কোন কিছু পছন্দ করছো যা তোমাদের জন্য মন্দ। আল্লাহ জানেন যখন তোমরা জানো না।"],
  "2:217": ["They ask you about fighting in the sacred month. Say, \"Fighting in it is grave, and barring from Allah's way and disbelief in Allah and the Sacred Mosque, and driving out its people from it, is graver with Allah. And transgression is graver than killing.\" They will not cease fighting you until they turn you back from your way, if they can. Whoever of you turns back from their way and dies while committing kufr — those, their deeds are void in the nearer life and the Last, and those are the companions of the Fire; they abide in it forever.", "তারা তোমাকে পবিত্র মাসসমূহ এবং তাতে যুদ্ধ করা সম্পর্কে জিজ্ঞাসা করে; বল, “তাতে যুদ্ধ করা একটি অপবিত্র কাজ। কিন্ত, আল্লাহর পথে প্রতিবন্ধকতা সৃষ্টি করা,এবং অবিশ্বাস করা তাঁকে ও পবিত্র মসজিদের পবিত্রতায়,এবং এর লোকেদের উচ্ছেদ করা,আল্লাহর দৃষ্টিতে আরও বড় অপবিত্র কাজ। অত্যাচার হত্যা থেকে অধিকতর মন্দ”। তারা সব সময় তোমাদের সাথে লড়াই করবে তোমাদেরকে তোমাদের ধর্ম থেকে ফিরিয়ে দিতে,যদি তারা পারে। তোমাদের মধ্যে যারা তাদের ধর্ম থেকে ফিরে যাবে,এবং অবিশ্বাসী হিসেবে মৃত্যুবরণ করবে,তারা বিনষ্ট করে ফেলেছে তাদের কাজ এই জীবনে এবং পরকালে। এরাই নরকের বাসিন্দা,যেখানে তারা চিরকাল বসবাস করবে।"],
  "2:218": ["Indeed those who believed, and those who emigrated and strove in Allah's way — those hope for Allah's mercy. And Allah is forgiving, merciful.", "যারা বিশ্বাস করে,এবং যারা দেশান্তরী হয় এবং আল্লাহর উদ্দেশ্য সংগ্রাম করে,তারা আল্লাহর করুণা পাবার যোগ্য হয়েছে। আল্লাহ ক্ষমাশীল, পরম করুণাময়।"],
  "2:219": ["They ask you about wine and gaming. Say, \"In both is grave sin, and benefit for people, but their sin is greater than their benefit.\" And they ask you what to spend. Say, \"The surplus.\" Thus Allah makes the signs clear to you, so that you may reflect", "তারা তোমাকে মাদকদ্রব্য এবং জুয়া সম্পর্কে জিজ্ঞাসা করে; বল, “এগুলোর মধ্যে রয়েছে মহাপাপ এবং লোকেদের জন্য কিছু উপকার। কিন্তু,এগুলোর পাপ উপকার থেকে অনেক বেশি”। তারা তোমাকে আরও জিজ্ঞাসা করে কি দান করবে; বল, “অতিরিক্তটা”। আল্লাহ এভাবে প্রকাশনাবলী তোমাদের জন্য সুস্পষ্ট করেন, যাতে তোমরা অনুধাবন করো,"],
  "2:220": ["in the nearer life and the Last. And they ask you about the orphans. Say, \"Setting right for them is best.\" And if you mix with them, they are your brothers. And Allah knows the corrupter from the setter-right. Had Allah willed, Allah could have put you in hardship. Indeed Allah is mighty, wise.", "এই জীবন এবং পরকালের বিষয়ে। এবং তারা তোমাকে এতিমদের সম্পর্কে জিজ্ঞেস করেঃ বল, \"তোমরা তাদের জন্য যা করতে পারো তন্মধ্যে তাদেরকে সৎকর্মশীল হিসেবে বড় করাই সর্বোত্তম। তোমরা যদি তাদের সম্পত্তির সাথে তোমাদের সম্পদ মিশিয়ে ফেল, তবে তোমরা তাদের সাথে পরিবারের সদস্যের মতো ব্যবহার করবে”। আল্লাহ সৎকর্মশীল এবং মন্দদের জানেন। আল্লাহ যদি চাইতেন, তবে তিনি তোমাদের উপর কঠোরতর নিয়ম আরোপ করতে পারতেন। আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "2:221": ["And do not marry the associating nisa until they believe; a believing bondimra'a is better than an imra'a who associates, even if she impresses you. And do not marry the associating men until they believe; a believing slave is better than an associator, even if he impresses you. Those call to the Fire, and Allah calls to the garden and forgiveness, by Allah's leave. And Allah makes the signs clear to people, so that they may remember.", "প্রতিমা উপাসক নারীদের বিয়ে করো না যদি না তারা বিশ্বাস করে; একজন বিশ্বাসী নারী একজন প্রতিমা উপাসক নারীর চেয়ে উত্তম, যদিও তোমরা তাকে পছন্দ করো। না তোমরা তোমাদের কন্যাদের প্রতিমা উপাসক পুরুষের সাথে বিয়ে দেবে,যদি না তারা বিশ্বাস করে। একজন বিশ্বাসী পুরুষ একজন প্রতিমা উপাসক পুরুষের চেয়ে উত্তম যদিও তোমরা তাকে পছন্দ করো। এরা নরকের দিকে আহবান করে,যখন আল্লাহ স্বর্গ এবং ক্ষমাশীলতার দিকে আহবান করেন, যেমন তিনি ইচ্ছা করেন। তিনি লোকদের জন্য তাঁর প্রত্যাদেশাবলী সুস্পষ্ট করেন, যাতে তারা সতর্ক হতে পারে।"],
  "2:222": ["And they ask you about the monthly course. Say, \"It is harm, so keep away from the nisa during the monthly course, and do not approach them until they are purified. When they have purified themselves, then come to them from where Allah commanded you.\" Indeed Allah loves the ones who turn back and loves the ones who purify themselves.", "তারা তোমাকে রজঃস্রাব সম্পর্কে জিজ্ঞাসা করেঃ বল, “এটা ক্ষতিকারক; তোমরা রজঃস্রাবের সময় স্ত্রীদের সাথে যৌন সহবাস এড়িয়ে চলবে; তাদের সান্নিধ্যে যেও না যতক্ষণ না তারা এটা থেকে মুক্ত হয়। যখন তারা এটা থেকে মুক্ত হয়, তোমরা তাদের সাথে সহবাস করতে পার, আল্লাহর পরিকল্পিত পদ্ধতিতে। আল্লাহ অনুশোচনাকারীদের ভালোবাসেন, এবং তিনি তাদের ভালোবাসেন যারা পরিষ্কার।"],
  "2:223": ["Your nisa are tillage for you, so come to your tillage as you wish, and send ahead for yourselves. And be reverent to Allah, and know that you will meet Allah. And give glad tidings to the muminin.", "তোমাদের স্ত্রীরা তোমাদের বীজের ধারক। তাই, তোমরা এই বিশেষ সুবিধা উপভোগ করতে পারো যেভাবে তোমরা পছন্দ করো,যতক্ষণ তোমরা ন্যায়পরায়ণতা বজায় রাখো। তোমরা আল্লাহকে মান্য করবে,এবং জেনে রাখো যে তোমরা তাঁর সাথে সাক্ষাৎ করবে। বিশ্বাসীদের সুসংবাদ দাও।"],
  "2:224": ["And do not make Allah an excuse in your oaths against being good, and reverent, and making things right between the people. And Allah is hearing, knowing.", "তোমাদের নৈমিত্তিক শপথে আল্লাহর নামকে উপলক্ষ্য বানিয়ো না,যাতে তোমরা সৎকর্মশীল, সৎকর্মশীল প্রতীয়মান হতে পারো,অথবা মানুষের মাঝে বিশ্বাসযোগ্যতা অর্জন করতে পারো। আল্লাহ শ্রোতা,জ্ঞাতা।"],
  "2:225": ["Allah does not take you to task for idle talk in your oaths, but takes you to task for what your hearts earned. And Allah is forgiving, forbearing.", "শুধুমাত্র শপথ উচ্চারণের কারনে আল্লাহ তোমাদের দায়ী করেন না; তিনি তোমাদের দায়ী করেন তোমাদের গভীরতম অভিপ্রায়ের জন্য। আল্লাহ ক্ষমাশীল, সহিষূ।"],
  "2:226": ["For those who vow off their nisa, a wait of four months; then if they turn back, indeed Allah is forgiving, merciful.", "যারা তাদের স্ত্রীদের সাথে বিবাহ-বিচ্ছেদ করতে মনস্থ করে তারা চার মাস অপেক্ষা করবে (শান্ত হতে); তারা যদি তাদের মন পরিবর্তন করে এবং পূনঃর্মিলিত হয়, তবে আল্লাহ ক্ষমাশীল, দয়ালু।"],
  "2:227": ["And if they resolve on divorce, then indeed Allah is hearing, knowing.", "তারা যদি বিবাহ-বিচ্ছেদের মধ্য দিয়ে যায়, তবে আল্লাহ শ্রোতা,জ্ঞাতা।"],
  "2:228": ["The divorced nisa wait by themselves for three monthly courses, and it is not lawful for them to hide what Allah created in their wombs, if they believe in Allah and the Last Day. And their husbands are more entitled to take them back in that, if they want setting right. And for them is the like of what is upon them, with kindness, and for men over them is a degree. And Allah is mighty, wise.", "বিবাহ-বিচ্ছেদ প্রাপ্ত নারী তিন রজঃস্রাব পর্যন্ত অপেক্ষা করবে (অন্য পুরুষকে বিয়ে করার পূর্বে)। এটা তাদের জন্য আইনসম্মত নয়, যা আল্লাহ তাদের গর্ভে সৃষ্টি করেন তা গোপন করা,যদি তারা আল্লাহ এবং পরকালে বিশ্বাস করে। (গর্ভাবস্থার ক্ষেত্রে) স্বামীর ইচ্ছা স্ত্রীর ইচ্ছার উপর স্থান পাবে,যদি সে তাকে পুনরায় বিয়ে করতে চায়। নারীর অধিকার রয়েছে,পাশাপাশি রয়েছে দায়িত্ব, সমানভাবে। এভাবে,স্বামীর ইচ্ছা প্রাধান্য পায় (গর্ভাবস্থার ক্ষেত্রে)। আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "2:229": ["Divorce is twice; then either kind holding or kind release. And it is not lawful for you to take anything of what you gave them, unless the two fear that they cannot uphold Allah's limits. If you fear that the two cannot uphold Allah's limits, there is no blame on the two in what she ransoms herself with. Those are Allah's limits, so do not transgress them. And whoever transgresses Allah's limits — those are the wrongdoers.", "বিবাহ-বিচ্ছেদ দু’বার বাতিল করা যেতে পারে। বিবাহ-বিচ্ছেদ প্রাপ্ত নারী একই বাড়িতে সৌহার্দ্যপূর্ণভাবে বাস করতে,অথবা সৌহার্দ্যপূর্ণভাবে ছেড়ে চলে যেতে অনুমোদিত হবে। এটা স্বামীর জন্য আইনসম্মত নয় যে যা সে তাকে দিয়েছে এর কোনকিছু ফিরিয়ে নেয়া। কিন্তু,দম্পত্তির আশংকা হতে পারে যে তারা হয়তো আল্লাহর আইনের সীমালঙ্ঘন করবে। যদি কোন আশংকা থাকে যে তারা আল্লাহর আইনের সীমালঙ্ঘন করবে,তারা কোন ভুল করে না যদি স্ত্রী স্বেচ্ছায় ফিরিয়ে দেয় যা কিছু সে পছন্দ করে। এগুলো আল্লাহর আইন, এগুলোর সীমালঙ্ঘন করো না। যারা আল্লাহর আইনের সীমালঙ্ঘন করে তারা অবিবেচক।"],
  "2:230": ["So if he divorces her, she is not lawful for him after that until she marries a spouse other than him. And if he divorces her, there is no blame on the two that they turn back to each other, if they think that they can uphold Allah's limits. And those are Allah's limits, which Allah makes clear for a people who know.", "সে যদি তার (স্ত্রীর) সাথে (তৃতীয়বারের মতো) বিবাহ-বিচ্ছেদ করে,তাকে পুনরায় বিয়ে করা তার জন্য বে-আইনি,যদি না সে অন্য পুরুষকে বিয়ে করে নেয়,এরপর সে (পুরুষ) তার সাথে বিবাহ-বিচ্ছেদ করে। প্রথম স্বামী তখন তাকে পুনরায় বিয়ে করতে পারে,যতক্ষণ পর্যন্ত তারা আল্লাহর আইন মান্য করে। এগুলো আল্লাহর আইন; তিনি এগুলো ব্যাখ্যা করেন তাদের জন্য যারা জানে।"],
  "2:231": ["And when you divorce nisa and they reach their term, then either hold them with kindness or release them with kindness, and do not hold them in harm to transgress. Whoever does that has wronged themselves. And do not take Allah's signs in mockery, and remember Allah's favor upon you and what was sent down upon you of the Book and the wisdom, with which Allah admonishes you. And be reverent to Allah, and know that Allah is knowing of all things.", "যদি তোমরা স্ত্রীদের সাথে বিবাহ-বিচ্ছেদ করো,যখন তারা অন্তর্বর্তী সময় (তিন রজঃস্রাব) সম্পূর্ণ করে,তোমরা একই বাড়িতে তাদেরকে সৌহার্দ্যপূর্ণভাবে বাস করতে দেবে,অথবা সৌহার্দ্যপূর্ণভাবে তাদেরকে চলে যেতে দেবে। তাদের ইচ্ছার বিরুদ্ধে তাদেরকে থাকার জন্য বল  প্রয়োগ করো না,প্রতিশোধ হিসাবে। যে কেউ এই কাজ করে সে নিজের আত্মার ক্ষতি করে। আল্লাহর প্রকাশনাবলিকে নিরর্থকভাবে নিও না। তোমাদের প্রতি আল্লাহর আশীর্বাদ স্মরণ করো,এবং এটা যে তিনি তোমাদের কাছে অবতীর্ণ করেছেন ঐশীগ্রন্থ এবং জ্ঞান, তোমাদের আলোকিত করার জন্য। তোমরা আল্লাহকে মান্য করবে,এবং জানো যে আল্লাহ সবকিছু সম্পর্কে সচেতন।"],
  "2:232": ["And when you divorce nisa and they reach their term, do not hinder them from marrying their husbands when the two are pleased with each other in kindness. That is admonished with, for whoever among you believes in Allah and the Last Day. That is purer for you and cleaner. And Allah knows, while you do not know.", "যদি তোমরা স্ত্রীদের সাথে বিবাহ-বিচ্ছেদ করো,যখন তারা অন্তর্বর্তী সময় সম্পূর্ণ করে,তাদেরকে তাদের স্বামীদের পুনরায় বিয়ে করতে বাধা দিও না,যদি তারা সৌহার্দ্যপূর্ণভাবে পুনঃর্মিলিত হয়। এটা তোমাদের মধ্যে তাদের দ্বারা মান্য হবে যারা আল্লাহ এবং শেষ দিনে বিশ্বাস করে। এটা তোমাদের জন্য পবিত্র, এবং অধিক ধর্মনিষ্ঠ। আল্লাহ জানেন, যখন তোমরা জানো না।"],
  "2:233": ["The mothers nurse their children two full years, for whoever wants to complete the nursing. And upon the one to whom the child is born is their provision and clothing, with kindness. No self is charged beyond its capacity. No harm shall be done to a mother by her child, nor to a child by its mother. And upon the heir is the like of that. And if the two want weaning, by mutual consent and consultation between them, there is no blame on the two. And if you want to seek nursing for your children, there is no blame on you when you deliver what you gave, with kindness. And be reverent to Allah, and know that Allah is all-seeing of what you do.", "বিবাহ বিচ্ছেদকৃত মা,তাদের শিশুদের পূর্ণ দুই বছর স্তন্যপান করাবে,যদি পিতা এরকম ইচ্ছা করে। পিতা ন্যায়সঙ্গত ভাবে মায়ের খাদ্য ও বস্ত্রের সংস্থান করবে। কাউকে তার ক্ষমতার অতিরিক্ত দায়িত্ব চাপানো যাবে না। কোন মা তার শিশুর কারণে ক্ষতিগ্রস্ত হবে না,না কোন পিতা ক্ষতিগ্রস্ত হবে তার শিশুর কারণে। (যদি পিতা মারা যায়),তার উত্তরাধিকারী এই দায়িত্বসমূহ গ্রহণ করবে। যদি শিশুর পিতা-মাতা আলাদা হওয়ার ব্যপারে পরস্পর সম্মত হয়, যথোচিত পরামর্শের পর, এরকম করে তারা কোন ভুল করে না। তোমরা দুধ-মা ভাড়া করে কোন ভুল করো না,যতক্ষণ তোমরা তাদেরকে ন্যায়সঙ্গত পারিশ্রমিক দাও। তোমরা আল্লাহকে মান্য করবে,এবং জান যে আল্লাহ সবকিছুর দ্রষ্টা যা তোমরা করো।"],
  "2:234": ["And those of you who are taken in death and leave behind spouses — the nisa wait by themselves four months and ten. When they reach their term, there is no blame on you in what they do with themselves with kindness. And Allah is aware of what you do.", "যারা মারা যায় এবং স্ত্রীদের ছেঁড়ে যায়,তাদের বিধবারা চার মাস এবং দশ দিন অপেক্ষা করবে (তারা পুনরায় বিয়ে করার আগে)। যখন তারা অন্তর্বর্তী সময় পূর্ণ করে,যে কোন ন্যায়সঙ্গত বিষয় তারা করতে ইচ্ছা করে,তাদেরকে তা করতে দিয়ে তোমরা ভুল করো না। আল্লাহ সম্পূর্ণ জ্ঞাত সে সবকিছু সম্পর্কে যা তোমরা করো।"],
  "2:235": ["There is no blame on you in what you offer of proposal to nisa, or what you conceal in yourselves. Allah knows that you will remember them. But do not promise them secretly, except that you say a kind word. And do not resolve on the knot of marriage until the waiting-term reaches its term. And know that Allah knows what is in yourselves, so beware of Allah. And know that Allah is forgiving, forbearing.", "তোমরা কোন পাপ করো না তোমাদের সাথে সেই নারীদের বিবাহের বাগদান ঘোষণা করে,অথবা তা গোপন রেখে। আল্লাহ জানেন যে তোমরা তাদের ব্যাপারে চিন্তা করবে। তাদের সাথে গোপনে সাক্ষাৎ করো না,যদি না আলোচনা করার জন্য তোমাদের কোন ন্যায়সঙ্গত বিষয় থাকে। বিয়ে সুসম্পূর্ণ করো না যতক্ষণ না তাদের অন্তর্বর্তী সময় পূর্ণ হয়। তোমাদের জানা উচিৎ যে,আল্লাহ জানেন তোমাদের গভীরতম চিন্তা,এবং তাঁকে মান্য করো। তোমাদের জানা উচিৎ যে,আল্লাহ ক্ষমাশীল, সহিষ্ণু।"],
  "2:236": ["There is no blame on you if you divorce nisa when you have not touched them or appointed for them an appointed portion. And provide for them — upon the ample according to their means, and upon the constrained according to their means — a provision with kindness, a duty upon the doers of good.", "তোমরা কোন ভুল করো না নারীদের সাথে বিবাহ-বিচ্ছেদ করে তাদেরকে স্পর্শ করার আগে,অথবা তাদের জন্য দেন-মোহর নির্ধারণ করার আগে। এক্ষেত্রে,তোমরা তাদেরকে ক্ষতিপূরণ দিবে- ধনিরা তাদের সামর্থ অনুসারে এবং দরিদ্ররা তাদের সামর্থ অনুসারে- একটি ন্যায়সঙ্গত ক্ষতিপূরণ। এটা সৎকর্মশীলদের উপর একটি দায়িত্ব।"],
  "2:237": ["And if you divorce them before you have touched them, but you have appointed for them an appointed portion, then half of what you appointed — unless they waive it, or the one in whose hand is the knot of marriage waives it. And that you waive is nearer to reverence. And do not forget the grace between you. Indeed Allah is all-seeing of what you do.", "যদি তোমরা তাদের সাথে বিবাহ-বিচ্ছেদ করো তাদেরকে স্পর্শ করার আগে,কিন্তু তোমরা তাদের জন্য দেন-মোহর নির্ধারণ করার পর, তবে ক্ষতিপূরণটি দেন-মোহরের অর্ধেক হবে,যদি না তারা স্বেচ্ছায় তাদের অধিকার ছেঁড়ে দেয়, অথবা বিবাহ-বিচ্ছেদ হবার জন্য দায়ী পক্ষটি দেন-মোহরটি ছেঁড়ে দিতে পছন্দ করে। ক্ষতিস্বীকার করা সতকর্মশীলতার নিকটবর্তী। তোমরা তোমাদের মধ্যে সৌহার্দ্যপূর্ন সম্পর্ক বজায় রাখবে। তোমরা যা কিছু করো আল্লাহ সবকিছুর দ্রষ্টা।"],
  "2:238": ["Guard the prayers, and the middle prayer, and stand up devoutly for Allah.", "তোমরা নিয়মিত সংযোগ প্রার্থনাসমূহ পালন করবে,বিশেষ করে মধ্যবর্তী প্রার্থনা,এবং নিজেদেরকে পুরোপুরি আল্লাহর নিকট উৎসর্গ করবে।"],
  "2:239": ["And if you fear, then on foot or riding; then when you are secure, remember Allah as Allah taught you what you did not know.", "অস্বাভাবিক পরিস্থিতিতে,তোমরা প্রার্থনা করতে পারো হাঁটা অথবা আরোহী অবস্থায়। যখন তোমরা নিরাপদ হও, তোমরা আল্লাহকে স্মরন করবে যেভাবে তিনি তোমাদের শিক্ষিয়েছিলেন যা তোমরা কখনোই জানতে না।"],
  "2:240": ["And those of you who are taken in death and leave behind spouses — a bequest for their spouses, provision for a year without driving out. But if they leave, there is no blame on you in what they do with themselves of kindness. And Allah is mighty, wise.", "যারা মারা যায় এবং স্ত্রীদের ছেড়ে যায়, একটি উইল তাদের স্ত্রীদের জন্য এক বছরের ভরণপোষণের ব্যবস্থা করবে,তাদেরকে একই বাড়িতে থাকতে দিয়ে। যদি তারা চলে যায়, তোমরা কোন পাপ করো না তারা যা করতে চায় তা করতে দিয়ে,যতক্ষন পর্যন্ত ন্যায়পরায়ণতা বজায় রাখা হয়। আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "2:241": ["And for the divorced nisa is provision with kindness — a duty upon the reverent.", "বিবাহ বিচ্ছেদকৃত নারীদেরকেও প্রদান করতে হবে,ন্যায়সঙ্গতভাবে। এটা সৎকর্মশীলদের উপর একটি দায়িত্ব।"],
  "2:242": ["Thus Allah makes Allah's signs clear to you, so that you may understand.", "আল্লাহ এভাবে তাঁর প্রকাশনাবলী তোমাদের জন্য ব্যাখ্যা করেন, যাতে তোমরা বুঝতে পারো।"],
  "2:243": ["Have you not seen those who went out from their homes by the thousands, wary of death? Allah said to them, \"Die,\" then brought them to life. Indeed Allah is possessor of favor over people, but most people are not grateful.", "তোমরা কি তাদের লক্ষ্য করেছ যারা তাদের ঘর থেকে পালিয়েছিল- যদিও তারা সংখ্যায় ছিল হাজার হাজার– মৃত্যু ভয়ে? আল্লাহ তাদের বললেন, “মরে যাও, ”এরপর তাদেরকে পুনরায় জীবিত করলেন। আল্লাহ মানুষের প্রতি তাঁর অনুগ্রহ বর্ষণ করেন, কিন্তু অধিকাংশ মানুষই অকৃতজ্ঞ।"],
  "2:244": ["And fight in Allah's way, and know that Allah is hearing, knowing.", "তোমরা আল্লাহর উদ্দেশ্যে যুদ্ধ করবে,এবং জানো যে আল্লাহ শ্রোতা,জ্ঞাতা।"],
  "2:245": ["Who is it that will lend Allah a goodly loan, so that Allah may multiply it for them many fold? And Allah draws in and spreads out, and to Allah you will be returned.", "কে আল্লাহকে সৎকর্ম ধার দিবে, এর চেয়ে বহুগুন বেশি ফেরত পেতে? আল্লাহ সেই সত্ত্বা  যিনি দেন এবং দেয়া থেকে বিরত থাকেন আর তাঁর কাছেই তোমরা ফিরে যাবে।"],
  "2:246": ["Have you not seen the chiefs of the Children of Israel after Musa, when they said to a Nabi of theirs, \"Raise up for us a king; we will fight in Allah's way.\" He said, \"Perhaps, if fighting is written upon you, you would not fight?\" They said, \"Why should we not fight in Allah's way when we have been driven out from our homes and our children?\" But when fighting was written upon them, they turned away, except a few of them. And Allah is knowing of the wrongdoers.", "তুমি কি মুসার পর ইসরাইলের নেতাদের লক্ষ্য করেছ? তারা তাদের নবীকে/ বলেছিল, \"তুমি যদি আমাদেরকে নেতৃত্ব দেয়ার জন্য একজন রাজা নিযুক্ত করো,আমরা আল্লাহর উদ্দেশ্যে লড়াই করবো। তিনি বলেছিলেন, \"এটাই কি তোমাদের উদ্দেশ্য যে,যদি তোমাদের জন্য লড়াই করার আদেশ জারি করা হয়, তোমরা লড়াই করবে না? তারা বলেছিল, \"কেন আমরা আল্লাহর উদ্দেশ্যে লড়াই করবো না,যখন আমরা আমাদের বাড়ি এবং সন্তানদের থেকে বঞ্চিত হয়েছি? \"এরপরও, যখন তাদের জন্য লড়াই করার আদেশ জারি করা হল, তারা মুখ ফিরিয়ে নিল, অল্প কয়েকজন ছাড়া। আল্লাহ সীমালঙ্ঘনকারীদের সম্পর্কে সচেতন।"],
  "2:247": ["And their Nabi said to them, \"Allah has raised up Talut as a king for you.\" They said, \"How can kingship be his over us when we have more right to kingship than him, and he has not been given ample wealth?\" He said, \"Allah has chosen him over you and increased him abundantly in knowledge and in body. And Allah gives Allah's kingdom to whomever Allah wills, and Allah is all-ample, knowing.\"", "তাদের নবী তাদেরকে বলেছিল, \"আল্লাহ তালুতকে তোমাদের রাজা হবার জন্য নির্ধারন করেছেন\"। তারা বলেছিল, কিভাবে সে আমাদের উপর রাজপদ পেতে পারে যখন আমরা তার চেয়ে বেশি রাজপদের যোগ্য; সে এমনকি ধনীও নয়? সে বলেছিল, \"আল্লাহ তোমাদের উপর তাকে পছন্দ করেছেন, এবং তাকে জ্ঞানে ও শারীরিকভাবে বেশি প্রাচুর্যতা দিয়ে সৌভাগ্যশালী করেছেন।”আল্লাহ তাঁর রাজপদ যাকে ইচ্ছা প্রদান করেন। আল্লাহ দানশীল, সর্বজ্ঞ।"],
  "2:248": ["And their Nabi said to them, \"The sign of his kingship is that the chest will come to you, in which is tranquility from your Rabb and a remnant of what the family of Musa and the family of Harun left behind; the malakat will carry it. Indeed in that is a sign for you, if you are muminin.\"", "তাদের নবী তাদেরকে বলেছিল, “তার রাজপদের চিহ্ন হলো এই যে,প্রতিশ্রুতির সিন্দুক তোমাদের কাছে ফিরিয়ে দেয়া হবে,বয়ে আনবে তোমাদের প্রভুর কাছ থেকে নিশ্চয়তা,এবং মুসার পরিবারের লোকদের ও হারুনের পরিবারের লোকদের পরিত্যক্ত সংরক্ষিত স্মৃতিচিহ্নসমূহ। এটি ফেরেশতাদের দ্বারা বয়ে আনা হবে। এটি তোমাদের জন্য একটি বিশ্বাসযোগ্য নিদর্শন হওয়া উচিৎ,যদি তোমরা সত্যিই বিশ্বাসী হয়ে থাকো।"],
  "2:249": ["And when Talut set out with the hosts, he said, \"Allah is testing you with a river: whoever drinks from it is not of me, and whoever does not taste it is of me — except one who scoops a scoop in their hand.\" But they drank from it, except a few of them. And when he crossed it, he and those who believed with him, they said, \"We have no strength today against Jalut and his hosts.\" Those who expected to meet Allah said, \"How many a small band has overcome a great band, by Allah's leave! And Allah is with the steadfast.\"", "যখন তালুত সৈন্যবাহিনীর নেতৃত্ব গ্রহন করলো,সে বলেছিল, “আল্লাহ তোমাদের একটি জলপ্রবাহ দ্বারা পরীক্ষা করছেন। যেকেউ এটি থেকে পান করবে সে আমার সাথে নয় – যদি না তা শুধু এক চুমুক হয় -শুধুমাত্র যারা এর স্বাদ নেবে না তারা আমার সাথে আছে”। তারা সেখান থেকে পান করলো,তাদের অল্প কয়েকজন ছাড়া। যখন সে তা পার হল তাদের সাথে যারা বিশ্বাস করেছিল, তারা বলেছিল, “এখন আমরা জালুত এবং তার সৈন্যবাহিনীর মুখোমুখি হওয়ার শক্তি হারিয়েছি”। যারা আল্লাহর সাথে সাক্ষাতের ব্যাপারে সচেতন ছিল তারা বলেছিল, “আল্লাহর সম্মতিক্রমে অনেক ছোট সৈন্যবাহিনী বড় সৈন্যবাহিনীকে পরাজিত করেছে। আল্লাহ তাদের সাথে আছেন যারা দৃড়তার সাথে অধ্যবসায়ী।"],
  "2:250": ["And when they came forth against Jalut and his hosts, they said, \"Our Rabb, pour steadfastness upon us, steady our feet, and help us against the committing kufr people.\"", "যখন তারা জালুত এবং তার সৈন্যবাহিনীর মুখোমুখি হলো,তারা প্রার্থনা করেছিল, “আমাদের প্রভু,আমাদের ধৈর্য্য দান করুন, আমাদের অবস্থানকে সুদৃড় করুন, এবং অবিশ্বাসী লোকদের বিরুদ্ধে আমাদের সহায়তা করুন।"],
  "2:251": ["So they routed them, by Allah's leave, and Dawud killed Jalut. And Allah gave him the kingdom and the wisdom, and taught him of what Allah wills. And if Allah did not push back people by means of others, the earth would be corrupted; but Allah is possessor of favor over the worlds.", "তারা আল্লাহর সম্মতিক্রমে তাদেরকে পরাজিত করেছিল, এবং দাউদ জালুতকে হত্যা করল। আল্লাহ তাকে রাজপদ এবং জ্ঞান দিলেন, এবং তাকে শেখালেন, যেমন তাঁর ইচ্ছা। কিছু লোকের প্রতি অন্যদের বিরুদ্ধে আল্লাহর সহায়তা যদি না থাকত, পৃথিবীতে বিশৃঙ্খলা ছড়িয়ে পড়ত। কিন্তু আল্লাহ মানুষের প্রতি তাঁর অনুগ্রহ বর্ষণ করেন।"],
  "2:252": ["Those are Allah's signs, which We recite to you with the truth, and you are indeed among the Rasuls.", "এগুলো আল্লাহর প্রকাশনাবলী। আমরা এগুলো তোমার মাধ্যমে আবৃত্তি করি,সত্যতার সাথে,কারন তুমি বার্তাবাহকদের একজন।"],
  "2:253": ["Those are the Rasuls: We favored some of them over others. Among them are those Allah spoke to, and Allah raised some of them by degrees. And We gave Isa son of Maryam clear proofs and strengthened him with the Holy Spirit. And had Allah willed, those after them would not have fought each other after the clear proofs came to them; but they differed, and among them were those who believed and those who kafara. And had Allah willed, they would not have fought each other, but Allah does what Allah wills.", "এই বার্তাবাহকরা; আমরা তাদের কয়েকজনকে অন্যদের থেকে বেশি অনুগ্রহ করেছি। উদাহরন স্বরূপ, একজনের সাথে আল্লাহ কথা বলেছিলেন, এবং আমরা তাদের কয়েকজনকে উচ্চতর পদে উন্নিত করেছিলাম। এবং আমরা মরিয়ম পুত্র ঈসাকে দিয়েছিলাম প্রগাঢ় অলৌকিক নিদর্শনসমূহ এবং তাকে পবিত্র আত্মার দ্বারা সহায়তা করেছিলাম। আল্লাহ যদি চাইতেন, তাদের অনুসারীরা পরস্পর লড়াই করত না,তাদের কাছে পরিষ্কার প্রমান এসে যাবার পর। অথচ, তারা নিজেদের মধ্যে বিবাদ করলো,তাদের কেউ কেউ বিশ্বাস করলো,এবং কেউ কেউ অবিশ্বাস করলো। আল্লাহ যদি চাইতেন, তারা লড়াই করতো না। সবকিছুই আল্লাহর ইচ্ছা অনুসারে হয়।"],
  "2:254": ["O you who believe, spend of what We provided you before a day comes in which there is no trade, and no bosom friendship, and no intercession. And the kafirin — they are the wrongdoers.", "হে তোমরা যারা বিশ্বাস করো,তোমাদেরকে দেয়া আমাদের জীবিকা থেকে তোমরা দান করবে,সে দিন আসার আগে যেখানে না আছে কোন বাণিজ্য, না স্বজনপ্রীতি,এবং না কোন সুপারিশ। অবিশ্বাসীরা অবিবেচক।"],
  "2:255": ["Allah — there is no ilah but Allah, the Living, the Upholder. Neither slumber nor sleep overtakes Allah. To Allah belongs whatever is in the heavens and whatever is in the earth. Who is it that can intercede with Allah except by Allah's leave? Allah knows what is before them and what is behind them, and they encompass nothing of Allah's knowledge except what Allah wills. Allah's seat encompasses the heavens and the earth, and preserving them does not burden Allah. And Allah is the Most High, the Most Great.", "আল্লাহঃ তাঁর পাশে অন্য কোন উপাস্য নেই, জীবিত, চিরস্থায়ী। কখনো ক্ষণিকের অসচেতনতা অথবা তন্দ্রা তাঁকে স্পর্শ করে না। আকাশমন্ডলীতে যা কিছু আছে এবং পৃথিবীতে যা কিছু আছে,সব তাঁর। কে তাঁর কাছে সুপারিশ করতে পারে,তাঁর ইচ্ছানুসারে ছাড়া? তিনি জানেন তাদের অতীত এবং তাদের ভবিষ্যৎ। তিনি যেমন ইচ্ছা করেন তা ব্যতিত, কেউ কোন জ্ঞান অর্জন করে না। তাঁর রাজত্ব পরিবেষ্টন করে আছে আকাশমন্ডলী এবং পৃথিবীকে,এবং এগুলোর পরিচালনা তাঁকে কখনো ভারগ্রস্থ করে না। তিনি সর্বোচ্চ, মহান।"],
  "2:256": ["There is no compulsion in the way: the course has become clear from the misguidance. So whoever disbelieves in the false arbiter and believes in Allah has grasped the firmest handhold, with no breaking of it. And Allah is hearing, knowing.", "ধর্মে জোর-জবরদস্তি থাকবে না। সঠিক পথ এখন ভুল পথ থেকে আলাদা। যেকেউ শয়তানকে প্রত্যাখ্যান করে এবং আল্লাহতে বিশ্বাস করে,সে আঁকড়ে ধরলো সবচেয়ে শক্তিশালী বন্ধন;যা কখনও ভেঙ্গে যায় না। আল্লাহ শ্রোতা,সর্বজ্ঞ।"],
  "2:257": ["Allah is the protecting friend of those who believe, bringing them out from darkness into light. And those who kafara — their protecting friends are the false arbiters, bringing them out from light into darkness. Those are the companions of the Fire; they abide in it forever.", "আল্লাহ তাদের প্রভু যারা বিশ্বাস করে; তিনি তাদেরকে অন্ধকার থেকে বের করে আলোয় পরিচালিত করেন। আর তারা যারা অবিশ্বাস করে,তাদের প্রভুরা হচ্ছে তাদের উপাস্যরা ; তারা তাদেরকে আলো থেকে বের করে অন্ধকারে পরিচালিত করে- এরাই হবে নরকের বাসিন্দা; এতে তারা চিরকাল বাস করবে।"],
  "2:258": ["Have you not seen the one who argued with Ibrahim about his Rabb, because Allah gave him the kingdom? When Ibrahim said, \"My Rabb is the one who gives life and causes death,\" he said, \"I give life and cause death.\" Ibrahim said, \"Indeed Allah brings the sun from the east, so bring it from the west.\" So the kafir was stunned. And Allah does not guide the wrongdoing people.", "তুমি কি তাকে লক্ষ্য করেছ যে ইব্রাহীমের সাথে তর্ক করেছিল তার প্রভুর ব্যাপারে,যদিও আল্লাহ তাকে রাজ পদ দান করেছিলেন? ইব্রাহীম বলল, “আমার প্রভু জীবন ও মৃত্যু প্রদান করেন”। সে বলল, “আমি জীবন ও মৃত্যু প্রদান করি”। ইব্রাহীম বলল, “আল্লাহ সূর্যকে পূর্ব দিক থেকে উদিত করেন, তুমি কি একে পশ্চিম দিক থেকে উদিত করতে পারো”? সেই অবিশ্বাসী হতবুদ্ধ হয়ে গেল। আল্লাহ দুষ্টদেরকে পথ প্রদর্শন করেন না।"],
  "2:259": ["Or like the one who passed by a town while it had collapsed on its raised frames. He said, \"How will Allah give life to this after its death?\" So Allah made him die a hundred years, then raised him. Allah said, \"How long did you tarry?\" He said, \"I tarried a day or part of a day.\" Allah said, \"No, you tarried a hundred years. So look at your food and your drink — it has not changed. And look at your donkey. And so that We may make you a sign for the people, look at the bones, how We raise them up and then clothe them with flesh.\" And when it became clear to him, he said, \"I know that Allah is over all things able.\"", "সেই ব্যাক্তির বিষয়ে ভেবে দেখো যে একটি ভূতুড়ে শহরের পাশ দিয়ে যাচ্ছিলো এবং অবাক হলো,“কেমন করে আল্লাহ একে জীবিত করতে পারেন এর মৃত্যু ঘটার পর? আল্লাহ তখন তাকে একশ বছরের জন্য মৃত অবস্থায় রাখলেন, এরপর তাকে পুনর্জীবিত করলেন। তিনি বললেন, “তুমি কতকাল এখানে অবস্থান করেছ?”সে বলল, “আমি এখানে এক দিন, অথবা এক দিনের কিছু অংশ অবস্থান করেছি।”তিনি বললেন, “না! তুমি এখানে একশো বছর ছিলে। তারপরও, তোমার খাদ্য ও পানীয়ের দিকে তাকাও; সেগুলো নষ্ট হয়নি। তোমার গাঁধার দিকে তাকাও- আমরা এভাবে তোমাকে মানুষের জন্য একটি  শিক্ষামূলক উদাহরণ  করেছি। এখন, লক্ষ্য করো,কিভাবে আমরা হাড়গুলোকে নির্মাণ করি,এরপর সেগুলোকে মাংস দিয়ে ঢেকে দেই”। যখন সে উপলব্ধি করলো কি ঘটেছে,সে বলল, “এখন আমি জানি যে আল্লাহ সর্বশক্তিমান”।"],
  "2:260": ["And when Ibrahim said, \"Rabb, show me how You give life to the dead.\" Allah said, \"Have you not believed?\" He said, \"Yes, but so that my heart may be settled.\" Allah said, \"Then take four birds and incline them to yourself, then place on every hill a portion of them, then call them — they will come to you swiftly. And know that Allah is mighty, wise.\"", "ইব্রাহীম বলল, “আমার প্রভু,আমাকে দেখান কিভাবে আপনি মৃতকে পুনর্জীবিত করেন”। তিনি বললেন, “তুমি কি বিশ্বাস করো না?”সে বলল, “হ্যাঁ,কিন্তু আমি আমার হৃদয়কে পুনরায় আশ্বস্ত করতে চাই”। তিনি বললেন, “চারটি পাখি নাও, তাদের চিহ্নগুলো চিনে নাও, প্রত্যেক পাখির একেক টুকরো একেকটি পাহাড়ের উপর রেখে দাও, এরপর তাদেরকে তোমার কাছে ডাকো। তারা তোমার কাছে ছুটে আসবে। তোমার জানা উচিৎ যে আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী”।"],
  "2:261": ["The likeness of those who spend their wealth in Allah's way is the likeness of a grain that grew seven ears; in every ear a hundred grains. And Allah multiplies for whomever Allah wills. And Allah is all-ample, knowing.", "যারা তাদের অর্থ আল্লাহর পথে ব্যয় করে তাদের উদাহরন হলো একটি শস্যদানা যা উৎপন্ন করে সাতটি শীষ, যার প্রত্যেকটিতে রয়েছে একশটি শস্যদানা। আল্লাহ যার জন্য ইচ্ছা একে বহুগুণ বৃদ্ধি করে দেন। আল্লাহ দানশীল, সর্বজ্ঞ।"],
  "2:262": ["Those who spend their wealth in Allah's way, then do not follow up what they spent with favor nor harm — their reward is with their Rabb, and no fear upon them, nor will they grieve.", "যারা তাদের অর্থ আল্লাহর পথে ব্যয় করে,অতঃপর তাদের দানের পর অপমান বা ক্ষতি করে না,তাদের প্রভুর পক্ষ থেকে তারা প্রতিদান পাবে;তাদের ভয়ের কিছুই নেই, না তারা শোক করবে।"],
  "2:263": ["A kind word and forgiveness are better than charity followed by harm. And Allah is free of need, forbearing.", "সদয় কথা এবং সহানুভূতি সেই দানের চেয়ে উত্তম যার পর অপমান করা হয়। আল্লাহ সমৃদ্ধ, সহিষ্ণু।"],
  "2:264": ["O you who believe, do not void your charities with favor and harm, like the one who spends their wealth to be seen of the people and does not believe in Allah and the Last Day. His likeness is the likeness of a smooth rock with dust upon it: a downpour strikes it and leaves it bare. They have no power over anything of what they earned. And Allah does not guide the committing kufr people.", "হে তোমরা যারা বিশ্বাস করো,তোমাদের দান ভর্ৎসনা ও অপমান দ্বারা নিরর্থক করে দিয়ো না,তার মতো যে লোক-দেখানোর জন্য অর্থ খরচ করে,অথচ সে অবিশ্বাস করে আল্লাহ এবং শেষ দিনে। তার উদাহরণ হলো এমন একটি পাথরের মতো যা একটি পাতলা মাটির স্তর দ্বারা আবৃত; যখনই ভারি বর্ষণ হয়, তা মাটিকে ধুয়ে ফেলে,একে একটি অকার্যকর পাথর় করে দিয়ে যায়। তারা তাদের প্রচেষ্টা থেকে কোন কিছু অর্জন করে না। আল্লাহ অবিশ্বাসী লোকদের পথ প্রদর্শন করেন না।"],
  "2:265": ["And the likeness of those who spend their wealth seeking Allah's good pleasure and as a steadying from themselves is the likeness of a garden on high ground: a downpour strikes it, and it brings forth its fruit twofold; and if no downpour strikes it, then dew. And Allah is all-seeing of what you do.", "যারা তাদের অর্থ, আন্তরিক প্রত্যয়ে,আল্লাহর সন্তুষ্টি অর্জনের জন্য দান করে তাদের উদাহরণ হচ্ছে উঁচু উর্বর ভূমিতে যেন একটি বাগান; যখন ভারী বর্ষণ হয়, এটি দ্বিগুন শস্য দেয়,যদি ভারী বর্ষণ না-ও হয়, গুড়ি গুড়ি বৃষ্টিই যথেষ্ট। আল্লাহ দেখেন সবকিছু যা তোমরা করো।"],
  "2:266": ["Would any of you like to have a garden of palms and grapes, with rivers flowing beneath it, for them in it every fruit — and old age strikes them, and they have weak offspring, and a whirlwind with fire in it strikes it, and it burns? Thus Allah makes the signs clear to you, so that you may reflect.", "তোমাদের কেউ কি খেজুর গাছ এবং আঙুর বিশিষ্ট একটি বাগানের মালিক হতে চাও, যার সাথে থাকবে প্রবাহিত ঝর্নাধারা এবং প্রচুর পরিমান ফসল, এরপর, যখনই সে বৃদ্ধ হয়, এবং যখন  তার সন্তানেরা তখনও তার উপর নির্ভরশীল, একটি অগ্নিকান্ড আঘাত করে এবং তার বাগানকে জ্বালিয়ে দেয়? আল্লাহ এভাবে তোমাদের জন্য প্রকাশনাবলি সুস্পষ্ট করেন, যাতে তোমরা অনুধাবন করতে পার।"],
  "2:267": ["O you who believe, spend of the good of what you earned and of what We brought forth for you from the earth, and do not aim for the vile of it to spend, when you would not take it except that you shut your eyes to it. And know that Allah is free of need, praiseworthy.", "হে যারা বিশ্বাস করো,তোমরা দান করবে তোমাদের উপার্জন করা ভাল জিনিস থেকে,এবং যা আমরা তোমাদের জন্য পৃথিবী থেকে উৎপন্ন করেছি তা থেকে। তার মধ্য থেকে খারাপটি বেছে নিও না দেয়ার জন্য, যখন তোমরা নিজেরা তা গ্রহণ করো না,যদি না তোমাদের চোখ বন্ধ থাকে। তোমাদের জানা উচিত যে আল্লাহ ধনী,প্রশংসনীয়।"],
  "2:268": ["The satan promises you need and commands you to obscenity, and Allah promises you forgiveness from that and favor. And Allah is all-ample, knowing.", "শয়তান তোমাদের প্রতিশ্রুতি দেয় দারিদ্র্যতার এবং আদেশ দেয় মন্দ করার, যখন আল্লাহ তোমাদের প্রতিশ্রুতি দেন তার পক্ষ থেকে ক্ষমা এবং অনুগ্রহের। আল্লাহ উদার, সর্বজ্ঞ।"],
  "2:269": ["The wisdom is given to whomever Allah wills, and whoever is given the wisdom has been given much good. And none remember except people of understanding.", "তিনি প্রজ্ঞা প্রদান করেন যাকে তিনি পছন্দ করেন, এবং যেকেউ প্রজ্ঞা অর্জন করে,অর্জন করেছে এক মহা প্রাচুর্য। তারাই শুধুমাত্র উপদেশ গ্রহণ করবে যারা বুদ্ধিমত্তার অধিকারী।"],
  "2:270": ["And whatever expense you spent or vow you vowed — indeed Allah knows it. And the wrongdoers have no helpers.", "যা কিছু তোমরা দান করো,অথবা দানের অঙ্গীকার তোমরা পরিপূর্ণ করো,আল্লাহ তা সম্পর্কে সম্পূর্ণ অবগত। অন্যায়কারীদের বিষয়ে,তাদের কোন সাহায্যকারী থাকবে না।"],
  "2:271": ["If you manifest the charities, how good they are; and if you hide them and give them to the needy, it is better for you, and it will wipe away from you your evil deeds. And Allah is aware of what you do.", "তোমরা যদি তোমাদের দান প্রকাশ্যে করো,তখনও তা ভাল। কিন্তু যদি তোমরা তা অপ্রকাশিত রাখো,এবং তা গরিবদের দিয়ে দাও, সেটা তোমাদের জন্য উত্তম, এবং তোমাদের অধিক পাপ মোচন করে। আল্লাহ পরিপূর্ণভাবে জ্ঞাত যা কিছু তোমরা করো।"],
  "2:272": ["Guiding them is not upon you, but Allah guides whomever Allah wills. And whatever good you spend is for yourselves: you spend only seeking the face of Allah. And whatever good you spend will be repaid to you in full, and you will not be wronged.", "কাউকে পথ-প্রদর্শনের জন্য তুমি দায়ী নও। শুধুমাত্র আল্লাহ সেই সত্ত্বা  যিনি পথ-প্রদর্শন করেন, যেকেউ পছন্দ করে (পথ প্রদর্শিত হতে)। যা কিছু দান তোমরা করো তা তোমাদের নিজেদের ভালোর জন্য। যা কিছু দান তোমরা করো তা হবে আল্লাহর উদ্দেশ্যে। যা কিছু দান তোমরা করো তা তোমাদেরকে পরিশোধ করা হবে,সামান্যতম অবিচার ছাড়াই।"],
  "2:273": ["For the needy who are confined in Allah's way, unable to go about in the earth: the ignorant think them rich because of their self-restraint. You know them by their marks — they do not ask people importunately. And whatever good you spend, indeed Allah is knowing of it.", "দান হবে গরিবদের জন্য যারা আল্লাহর পথে কষ্ট ভোগ করছে,এবং দেশান্তরিত হতে পারে না। অসচেতনরা ভাবতে পারে যে তারা ধনী,তাদের মর্যাদাপূর্ণ অবস্থানের কারণে। কিন্তু তোমরা তাদের নির্দিষ্ট চিহ্ন দ্বারা চিনতে পারো; তারা কখনোই মানুষের কাছে অনবরত চাইতে থাকে না। তোমরা যা কিছু দান করো,আল্লাহ সে সম্পর্কে সম্পূর্ণ সচেতন।"],
  "2:274": ["Those who spend their wealth by night and day, secretly and openly — their reward is with their Rabb, and no fear upon them, nor will they grieve.", "যারা রাতে এবং দিনে দান করে,গোপনে এবং প্রকাশ্যে,তারা তাদের প্রভুর কাছ থেকে প্রতিদান পায়; তাদের ভয়ের কিছু থাকবে না,আর না তারা শোক করবে।"],
  "2:275": ["Those who devour usury do not stand except as one stands whom the satan throws into convulsion by the touch. That is because they say, \"Trade is just like usury.\" But Allah has made trade lawful and made usury forbidden. Whoever receives an admonition from their Rabb and desists — theirs is what is past, and their matter is with Allah. And whoever returns — those are the companions of the Fire; they abide in it forever.", "যারা চড়া সুদ আদায় করে,তারা সে একই অবস্থানে রয়েছে ওদের মত, যারা শয়তানের প্রভাব দ্বারা নিয়ন্ত্রিত। এটার কারন হচ্ছে তারা দাবী করে চড়া সুদ এবং বাণিজ্য একই। কিন্তু,আল্লাহ বাণিজ্যের অনুমতি দিয়েছেন, এবং চড়া সুদ নিষিদ্ধ করেছেন। এভাবে,যেকেউ তার প্রভুর কাছ থেকে আসা এই প্রত্যাদেশ মান্য করে,এবং চড়া সুদ থেকে বিরত থাকে,সে তার অতীতের উপার্জন রাখতে পারে,এবং তার বিচার রয়েছে আল্লাহর হাতে। তাদের বিষয়ে যারা চড়া সুদে অটল থাকে,তারা তাদের উপর নরক টেনে আনে,যেখানে তারা চিরকাল বসবাস করে।"],
  "2:276": ["Allah blots out usury and grows charities. And Allah loves not every committing kufr sinner.", "আল্লাহ চড়া সুদকে অব্যবহার্য বলে ঘোষনা করেন, এবং দানকে আশীর্বাদ করেন। আল্লাহ প্রত্যেক অবিশ্বাসী,অপরাধীকে অপছন্দ করেন।"],
  "2:277": ["Indeed those who believe and do the good deeds and keep up the prayer and give the alms — their reward is with their Rabb, and no fear upon them, nor will they grieve.", "তারা যারা বিশ্বাস করে এবং সৎ-জীবন যাপন করে,এবং সংযোগ প্রার্থনা (সালাত) প্রতিষ্ঠা করে,এবং বাধ্যতামূলক দান (যাকাত) দেয়, তারা তাদের প্রভুর পক্ষ থেকে তাদের প্রতিদান গ্রহণ করে; তাদের ভয়ের কিছু থাকবে না,আর না তারা শোক করবে।"],
  "2:278": ["O you who believe, be reverent to Allah and leave what remains of the usury, if you are muminin.", "হে যারা বিশ্বাস করো,তোমরা আল্লাহকে মান্য করবে এবং সকল ধরনের চড়া সুদ থেকে বিরত থাকবে,যদি তোমরা বিশ্বাসী হও।"],
  "2:279": ["But if you do not, then take notice of war from Allah and from Allah's Rasul. And if you repent, then yours are the heads of your wealth: you wrong not, and you are not wronged.", "যদি তোমরা না করো,তাহলে আল্লাহ এবং তাঁর রাসূলের পক্ষ থেকে একটি যুদ্ধের আশা করো। কিন্তু যদি তোমরা অনুশোচনা করো,তবে তোমরা তোমাদের মূলধন রাখতে পারো,অবিচার করা বা অবিচার টেনে আনা ছাড়া।"],
  "2:280": ["And if one is in hardship, then a waiting until ease. And that you give charity is better for you, if only you knew.", "যদি ঋণগ্রহীতা পরিশোধ করতে অক্ষম হয়, উত্তম সময়ের জন্য অপেক্ষা করো। যদি তোমরা ধারটি দান হিসেবে ছেঁড়ে দাও, এটি তোমাদের জন্য উত্তম, যদি শুধু তোমরা জানতে।"],
  "2:281": ["And beware a day in which you will be returned to Allah; then every self will be paid in full what it earned, and they will not be wronged.", "তোমরা আল্লাহর কাছে ফিরে যাওয়ার সেই দিনের ব্যাপারে সতর্ক হও, এবং প্রতিটি আত্মা যা করেছে সে সবকিছুর জন্য প্রতিফল পায়, সামান্যতম অবিচার ছাড়াই।"],
  "2:282": ["O you who believe, when you contract a debt to a stated term, then write it down. And let a scribe write it down between you with justice. Let no scribe refuse to write as Allah taught them, so let them write. And let the one upon whom is the right dictate, and let them be reverent to Allah their Rabb, and let them not diminish from it anything. And if the one upon whom is the right is foolish or weak or unable to dictate themselves, then let their guardian dictate with justice. And call two witnesses from your men; but if there are not two men, then a man and two nisa from those you approve of as witnesses, so that if one of the two errs, the one may remind the other. And let the witnesses not refuse when they are called. And do not weary of writing it, small or great, to its term. That is more equitable with Allah, and more upright for testimony, and nearer that you not doubt — unless it be a present trade you circulate among yourselves; then there is no blame on you not to write it. And call witnesses when you trade with one another. And let no scribe be harmed, nor any witness. And if you do that, then it is transgression on your part. And be reverent to Allah, and Allah teaches you. And Allah is knowing of all things.", "হে তোমরা যারা বিশ্বাস করো,যখন তোমরা যেকোন সময়ের জন্য কোন ঋণ আদান প্রদান করো,তোমরা তা লিখে রাখবে। একজন নিরপেক্ষ লেখক তা লিখবে। কোন লেখক এই কাজ করতে অস্বীকার করবে না,আল্লাহর শিক্ষা অনুযায়ী। সে লিখবে,যেভাবে ঋণ গ্রহীতা শর্তাবলী বর্ণনা করবে। সে তার প্রভু,আল্লাহকে মান্য করবে এবং কখনো প্রতারণা করবে না। যদি ঋণ গ্রহীতা মানসিকভাবে অসমর্থ, অথবা অসহায় হয়, অথবা লেখার বিষয় বলে দিতে না পারে,তবে তার অভিভাবক ন্যায়সঙ্গতভাবে লেখার বিষয় বলে দেবে। দু’জন পুরুষ সাক্ষী হিসাবে থাকবে,যদি দুজন পুরুষ না হয়, তবে একজন পুরুষ এবং দু’জন স্ত্রীলোক, যাদের সাক্ষ্য সকলের কাছে গ্রহণযোগ্য হবে। এভাবে,একজন স্ত্রীলোক যদি পক্ষপাতিত্ব করে,অন্যজন তাকে স্মরণ করিয়ে দিবে। যখন সাক্ষ্য দিতে ডাকা হয় তখন সাক্ষ্য দেয়া সাক্ষীদের উপর একটি দায়িত্ব। পরিশোধের সময় সহ, বিস্তারিত বর্ণনা লিখতে ক্লান্ত হইয়ো না,তা যতোই দীর্ঘ হোক না কেন। এটা আল্লাহর দৃষ্টিতে ন্যায়সঙ্গত, নিশ্চিত করে উত্তম সাক্ষ্য, এবং তোমাদের মনে থাকতে পারে,এমন যেকোন সন্দেহ দূর করে দেয়। ব্যবসায়িক লেনদেন যা তোমরা ঘটনাস্থলে সম্পাদন করো,তা নথিভুক্ত করার প্রয়োজন নেই, কিন্তু সেগুলোর সাক্ষী রাখো। কোন লেখক বা সাক্ষিকে তার কাজের কারনে ক্ষতিগ্রস্ত করা যাবে না। যদি তোমরা তাদের ক্ষতি করো,তবে তা হবে তোমাদের পক্ষ থেকে পাপাচার। তোমরা আল্লাহকে মান্য করবে,এবং আল্লাহ তোমাদের শিক্ষা দিবেন, আল্লাহ সর্বজ্ঞ।"],
  "2:283": ["And if you are on a journey and find no scribe, then a pledge taken in hand. And if some of you trust others, then let the one entrusted deliver the trust and be reverent to Allah their Rabb. And do not hide the testimony. And whoever hides it — then it is a sin of the heart. And Allah is knowing of what you do.", "যদি তোমরা ভ্রমনে থাকো,এবং কোন লেখক না পাওয়া যায়, ঋণ পরিশোধের প্রতিশ্রুতি হিসেবে একটি বন্ধক রাখতে হবে। যদি কাউকে এভাবে বিশ্বাস করা হয়, সে বন্ধক যথাসময়ে ফেরত দেবে,এবং সে তার প্রভু আল্লাহকে মান্য করবে। তুমি যার সাক্ষী হয়েছিলে তা গোপন করে কোন সাক্ষ্য দেয়া থেকে বিরত হইয়ো না। যে কেউ সাক্ষ্য দেয়া থেকে বিরত থাকে তার মন পাপপূর্ণ। তোমরা যা কিছু করো সে সম্পর্কে আল্লাহ পরিপূর্ণভাবে অবগত।"],
  "2:284": ["To Allah belongs whatever is in the heavens and whatever is in the earth. Whether you manifest what is in yourselves or hide it, Allah will call you to account for it. Then Allah forgives whomever Allah wills and punishes whomever Allah wills. And Allah is over all things able.", "আকাশমন্ডলী ও পৃথিবীর সবকিছু আল্লাহর। তুমি তোমার গভীরতম  চিন্তাগুলো প্রকাশ করো,বা সেগুলো গোপন রাখো,আল্লাহ সেগুলোর জন্য তোমাদের দায়ী করবেন। তিনি যাকে ইচ্ছা ক্ষমা করেন, এবং যাকে ইচ্ছা শাস্তি দেন। আল্লাহ সর্বশক্তিমান।"],
  "2:285": ["The Rasul believed in what was sent down to him from his Rabb, and the muminin: each believed in Allah and Allah's malakat and Allah's books and Allah's rusul. We make no division between any of them. And they said, \"We hear and we obey. Your forgiveness, our Rabb — and to You is the arrival.\"", "বার্তাবাহক তার প্রভুর পক্ষ থেকে যা তার কাছে অবতীর্ণ হয়েছে তাতে বিশ্বাস স্থাপন করেছে, এবং বিশ্বাসীরাও তা-ই করেছে। তারা বিশ্বাস করে আল্লাহতে,তাঁর ফেরেশতাদের, তাঁর ধর্মগ্রন্থে,এবং তাঁর বার্তাবাহকদেরঃ “আমরা তাঁর বার্তাবাহকদের মধ্যে কোন পার্থক্য করি না”। তারা বলে, “আমরা শুনি,এবং আমরা মান্য করি। আমাদের প্রভু,আমাদের ক্ষমা করুন। আপনার কাছেই চূড়ান্ত নিয়তি”।"],
  "2:286": ["Allah does not charge a self beyond its capacity: for it what it earned, and upon it what it acquired. Our Rabb, do not take us to task if we forget or err. Our Rabb, and do not lay upon us a burden as You laid it upon those before us. Our Rabb, and do not lay upon us what we have no strength for. And pass over us, and forgive us, and have mercy on us. You are our protecting friend, so help us against the committing kufr people.", "আল্লাহ কখনোই কোন আত্মার উপর তার সামর্থের অতিরিক্ত বোঝা চাপান নাঃ যা (ভাল) সে অর্জন করে সেটা তার জন্য জমা থাকবে, এবং যা সে (মন্দ) সম্পাদন করে তা তার বিরুদ্ধে থাকবে। “আমাদের প্রভু,আমাদের দোষী সাব্যস্ত করবেন না,যদি আমরা ভুলে যাই অথবা ভুল করি। আমাদের প্রভু,এবং আমাদের রক্ষা করুন আপনার বিরুদ্ধে মিথ্যাচার করা থেকে,যেভাবে আমাদের পূর্ববর্তীগণ করে গেছেন। আমাদের প্রভু,অনুশোচনার জন্য খুব বেশি দেরি হয়ে যাওয়ার আগে আমাদের পাপ থেকে রক্ষা করুন, আমাদের মার্জনা করুন এবং আমাদের ক্ষমা করুন। আপনি আমাদের প্রভু এবং মনিব। অবিশ্বাসী লোকদের উপর আমাদের জয়ী করুন”।"],
  "3:1": ["Alif. Lam. Mim.", "অ.ল.ম."],
  "3:2": ["Allah — there is no ilah but Allah, the Living, the Self-Sustaining.", "আল্লাহ: তিনি ছাড়া আর কোন উপাস্য নেই; জীবিত, চিরস্থায়ী।"],
  "3:3": ["Allah sent down upon you the Book with the truth, confirming what was before Allah's hands, and sent down the Torah and the Gospel.", "তিনি তোমাদের কাছে অবতীর্ণ করেছেন এই ঐশীগ্রন্থ, সত্যতার সাথে,যা নিশ্চিত করে সকল পূর্ববর্তী ঐশীগ্রন্থ সমূহকে,এবং তিনি অবতীর্ণ করেছেন তওরাত এবং ইঞ্জীল।"],
  "3:4": ["Earlier, as guidance for people, and sent down the Criterion. Truly those who rejected the signs of Allah — for them is a severe punishment, and Allah is Mighty, Rabb of requital.", "তার আগে,মানুষকে পথ প্রদর্শনের জন্য, এবং তিনি অবতীর্ণ করেছেন বিধিবদ্ধ আইনগ্রন্থ, যারা আল্লাহর প্রকাশনাবলীকে অবিশ্বাস করে তারা টেনে আনে কঠোর শাস্তি। আল্লাহ সর্বশক্তিমান, প্রতিশোধ গ্রহণকারী।"],
  "3:5": ["Truly nothing is hidden from Allah in the earth nor in the heaven.", "আল্লাহর কাছে কোনকিছুই লুকানো নেই, পৃথিবীতে,অথবা আসমানে।"],
  "3:6": ["It is Allah who forms you in the wombs as Allah wills. There is no ilah but Allah, the Mighty, the Wise.", "তিনিই একজন যিনি তোমাদের আকৃতি দেন মাতৃগর্ভে,যেমন তিনি ইচ্ছে করেন। তাঁর পাশে অন্য কোন উপাস্য নেই; সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "3:7": ["It is Allah who sent down upon you the Book; of it are verses decisive — those are the mother of the Book — and others resembling. As for those in whose hearts is swerving, they follow what resembles of it, seeking dissension and seeking its interpretation; and none knows its interpretation but Allah. And those firm-rooted in knowledge say: We believe in it, all of it is from our Rabb. And none remembers but people of understanding.", "তিনি তোমাদের প্রতি এই ঐশীগ্রন্থ অবতীর্ণ করেছেন, যাতে আছে সহজবোধ্য চরণসমূহ - যা এই ঐশীগ্রন্থের মূল বিষয়কে স্থাপন করে - আরো আছে বহু অর্থবোধক বা রুপকধর্মী চরণসমূহ। যারা তাদের হৃদয়ে সন্দেহ পোষন করে,তারা বহু অর্থবোধক চরণসমূহের পিছনে লেগে থাকবে,বিভ্রান্তি সৃষ্টি করতে,এবং বের করতে একটি নির্দিষ্ট অর্থ। এগুলোর প্রকৃত অর্থ কেউ জানে না আল্লাহ এবং যাদের জ্ঞান দৃঢ় ভিত্তির উপর প্রতিষ্ঠিত তারা ছাড়া। তারা বলে,\"আমরা এতে বিশ্বাস করি- এর সবটুকুই আমাদের প্রভু থেকে আসে\"। শুধুমাত্র যারা বুদ্ধিমত্তার অধিকারী তারাই উপদেশ গ্রহণ করবে।"],
  "3:8": ["Our Rabb, do not make our hearts swerve after You have guided us, and grant us mercy from Your presence; truly You are the Bestower.", "\"আমাদের প্রভু,আমাদের অন্তরকে দ্বিধান্বিত হতে দিয়েন না,এখন যখন আপনি আমাদের পথ-প্রদর্শন করেছেন। আমাদের উপর আপনার দয়া বর্ষন করুণ; আপনিই দাতা।"],
  "3:9": ["Our Rabb, it is You who will gather people for a day of which there is no doubt; truly Allah does not break the appointment.", "\"আমাদের প্রভু,নিশ্চয় আপনি লোকদের জড়ো করবেন এক অনিবার্য দিনে। আল্লাহ কখনো প্র্রতিশ্রুতি ভঙ্গ করেন না।\""],
  "3:10": ["Truly neither the wealth nor the children of those who rejected will avail them anything against Allah, and those are fuel for the fire.", "যারা অবিশ্বাস করে তারা কখনো আল্লাহর বিপক্ষে সাহায্য প্রাপ্ত হবে না,তাদের অর্থ দ্বারা,না তাদের সন্তানদের দ্বারা। তারা হবে নরকের জ্বালানী।"],
  "3:11": ["Like the way of Fir'awn's people and those before them: they denied our signs, so Allah seized them for their offenses, and Allah is severe in punishment.", "ফেরাউনের লোকদের এবং তাদের আগে যারা ছিল তাদের মতো,তারা আমাদের প্রকাশনাবলীকে প্রত্যাখ্যান করেছিল এবং,ফলস্বরূপ, আল্লাহ তাদের পাপের জন্য তাদের শাস্তি দিয়েছিলেন। আল্লাহ প্রতিফল আরোপে কঠোর।"],
  "3:12": ["Say to those who reject: You shall be overcome and gathered into hell, and an evil couch it is.", "যারা অবিশ্বাস করে তাদের বল, “তোমরা পরাজিত হবে,এরপর নরকে একত্রিত হবে; কি এক শোচনীয় বাসস্থান!”"],
  "3:13": ["There has already been a sign for you in the two bands that met: a band fighting in Allah's path and another rejecting, seeing them twice their number as the eye sees. And Allah strengthens with Allah's help whom Allah wills. Truly in that is a lesson for people of vision.", "তোমাদের জন্য একটি উদাহরণ স্থাপন করা হয়েছে দুই সেনাদলের দ্বারা,যারা সংঘর্ষে লিপ্ত হয়েছিল- একটি সেনাদল আল্লাহর উদ্দশ্যে যুদ্ধ করছিল, যখন অন্যটি ছিল অবিশ্বাসী। তারা স্বচোখে দেখেছিল যে তারা সংখ্যায় দিগুন। আল্লাহ যাকে ইচ্ছা তাঁর বিজয় দিয়ে সমর্থন করেন। যারা দূরদর্শিতার অধিকারী এটা তাদের জন্য একটি নিশ্চয়তা হওয়া উচিৎ।"],
  "3:14": ["Adorned for people is the love of desires: nisa, sons, heaped-up hoards of gold and silver, branded horses, cattle, and tillage. That is the enjoyment of the worldly life, and with Allah is the goodly return.", "মানুষের জন্য সুশোভিত করা হয়েছে পার্থিব আনন্দ, যেমন নারী,সন্তানাদি,রাশি রাশি স্বর্ণ এবং রৌপ্য, প্রশিক্ষিত ঘোড়া,গবাদিপশু,এবং শস্য। এগুলো পার্থিব উপকরণ। আল্লাহর কাছে সংরক্ষিত রয়েছে একটি অতি উত্তম বাসস্থান।"],
  "3:15": ["Say: Shall I inform you of what is better than that? For those who keep their duty, with their Rabb are gardens with rivers flowing beneath, abiding therein forever, and purified spouses, and good pleasure from Allah. And Allah sees the servants.", "বল, “তোমাদেরকে একটি আরো উত্তম চুক্তির ব্যাপারে আমাকে অবহিত করতে দাওঃ যারা সৎজীবন যাপন করে তাদের জন্য, তাদের প্রভুর কাছে সংরক্ষিত রয়েছে,প্রবাহিত জলস্রোত সহ বাগান, এবং বিশুদ্ধ সহধর্মী/সহধর্মীনি এবং আল্লাহর আশীর্বাদের মাঝে পরমানন্দ”। আল্লাহ তাঁর উপাসনাকারীদের দেখেন।"],
  "3:16": ["Those who say: Our Rabb, we have believed, so forgive us our offenses and shield us from the punishment of the fire.", "তারা বলে,\"আমাদের প্রভু,আমরা বিশ্বাস করেছি,অতএব আমাদের পাপসমূহ ক্ষমা করুণ, এবং নরকাগ্নির তীব্র-যন্ত্রণা থেকে আমাদের নিষ্কৃতি দিন।"],
  "3:17": ["The sabirin, the sadiqin, the qanitin, the munfiqin, and those who seek forgiveness at the dawn hours.", "তারা অবিচল, সত্যবাদী,আত্মসমর্পণকারী,দানশীল, এবং ভোরে ধ্যানকারী।"],
  "3:18": ["Allah bears witness that there is no ilah but Allah — and the malakat, and people of knowledge, upholding equity. There is no ilah but Allah, the Mighty, the Wise.", "আল্লাহ সাক্ষ্য প্রদান করছেন যে,তিনি ছাড়া কোন উপাস্য নেই, এবং ফেরেশতারা ও যারা জ্ঞানের অধিকারী তারাও একই সাক্ষ্য দেয়। সত্যনিষ্ঠার সঙ্গে এবং ন্যায়সঙ্গত পন্থায়, তিনি পরম আল্লাহ; তিনি ছাড়া কোন আল্লাহ নেই, সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "3:19": ["Truly the religion with Allah is surrender. And those who were given the Book did not differ except after knowledge came to them, out of rivalry among themselves. And whoever rejects the signs of Allah — then Allah is swift in reckoning.", "আল্লাহর অনুমোদিত একমাত্র ধর্ম \"আত্মসমর্পণ\"। দুঃখজনক ভাবে,যারা ঐশীগ্রন্থ গ্রহণ করেছে তারা-ই এই প্রকৃত বিষয়টি নিয়ে বিবাদে লিপ্ত হয়, তারা যে জ্ঞান অর্জন করেছে তা সত্ত্বেও, ঈর্ষার কারনে। আল্লাহর প্রকাশনাবলীর এরুপ প্রত্যাক্ষানকারীদের জন্য, আল্লাহ হিসাব গ্রহনে সবচেয়ে কঠোর।"],
  "3:20": ["So if they argue with you, say: I have surrendered my face to Allah, and so has whoever follows me. And say to those who were given the Book and to the unlettered: Have you surrendered? So if they have surrendered, they are guided; and if they turn away, then upon you is only the delivering. And Allah sees the servants.", "তারা যদি তোমার সাথে বিবাদে লিপ্ত হয়, তবে বল, \"আমি কেবল নিজেকে আল্লাহর কাছে সমর্পন করেছি; আমি এবং তারা যারা আমাকে অনুসরণ করে।”যারা ঐশীগ্রন্থ গ্রহণ করেছে আর যারা করেনি তাদের কাছে তুমি ঘোষনা করবে,\"তোমরা কি আত্মসমর্পণ করবে? “তারা যদি আত্মসমর্পণ করে,তবে তারা পথনির্দেশিত হয়েছে,কিন্তু যদি তারা মুখ ফিরিয়ে নেয়, এই বার্তা পৌঁছে দেয়া তোমার একমাত্র কাজ। আল্লাহ সব মানুষকে দেখেন।"],
  "3:21": ["Truly those who reject the signs of Allah and kill the nabis without right and kill those among people who command equity — give them tidings of a painful punishment.", "যারা আল্লাহর প্রকাশনাবলি প্রত্যাখ্যান করেছে,এবং নবীদের অন্যায়ভাবে হত্যা করেছে,এবং তাদেরকে হত্যা করেছে,যারা মানুষের মাঝে ন্যায়পরায়ণতার সমর্থন করেছে,তাদেরকে একটি যন্ত্রণাদায়ক প্রতিফলের প্রতিশ্রুতি দাও।"],
  "3:22": ["Those are the ones whose deeds are void in the worldly life and the world to come, and they have no helpers.", "তাদের কাজগুলো এই দুনিয়া এবং পরকাল উভয়লোকেই বিনষ্ট হয়ে গেছে,এবং তাদের কোন সাহায্যকারী থাকবে না।"],
  "3:23": ["Have you not seen those who were given a portion of the Book? They are called to the Book of Allah that it may judge between them; then a party of them turns away, and they are averse.", "তুমি কি তাদেরকে লক্ষ্য করেছ, যাদেরকে ঐশীগ্রন্থের অংশবিশেষ দেওয়া হয়েছিল, এবং কেমন করে তারা আমন্ত্রিত হয়েছিল আল্লাহর এই ঐশীগ্রন্থ মেনে চলতে,এবং একে তাদের নিজেদের জীবনে প্রয়োগ করতে,তারপর তাদের কেউ কেউ বিদ্বেষে মুখ ফিরিয়ে নিল।"],
  "3:24": ["That is because they say: The fire will not touch us except for counted days. And what they used to invent has deceived them in their religion.", "এটা এ কারনে যে তারা বলেছিল, “নরকের আগুন আমাদের স্পর্শ করবে না,অল্প কিছু দিন ছাড়া”। এভাবে তারা তাদের ধর্মে প্রতারিত হয়েছিল তাদের নিজেদের মিথ্যা উদ্ভাবনের দ্বারা।"],
  "3:25": ["So how will it be when We gather them for a day of which there is no doubt, and every soul is paid in full what it earned, and they are not wronged?", "এটা তাদের জন্য কেমন হবে,যখন আমরা তাদেরকে একত্রিত করি সেই অনিবার্য দিনে? প্রত্যেক আত্মা যা কিছু অর্জন করেছে তার জন্য মূল্য প্রদান করা হবে,সামান্যতম অবিচার ছাড়াই।"],
  "3:26": ["Say: O Allah, Owner of kingship, You give kingship to whom You will and strip kingship from whom You will; You strengthen whom You will and abase whom You will. In Your hand is all good. Truly You have power over everything.", "বল, \"আমাদের উপাস্য: সকল সার্বভৌমত্বের অধিকারী। আপনি যাকে পছন্দ করেন সার্বভৌমত্ব প্রদান করেন, আপনি যার থেকে পছন্দ করেন সার্বভৌমত্ব নিয়ে নেন। আপনি যাকে পছন্দ করেন মর্যাদা প্রদান করেন, এবং আপনি যাকে পছন্দ করেন অপদস্থতায় পতিত করেন। আপনার হাতেই সব কিছুর বন্দোবস্ত। আপনি সর্বশক্তিমান।"],
  "3:27": ["You make the night enter into the day and make the day enter into the night; You bring forth the living from the dead and bring forth the dead from the living; and You provide for whom You will without reckoning.", "\"আপনি রাতকে দিনের মধ্যে মিলিয়ে দেন, এবং দিনকে রাতের মধ্যে মিলিয়ে দেন। আপনি জীবিতকে মৃত থেকে বের করেন, এবং মৃতকে জীবিত থেকে বের করেন, এবং আপনি যাকে পছন্দ করেন সীমাহীনভাবে প্রদান করেন।"],
  "3:28": ["The muminin must not take the rejecters as allies apart from the muminin. Whoever does that has nothing with Allah — unless it be that you protect yourselves against them out of protection. And Allah warns you of Allah. And to Allah is the arrival.", "বিশ্বাসীরা কখনো নিজেদেরকে অবিশ্বাসীদের মিত্র বানায় না,বিশ্বাসীদের বদলে। যেকেউ তা করে,সে আল্লাহর থেকে নির্বাসিত হয়। তারা দায়মুক্ত, যারা তা করতে বাধ্য হয়, নিপীড়ন এড়াতে। আল্লাহ তোমাদেরকে সতর্ক করেন যে,তোমরা কেবল তাঁর ভক্তি করবে। আল্লাহর কাছেই চূড়ান্ত নিয়তি।"],
  "3:29": ["Say: Whether you hide what is in your breasts or manifest it, Allah knows it. And Allah knows what is in the heavens and what is in the earth, and Allah has power over everything.", "বল, \"তুমি তোমার গভীরতম  চিন্তাগুলো গোপন রাখো,অথবা তা প্রকাশ করো,আল্লাহ সে সম্পর্কে সম্পূর্ণ অবগত।”তিনি আকাশমন্ডলী এবং পৃথিবীর সবকিছু সম্পর্কে পূর্ণ অবগত। আল্লাহ সর্বশক্তিমান।"],
  "3:30": ["On the day every soul finds present what it did of good, and what it did of evil it will wish there were a great distance between itself and that. And Allah warns you of Allah. And Allah is gentle in mercy toward the servants.", "সে দিন আসবে যখন প্রত্যেক আত্মা এর করা সব ভাল কাজ সামনে উত্থাপিত পাবে। আর মন্দ কাজের বেলায়, এটি ইচ্ছা করবে যে এগুলো যদি অনেক অনেক দূরে সরিয়ে নেয়া হত। আল্লাহ তোমাদেরকে সতর্ক করেন যে,তোমরা একমাত্র তাঁকে ভক্তি করবে। আল্লাহ লোকদের প্রতি সবচেয়ে দয়াবান।"],
  "3:31": ["Say: If you love Allah, then follow me; Allah will love you and forgive you your offenses. And Allah is forgiving, merciful.", "ঘোষণা করোঃ “যদি তোমরা আল্লাহকে ভালোবাস, তোমাদের উচিৎ আমাকে অনুসরন করা”। আল্লাহ তখন তোমাদের ভালবাসবেন, এবং তোমাদের পাপ ক্ষমা করে দেবেন। আল্লাহ ক্ষমাশীল, পরম দয়ালু।"],
  "3:32": ["Say: Obey Allah and the Rasul. But if they turn away, then Allah does not love the rejecters.", "ঘোষণা করোঃ “তোমরা আল্লাহ এবং বার্তাবাহকে মান্য করবে”। যদি তারা মুখ ফিরিয়ে নেয়, আল্লাহ অবিশ্বাসীদের ভালবাসেন না।"],
  "3:33": ["Truly Allah chose Adam and Nuh and the family of Ibrahim and the family of Imran above the worlds.", "আল্লাহ আদম, নূহ, ইবরাহীমের পরিবার, এবং ইমরানের পরিবারকে লোকেদের কাছে (বার্তাবাহক হিসাবে) পছন্দ করেছেন।"],
  "3:34": ["Offspring, some of it from some; and Allah hears, knows.", "তারা একই বংশের অন্তর্ভূক্ত। আল্লাহ শ্রবণকারী,সর্বজ্ঞ।"],
  "3:35": ["When the imra'a of Imran said: My Rabb, I have vowed to You what is in my belly, devoted; so accept it from me. Truly You are the Hearing, the Knowing.", "ইমরানের স্ত্রী বলল, “আমার প্রভু,আমি আমার পেটের (শিশুকে) আপনার কাছে উৎসর্গ করছি,পূর্ণরূপে,সুতরাং আমার থেকে গ্রহণ করুণ। আপনি শ্রবণকারী,সর্বজ্ঞ।"],
  "3:36": ["So when she gave birth to her she said: My Rabb, I have given birth to her, a female — and Allah knew best what she had given birth to, and the male is not like the female — and I have named her Maryam, and I seek Your refuge for her and her offspring from the stoned satan.", "যখন সে তাকে জন্ম দিল, সে বলল, “আমার প্রভু, আমি একটি কন্যা জন্ম দিয়েছি”-আল্লাহ পরিপূর্ণভাবে অবগত ছিলেন কি সে গর্ভে ধারন করছিল- “পুরুষ একই রকম নয়, নারীর মত। আমি তার নাম দিয়েছি মরিয়ম এবং আমি বিতাড়িত শয়তান থেকে তার এবং তার বংশধরদের জন্য আশ্রয় প্রার্থনা করছি”।"],
  "3:37": ["So her Rabb accepted her with a good acceptance, and made her grow a good growth, and Zakaria undertook her care. Whenever Zakaria entered the sanctuary upon her he found provision with her. He said: O Maryam, from where is this to you? She said: It is from Allah. Truly Allah provides for whom Allah wills without reckoning.", "তার প্রভু তাকে গ্রহণ করেছিলেন অনুগ্রহময় গ্রহণ, এবং তাকে প্রতিপালন করেছিলেন অনুগ্রহময় প্রতিপালন, জাকারিয়ার অভিভাবকত্বে। যখনি  জাকারিয়া তার উপাসনাস্থলে প্রবেশ করতো সে তার কাছে খাদ্যসম্ভার পেত। সে জিজ্ঞাসা করতো,“মরিয়ম, এগুলো তুমি কোথা থেকে পেয়েছ? সে বলত, ‘এটা আল্লাহর থেকে। আল্লাহ যাকে পছন্দ করেন প্রদান করেন, সীমাহীনভাবে।\""],
  "3:38": ["There Zakaria called upon his Rabb. He said: My Rabb, grant me from Your presence goodly offspring; truly You hear the call.", "তখনই জাকারিয়া তার প্রভুর কাছে মিনতি করলেনঃ “আমার প্রভু,আমাকে এমন একটি সুসন্তান দান করুন; আপনি প্রার্থনা শ্রবণকারী”।"],
  "3:39": ["So the malakat called to him while he stood praying in the sanctuary: Allah gives you good tidings of Yahya, confirming a word from Allah, and a master, chaste, and a Nabi of the salihin.", "ফেরেশতারা তাকে আহবান করেছিল যখন সে উপাসনাস্থলে প্রার্থনা করছিলঃ “আল্লাহ তোমাকে ইয়াহিয়ার শুভ সংবাদ দেন; একজন আল্লাহর বাণীতে বিশ্বাসী,সন্মানিত, ন্যায়পরায়ণ, এবং একজন সৎকর্মশীল নবী”।"],
  "3:40": ["He said: My Rabb, how shall I have a boy when old age has reached me and my imra'a is barren? Allah said: Thus — Allah does what Allah wills.", "সে বলেছিল, “কেমন করে আমার পুত্র হতে পারে,যখন আমি এতো বৃদ্ধ, এবং আমার স্ত্রী বন্ধ্যা? সে বলেছিল, “আল্লাহ যা ইচ্ছা করেন”।"],
  "3:41": ["He said: My Rabb, appoint for me a sign. Allah said: Your sign is that you shall not speak to the people for three days except by gesture. And remember your Rabb much, and glorify in the evening and the morning.", "সে বলেছিল, \"আমার প্রভু,আমাকে একটি নিদর্শন দিন।” তিনি বলেছিলেন, \"তোমার নিদর্শন এটা যে,তুমি ইশারা ব্যতীত লোকদের সাথে তিন দিন কথা বলবে না। বার বার তোমার প্রভুর স্মরণ কর;এবং রাতে ও দিনে ধ্যান করো।\""],
  "3:42": ["And when the malakat said: O Maryam, truly Allah has chosen you and purified you and chosen you above the nisa of the worlds.", "ফেরেশতারা বলেছিল, \"হে মরিয়ম, আল্লাহ তোমাকে পছন্দ করেছেন এবং তোমাকে পরিশুদ্ধ করেছেন। তিনি তোমাকে সকল নারীদের থেকে পছন্দ করেছেন।"],
  "3:43": ["O Maryam, be devout to your Rabb and bow and bow down with those who bow.", "\"হে মরিয়ম, তুমি তোমার প্রভুর নিকট আত্মসমর্পণ করবে,এবং সেজদা করবে ও অবনত হবে (রুকু করবে) তাদের সাথে যারা অবনত হয় (রুকু করে)।\""],
  "3:44": ["That is from the tidings of the unseen We reveal to you. And you were not with them when they cast their quills as to which of them should undertake Maryam, and you were not with them when they contended.", "এটি অতীতের সংবাদ যা আমরা তোমার কাছে প্রকাশ করি। তুমি সেখানে ছিলে না,যখন তারা মরিয়মের অভিভাবক নির্বাচন করতে তাদের ভাগ্য নির্নয় করছিল। তুমি উপস্থিত ছিলে না,যখন তারা একে অন্যের সাথে তর্ক করছিল।"],
  "3:45": ["When the malakat said: O Maryam, truly Allah gives you good tidings of a word from Allah whose name is the Messiah, Isa, son of Maryam, honored in the worldly life and the world to come, and among those brought near.", "ফেরেশতারা বলেছিল, \"হে মরিয়ম, আল্লাহ তোমাকে সুসংবাদ দেন: তাঁর থেকে একটি বানী যার নাম 'মসিহ, মরিয়মের পুত্র ঈসা।' সে এই জীবনে এবং পরকালে বিশিষ্ট হবে,এবং আমার সবচেয়ে নিকটবর্তীদের একজন হবে।"],
  "3:46": ["And Allah will speak to the people in the cradle and in maturity, and is one of the salihin.", "“সে কোলে থেকে লোকদের সাথে কথা বলবে,একই ভাবে পূর্ণবয়স্ক হয়ে; সে সৎকর্মশীলদের একজন হবে”।"],
  "3:47": ["She said: My Rabb, how shall I have a child when no human has touched me? Allah said: Thus — Allah creates what Allah wills. When Allah decrees a matter, Allah only says to it \"Be,\" and it is.", "সে বলেছিল, “আমার প্রভু,কেমন করে আমার একটি পুত্র হতে পারে,যখন কোন পুরুষ আমাকে স্পর্শ করেনি?”তিনি বলেছিলেন, \"আল্লাহ এভাবে সৃষ্টি করেন, যা তিনি ইচ্ছা করেন। কোন কিছু করতে,তিনি শুধু এটাকে বলেন, 'হও',এবং তা হয়ে যায়।"],
  "3:48": ["And Allah will teach him the Book and the wisdom and the Torah and the Gospel.", "\"তিনি তাকে শিক্ষা দিবেন ঐশীগ্রন্থ, জ্ঞান, তওরাত, এবং ইঞ্জিল।\""],
  "3:49": ["And a Rasul to the children of Israel: I have come to you with a sign from your Rabb — that I create for you from clay the form of a bird, then I breathe into it and it becomes a bird by Allah's leave; and I heal the blind from birth and the leprous, and I bring the dead to life by Allah's leave; and I inform you of what you eat and what you store up in your houses. Truly in that is a sign for you, if you are muminin.", "ইসরাইলের সন্তানদের কাছে একজন বার্তাবাহক হিসেবেঃ “আমি তোমাদের কাছে তোমাদের প্রভুর কাছ থেকে একটি নিদর্শন নিয়ে আসি-আমি তোমাদের জন্য কাদা থেকে একটি পাখির আকৃতি তৈরি করি,এরপর আমি এটির মধ্যে ফুঁৎকার দেই, এবং এটি আল্লাহর অনুমতিতে একটি জীবন্ত পাখি হয়ে যায়। আমি আল্লাহর অনুমতিতে অন্ধের দৃষ্টি ফিরিয়ে দেই, কুষ্ঠ ব্যাধিগ্রস্থকে আরোগ্য করি,এবং আমি মৃতকে জীবিত করি। আমি তোমাদের বলতে পারি কি তোমরা খাও, এবং কি তোমরা তোমাদের ঘরে মজুদ করো। এটা তোমাদের জন্য একটি প্রমান হওয়া উচিৎ,যদি তোমরা বিশ্বাসী হয়ে থাকো।"],
  "3:50": ["And confirming what was before me of the Torah, and to make lawful for you some of what was forbidden to you; and I have come to you with a sign from your Rabb. So keep your duty to Allah and obey me.", "“আমি সুনিশ্চিত করি পূর্ববর্তী ঐশীগ্রন্থ-তওরাত-এবং আমি বাতিল করি তোমাদের উপর আরোপিত নির্দিষ্ট নিষেধাজ্ঞা। আমি তোমাদের প্রভুর থেকে যথেষ্ট প্রমান নিয়ে তোমাদের কাছে আসি। সুতরাং,তোমরা আল্লাহতে মনোযোগী হবে,এবং আমাকে মান্য করবে।"],
  "3:51": ["Truly Allah is my Rabb and your Rabb, so serve Allah. This is a straight path.", "\"আল্লাহ আমার প্রভু এবং তোমাদের প্রভু; তোমরা একমাত্র তাঁর উপাসনা করবে। এটাই সঠিক পথ।\""],
  "3:52": ["So when Isa perceived rejection from them he said: Who will be my helpers to Allah? The disciples said: We are Allah's helpers. We believe in Allah; and bear witness that we are those who surrender.", "যখন ঈসা তাদের অবিশ্বাস টের পেল, সে বলল, \"আল্লাহর পক্ষে () কারা আমার সমর্থক?”অনুসারীরা বলল, \"আমরা আল্লাহর সমর্থক; আমরা আল্লাহতে বিশ্বাস করি,এবং সাক্ষী থাক যে,আমরা আত্মসমর্পণকারী।"],
  "3:53": ["Our Rabb, we believe in what You sent down and we follow the Rasul, so write us down among the witnesses.", "\"আমাদের প্রভু,আমরা বিশ্বাস করেছি যা আপনি অবতীর্ণ করেছেন, এবং আমরা বার্তাবাহককে অনুসরণ করেছি; আমাদের সাক্ষীদের মাঝে গননা করুণ।\""],
  "3:54": ["And they planned, and Allah planned; and Allah is the best of planners.", "তারা চক্রান্ত করেছিল এবং পরিকল্পনা করল, কিন্তু আল্লাহ তা-ই করেছিলেন, এবং আল্লাহ সর্বোত্তম পরিকল্পনাকারী।"],
  "3:55": ["When Allah said: O Isa, I am taking you to Myself and raising you to Me and purifying you of those who rejected, and setting those who follow you above those who rejected until the day of rising. Then to Me is your return, and I shall judge between you concerning what you differed about.", "এভাবে,আল্লাহ বলেছিলেন, “হে ঈসা,আমি তোমার জীবন সমাপ্ত করছি,তোমাকে আমার কাছে তুলে নিচ্ছি,এবং তোমাকে অবিশ্বাসীদের থেকে নিষ্কৃতি দিচ্ছি। আমি উচ্চে অধিষ্ঠিত রাখব তাদেরকে,যারা তোমাকে অনুসরণ করে,তাদের উপর যারা অবিশ্বাস করে,পুনুরুত্থান দিবস পর্যন্ত। এরপর আমার নিকটে তোমাদের সবার চূড়ান্ত নিয়তি,তখন আমি তোমাদের বিবাদের বিষয়ে তোমাদের মধ্যে বিচার করবো।"],
  "3:56": ["So as for those who rejected, I shall punish them with a severe punishment in the worldly life and the world to come, and they have no helpers.", "“যারা অবিশ্বাস করে,আমি তাদেরকে যন্ত্রণাদায়ক প্রতিফল দেব, এই দুনিয়াতে এবং পরকালে। তাদের কোন সাহায্যকারী থাকবে না”।"],
  "3:57": ["But as for those who believed and did the right deeds, I shall pay them their rewards in full. And Allah does not love the wrongdoers.", "যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে,তিনি তাদের পরিপূর্ণ প্রতিদান দিবেন। আল্লাহ অন্যায়কারীদের ভালবাসেন না।"],
  "3:58": ["This We recite to you of the verses and the wise reminder.", "এগুলো প্রকাশনাবলী যা আমরা তোমার কাছে আবৃত্তি করি,যা একটি জ্ঞানে পরিপূর্ণ বার্তা প্রদান করে।"],
  "3:59": ["Truly the likeness of Isa with Allah is as the likeness of Adam: Allah created him from dust, then said to him \"Be,\" and he was.", "আল্লাহর দৃষ্টিভঙ্গি থেকে,ঈসার উদাহরণ, আদমের মতই; তিনি তাকে ধূলা থেকে সৃষ্টি করেছিলেন, তারপর তাকে বলেছিলেন, “হও, ”এবং সে হয়ে গিয়েছিল।"],
  "3:60": ["The truth is from your Rabb, so do not be of the doubters.", "তোমার প্রভু থেকে এটি সত্যতা; কোন সন্দেহ পোষণ করো না।"],
  "3:61": ["Whoever argues with you about it after the knowledge that has come to you, then say: Come, let us call our sons and your sons, our nisa and your nisa, our souls and your souls; then let us pray humbly, and we shall make the curse of Allah upon the kazibin.", "যদি কেউ তোমার সাথে তর্ক করে,তুমি যে জ্ঞান পেয়েছ তা সত্ত্বেও, তাহলে বল, “চল, আমরা আমাদের সন্তান এবং তোমাদের সন্তান, আমাদের নারী এবং তোমাদের নারী,আমাদের নিজেদের এবং তোমাদের নিজেদেরকে ডেকে আনি,তারপর চল মিথ্যাবাদীদের উপর আল্লাহর অভিশাপের জন্য প্রার্থনা করি।\""],
  "3:62": ["Truly this is the true narrative, and there is no ilah but Allah; and truly Allah is the Mighty, the Wise.", "নিঃসন্দেহে,এটি সত্য বর্ননা। নিঃসন্দেহে,আল্লাহ ছাড়া কোন উপাস্য নেই। নিঃসন্দেহে,আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "3:63": ["So if they turn away — then Allah knows the corrupters.", "যদি তারা মুখ ফিরিয়ে নেয়, তবে আল্লাহ মন্দকর্মীদের সম্পর্কে সম্পূর্ণ অবগত।"],
  "3:64": ["Say: O people of the Book, come to a word equal between us and you: that we serve none but Allah, and ascribe nothing as partner to Allah, and that some of us do not take others as rabbs apart from Allah. So if they turn away, say: Bear witness that we are those who surrender.", "বল, \"হে ঐশীগ্রন্থের অনুসারীরা,চল আমরা আমাদের এবং তোমাদের মধ্যে একটি যৌক্তিক সম্মতিতে আসি: যে আমরা আল্লাহ ব্যতীত উপাসনা করবো না; যে আমরা কখনো আল্লাহর পাশে কোন অংশীদার সাব্যস্ত করবো না,না কোন মানুষকে আল্লাহর পাশে প্রভু হিসেবে সাব্যস্ত করবো।”যদি তারা মুখ ফিরিয়ে নেয়, বল, সাক্ষী থাক যে,আমরা আত্মসমর্পণকারী।\""],
  "3:65": ["O people of the Book, why do you argue about Ibrahim when the Torah and the Gospel were not sent down except after him? Do you not understand?", "হে ঐশীগ্রন্থের অনুসারীরা,কেন তোমরা ইব্রাহিম সম্পর্কে তর্ক কর, যখন তওরাত এবং ইঞ্জিল তার পরে অবতীর্ণ হয়েছিল? তোমরা কি বুঝ না?"],
  "3:66": ["Here you are, arguing about what you have knowledge of — so why do you argue about what you have no knowledge of? And Allah knows, and you do not know.", "তোমরা তর্ক করেছ সেই জিনিসের ব্যাপারে যা তোমরা জানতে,কেন তোমরা তর্ক কর সেই জিনিসের ব্যাপারে যা তোমরা জানো না? আল্লাহ জানেন, যখন তোমরা জানো না।"],
  "3:67": ["Ibrahim was not a Jew nor a Christian, but he was upright, surrendered, and not among those who ascribe partners.", "ইবরাহীম না ছিলেন ইহুদী,না ছিলেন খ্রীষ্টান; তিনি ছিলেন একজন একেশ্বরবাদী আত্মসমর্পণকারী। তিনি কখনই একজন অংশীদার সাব্যস্তকারী ছিলেন না।"],
  "3:68": ["Truly the people closest to Ibrahim are those who followed him, and this Nabi, and those who believe; and Allah is the ally of the muminin.", "ইবরাহীমের সবচেয়ে যোগ্য লোক হলো তারা যারা তাকে অনুসরণ করেছিল, এবং এই নবীকে,এবং তারা যারা বিশ্বাস করে। আল্লাহ বিশ্বাসীদের প্রভু এবং অভিভাবক।"],
  "3:69": ["A faction of the people of the Book would love to lead you astray, but they lead astray none but themselves, and they do not perceive.", "ঐশীগ্রন্থের কিছু অনুসারীরা তোমাদেরকে বিপথগামী করতে চায়, কিন্তু তারা শুধু তাদের নিজেদেরকেই বিপথগামী করে,না বুঝেই।"],
  "3:70": ["O people of the Book, why do you reject the signs of Allah while you witness?", "হে ঐশীগ্রন্থের অনুসারীগন, কেন তোমরা প্রত্যাখ্যান করো আল্লাহর এই প্রকাশনাবলী,যদিও তোমরা সাক্ষী দাও (যে এটাই সত্য)?"],
  "3:71": ["O people of the Book, why do you clothe truth with falsehood and hide the truth while you know?", "হে ঐশীগ্রন্থের অনুসারীরা,কেন তোমরা সত্যকে মিথ্যার সাথে মিশ্রিত কর, এবং জেনে-শুনে সত্য গোপন কর?"],
  "3:72": ["And a faction of the people of the Book say: Believe in what was sent down on those who believe at the beginning of the day, and reject at its end — perhaps they may return.", "ঐশীগ্রন্থের কিছু অনুসারীরা বলে,“যা বিশ্বাসীদের কাছে অবতীর্ণ হয়েছে তা সকালে বিশ্বাস কর, এবং সন্ধায় প্রত্যাক্ষান কর; হতে পারে একদিন তারা ফিরে আসবে।"],
  "3:73": ["And believe only those who follow your religion. Say: Truly the guidance is Allah's guidance — that anyone should be given the like of what you were given, or that they should argue with you before your Rabb. Say: Truly the bounty is in Allah's hand; Allah gives it to whom Allah wills, and Allah is all-ample, knowing.", "\"এবং যারা তোমাদের ধর্ম অনুসরণ করে তাদের মত ছাড়া বিশ্বাস কর না।”বল, \"আল্লাহর পথ-নির্দেশনাই সত্য পথ-নির্দেশনা।”যদি তারা দাবি করে যে তাদের একই পথ-নির্দেশনা আছে,অথবা তোমাদের প্রভু সম্পর্কে তোমাদের সাথে তর্ক করে,বল, \"আল্লাহর হাতে সকল অনুগ্রহ; তিনি যার উপর ইচ্ছা তা অর্পণ করেন।”আল্লাহ দানশীল, সর্বজ্ঞ।"],
  "3:74": ["Allah singles out for Allah's mercy whom Allah wills; and Allah is the Owner of tremendous bounty.", "তিনি যার জন্য ইচ্ছা করেন, তাঁর অনুগ্রহ নির্দিষ্ট করেন; আল্লাহ সীমাহীন অনুগ্রহের অধিকারী।"],
  "3:75": ["Among the people of the Book is the one who, if you entrust him with a hoard, pays it back to you; and among them is the one who, if you entrust him with a single coin, does not pay it back to you unless you keep standing over him. That is because they say: There is no charge upon us regarding the unlettered. And they speak falsehood against Allah while they know.", "ঐশীগ্রন্থের কিছু অনুসারীদের সব কিছু দিয়ে বিশ্বাস করা যেতে পারে,এবং তারা তা তোমাকে ফিরিয়ে দিবে। তাদের মধ্যে বাকিদের এক দিনার দিয়েও বিশ্বাস করা যেতে পারে না; তারা তোমাকে পরিশোধ করবে না,যদি না তুমি তাদের পিছনে লেগে থাক। এর কারন এই যে তারা বলে,\"যারা ঐশীগ্রন্থ অনুসরণ করে না (উম্মী)  তাদের সাথে লেনদেনে আমাদেরকে সৎ হতে হবে না!”এভাবে,তারা জেনে-শুনে আল্লাহর উপর মিথ্যা আরোপ করে।"],
  "3:76": ["Rather, whoever fulfills his pledge and keeps his duty — then Allah loves the dutiful.", "প্রকৃতপক্ষে,যারা পূর্ণ করে তাদের অঙ্গীকার এবং সৎ জীবন যাপন করে,আল্লাহ সৎকর্মশীলদের ভালবাসেন।"],
  "3:77": ["Truly those who sell Allah's pledge and their oaths for a small price — those have no portion in the world to come, and Allah will not speak to them nor look at them on the day of rising, nor purify them, and for them is a painful punishment.", "আর তাদের জন্য যারা আল্লাহর চুক্তির বাণিজ্য করে,এবং তাদের বাধ্যবাধকতার, সস্তা মুল্যের জন্য, তারা পরকালে কোন অংশ পায় না। আল্লাহ তাদের সাথে কথা বলবেন না,না তাদের দিকে তাকাবেন, পুনুরুত্থানের দিনে,না তিনি তাদেরকে পরিশুদ্ধ করবেন। তারা টেনে এনেছে একটি যন্ত্রণাদায়ক প্রতিফল।"],
  "3:78": ["And indeed among them is a party who twist their tongues with the Book so that you may reckon it part of the Book, though it is not part of the Book; and they say: It is from Allah, when it is not from Allah; and they speak falsehood against Allah while they know.", "তাদের মধ্যে রয়েছে তারা যারা তাদের জিহ্বা আওড়ায় ঐশীগ্রন্থের অনুকরণ করতে,যাতে তোমরা ভাব যে এটা ঐশীগ্রন্থ থেকে,যখন এটা ঐশীগ্রন্থ থেকে নয়, এবং তারা দাবী করে যে এটা আল্লাহর থেকে,যখন এটা আল্লাহর থেকে নয়। এভাবে,তারা মিথ্যা বলে এবং সেগুলো আল্লাহর উপর আরোপ করে,জেনে-শুনে।"],
  "3:79": ["It was not for any human that Allah should give him the Book, the judgment, and the Nabihood, then he should say to the people: Be servants to me apart from Allah; but rather: Be teachers, devout, by what you know of the Book and by what you study.", "একজন মানুষ যাকে আল্লাহ ঐশীগ্রন্থ এবং নবীত্ব দিয়ে আশীর্বাদ করেছেন সে কখনই মানুষকে বলবে না,“আল্লাহর পাশে আমার উপাসনা করো”। বরং,(সে বলবে),“তোমাদের নিজেদেরকে সম্পূর্ণরূপে একমাত্র তোমাদের প্রভুর কাছে উৎসর্গ করো,”ঐশীগ্রন্থ যা তোমরা প্রচার করো এবং শিক্ষা যা তোমরা শেখ তা অনুসারে।"],
  "3:80": ["And he would not command you to take the malakat and the nabis as rabbs. Would he command you to rejection after you have surrendered?", "না সে তোমাদেরকে আদেশ করবে প্রভু হিসাবে ফেরেশতাদের এবং নবিদের উপাসনা করতে। আত্মসমর্পণকারী হবার পর সে কি তোমাদের অবিশ্বাস করতে উৎসাহিত করবে?"],
  "3:81": ["And when Allah took the pledge of the nabis: Whatever I give you of Books and wisdom, then a Rasul comes to you confirming what is with you, you shall surely believe in him and surely help him. Allah said: Do you affirm and take My bond upon that? They said: We affirm. Allah said: Then bear witness, and I am with you among the witnesses.", "আল্লাহ নবীদের থেকে একটি প্রতিজ্ঞা নিয়েছিলেন, এই বলে যে,\"আমি তোমাদেরকে ঐশীগ্রন্থ এবং বিজ্ঞতা দিব। পরবর্তীকালে,একজন বার্তাবাহক বিদ্যমান সকল ঐশীগ্রন্থসমূহ সত্যায়ন করতে আসবে। তোমরা তাকে বিশ্বাস করবে এবং তাকে সমর্থন করবে।” তিনি বলেছিলেন, \"তোমরা কি এর সাথে সম্মত হয়েছ, এবং এই চুক্তি পূর্ণ করার অঙ্গীকার করছ?” তারা বলেছিল, \"আমরা সম্মত।” তিনি বলেছিলেন, \"তাহলে তোমরা সাক্ষী রইলে এবং আমি তোমাদের সাথে সাক্ষী রইলাম।"],
  "3:82": ["Then whoever turns away after that — those are the defiant.", "যারা এটি (কুরআনের ভবিষ্যদ্বাণী) প্রত্যাক্ষান করে তারা মন্দ।"],
  "3:83": ["Is it other than Allah's religion that they seek, when to Allah has surrendered whatever is in the heavens and the earth, willingly or unwillingly, and to Allah they are returned?", "তারা কি আল্লাহর ধর্ম ব্যতীত অন্যকিছু খুজঁছে,যখন আকাশমন্ডলী ও পৃথিবীর সবকিছু তাঁর কাছে আত্মসমর্পণ করেছে, ইচ্ছায় ও অনিচ্ছায়, এবং  তাঁর কাছেই তারা ফিরে যাবে?"],
  "3:84": ["Say: We believe in Allah and what was sent down on us, and what was sent down on Ibrahim and Ismail and Ishaq and Yaqub and the tribes, and what was given to Musa and Isa and the nabis from their Rabb. We make no division between any of them, and to Allah we are those who surrender.", "বল, \"আমরা বিশ্বাস করি আল্লাহতে,এবং যা আমাদের কাছে অবতীর্ণ হয়েছিল, এবং যা অবতীর্ণ হয়েছিল ইব্রাহিম, ইসমাইল, ইসহাক, ইয়াকুব, এবং পিতৃপুরুষদের কাছে,এবং যা দেয়া হয়েছিল মূসা,ঈসা,এবং নবীদেরকে তাদের প্রভুর পক্ষ থেকে। আমরা তাদের কারো মধ্যে কোন পার্থক্য করি না। একমাত্র তাঁরই কাছে আমরা আত্মসমর্পণকারী।"],
  "3:85": ["Whoever seeks other than surrender as religion, it will not be accepted from him, and in the world to come he is among the khasirin.", "যেকেউ আত্মসমর্পণ ছাড়া অন্য কিছু তার ধর্ম হিসেবে গ্রহণ করে,এটি তাঁর থেকে গৃহীত হবে না,এবং পরকালে,সে হতভাগাদের সাথে থাকবে।"],
  "3:86": ["How shall Allah guide a people who rejected after their faith, and bore witness that the Rasul is true, and clear proofs came to them? And Allah does not guide the wrongdoing people.", "কেন আল্লাহর উচিৎ সেসব মানুষকে পথ প্রদর্শন করা যারা বিশ্বাস করার পর অবিশ্বাস করেছে,এবং বার্তাবাহকের সত্যতার সাক্ষী হবার পর, এবং তাদেরকে দৃঢ় প্রমান  দেওয়ার পর? আল্লাহ অন্যায়কারীদের পথ প্রদর্শন করেন না।"],
  "3:87": ["Those — their reward is that upon them rests the curse of Allah, the malakat, and all people together.", "তারা আল্লাহ, এবং ফেরেশতা,এবং সকল মানুষ থেকে শাস্তি টেনে এনেছে।"],
  "3:88": ["Abiding therein; the punishment will not be lightened for them, nor will they be looked at.", "অনন্তকাল তারা সেখানে বাস করবে; তাদের জন্য শাস্তি কখনোই কমানো হবে না,না তারা পরিত্রান পাবে।"],
  "3:89": ["Except those who repented after that and made right — then Allah is forgiving, merciful.", "তারা নিষ্কৃতি পাবে যারা এরপর অনুশোচনা করে,এবং সংশোধিত হয়। আল্লাহ ক্ষমাশীল, পরম দয়ালু।"],
  "3:90": ["Truly those who rejected after their faith, then increased in rejection — their repentance will not be accepted, and those are the ones astray.", "যারা বিশ্বাস করার পর অবিশ্বাস করে,তারপর অবিশ্বাসের গভীরে ডুবে যায়, তাদের অনুশোচনা তাদের থেকে গ্রহণ করা হবে না; তারাই আসল পথভ্রষ্ট।"],
  "3:91": ["Truly those who rejected and died while they were rejecters — not one of them will be accepted even if he offered a fill of the earth in gold as ransom. Those have a painful punishment, and they have no helpers.", "যারা অবিশ্বাস করে এবং অবিশ্বাসী হিসেবে মারা যায়, একটি স্বর্নে পরিপূর্ণ পৃথিবী তাদের কারো কাছ থেকে গ্রহণ করা হবে না,যদি এরকম মুক্তিপণ সম্ভব হয়। তারা যন্ত্রনাদায়ক শাস্তি টেনে এনেছে; তাদের কোন সাহায্যকারী থাকবে না।"],
  "3:92": ["You will never reach goodness until you spend of what you love; and whatever you spend of anything, then Allah knows it.", "তোমরা সৎকর্মশীলতা অর্জন করতে পার না,যতক্ষন না তোমরা তোমাদের অধিকৃত প্রিয় বস্তু থেকে দান করো। যাকিছু তোমরা দান কর, আল্লাহ সে সম্পর্কে সম্পূর্ণ অবগত।"],
  "3:93": ["All food was lawful to the children of Israel, except what Israel forbade to himself before the Torah was sent down. Say: Bring the Torah and recite it, if you are sadiq.", "ইসরাইলের সন্তানদের জন্য সকল খাদ্য আইনসম্মত ছিল, যতক্ষন না ইসরাইলীরা তাদের নিজেদের উপর নির্দিষ্ট নিষেধসমূহ আরোপ করেছিল, তওরাত অবতীর্ণ হবার আগে। বল, \"তওরাত আন এবং তা পড়, যদি তোমরা সত্যবাদী হও।"],
  "3:94": ["So whoever invents falsehood against Allah after that — those are the wrongdoers.", "যারা এরপর মিথ্যা নিষেধসমূহ উদ্ভাবন করে,এবং সেগুলো আল্লাহর উপর আরোপ করে,তারা প্রকৃতপক্ষে অন্যায়কারী।"],
  "3:95": ["Say: Allah speaks truth, so follow the creed of Ibrahim, upright; and he was not among those who ascribe partners.", "বল, \"আল্লাহ সেই সত্য ঘোষনা করেছেন: তোমরা অনুসরণ করবে ইব্রাহিমের ধর্ন- একেশ্বরবাদ। সে কখনো অংশীদার সাব্যস্তকারী ছিল না।"],
  "3:96": ["Truly the first house placed for people is the one at Makkah, blessed and a guidance for the worlds.", "মানুষের জন্য সব থেকে গুরুত্বপূর্ণ ঘর হচ্ছে সেটি যা বাক্কায় স্থাপিত; একটি পবিত্র আলোকবর্তিকা,সকল মানুষের জন্য।"],
  "3:97": ["In it are clear signs — the station of Ibrahim — and whoever enters it is secure. And owed to Allah from people is the pilgrimage to the house, for whoever can find a way to it. And whoever rejects — truly Allah has no need of the worlds.", "এর মধ্যে রয়েছে স্পষ্ট নিদর্শনসমূহ: ইবরাহীমের অবস্থানস্থল। যে কেউ এতে প্রবেশ করে তাকে প্রদান করা হবে নিরাপদ অবস্থান। আল্লাহর কাছে মানুষ এতে বাধ্য যে তারা এই ঘরে হজ্জ পালন করবে,যখন তারা এর  সামর্থ অর্জন করতে পারে আর যারা অবিশ্বাস করে,আল্লাহর কাউকে প্রয়োজন নেই।"],
  "3:98": ["Say: O people of the Book, why do you reject the signs of Allah, when Allah is witness to what you do?", "বল, “হে ঐশীগ্রন্থের অনুসারীরা,কেন তোমরা আল্লাহর এই প্রকাশনাবলী প্রত্যাখ্যান কর, যখন আল্লাহ সবকিছু প্রত্যক্ষ করছেন, যা তোমরা করো।"],
  "3:99": ["Say: O people of the Book, why do you bar from Allah's path those who believe, seeking to make it crooked, while you are witnesses? And Allah is not unmindful of what you do.", "বল, “হে ঐশীগ্রন্থের অনুসারীরা,কেন তোমরা আল্লাহর পথে বাধা দাও, তাদেরকে যারা বিশ্বাস করতে চায়, এবং তা বিকৃত করার পথ খোঁজ, যদিও তোমরা প্রত্যক্ষ করছ”। তোমরা যা কিছু করো তা সম্পর্কে আল্লাহ কখনই অনবগত নন।"],
  "3:100": ["O you who believe, if you obey a party of those who were given the Book, they will turn you back after your faith into rejecters.", "হে তোমরা যারা বিশ্বাস করো, যারা ঐশীগ্রন্থ গ্রহণ করেছে, তাদের কতককে যদি তোমরা মান্য করো, তারা তোমাদেরকে পিছনে ফিরিয়ে দেবে, বিশ্বাস আনার পর, অবিশ্বাসীতে।"],
  "3:101": ["And how could you reject when the verses of Allah are recited to you and among you is Allah's Rasul? Whoever holds fast to Allah is guided to a straight path.", "কিভাবে তোমরা অবিশ্বাস করতে পার: যখন আল্লাহর এই প্রকাশনাবলি তোমাদের কাছে আবৃতি করা হয়েছে,এবং তার বার্তাবাহক তোমাদের কাছে এসেছে? যেকেউ আল্লাহতে দৃড়ভাবে আঁকড়ে থাকে,সে সঠিক পথে পথ-প্রদর্শিত হবে।"],
  "3:102": ["O you who believe, keep your duty to Allah with the duty due to Allah, and do not die except as those who surrender.", "হে যারা বিশ্বাস কর, তোমরা আল্লাহকে মান্য করবে,যেমন তাকে মান্য করা উচিৎ,এবং আত্মসমর্পণকারী হিসেবে ছাড়া মৃত্যুবরণ করো না।"],
  "3:103": ["And hold fast all together to the rope of Allah and do not divide. And remember Allah's favor upon you: when you were enemies, and Allah joined your hearts, so by Allah's favor you became brothers; and you were on the brink of a pit of the fire and Allah rescued you from it. Thus Allah makes the signs clear to you, that perhaps you may be guided.", "তোমরা আল্লাহর রশি দৃড়ভাবে আঁকড়ে থাকবে,তোমরা সবাই, এবং বিভক্ত হইও না। স্মরণ কর, তোমাদের উপর আল্লাহর আশীর্বাদ- তোমরা শত্রু হয়ে ছিলে এবং তিনি তোমাদের অন্তরসমূহ পূনর্মিলিত করেছিলেন। তাঁর অনুগ্রহে,তোমরা ভাই হয়ে গিয়েছিলে। তোমরা ছিলে অগ্নিকুন্ডের কিনারে,তিনি তোমাদেরকে সেখান থেকে রক্ষা করেছিলেন। আল্লাহ এভাবে তোমাদের জন্য তাঁর প্রকাশনাবলি ব্যাখ্যা করেন, যাতে তোমরা পথ-প্রদর্শিত হতে পার।"],
  "3:104": ["And let there be among you a community calling to the good and commanding what is recognized and forbidding what is rejected; and those are the muflihin.", "তোমাদের একটি সম্প্রদায় হোক, যারা যাকিছু ভাল তাতে আহবান করে,সৎকর্মশীলতার উপদেশ দেয়, এবং মন্দ করতে নিষেধ করে। এরাই বিজয়ী।"],
  "3:105": ["And do not be like those who divided and differed after clear proofs came to them; and those have a tremendous punishment.", "তাদের মত হইও না যারা বিভক্ত এবং বিবাদে লিপ্ত হয়ে পড়েছিল, সুস্পষ্ট প্রমান সত্ত্বেও, যা তাদেরকে দেয়া হয়েছিল। এর জন্য, এরা টেনে এনেছে এক ভয়ানক শাস্তি।"],
  "3:106": ["On the day when faces are whitened and faces are blackened. As for those whose faces are blackened: Did you reject after your faith? Then taste the punishment for what you were rejecting.", "সে দিন আসবে যখন কিছু মুখ উজ্জল হবে (আনন্দে),যখন অন্য মুখগুলো অন্ধকারাচ্ছন্ন হবে (দুর্দশায়)। তাদের ক্ষেত্রে যাদের মুখসমূহ অন্ধকারাচ্ছন্ন হবে,তারা জিজ্ঞাসিত হবে,”তোমরা কি বিশ্বাস করার পর অবিশ্বাস করনি? কাজেই তোমাদের অবিশ্বাসের জন্য প্রতিফল ভোগ করো।\""],
  "3:107": ["But as for those whose faces are whitened — they are in Allah's mercy, abiding therein forever.", "আর তাদের ক্ষেত্রে যাদের মুখসমূহ উজ্জ্বল হবে,তারা আল্লাহর দয়ায় আনন্দ করবে; তারা সেখানে চিরকাল বাস করবে।"],
  "3:108": ["Those are the verses of Allah We recite to you in truth; and Allah does not intend wrong for the worlds.", "এগুলো আল্লাহর প্রকাশনাবলী; আমরা সেগুলো তোমার কাছে আবৃত্তি করি,সত্যতার সাথে। আল্লাহ মানুষের জন্য কোন কষ্ট চান না।"],
  "3:109": ["And to Allah belongs whatever is in the heavens and whatever is in the earth, and to Allah all affairs are returned.", "আকাশমন্ডলীর সবকিছু এবং পৃথিবীর উপরের সবকিছু আল্লাহর, এবং সকল বস্তু আল্লাহর দ্বারা নিয়ন্ত্রিত।"],
  "3:110": ["You were the best community brought forth for people: you command what is recognized, forbid what is rejected, and believe in Allah. And if the people of the Book had believed, it would have been better for them. Among them are muminin, but most of them are defiant.", "এযাবতকালে উত্থিত মানুষের মাঝে তোমরা শ্রেষ্ঠ সম্প্রদায়ঃ তোমরা সৎকর্মের উপদেশ দাও এবং মন্দে নিষেধ করো,এবং তোমরা আল্লাহতে বিশ্বাস করো। যদি ঐশীগ্রন্থের অনুসারীরা বিশ্বাস করত, এটা তাদের জন্য উত্তম হত। তাদের কেউ কেউ বিশ্বাস করে,কিন্তু তাদের বেশির ভাগ পাপী।"],
  "3:111": ["They will never harm you except with hurt; and if they fight you, they will turn their backs to you, then they will not be helped.", "তোমাদেরকে অপমান করার অতিরিক্ত, তারা কখনো তোমাদের ক্ষতি করতে পারে না। যদি তারা তোমাদের সাথে লড়াই করে,তারা ঘুরে দাঁড়াবে এবং পালিয়ে যাবে। তারা কখনো জয়ী হতে পারে না।"],
  "3:112": ["Abasement has been struck upon them wherever they are found, except through a rope from Allah and a rope from people; and they have met with wrath from Allah, and poverty has been struck upon them. That is because they rejected the signs of Allah and killed the nabis without right. That is because they disobeyed and used to transgress.", "যখনি তোমরা তাদের মোকাবেলা কর, তারা অপদস্থ হবে,যদি না তারা বহাল থাকে আল্লাহর চুক্তিতে, পাশাপাশি তোমাদের সাথে করা তাদের শান্তি চুক্তিতে। তারা আল্লাহর ক্রোধ টেনে এনেছে,এবং,ফলস্বরুপ, তারা অসম্মানে পতিত হয়। এটা এ কারনে যে তারা আল্লাহর প্রকাশনাবলিকে প্রত্যাক্ষান করেছিল, এবং নবীদেরকে অন্যায়ভাবে হত্যা করেছিল। এটা এ কারনে যে তারা অমান্য করেছিল এবং সীমালঙ্ঘন করেছিল।"],
  "3:113": ["They are not all alike. Among the people of the Book is a community standing upright, reciting the verses of Allah through the night hours while they bow down.", "তারা সবাই একই রকম নয়; ঐশীগ্রন্থের অনুসারীদের মধ্যে রয়েছে তারা যারা সৎকর্মশীল। তারা রাত জুড়ে আল্লাহর প্রকাশনাবলি আবৃতি করে,এবং তারা সেজদায় অবনত হয়।"],
  "3:114": ["They believe in Allah and the last day, and command what is recognized and forbid what is rejected, and hasten to good deeds; and those are among the salihin.", "তারা আল্লাহতে এবং শেষ দিবসে বিশ্বাস করে,তারা সৎকর্মশীলতার উপদেশ দেয় এবং মন্দ করতে নিষেধ করে,এবং তারা সৎ কাজ করতে ত্বরা করে। এরাই সৎকর্মশীল।"],
  "3:115": ["And whatever they do of good, they will not be denied it; and Allah knows the dutiful.", "যেকোন ভাল তারা করে,তা অপুরস্কৃত হবে না। আল্লাহ সৎকর্মশীলদের ব্যপারে সম্পূর্ণ অবগত।"],
  "3:116": ["Truly neither the wealth nor the children of those who rejected will avail them anything against Allah, and those are the companions of the fire, abiding therein forever.", "যারা অবিশ্বাস করেছে তারা কখনই আল্লাহর বিরুদ্ধে তাদের অর্থ অথবা তাদের সন্তানদের দ্বারা সাহায্য প্রাপ্ত হতে পারে না। তারা নরক টেনে এনেছে,যার মধ্যে তারা চিরকাল বাস করবে।"],
  "3:117": ["The likeness of what they spend in this worldly life is as a likeness of a wind in which is a biting chill; it struck the tillage of a people who wronged themselves and destroyed it. And Allah did not wrong them, but they wronged themselves.", "এই জীবনে তাদের সম্পাদিত কাজের উদাহরন হচ্ছে,প্রবল বাতাসের মতো যা আঘাত করে ঐসব মানুষের ফসলে যারা তাদের আত্মার ক্ষতি করেছে,এবং একে নিশ্চিহ্ন করে ফেলে। আল্লাহ কখনই তাদের ক্ষতি করেননি; তারা নিজেরাই নিজেদের ক্ষতি করেছে।"],
  "3:118": ["O you who believe, do not take as intimates other than yourselves; they will not stint you corruption. They love what distresses you. Hatred has already shown from their mouths, and what their breasts hide is greater. The signs have been made clear to you — if you use your understanding.", "হে তোমরা যারা বিশ্বাস করো, বহিরাগতদের সাথে বন্ধুত্ব করো না যারা কখনই তোমাদের অনিষ্ট কামনা বন্ধ করে না। এমনকি, তারা দেখতে চায়, তোমরা কষ্ট ভোগ করো। তাদের মুখ থেকে ঘৃণা প্রবাহিত হয় এবং যা তারা তাদের বুকে লুকিয়ে রাখে তা আরো মন্দ। এভাবে,আমরা তোমাদের জন্য প্রকাশনাবলী সুস্পষ্ট করি, যেন তোমরা বুঝতে পার।"],
  "3:119": ["There you are, loving them, while they do not love you, and you believe in the whole Book. When they meet you they say: We believe; but when they are alone they bite at you the fingertips from rage. Say: Die in your rage! Truly Allah knows what the breasts hide.", "দেখো, তোমরা তাদেরকে ভালবাস, যখন তারা তোমাদেরকে ভালবাসে না, এবং তোমরা সকল ঐশীগ্রন্থে বিশ্বাস করো। যখন তারা তোমাদের সাথে সাক্ষাৎ করে তারা বলে, “আমরা বিশ্বাস করি,” কিন্তু, যে-মুহূর্তে তারা চলে যায় তারা তোমাদের প্রতি প্রচণ্ড ক্রোধ বসত তাদের আঙ্গুল কামড়াতে থাকে। বল, “মর, তোমাদের প্রচণ্ড ক্রোধে”। আল্লাহ সব থেকে গভীরতম চিন্তাসমূহ সম্পর্কে পরিপূর্ণভাবে অবগত।"],
  "3:120": ["If a good thing touches you, it grieves them; and if a misfortune befalls you, they rejoice at it. And if you are sabir and keep your duty, their scheme will not harm you anything. Truly Allah encompasses what they do.", "যখন তোমাদের পথে ভালো কিছু আসে তারা আঘাত পায়, এবং যখন তোমাদের মন্দ কিছু হয় তারা আনন্দিত হয়। যদি তোমরা দৃড়তার সাথে অধ্যবসায়ী হও, এবং সৎকর্মশীলতা বজায় রাখো, তাদের চক্রান্ত কখনই তোমাদের ক্ষতি করতে পারবে না। তারা যাকিছু করে আল্লাহ সে সম্পর্কে পরিপূর্ণভাবে অবগত।"],
  "3:121": ["And when you set out from your family at morning, settling the muminin in their places for the battle — and Allah hears, knows.", "স্মরণ কর যে,তুমি (মুহাম্মদ) তোমার লোকদের মাঝে ছিলে,যখন তুমি বিশ্বাসীদের জন্য তাদের যুদ্ধের অবস্থান নির্ধারণ করতে গিয়েছিলে। আল্লাহ শ্রোতা,সর্বজ্ঞ।"],
  "3:122": ["When two parties of you resolved to lose heart, and Allah was their ally; and upon Allah let the muminin rely.", "তোমাদের মধ্যে দুই দল প্রায় ব্যর্থ হয়েছিল, কিন্তু আল্লাহ ছিলেন তাদের প্রভু। বিশ্বাসীরা আস্থা রাখবে আল্লাহতে।"],
  "3:123": ["Allah has already helped you at Badr when you were abased. So keep your duty to Allah, that perhaps you may give thanks.", "আল্লাহ বদরে তোমাদের বিজয় দান করেছেন, তোমাদের দুর্বলতা সত্ত্বেও। অতএব, তোমরা আল্লাহকে মান্য করবে,তোমাদের কৃতজ্ঞতা প্রদর্শনের জন্য।"],
  "3:124": ["When you said to the muminin: Will it not suffice you that your Rabb supply you with three thousand malakat sent down?", "তুমি বিশ্বাসীদের বলেছিলে,\"এটা কি যথেষ্ট নয় যে,তোমাদের প্রভু তোমাদের সমর্থন করেন অবতীর্ণ তিন হাজার ফেরেশতা দিয়ে?\""],
  "3:125": ["Yes — if you are sabir and keep your duty, and they come at you suddenly like this, your Rabb will supply you with five thousand malakat marked.", "নিশ্চয়, যদি তোমরা দৃড়তার সাথে অধ্যবসায়ী হও এবং সৎকর্মশীলতা বজায় রাখ, তারপর তারা তোমাদের অকস্মাৎ আক্রমণ করে, তোমাদের প্রভু তোমাদেরকে সুপ্রশিক্ষিত পাঁচ হাজার ফেরেশতা দিয়ে সমর্থন করবেন।"],
  "3:126": ["And Allah made it nothing but good tidings for you, so that your hearts might be settled by it; and help is none but from Allah, the Mighty, the Wise.", "এভাবে,আল্লাহ তোমাদেরকে অবহিত করেন, তোমাদের সুসংবাদ দেওয়ার জন্য, এবং তোমাদের হৃদয়কে আশ্বস্ত করার জন্য। বিজয় একমাত্র আল্লাহ থেকে আসে,সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "3:127": ["That Allah may cut off a fringe of those who reject, or overwhelm them so they turn back disappointed.", "এভাবে,তিনি কিছু অবিশ্বাসীকে নির্মূল করেন, অথবা তাদেরকে নিষ্ক্রিয় করে দেন, শেষ পর্যন্ত তারা সবসময় পরাজিত হয়।"],
  "3:128": ["You have no say in the matter: whether Allah turns to them or punishes them — for they are wrongdoers.", "এটা তোমার অধীনে নয়; তিনি হয়তো তাদের উদ্ধার করবেন, অথবা তাদের শাস্তি দিবেন, তাদের সীমালঙ্ঘনের জন্য।"],
  "3:129": ["And to Allah belongs whatever is in the heavens and whatever is in the earth: Allah forgives whom Allah wills and punishes whom Allah wills. And Allah is forgiving, merciful.", "আকাশমন্ডলী ও পৃথিবীর সবকিছু আল্লাহর। তিনি যাকে ইচ্ছা ক্ষমা করেন, এবং যাকে ইচ্ছা শাস্তি দেন। আল্লাহ ক্ষমাশীল, পরম দয়ালু।"],
  "3:130": ["O you who believe, do not devour usury, doubled and multiplied; and keep your duty to Allah, that perhaps you may succeed.", "হে তোমরা যারা বিশ্বাস করো,তোমরা চড়া সুদ নেবে না,চক্রবৃদ্ধি হারে। আল্লাহকে মান্য করো,যাতে তোমরা সফলকাম হতে পার।"],
  "3:131": ["And keep your duty to the fire prepared for the rejecters.", "সতর্ক হও, সেই নরকাগ্নির বিষয়ে যা অবিশ্বাসীদের জন্য অপেক্ষা করে।"],
  "3:132": ["And obey Allah and the Rasul, that perhaps you may be shown mercy.", "তোমরা আল্লাহ এবং বার্তাবাহককে মান্য করবে,যাতে ঐশরিক দয়া অর্জন করতে পার।"],
  "3:133": ["And hasten to forgiveness from your Rabb and a garden whose width is the heavens and the earth, prepared for the dutiful.", "তোমাদের উচিত আগ্রহের সঙ্গে প্রতিযোগিতা করা,তোমাদের প্রভুর থেকে ক্ষমাপ্রাপ্তির এবং একটি স্বর্গের, যার প্রশস্ততা বেষ্টন করে আকাশমন্ডলী  এবং পৃথিবীকে; এটি সৎকর্মশীলদের জন্য অপেক্ষা করে,"],
  "3:134": ["Those who spend in ease and hardship, and hold in their rage, and pass over the people; and Allah loves the doers of good.", "যারা দান করে ভাল সময়ে,একই সাথে দু:সময়ে। তারা ক্রোধ দমনকারী,এবং লোকদের ক্ষমাকারী। আল্লাহ দানশীলকে ভালবাসেন।"],
  "3:135": ["And those who, when they commit an obscenity or wrong themselves, remember Allah and seek forgiveness for their offenses — and who forgives the offenses but Allah? — and do not persist in what they did while they know.", "যদি তারা পাপে পতিত হয় অথবা তাদের আত্মার ক্ষতি করে,তারা আল্লাহকে স্মরণ করে এবং তাদের পাপের জন্য ক্ষমা চায়- এবং কে পাপ ক্ষমা করে আল্লাহ ছাড়া- এবং জেনে-শুনে তারা পাপ করতে থাকে না।"],
  "3:136": ["Those — their reward is forgiveness from their Rabb and gardens with rivers flowing beneath, abiding therein forever. And an excellent reward for the workers.", "তাদের প্রতিদান হল তাদের প্রভুর পক্ষ থেকে ক্ষমা,এবং প্রবাহিত জলস্রোত সহ বাগান; তারা সেখানে চিরকাল বসবাস করে। পরিশ্রমকারীদের জন্য কি এক মনোরম পুরস্কার!"],
  "3:137": ["Ways have passed before you; so journey in the earth and look how was the end of the mukazzibin.", "তোমাদের জন্য অতীতের উদাহরণ স্থাপন করা হয়েছে; পৃথিবীতে ভ্রমন কর এবং লক্ষ্য কর অবিশ্বাসীদের পরিণাম।"],
  "3:138": ["This is a clarification for people, and a guidance and admonition for the dutiful.", "এটা মানুষের জন্য একটি ঘোষণা,এবং সৎকর্মশীলদের জন্য একটি পথ নির্দেশনা এবং জ্ঞানালোক।"],
  "3:139": ["And do not weaken nor grieve; you are the uppermost, if you are muminin.", "তোমরা দ্বিধাগ্রস্থ হবে না,না তোমরা শোকার্ত হবে,কারন তোমরাই চূড়ান্ত বিজয়ী,যদি তোমরা বিশ্বাসী হয়ে থাকো।"],
  "3:140": ["If a wound touches you, a wound the like of it has already touched the people; and such days We alternate among the people — and so that Allah may know those who believe, and take witnesses from you. And Allah does not love the wrongdoers.", "যদি তোমরা কষ্ট ভোগ কর, শত্রুরাও একই কষ্ট ভোগ করে। আমরা মানুষের মাঝে জয় এবং পরাজয়ের দিনগুলো পালাক্রমে পরিবর্তন করি। আল্লাহ এভাবে পৃথক করেন সত্যিকার বিশ্বাসীদের, এবং তোমাদের কতককে শহীদত্ব দিয়ে আশীর্বাদ করেন। আল্লাহ অবিচার অপছন্দ করেন।"],
  "3:141": ["And so that Allah may purify those who believe and erase the rejecters.", "এভাবে,আল্লাহ তাদেরকে বলিষ্ঠ করেন, যারা বিশ্বাস করে এবং অপদস্থ করেন, অবিশ্বাসীদের।"],
  "3:142": ["Or did you reckon you would enter the garden while Allah has not yet known those who strove among you and known the sabirin?", "তোমরা কি স্বর্গে প্রবেশের আশা কর, তোমাদের মধ্যে তাদেরকে আলাদা করা ব্যতিত, যারা সংগ্রাম করে,এবং তাদেরকে আলাদা করা ব্যতিত, যারা দৃড়?"],
  "3:143": ["You used to wish for death before you met it; so you have seen it while you were looking on.", "তোমরা মৃত্যুর জন্য আকাংখা করতে,এর মুখোমুখি হবার আগে। এখন, তোমরা এর মুখোমুখি হয়েছ, ঠিক তোমাদের চোখের সামনে।"],
  "3:144": ["Muhammad is nothing but a Rasul; rusul have passed before him. So if he dies or is killed, will you turn back on your heels? Whoever turns back on his heels will not harm Allah anything, and Allah will repay the thankful.", "মুহাম্মদ তার পূর্বের বার্তাবাহকদের মত, একজন বার্তাবাহকের চেয়ে বেশি কিছু ছিল না। সে মরে গেলে অথবা নিহত হলে,তোমরা কি পূর্বের অবস্থায় ফিরে যেতে? যেকেউ তার পূর্বের অবস্থায় ফিরে যায়, সে আল্লাহর সামান্যতম ক্ষতি করে না। আল্লাহ তাদেরকে পুরস্কৃত করেন, যারা কৃতজ্ঞ।"],
  "3:145": ["No soul can die except by Allah's leave — a fixed term prescribed. And whoever desires the reward of this world, We give him of it; and whoever desires the reward of the world to come, We give him of it; and We will repay the thankful.", "আল্লাহর অনুমতি ছাড়া কেউই মৃত্যুবরণ করে না,এক পূর্বনির্ধারিত সময়ে। যেকেউ এই দুনিয়ার আড়ম্বর খোঁজে,আমরা তাকে সেখান থেকে দেই, এবং যেকেউ পরকালের পুরস্কার খোঁজে,আমরা তাকে সেখানে আশীর্বাদ করি। আমরা তাদেরকে পুরস্কৃত করি,যারা কৃতজ্ঞ।"],
  "3:146": ["And how many a Nabi was killed, with whom were many rabbiyyin; and they did not weaken for what befell them in Allah's path, and did not weaken and did not submit. And Allah loves the sabirin.", "অনেক নবিদের সাথে আল্লাহপ্রেমী লোকেরা ছিল যুদ্ধ করার জন্য, আল্লাহর উদ্দেশ্যে চাপের মুখে কখনো দিধাগ্রস্থ না হয়ে,না তারা ইতস্তত করতো অথবা নিরুৎসাহিত হয়ে পড়তো। আল্লাহ অবিচলদের ভালবাসেন।"],
  "3:147": ["And their word was only that they said: Our Rabb, forgive us our offenses and our extravagance in our affair, and make firm our feet and help us against the rejecting people.", "তাদের একমাত্র উক্তি ছিল, “আমাদের প্রভু,ক্ষমা করুন- আমাদের পাপ, এবং আমাদের সীমালঙ্ঘনসমূহ, আমাদের অবস্থানকে সুদৃঢ় করুন, এবং অবিশ্বাসীদের উপর আমাদের জয় প্রদান করুন। \""],
  "3:148": ["So Allah gave them the reward of the world and the goodly reward of the world to come; and Allah loves the doers of good.", "ফলস্বরূপ, আল্লাহ তাদেরকে প্রদান করেছিলেন এই দুনিয়ার পুরুস্কার, এবং পরকালের উত্তম পুরুস্কার। আল্লাহ সৎকর্মশীলদের ভালোবাসেন।"],
  "3:149": ["O you who believe, if you obey those who reject, they will turn you back on your heels and you will turn back as losers.", "হে তোমরা যারা বিশ্বাস কর, তোমরা যদি তাদেরকে মান্য কর যারা অবিশ্বাস করে,তারা তোমাদেরকে পূর্বের অবস্থায় ফিরিয়ে দেবে,তখন তোমরা শেষ পর্যন্ত পরাজিত হবে।"],
  "3:150": ["No — Allah is your ally; and Allah is the best of helpers.", "আল্লাহ একমাত্র তোমাদের প্রভু এবং মনিব, এবং তিনিই সর্বোত্তম সমর্থনকারী।"],
  "3:151": ["We shall cast terror into the hearts of those who reject, for what they ascribed to Allah of partners for which Allah sent down no warrant; and their destination is the fire — and an evil lodging for the wrongdoers.", "যারা অবিশ্বাস করেছিল তাদের অন্তরে আমরা আতঙ্ক ছুড়ে দেব, যেহেতু তারা আল্লাহর সাথে ক্ষমতাহীন উপাস্য স্থাপন করেছিল। তাদের নিয়তি হল নরক; কতই না দুর্বিষহ আবাস সীমালঙ্ঘনকারীদের জন্য।"],
  "3:152": ["Allah has indeed been true to you in the promise when you were crushing them by Allah's leave, until when you lost heart and quarreled about the affair and disobeyed after Allah showed you what you love. Among you are those who desire the world, and among you are those who desire the world to come. Then Allah turned you away from them to test you; and Allah has indeed passed over you, and Allah is bounteous to the muminin.", "আল্লাহ তোমাদের প্রতি তাঁর অঙ্গীকার পরিপূর্ণ করেছেন, এবং তোমরা তাঁর সম্মতিক্রমে তাদের পরাজিত করেছিলে। কিন্তু এরপর তোমরা দ্বিধান্বিত হয়ে পড়েছিলে,তোমাদের নিজেদের মধ্যে বিবাদে লিপ্ত হয়েছিলে,এবং অমান্য করেছিলে তিনি তোমাদের আকাংক্ষিত (বিজয়) দেখানোর পর। কিন্তু এরপর, তোমাদের কেউ কেউ এই দুনিয়ার যুদ্ধলব্ধ মালের দ্বারা বিভ্রান্ত হয়ে পড়েছিলে,যখন অন্যান্যরা সঠিকভাবে পরকাল নিয়ে উদ্বিগ্ন ছিল। তিনি তখন তোমাদের পরীক্ষা করতে তাদের থেকে সরিয়ে দিলেন। তিনি তোমাদের মার্জনা করেছেন। আল্লাহ বিশ্বাসীদের উপর তাঁর অনুগ্রহ বর্ষন করেন।"],
  "3:153": ["When you were climbing and not turning to anyone, while the Rasul was calling you from behind you, so Allah rewarded you with grief upon grief, that you might not grieve for what escaped you nor for what befell you. And Allah is well aware of what you do.", "স্মরণ কর যে,তোমরা (যুদ্ধলব্ধ মালের পিছনে) হুমড়ি খেয়ে পড়েছিলে,কারো প্রতি কোন দৃষ্টিপাত না করে,এমনকি যখন বার্তাবাহক তোমাদেরকে পিছন থেকে ডাকছিল। ফলস্বরুপ, তিনি একটি দুর্দশাকে অন্যটি দ্বারা প্রতিস্থাপন করেছিলেন, যাতে তোমাদের শোক করতে না হয় তোমাদের হাত-ছাড়া হয়েছিল এমন কোনকিছুর উপর, অথবা যন্ত্রণা না পেতে হয় এমন কোন কষ্টের কারনে যা তোমরা ভোগ করেছিলে। আল্লাহ তোমাদের করা সবকিছু সম্পর্কে অবগত।"],
  "3:154": ["Then after the grief Allah sent down upon you security — a slumber overcoming a party of you, while a party had their souls trouble them, thinking of Allah other than the truth — the thought of the pagan way. They say: Is there any part in the affair for us? Say: Truly the whole affair belongs to Allah. They hide in themselves what they do not disclose to you, saying: If we had any part in the affair, we would not have been killed here. Say: If you had been in your houses, those for whom killing was decreed would have marched out to their resting-places. And so that Allah may test what is in your breasts and purify what is in your hearts; and Allah knows what the breasts hide.", "এই প্রতিবন্ধকতার পর, তিনি তোমাদের উপর শান্তিময় ঘুম অবতীর্ণ করেছিলেন যা তোমাদের কাউকে কাউকে শান্ত করেছিল। তোমাদের মধ্যে অন্যরা সার্থপরভাবে তাদের নিজেদের নিয়ে উদ্বিগ্ন ছিল। তারা আল্লাহ সম্পর্কে এমন চিন্তা পোষণ করেছিল যা সঠিক ছিল না- সে একই চিন্তাসমূহ যা তারা অজ্ঞতার দিনগুলোতে পোষণ করতো। একারনে,তারা বলেছিল, \"আমাদের হাতে কি কোনকিছু আছে? বল, \"সবকিছু আল্লাহর হাতে।”তারা তাদের নিজেদের ভিতরে গোপন করেছিল, যা তারা তোমার কাছে প্রকাশ করেনি। তারা বলেছিল, \"যদি এটা আমাদের হাতে থাকত, আমাদের কেউই এই যুদ্ধে নিহত হত না।” বল, \"তোমরা যদি তোমাদের বাড়িতে অবস্থান করতে,যাদের নিহত হওয়া পূর্বনির্ধারিত ছিল তারা হামাগুড়ি দিত তাদের মৃত্যু শয্যায়।” এভাবে,আল্লাহ তোমাদের পরীক্ষায় ফেলেন তোমাদের প্রকৃত অভিপ্রায়কে প্রকাশ করতে,এবং পরীক্ষা করতে তোমাদের অন্তরে কি আছে। আল্লাহ গভীরতম  চিন্তাসমূহ সম্পর্কে সম্পূর্ণ অবগত।"],
  "3:155": ["Truly those of you who turned away on the day the two hosts met — it was only the satan who made them stumble for some of what they earned; and Allah has indeed passed over them. Truly Allah is forgiving, forbearing.", "নিশ্চয়, তোমাদের মধ্যে যারা পিছু হটেছিল দুই সেনাবাহিনীর সংঘর্ষের দিনে,তারা শয়তানের দ্বারা প্রতারিত হয়েছিল। এটা প্রতিফলন করে কিছু (মন্দ) কর্ম, যা তারা করেছিল। আল্লাহ তাদের মার্জনা করেছেন। আল্লাহ ক্ষমাশীল, সহিষ্ণু।"],
  "3:156": ["O you who believe, do not be like those who rejected and said of their brothers when they journeyed in the land or were raiding: If they had been with us, they would not have died and would not have been killed — so that Allah may make that a regret in their hearts. And Allah gives life and causes death; and Allah sees what you do.", "হে তোমরা যারা বিশ্বাস কর, তাদের মতো হইয়ো না যারা অবিশ্বাস করেছিল এবং তাদের আত্মীয়দের বলেছিল, যারা যুদ্ধের জন্য ভ্রমন করেছিল অথবা একত্রিত হয়েছিল, “তারা যদি আমাদের সাথে থাকতো,তবে তারা মারা যেত না অথবা নিহত হতো না”। আল্লাহ এটাকে তাদের হৃদয়ে একটি তীব্র শোকের উৎসে পরিণত করেছেন। আল্লাহ জীবন এবং মৃত্যু নিয়ন্ত্রন করেন। আল্লাহ তোমাদের করা সবকিছুর দ্রষ্টা।"],
  "3:157": ["And if you are killed in Allah's path or die — forgiveness from Allah and mercy are better than what they amass.", "তোমরা আল্লাহর উদ্দেশ্য নিহত হও অথবা মারা যাও, তারা যা কিছু জমা করে তার চেয়ে আল্লাহর ক্ষমা,এবং দয়া অনেক উত্তম।"],
  "3:158": ["And whether you die or are killed, to Allah you shall be gathered.", "তোমরা মারা যাও অথবা নিহত হও, তোমাদেরকে আল্লাহর সামনে ডাকা হবে।"],
  "3:159": ["So by mercy from Allah you were gentle to them; and had you been harsh, hard of heart, they would have scattered from around you. So pardon them and seek forgiveness for them and consult them in the affair; then when you resolve, rely upon Allah. Truly Allah loves those who rely.", "এটা আল্লাহর করুণা ছিল যে তুমি তাদের প্রতি দয়াশীল হয়েছিলে। তুমি যদি কঠোর এবং ছোট মনের হতে,তাহলে তারা তোমাকে পরিত্যাগ করতো। অতএব, তুমি তাদেরকে মার্জনা করবে এবং তাদের জন্য ক্ষমা প্রার্থনা করবে,এবং তাদের সাথে পরামর্শ করবে। তোমরা একবার একটি সিদ্ধান্ত নিলে,তোমাদের পরিকল্পনা সম্পন্ন কর, এবং আল্লাহর প্রতি আস্থা রাখো। আল্লাহ তাদেরকে ভালবাসেন যারা তার প্রতি আস্থা রাখে।"],
  "3:160": ["If Allah helps you, none can overcome you; and if Allah forsakes you, who is it that can help you after that? And upon Allah let the muminin rely.", "যদি আল্লাহ তোমাদেরকে সমর্থন করেন, কেউ তোমাদেরকে পরাজিত করতে পারে না। এবং যদি তিনি তোমাদেরকে পরিত্যাগ করেন, আর কে তোমাদেরকে সমর্থন করতে পারে? বিশ্বাসীরা আল্লাহর প্রতি আস্থা রাখবে।"],
  "3:161": ["And it is not for a Nabi to embezzle; and whoever embezzles shall bring what he embezzled on the day of rising. Then every soul is paid in full what it earned, and they will not be wronged.", "এমনকি নবী তার নির্ধারিত অংশের বেশি যুদ্ধলব্ধ সম্পদ নিতে পারে না। যে কেউ তার ন্যায্য অংশের বেশি নেয়, তাকে এর হিসাব দিতে হবে পুনরুত্থান দিবসে। অর্থাৎ,যখন প্রত্যেক আত্মাকে প্রতিফল দেওয়া হয, সেজন্য যা কিছু সে অর্জন করেছে,সামান্যতম অবিচার ছাড়াই।"],
  "3:162": ["So is one who follows the good pleasure of Allah like one who meets with wrath from Allah, whose destination is hell? And an evil arrival it is.", "যে ব্যক্তি আল্লাহর সন্তুষ্টি অন্বেষণ করে কি একই, সে ব্যক্তির মত যে আল্লাহর তীব্র ক্রোধ টেনে আনে এবং তার নিয়তি হল নরক, সবচেয়ে দুর্দশাগ্রস্ত আবাস।"],
  "3:163": ["They are degrees in Allah's sight, and Allah sees what they do.", "নিশ্চিতভাবে,তারা আল্লাহর কাছে বিভিন্ন পদে অধিষ্ঠিত। আল্লাহ তাদের করা সবকিছুর দ্রষ্টা।"],
  "3:164": ["Allah has indeed bestowed a favor upon the muminin when Allah raised up among them a Rasul from themselves, reciting Allah's verses to them and purifying them and teaching them the Book and the wisdom, though before that they were in manifest error.", "আল্লাহ বিশ্বাসীদের আশীর্বাদপুষ্ট করেছেন, তাদের মাঝে তাদের মধ্য থেকে একজন বার্তাবাহক উত্থিত করে,তাদের জন্য তাঁর প্রত্যাদেশসমূহ আবৃত্তি করতে,এবং তাদের পরিশুদ্ধ করতে,এবং তাদেরকে ঐশীগ্রন্থ ও প্রজ্ঞা শিক্ষা দিতে। এর আগে,তারা পুরোপুরি পথভ্রষ্ট হয়ে গিয়েছিল।"],
  "3:165": ["Or when a misfortune befell you — you had struck a misfortune the like of it — you said: From where is this? Say: It is from yourselves. Truly Allah has power over everything.", "এখন তোমরা যে একটি প্রতিবন্ধকতা ভোগ করেছ, এবং এমনকি যদিও তোমরা এর দ্বিগুণ পরিমাণ দুর্ভোগ চাপিয়েছিলে (তোমাদের শত্রুদের উপর),তোমরা বলেছিলে,\"কেন এটা আমাদের প্রতি ঘটেছিল? বল, \"এটা তোমাদের নিজেদের কর্মের একটি প্রতিফল\"। আল্লাহ সর্বশক্তিমান।"],
  "3:166": ["And whatever befell you on the day the two hosts met was by Allah's leave, and so that Allah may know the muminin.", "দুই সেনাবাহিনীর সংঘর্ষের দিনে যা তোমাদেরকে দুর্দশাগ্রস্ত করেছিল তা আল্লাহর ইচ্ছা অনুযায়ী ছিল, এবং বিশ্বাসীদের পৃথক করার জন্য।"],
  "3:167": ["And so that Allah may know the munafiqin: and it was said to them: Come, fight in Allah's path or repel. They said: If we knew fighting, we would have followed you. They were closer to rejection that day than to faith. They say with their mouths what is not in their hearts, and Allah knows best what they hide.", "এবং ভণ্ডদের প্রকাশ করার জন্য, যাদেরকে বলা হয়েছিল, “আসো,আল্লাহর উদ্দেশ্যে যুদ্ধ কর, অথবা অবদান রাখ”।তারা বলেছিল, “আমরা যদি জানতাম কিভাবে যুদ্ধ করতে হয়, আমরা তোমার সাথে যোগদান করতাম”। তখন তারা বিশ্বাসের চেয়ে অবিশ্বাসের নিকটবর্তী ছিল। তারা তাদের মুখে বলেছিল যা তাদের হৃদয়ে ছিল না। আল্লাহ জানেন যা তারা গোপন করে।"],
  "3:168": ["Those who said of their brothers, while they sat back: If they had obeyed us, they would not have been killed. Say: Then ward off death from yourselves, if you are sadiq.", "তারা তাদের আত্মীয়দের ব্যাপারে বলেছিল, যখন তারা পেছনে থেকে গিয়েছিল, “তারা যদি আমাদের কথা মান্য করতো,তারা নিহত হতো না”। বল, “তাহলে তোমাদের নিজেদের মৃত্যুকে প্রতিহত কর, যদি তোমরা সত্যবাদী হয়ে থাকো”।"],
  "3:169": ["And do not reckon those killed in Allah's path as dead; rather, they are alive with their Rabb, provided for.", "এটা ভেবো না যে যারা আল্লাহর উদ্দেশ্যে নিহত হয় তারা মৃত; তারা তাদের প্রভুর নিকট জীবিত, উপভোগ করছে তাঁর জীবিকা।"],
  "3:170": ["Rejoicing in what Allah has given them of bounty, and rejoicing for those who have not yet joined them from behind them: no fear is upon them, nor do they grieve.", "তারা আল্লাহর অনুগ্রহে আনন্দ করছে,এবং তাদের কাছে তাদের সে সহযোদ্ধাদের জন্য সুসংবাদ আছে যারা তাদের সাথে মৃত্যুবরণ করেনি,যে তাদের কোন ভয় নেই, না তারা শোক করবে।"],
  "3:171": ["Rejoicing at a blessing from Allah and bounty, and that Allah does not waste the reward of the muminin.", "তাদের জন্য সুসংবাদ আছে,আল্লাহর আশীর্বাদ এবং অনুগ্রহের, এবং যে আল্লাহ কখনো বিশ্বাসীদের পুরষ্কৃত করতে ব্যর্থ হন না।"],
  "3:172": ["Those who answered Allah and the Rasul after the wound struck them — for those of them who did good and kept their duty is a tremendous reward.", "যারা আল্লাহ এবং বার্তাবাহকের ডাকে সাড়া দেয়, তারা যে নিপীড়ন ভোগ করে তা সত্ত্বেও, এবং তাদের ভাল কাজসমূহ চালিয়ে যায়, এবং একটি ন্যায়নিষ্ঠ জীবন অতিবাহিত করে,তাদের জন্য রয়েছে এক মহা পুরষ্কার।"],
  "3:173": ["Those to whom people said: The people have gathered against you, so fear them; but it only increased them in faith, and they said: Allah is sufficient for us, and an excellent guardian is Allah.", "যখন লোকেরা তাদেরকে বলে,\"লোকেরা তোমাদের বিরুদ্ধে একত্রিত হয়েছে; তোমাদের উচিত তাদের ভয় করা,”এটা শুধু তাদের বিশ্বাসকে দৃড় করে এবং তারা বলে,\"আল্লাহ আমাদের জন্য যথেষ্ট; তিনি সবচেয়ে উত্তম রক্ষাকারী।"],
  "3:174": ["So they returned with a blessing from Allah and bounty; no harm touched them, and they followed the good pleasure of Allah; and Allah is the Owner of tremendous bounty.", "TBD"],
  "3:175": ["That is only the satan frightening his allies. So do not fear them, and fear Me — if you are muminin.", "এটা শয়তানের পদ্ধতি,তার অধীনস্থদের ভিতরে ধীরে ধীরে ভয়ের সঞ্চার করা। তাদেরকে ভয় করো না এবং পরিবর্তে আমাকে ভয় কর, যদি তোমরা বিশ্বাসী হও।"],
  "3:176": ["And do not grieve for those who hasten into rejection; they will not harm Allah anything. Allah intends to give them no portion in the world to come, and for them is a tremendous punishment.", "TBD"],
  "3:177": ["Truly those who purchased rejection in exchange for faith will not harm Allah anything, and for them is a painful punishment.", "যারা অবিশ্বাসকে পছন্দ করে,বিশ্বাসের বদলে,তারা আল্লাহর সামান্যতম ক্ষতি করে না; তারা টেনে এনেছে যন্ত্রণাদায়ক শাস্তি।"],
  "3:178": ["And let not the rejecters reckon that Our respite to them is good for themselves; We only respite them so that they may increase in sin, and for them is a humiliating punishment.", "অবিশ্বাসীরা যেন না ভাবে যে আমরা তাদের নিজেদের ভালোর জন্য তাদের পরিচালনা করবো। আমরা শুধু তাদের পরিচালিত করি তাদের পাপময়তা নিশ্চিত করতে। তারা টেনে এনেছে অপমানজনক শাস্তি।"],
  "3:179": ["It is not for Allah to leave the muminin upon what you are upon until Allah distinguishes the vile from the good; nor is Allah to give you access to the unseen. But Allah chooses from among the Rasuls whom Allah wills. So believe in Allah and Allah's rusul; and if you believe and keep your duty, then for you is a tremendous reward.", "আল্লাহ বিশ্বাসীদের পরিত্যাগ করেন না যেমন তোমরা করো,ভাল থেকে মন্দকে পৃথক করা ছাড়া। না আল্লাহ তোমাদেরকে ভবিষ্যৎ অবহিত করেন, তবে আল্লাহ এমন জ্ঞান তাঁর বার্তাবাহকদের মধ্যে যাকে তিনি পছন্দ করেন তার উপর অর্পণ করেন। সেজন্য, তোমরা আল্লাহ এবং তাঁর বার্তাবাহকদেরকে বিশ্বাস করবে। যদি তোমরা বিশ্বাস করো এবং সৎজীবন যাপন করো,তোমরা এক মহা প্রতিদান প্রাপ্ত হও।"],
  "3:180": ["And let not those who stint reckon that what Allah has given them of bounty that they stint is good for them; no, it is evil for them. They shall be collared with what they stinted on the day of rising. And to Allah belongs the inheritance of the heavens and the earth, and Allah is well aware of what you do.", "যারা আটকে রাখে এবং মজুত করে আল্লাহর দান, তারা যেন না ভাবে যে এটা তাদের জন্য ভাল; এটা তাদের জন্য মন্দ। কারন পুনুরুত্থানের দিবসে তারা তাদের মজুত তাদের গলায় বেষ্টন করে বহন করবে। আল্লাহ আসমান সমূহ এবং পৃথিবীর চূড়ান্ত উত্তরাধিকারী। আল্লাহ সবকিছু পূর্ণভাবে অবগত যা তোমরা করো।"],
  "3:181": ["Allah has indeed heard the saying of those who say: Allah is poor and we are rich. We shall write down what they say and their killing of the nabis without right, and We shall say: Taste the punishment of the burning.", "আল্লাহ তাদের কথা শুনেছেন যারা বলেছিল, \"আল্লাহ গরীব, পক্ষান্তরে আমরা ধনী। “তারা যা বলেছিল আমরা এর সবকিছু রেকর্ড  করবো,ঠিক যেমন আমরা রেকর্ড করেছিলাম, তাদের অন্যায়ভাবে নবীদেরকে হত্যা করা এবং আমরা বলব, \"নরকের শাস্তি ভোগ করো।"],
  "3:182": ["That is for what your hands have sent ahead, and that Allah is not unjust to the servants.", "\"এটা তোমাদের নিজেদের কর্মসমূহের প্রতিফল।”আল্লাহ লোকদের প্রতি কখনো অন্যায়কারী নন।"],
  "3:183": ["Those who said: Allah has pledged to us that we should not believe any Rasul until one brings us an offering which the fire consumes. Say: Messengers came to you before me with clear proofs and with what you speak of — so why did you kill them, if you are sadiq?", "এরা তারাই যারা বলেছিল, \"আল্লাহ আমাদের সাথে একটি চুক্তি করেছেন যে,আমরা কোন বার্তাবাহককে বিশ্বাস করবো না,যদি না সে একটি উৎসর্গীকৃত বস্তু উপস্থাপন করে,যা আগুনে গ্রাস হয়ে যায়। বল, “আমার আগে বার্তাবাহকরা তোমাদের কাছে সুস্পষ্ট প্রমানাদি সহ এসেছিল, তোমরা যা এইমাত্র দাবী করলে তা সহ। তাহলে,কেন তোমরা তাদেরকে হত্যা করেছিলে,যদি তোমরা সত্যবাদী হও? \""],
  "3:184": ["But if they deny you — so rusul were denied before you, who came with clear proofs and the scriptures and the enlightening Book.", "যদি তারা তোমাকে প্রত্যাক্ষান করে,তোমার আগে বার্তাবাহকদের প্রত্যাক্ষান করা হয়েছিল, যদিও তারা নিয়ে এসেছিল প্রমানাদি,যবুর, এবং আলোকময়★  কিতাব।"],
  "3:185": ["Every soul tastes death; and only on the day of rising are you paid your rewards in full. Whoever is drawn far from the fire and admitted to the garden has indeed won. And this worldly life is nothing but the enjoyment of deception.", "প্রত্যেক ব্যক্তি মৃত্যুর স্বাদ গ্রহণ করে,এরপর পুনরুত্থান দিবসে তোমরা তোমাদের প্রতিফল গ্রহণ করো। যে কেউ অল্পের জন্য নরক থেকে বাঁচে,এবং স্বর্গে যেতে সফল হয়, সে অর্জন করেছে এক মহা বিজয়। এই দুনিয়ার জীবন একটি বিভ্রমের চেয়ে বেশি কিছু নয়।"],
  "3:186": ["You shall surely be tested in your wealth and your souls, and you shall surely hear much hurt from those who were given the Book before you and from those who ascribe partners. And if you are sabir and keep your duty — truly that is among the resolute affairs.", "তোমরা নিশ্চিতভাবে পরিক্ষিত হবে,তোমাদের অর্থ এবং তোমাদের জীবনের মাধ্যমে,এবং তোমরা শুনবে যারা ঐশীগ্রন্থ গ্রহণ করেছে তাদের থেকে,এবং প্রতিমা উপাসকদের থেকে,অনেক অপমান। যদি তোমরা দৃঢ়তার সাথে অধ্যবসায়ী হও এবং সৎ জীবন যাপন করো,এটা তোমাদের বিশ্বাসের দৃঢ়তা প্রমান করবে।"],
  "3:187": ["And when Allah took the pledge of those who were given the Book: You shall make it clear to the people and not hide it. But they cast it behind their backs and sold it for a small price. And an evil purchase it is.", "আল্লাহ একটি অঙ্গীকার নিয়েছিলেন তাদের থেকে যারা ঐশীগ্রন্থ গ্রহণ করেছিলঃ “তোমরা এটি মানুষের কাছে ঘোষনা করবে,এবং কখনো এটি গোপন করবে না”। কিন্তু,তারা এটি উপেক্ষা করেছিল তাদের অগোচরে,এবং এটির বেচা-কেনা করেছিল একটি সস্তা মূল্যের জন্য। কি এক শোচনীয় বাণিজ্য।"],
  "3:188": ["Do not reckon those who rejoice in what they have brought and love to be praised for what they did not do — do not reckon them secure from the punishment; and for them is a painful punishment.", "যারা তাদের কাজের ব্যাপারে গর্ব করে,এবং এমন কিছুর জন্য প্রশংসিত হওয়ার আকাঙ্ক্ষা করে যা প্রকৃতপক্ষে তারা করে নাই, তাদের চিন্তা করা উচিৎ নয় যে,তারা কৌশলে শাস্তি এড়াতে পারে। তারা টেনে এনেছে একটি যন্ত্রণাদায়ক শাস্তি।"],
  "3:189": ["And to Allah belongs the kingship of the heavens and the earth, and Allah has power over everything.", "আকাশ সমূহ এবং পৃথিবীর সার্বভৌমত্ব আল্লাহর। আল্লাহ সর্বশক্তিমান।"],
  "3:190": ["Truly in the creation of the heavens and the earth and the alternation of night and day are signs for people of understanding.", "আকাশমন্ডলী ও পৃথিবীর সৃষ্টিতে,এবং রাত ও দিনের পালা-বদলে,তাদের জন্য নিদর্শন রয়েছে যারা বুদ্ধিমত্তার অধিকারী।"],
  "3:191": ["Those who remember Allah standing and sitting and on their sides, and reflect upon the creation of the heavens and the earth: Our Rabb, You did not create this in vain; glory be to You; so protect us from the punishment of the fire.", "তারা দাঁড়িয়ে, বসে, ও শায়িত অবস্থায় আল্লাহকে স্মরণ করে, এবং তারা আকাশমন্ডলী  ও পৃথিবীর সৃষ্টির বিষয়ে ভাবে: “আমাদের প্রভু, আপনি এই সবকিছু নিরর্থক সৃষ্টি করেননি। আপনি মহিমান্বিত। আমাদেরকে নরকের শাস্তি থেকে রক্ষা করুন।"],
  "3:192": ["Our Rabb, whoever You admit into the fire — You have disgraced them; and the wrongdoers have no helpers.", "\"আমাদের প্রভু,যাদেরকে আপনি নরকে দেন তারা হচ্ছে সেই লোকেরা,যাদেরকে আপনি পরিত্যাগ করেছেন। এরকম সীমালঙ্ঘনকারীদের কোন সাহায্যকারী নেই।"],
  "3:193": ["Our Rabb, we heard a caller calling to faith: Believe in your Rabb — and we believed. Our Rabb, so forgive us our offenses and wipe away our evil deeds, and take us to Yourself with the abrar.", "\"আমাদের প্রভু,আমরা শুনেছি একজন আহবায়ককে বিশ্বাসের দিকে আহবান করতে এবং প্রচার করতে: 'তোমরা তোমাদের প্রভুকে বিশ্বাস করবে,' এবং আমরা বিশ্বাস করেছি। আমাদের প্রভু,আমাদের সীমালঙ্ঘনসমূহ ক্ষমা করুন, আমাদের পাপসমূহ ক্ষমা করুন, এবং আমাদেরকে সৎকর্মশীল বিশ্বাসী হিসেবে মৃত্যু দিন।"],
  "3:194": ["Our Rabb, and give us what You promised us through Your rusul, and do not disgrace us on the day of rising. Truly You do not break the promise.", "\"আমাদের প্রভু,আমাদেরকে সেই আশীর্বাদসমূহ বর্ষন করুন, যা আপনি আপনার বার্তাবাহকদের মাধ্যমে আমাদেরকে প্রতিশ্রুতি দিয়েছিলেন, এবং পুনরুত্থান দিবসে আমাদেরকে পরিত্যাগ করবেন না। আপনি কখনো প্রতিশ্রুতি ভঙ্গ করেন না।\""],
  "3:195": ["So their Rabb answered them: I do not waste the work of any worker among you, whether male or female — some of you are from others. As for those who emigrated and were driven out of their homes and were hurt in My path, and fought and were killed — I shall surely wipe away their evil deeds from them and surely admit them into gardens with rivers flowing beneath, a reward from Allah; and with Allah is the excellent reward.", "তাদের প্রভু তাদের প্রতি সাড়া দিয়েছিলেন: \"আমি কখনো তোমাদের মধ্যে কোন কর্মীকে তোমাদের করা কোন কাজের জন্য প্রতিদান দিতে ব্যর্থ হই না,তোমরা নারী হও অথবা পুরুষ হও- তোমরা একে অন্যের সমান। তাই, যারা দেশান্তরিত হয়, এবং তাদের ঘর-বাড়ি থেকে উচ্ছেদ হয়, এবং আমার কারনে নির্যাতিত হয়, এবং যুদ্ধ করে ও নিহত হয়, আমি অবশ্যই তাদের পাপসমূহ ক্ষমা করবো এবং তাদেরকে প্রবাহিত ঝর্নাসহ বাগানসমূহে প্রবেশ করাব।”এরকমই আল্লাহর পক্ষ থেকে প্রতিদান। আল্লাহ পরম প্রতিদানের অধিকারী।"],
  "3:196": ["Let not the moving about of the rejecters in the towns deceive you.", "অবিশ্বাসীদের আপাত সফলতায় অভিভূত হইও না।"],
  "3:197": ["A little enjoyment, then their destination is hell — and an evil couch it is.", "তারা শুধু সাময়িকভাবে উপভোগ করে,তারপর নরকে এসে শেষ হয়; কি এক শোচনীয় নিয়তি!"],
  "3:198": ["But for those who keep their duty to their Rabb are gardens with rivers flowing beneath, abiding therein forever — hospitality from Allah; and what is with Allah is better for the salihin.", "আর তাদের জন্য যারা তাদের প্রভুকে মান্য করে,তারা প্রবাহিত ঝর্নাসহ বাগানসমূহের যোগ্য হয়েছে; তারা সেখানে চিরকাল বসবাস করে। এরকমই হচ্ছে তাদেরকে আল্লাহর দেয়া আবাস। যাকিছু আল্লাহর কাছে আছে তা সৎকর্মশীলদের জন্য অনেক উত্তম।"],
  "3:199": ["And indeed among the people of the Book are those who believe in Allah and what was sent down to you and what was sent down to them, humbled before Allah. They do not sell the signs of Allah for a small price. Those have their reward with their Rabb; truly Allah is swift in reckoning.", "নিশ্চিতভাবে,আগের ঐশীগ্রন্থসমূহের কিছু অনুসারীরা বিশ্বাস করে আল্লাহতে,এবং যা তোমার কাছে প্রকাশিত হয়েছিল, এবং যা তাদের কাছে প্রকাশিত হয়েছিল। তারা আল্লাহকে ভক্তি করে,এবং তারা কখনো আল্লাহর প্রত্যাদেশসমূহ সামান্য মূল্যে বিক্রি করে না। এরা তাদের প্রভুর কাছ থেকে প্রতিফল গ্রহণ করবে। আল্লাহ হিসাব গ্রহণে সবচেয়ে দক্ষ।"],
  "3:200": ["O you who believe, be of the sabirin and vie in patience and hold together, and keep your duty to Allah, that perhaps you may succeed.", "হে তোমরা যারা বিশ্বাস কর, তোমরা অবিচল হবে,তোমরা অধ্যবসায়ী হবে,তোমরা ঐক্যবদ্ধ হবে,তোমরা আল্লাহকে মান্য করবে,যাতে তোমরা সফল হতে পার।"],
  "4:1": ["O humankind, be mindful of your Rabb who created you from one soul, and created from it its mate, and scattered from the two many men and nisa. And be mindful of Allah, in whose name you demand from one another, and of the ties of kinship. Truly Allah has been a watcher over you.", "হে লোকেরা,তোমাদের প্রভুকে মান্য কর; সেই একজন যিনি তোমাদেরকে এক ব্যক্তি  থেকে সৃষ্টি করেছিলেন, এবং এর থেকে এর সঙ্গিনী সৃষ্টি করেছিলেন, এরপর সেই দুইজন থেকে অনেক পুরুষ ও নারী বিস্তার করেছেন। তোমরা আল্লাহর প্রতি মনোযোগী হবে,যার নামে তোমরা শপথ কর, এবং পিতামাতাকে সন্মান কর। আল্লাহ তোমাদেরকে লক্ষ্য করছেন।"],
  "4:2": ["And give the orphans their wealth, and do not substitute the vile for the good, and do not devour their wealth into your wealth. Truly that has been a tremendous sin.", "তোমরা এতিমদেরকে তাদের ন্যায্য সমত্তিসমুহ হস্তান্তর করবে। ভালটিকে মন্দ দিয়ে প্রতিস্থাপন করো না,এবং তাদের সম্পত্তিগুলো গ্রাস কর না,তাদের গুলোর সাথে তোমাদের গুলো মিশিয়ে। এটা হবে একটি ঘোর অন্যায়।"],
  "4:3": ["And if you fear that you cannot act equitably toward the orphans, then marry the nisa who seem good to you, two, three, or four. But if you fear that you will not be just, then one only, or what your right hands own. That is nearer, that you not act unjustly.", "যদি তোমরা এটি এতিমদের জন্য সর্বোত্তম মনে কর, তোমরা তাদের মাদেরকে বিয়ে করতে পার - তোমরা বিয়ে করতে পার দুই, তিন অথবা চারটি। যদি তোমরা ভয় করো যে পাছে তোমরা পক্ষপাতদুষ্ট হয়ে পড়বে,তাহলে শুধু একটিতেই, অথবা আগে থেকে তোমাদের যা রয়েছে তা নিয়ে সন্তুষ্ট থাকবে। উপরন্তু,এভাবে  খুব সম্ভবত  তোমরা আর্থিক কষ্ট এড়াতে পার।"],
  "4:4": ["And give the nisa their due portions gladly; but if they are pleased to give you back some of it willingly, then consume it with enjoyment and wholesome ease.", "তোমরা নারীদেরকে তাদের নির্ধারিত দেনমহর দিবে,ন্যায়সঙ্গতভাবে। যদি তারা স্বেচ্ছায় কোন কিছু ছেড়ে দেয়, তাহলে তোমরা তা গ্রহন করতে পার; এটি আইনসম্মতভাবে তোমাদের।"],
  "4:5": ["And do not give the foolish your wealth which Allah has made a mainstay for you. Provide for them from it, clothe them, and speak to them kind words.", "অপরিনত এতিমদের সে সমত্তিসমুহ দিবে না যা আল্লাহ তোমাদের কাছে  অভিভাবক হিসেবে গচ্ছিত রেখেছেন। তোমরা সেখান থেকে তাদের ব্যয় বহন করবে,এবং তাদেরকে পরিধান করাবে,এবং তাদের সাথে সদাচরণ করবে।"],
  "4:6": ["Test the orphans until, when they reach marriageable age, if you perceive right course in them, hand over to them their wealth. Do not devour it extravagantly and hastily for fear they will grow up. Whoever is rich, let him abstain; whoever is needy, let him consume what is fitting. And when you hand over to them their wealth, call witnesses over them. And sufficient is Allah as reckoner.", "তোমরা এতিমদেরকে পরীক্ষা করবে যখন তারা বয়ঃসন্ধিতে পৌঁছে। যখনি তোমরা তাদেরকে যথেষ্ট পরিণত পাবে,তাদেরকে তাদের সম্পত্তি দিয়ে দাও। তারা বড় হয়ে ওঠার আগে এগুলো তাড়াতাড়ি বেহিসাবিভাবে গ্রাস করে ফেলনা। ধনী অভিভাবক কোন পারিশ্রমিক গ্রহণ করবে না,কিন্তু দরিদ্র অভিভাবক ন্যায়সঙ্গত ভাবে গ্রহণ করতে পারে। যখন তোমরা তাদেরকে তাদের সম্পত্তি দাও, তোমরা সাক্ষী রাখবে। আল্লাহ হিসাব গ্রহণকারী হিসাবে যথেষ্ট।"],
  "4:7": ["For men is an allotted share of what parents and near kin leave behind, and for nisa is an allotted share of what parents and near kin leave behind, whether it is little or much — an ordained share.", "পিতামাতা এবং আত্মীয়রা যা রেখে যায় পুরুষরা তার একটি অংশ পায়। নারিরাও তার একটি অংশ পাবে,যা পিতামাতা এবং আত্মীয়রা রেখে যায়। হোক এটি একটি ছোট অথবা একটি বড় উত্তরাধিকার, (নারীরা অবশ্যই পাবে) একটি নির্দিষ্ট অংশ।"],
  "4:8": ["And when the division is at hand and the near kin, the orphans, and the needy are present, provide for them from it and speak to them kind words.", "উত্তরাধিকারের বণ্টনের সময়, যদি আত্মীয়, এতিম, এবং অভাবগ্রস্ত বাক্তিরা উপস্থিত থাকে,তোমরা তা থেকে তাদেরকে দেবে,এবং তাদের সাথে সদয় আচরণ করবে।"],
  "4:9": ["And let those have awe who, if they were to leave behind them weak offspring, would fear for them. So let them be mindful of Allah and speak a straight saying.", "যারা তাদের নিজেদের শিশু-সন্তানদের ব্যাপারে উদ্বিগ্ন, যে যদি তারা তাদেরকে পিছনে ছেড়ে যায়, তারা আল্লাহকে মান্য করবে এবং ন্যায়পরায়ণ হবে ।"],
  "4:10": ["Truly those who devour the wealth of orphans wrongfully only devour fire into their bellies, and they shall enter a blaze.", "যারা এতিমদের সম্পত্তি অন্যায়ভাবে গ্রাস করে,আগুন ভক্ষন করে তাদের পেটে,এবং কষ্টভোগ করবে নরকে।"],
  "4:11": ["Allah charges you concerning your children: for the male, the share of two females. If they are nisa, more than two, then for them two-thirds of what he left; and if she is one, then for her the half. And for his parents, for each one of the two a sixth of what he left, if he has a child. If he has no child and his parents inherit him, then for his mother a third. And if he has brothers, then for his mother a sixth — after any charge to be enjoined or a debt. Your parents and your children: you know not which of them is nearer to you in benefit. An ordinance from Allah. Truly Allah has been knowing, wise.", "আল্লাহ তোমাদের সন্তানদের সুবিধার জন্য একটি উইল জারি করেন; পুরুষরা নারীর অংশের দ্বিগুণ পায়। যদি উত্তরাধিকারীরা শুধু নারী হয়, দুইয়ের বেশি, তারা দুই-তৃতীয়াংশ পায় যা রেখে যাওয়া হয়। যদি শুধু এক কন্যা রেখে যায়, সে অর্ধেক পাবে। মৃত ব্যক্তির পিতা-মাতাদের প্রত্যেকে উত্তরাধিকারের এক-ষষ্ঠাংশ পাবে, যদি মৃত ব্যক্তি কোন সন্তানাদি রেখে যায়। যদি সে কোন সন্তানাদি রেখে না যায়, এবং তার পিতা-মাতাই শুধু উত্তরাধিকারী হয়, সেই মা এক-তৃতীয়াংশ পাবে। যদি তার ভাই-বোন থাকে, তাহলে মা এক-ষষ্ঠাংশ পাবে। এই সবকিছু, মৃত ব্যক্তির রেখে যাওয়া কোন উইল পরিপূর্ণ করার পর, এবং সকল ঋন পরিশোধ করার পর। যখন এটি তোমাদের পিতামাতা এবং সন্তানদের ক্ষেত্রে হয়, তোমরা জানো না তাদের কারা প্রকৃতপক্ষে তোমাদের কাছে সর্বোত্তম এবং সবচেয়ে উপকারী। এটি আল্লাহর আইন। আল্লাহ সর্বজ্ঞ, পরম জ্ঞানী।"],
  "4:12": ["And for you is half of what your spouses leave, if they have no child. But if they have a child, then for you a fourth of what they leave — after any charge they enjoin or a debt. And for them a fourth of what you leave, if you have no child; but if you have a child, then for them an eighth of what you leave — after any charge you enjoin or a debt. And if a man or an imra'a die leaving neither parent nor child, and he has a brother or sister, then for each one of the two a sixth; but if they are more than that, then they are partners in the third — after any charge to be enjoined or a debt, without harm. A charge from Allah. And Allah is knowing, forbearing.", "তোমরা অর্ধেক পাও যা তোমাদের স্ত্রীরা ফেলে যায়, যদি তাদের কোন সন্তানাদি না থাকে। যদি তাদের সন্তানাদি থাকে,তোমরা এক-চতুর্থাংশ পাও যা তারা ফেলে যায়। এই সবকিছু,তাদের রেখে যাওয়া কোন উইল পরিপূর্ণ করার পর, এবং সকল ঋন পরিশোধ করার পর। তারা এক-চতুর্থাংশ পায় যা তোমরা ফেলে যাও, যদি তোমাদের সন্তানাদি না থাকে। যদি তোমাদের সন্তানাদি থাকে,তারা এক-অষ্টমাংশ পায় যা তোমরা রেখে যাও। এই সবকিছু,তোমাদের রেখে যাওয়া কোন উইল পরিপূর্ণ করার পর, এবং সকল ঋন পরিশোধ করার পর। যদি মৃত পুরুষ অথবা নারী নিঃসঙ্গ হয়, এবং দুইজন ভাই বা বোন রেখে যায়, পুরুষ অথবা নারী,তারা প্রত্যেকেই উত্তরাধিকারের এক-ষষ্ঠাংশ পায়। যদি আরো ভাই-বোন থাকে,তখন তারা সমভাবে উত্তরাধিকারের এক-তৃতীয়াংশ ভাগ করে নেয়। এই সবকিছু,কোন উইল পরিপূর্ণ করার পর, এবং সকল ঋন পরিশোধ করার পর, যাতে কেউই আঘাতপ্রাপ্ত না হয়। এটি আল্লাহর দ্বারা জারীকৃত একটি উইল। আল্লাহ সর্বজ্ঞ, সহিষূ।"],
  "4:13": ["Those are the limits set by Allah. Whoever obeys Allah and the Rasul, Allah will admit him into gardens beneath which rivers flow, abiding therein forever. And that is the tremendous triumph.", "এগুলো আল্লাহর আইন। তারা যারা আল্লাহ এবং তাঁর বার্তাবাহককে মান্য করে,তিনি তাদেরকে প্রবেশ করাবেন প্রবাহিত ঝর্নাধারা সহ বাগানসমূহে,যেখানে তারা চিরকাল বসবাস করে। এটি শ্রেষ্ঠ বিজয়।"],
  "4:14": ["And whoever disobeys Allah and the Rasul and oversteps limits set by Allah, Allah will admit him into a fire, abiding therein forever, and for him is a humiliating punishment.", "আর সে ব্যক্তির জন্য যে আল্লাহ এবং তাঁর বার্তাবাহককে অমান্য করে,এবং তাঁর আইনগুলোর সীমালঙ্ঘন করে,তিনি তাকে নরকে প্রবেশ করাবেন, যেখানে সে চিরকাল বসবাস করে। সে এক লজ্জাকর প্রতিফল টেনে এনেছে।"],
  "4:15": ["As for those of your nisa who come to an obscenity, call four of you to witness against them. If they testify, then confine them to the houses until death takes them, or Allah makes for them a way.", "তোমাদের নারীদের মধ্যে তারা যারা ব্যভিচার করে,তোমাদের কাছে অবশ্যই তোমাদের মধ্য থেকে তাদের বিরুদ্ধে চারজন সাক্ষী থাকতে হবে। যদি তারা সাক্ষ্য প্রদান করে,তাহলে তোমরা এরকম নারীদের তাদের বাড়িতে রাখবে যতক্ষণ না পর্যন্ত তারা মারা যায়, অথবা যতক্ষণ না আল্লাহ তাদের জন্য বের হবার পথ সৃষ্টি করে দেন।"],
  "4:16": ["And the two who commit it among you, then do them harm. But if they repent and set right, then turn away from them. Truly Allah has been ever-turning, merciful.", "সেই যুগল শাস্তিপ্রাপ্ত হবে যারা ব্যাভিচারে লিপ্ত হয়। যদি তারা অনুতপ্ত হয় এবং সংশোধিত হয়, তোমরা তাদেরকে একা ছেড়ে দেবে। আল্লাহ উদ্ধার কর্তা,পরম দয়ালু।"],
  "4:17": ["Turning to Allah is only for those who do evil in ignorance, then turn soon after. Those — Allah turns to them. And Allah has been knowing, wise.", "অনুতাপ আল্লাহর দ্বারা গ্রহণযোগ্য তাদের কাছ থেকে যারা অজ্ঞতা থেকে পাপে পতিত হয়, সেক্ষেত্রে এরপর তৎক্ষণাৎ অনুতাপ করে। আল্লাহ তাদের উদ্ধার করেন। আল্লাহ সর্বজ্ঞ, পরম জ্ঞানী।"],
  "4:18": ["But turning is not for those who do evils until, when death presents itself to one of them, he says, \"I turn now\" — nor for those who die while committing kufr. Those — We have prepared for them a painful punishment.", "তাদের অনুশোচনা গ্রহণযোগ্য নয় যারা পাপ করে যতক্ষণ না মৃত্যু তাদের কাছে আসে,তখন বলে,“আমি এখন অনুশোচনা করি”। না এটা গ্রহণযোগ্য তাদের থেকে,যারা অবিশ্বাসী হিসাবে মৃত্যু বরণ করে। এদের জন্য, আমরা এক যন্ত্রণাদায়ক শাস্তি প্রস্তুত করেছি।"],
  "4:19": ["O muminin, it is not lawful for you to inherit nisa against their will, and do not hold them back to take away part of what you gave them, unless they come with a clear obscenity. And live with them in kindness. If you are averse to them, perhaps you are averse to something in which Allah places much good.", "হে তোমরা যারা বিশ্বাস করো,এটা তোমাদের জন্য আইনসিদ্ধ নয যা নারীরা ছেড়ে যায় তা উত্তরাধিকার করা,তাদের উইলের বিরুদ্ধে। তোমরা তাদেরকে কোন কিছু ছেড়ে দিতে বল প্রয়োগ করবে না /  বল প্রয়োগ করবে না কোন কিছু পরিত্যাগ করতে যা তোমরা তাদেরকে দিয়েছিলে,যদি না তারা একটি প্রমানিত ব্যাভিচার করে। তোমরা তাদের সাথে সুন্দর আচরন করবে। যদি তোমরা তাদেরকে অপছন্দ করো,হয়তো তোমরা কোনকিছুকে অপছন্দ করো যার মধ্যে আল্লাহ অনেক ভাল রেখেছেন।"],
  "4:20": ["And if you wish to replace one spouse in place of another, and you have given one of them a great sum, then do not take anything from it. Would you take it by slander and manifest sin?", "যদি তোমরা অন্য স্ত্রীকে বিয়ে করতে চাও, তোমাদের বর্তমান স্ত্রীর স্থলে,এবং তোমরা তাদের কাউকে প্রচুর দিয়ে থাকো,তোমরা কোনকিছুই ফেরত নেবে না যা তোমরা দিয়েছ। তোমরা কি তা প্রতারণাপূর্ণ ভাবে,বিদ্বেষপরায়ণ ভাবে,এবং পাপপূর্ণ ভাবে নেবে?"],
  "4:21": ["How could you take it when some of you have gone in to others, and they have taken from you a solemn pact?", "তোমরা কিভাবে তা ফেরত নিতে পার, যখন তোমরা একে-অন্যের ঘনিষ্ঠ হয়েছ, এবং তারা তোমাদের থেকে একটি সুদৃড় প্রতিজ্ঞা নিয়েছিল?"],
  "4:22": ["And do not marry nisa whom your fathers married — except what has already passed. Truly that was an obscenity and a loathing, and an evil way.", "সেই নারীকে বিয়ে কর না,যারা আগে তোমাদের পিতাদের সহিত বিবাহিত ছিল- বিদ্যমান বিবাহসমূহ নিষ্কৃতি প্রাপ্ত এবং ভঙ্গ করবে না- কারণ এটি একটি গুরুতর অপরাধ, এবং ঘৃণ্য কাজ।"],
  "4:23": ["Forbidden to you are your mothers, your daughters, your sisters, your paternal aunts, your maternal aunts, your brother's daughters, your sister's daughters, your mothers who suckled you, your suckling sisters, your mothers-in-law, your stepdaughters who are in your keeping from the nisa you have gone in to — but if you have not gone in to them, there is no blame on you — and the nisa of your sons who are from your loins; and that you gather together two sisters, except what has already passed. Truly Allah has been forgiving, merciful.", "তোমাদের জন্য নিষিদ্ধ (বিয়ের করার ক্ষেত্রে) তোমাদের মায়েরা,তোমাদের কন্যারা,তোমাদের বোনেরা,তোমাদের পিতাদের বোনেরা,তোমাদের মাতাদের বোনেরা,তোমাদের ভাইয়ের কন্যারা,তোমাদের বোনের কন্যারা,তোমাদের স্তন্য দানকারী মায়েরা,সে বালিকারা যারা স্তন্যপ্রাপ্ত হয়েছিল সে একই নারী থেকে যেমন তোমরা হয়েছিলে,তোমাদের স্ত্রীদের মায়েরা,তোমাদের স্ত্রীদের কন্যারা যাদের সাথে তোমরা বিয়ে পূর্ন করেছ - যদি বিয়ে পূর্নতাপ্রাপ্ত না হয়, তোমরা সে কন্যাকে বিয়ে করতে পার। তোমাদের জন্য আরো নিষিদ্ধ সে নারীরা যারা তোমাদের ঔরসজাত পুত্রদের বিবাহিত ছিল। এছাড়া,তোমরা একই সময়ে দুই বোনের সাথে বিবাহিত  থাকবে না- কিন্তু বিদ্যমান বিয়ে ভেঙো না। আল্লাহ ক্ষমাশীল, পরম দয়ালু।"],
  "4:24": ["And the fortified among nisa, except what your right hands own — that Allah has decreed upon you. And permitted to you, beyond that, is that you seek with your wealth in fortified chastity, not in license. Then whatever enjoyment you take from them, give them their ordained wages; and there is no blame on you in what you mutually agree upon after the ordinance. Truly Allah has been knowing, wise.", "আরো নিষিদ্ধ সে নারীরা যারা ইতোমধ্যে বিবাহিত, যদি না তারা তাদের অবিশ্বাসী স্বামীদের কাছ থেকে পালিয়ে আসে যারা তোমাদের সাথে যুদ্ধরত। এগুলো তোমাদের কাছে আল্লাহর প্রত্যাদেশ। অন্য সকল শ্রেনীসমূহ বিয়ে করার ক্ষেত্রে তোমাদের জন্য অনুমোদিত, যে পর্যন্ত তোমরা তাদেরকে তাদের ন্যায্য মোহরানা দাও। তোমরা তোমাদের নৈতিকতা বজায় রাখবে,ব্যভিচার না করে। এভাবে,তাদের মধ্যে যে কাউকে তোমরা পছন্দ কর, তোমরা তাদেরকে তাদের জন্য জারিকৃত মোহরানা পরিশোধ করবে। তোমরা কোন ভুল কর না পারস্পরিক সমঝোতার দ্বারা মোহরানার যেকোন নির্ধারণে। আল্লাহ সর্বজ্ঞ, পরম জ্ঞানী।"],
  "4:25": ["Whoever among you lacks the means to marry the believing fortified nisa, then from what your right hands own of your believing young nisa — and Allah knows best your faith, some of you from others. So marry them with the leave of their families, and give them their wages in kindness, fortified, not licentious, nor taking secret lovers. Then if they are fortified and come with an obscenity, upon them is half of the punishment upon the fortified nisa. That is for whoever among you fears hardship. And that you be of the sabirin is better for you. And Allah is forgiving, merciful.", "তোমাদের মধ্যে যাদের স্বাধীন বিশ্বাসী নারীদেরকে বিয়ে করার সামর্থ্য নেই, তারা বিশ্বাসী দাসী নারীদের বিয়ে করতে পারে। তোমাদের বিশ্বাস সম্পর্কে আল্লাহ সবচেয়ে ভাল জানেন, এবং তোমরা একে-অন্যের সমান, বিশ্বাস যতদূর সম্পর্কিত। তোমারা তাদের বিয়ে করার আগে তাদের অভিভাবকদের কাছ থেকে অনুমতি নিবে,এবং তোমরা ন্যায়সঙ্গতভাবে তাদের ন্যায্য মোহরানা পরিশোধ করবে। তারা নৈতিক আচরণ বজায় রাখবে,ব্যভিচার না করে,অথবা গোপন প্রেমিকদের না রেখে। একবার তারা বিয়ের মাধ্যমে মুক্ত হবার পর, যদি তারা ব্যভিচার করে,তাদের শাস্তি হবে স্বাধীন নারীদের অর্ধেক। দাসী বিয়ে করা হবে তাদের জন্য একটি শেষ অবলম্বন, যারা অপেক্ষা করতে অসমর্থ। ধৈর্যশীল হওয়া তোমাদের জন্য উত্তম। আল্লাহ ক্ষমাকারী,পরম দয়ালু।"],
  "4:26": ["Allah wills to make clear to you and to guide you to the ways of those before you, and to turn to you. And Allah is knowing, wise.", "আল্লাহ ইচ্ছা করেন তোমাদের জন্য বিষয় সমূহ ব্যাখ্যা করতে,এবং তোমাদের অতীত উদাহরণের সাহায্যে পথ প্রদর্শিত করতে,এবং তোমাদের উদ্ধার করতে। আল্লাহ সর্বজ্ঞ, সবচেয়ে জ্ঞানী।"],
  "4:27": ["And Allah wills to turn to you, but those who follow their desires wish you to deviate with a great deviation.", "আল্লাহ তোমাদের উদ্ধার করতে চান, যখন যারা তাদের লালসার অনুসরণ করে তারা চায় যে,তোমরা বিপথগামী হও এক মহা পথভ্রষ্টতায়।"],
  "4:28": ["Allah wills to lighten the burden upon you, for humankind was created weak.", "আল্লাহ তোমাদের বোঝা হালকা করতে চান, কারন মানুষ সৃষ্টিগতভাবে দুর্বল ।"],
  "4:29": ["O muminin, do not devour your wealth among yourselves falsely, unless it be trade by mutual agreement among you. And do not kill one another. Truly Allah has been merciful to you.", "হে তোমরা যারা বিশ্বাস করো,একে অন্যের সম্পত্তি অন্যায়ভাবে গ্রাস করো না- শুধুমাত্র পরস্পর গ্রহণযোগ্য লেনদেন অনুমোদিত। তোমরা নিজেদেরকে হত্যা করবে না। আল্লাহ তোমাদের প্রতি দয়াময়।"],
  "4:30": ["Whoever does that in aggression and wrong, We shall make him enter a fire. And that is easy for Allah.", "যে কেউ এই সীমালঙ্ঘনগুলো করে,বিদ্বেষপরায়ণভাবে এবং ইচ্ছাকৃত ভাবে,আমরা তাকে নরকের শাস্তি দেব। এটা করা আল্লাহর জন্য সহজ।"],
  "4:31": ["If you avoid the great sins of what you are forbidden, We will remit from you your evils and admit you into a noble entrance.", "যদি তোমরা গুরুতর পাপগুলো করা থেকে বিরত থাক যা তোমাদের জন্য নিষিদ্ধ, আমরা তোমাদের পাপসমূহ ক্ষমা করে দিব, এবং তোমাদের প্রবেশ করাব, এক সম্মানিত প্রবেশ।"],
  "4:32": ["And do not wish for that by which Allah has favored some of you over others. For men is a share of what they earn, and for nisa is a share of what they earn. And ask Allah of bounty. Truly Allah has been knowing of everything.", "তোমরা একে-অন্যের উপর আল্লাহ দ্বারা অর্পণ করা গুনাবলির লোভ করবে না; পুরুষরা নির্দিষ্ট গুনাবলি উপভোগ করে,এবং নারীরা নির্দিষ্ট গুনাবলি উপভোগ করে। তোমরা আল্লাহর কাছে মিনতি করতে পার তোমাদেরকে তাঁর অনুগ্রহ বর্ষন করতে। আল্লাহ সবকিছু সম্পর্কে সম্পূর্ণ অবগত।"],
  "4:33": ["And for each We have appointed heirs of what parents and near kin leave behind, and those whom your right hands have pledged — so give them their share. Truly Allah has been witness over everything.", "তোমাদের প্রত্যেকের জন্য, আমরা নির্ধারিত করেছি,মাতা -পিতা এবং আত্মীয়দের রেখে যাওয়া উত্তরাধিকার থেকে অংশ। আরো যারা বিবাহের মাধ্যমে তোমাদের সাথে সম্পর্কিত, তোমরা তাদেরকে তাদের ন্যায্য অংশ দিবে। আল্লাহ সবকিছু প্রত্যক্ষ করছেন।"],
  "4:34": ["Men are maintainers of nisa by what Allah has favored some of them over others, and by what they spend of their wealth. So the salihin nisa are devout, guarding in absence what Allah has guarded. As for those whose defiance you fear, admonish them, forsake them in the beds, and strike them. If they obey you, seek no way against them. Truly Allah has been high, great.", "পুরুষদের দায়িত্বপূর্ন করা হয়েছে নারীদের জন্য,এবং আল্লাহ তাদের উপর নির্দিষ্ট গুনাবলি আরোপিত করেছেন, এবং তাদেরকে করেছেন রুটি রোজগারকারী। সৎকর্মশীল নারীরা আনন্দের সাথে এই বিন্যাস গ্রহণ করে,যেহেতু এটি আল্লাহর প্রত্যাদেশ, এবং তাদের স্বামীদের সম্মান করে তাদের অনুপস্থিতিতে। যদি তোমরা নারীদের থেকে বিদ্রোহ প্রত্যক্ষ কর, প্রথমে তাদের সাথে কথা বলবে,তারপর (তোমরা ব্যবহার করতে পার নেতিবাচক উদ্দীপক যেমন) বিছানায় তাদের পরিত্যাগ করা,এরপর তোমরা (শেষ বিকল্প হিসেবে) তাদের প্রহার করতে পার। যদি তারা তোমাদের মান্য করে,তোমরা তাদের বিরুদ্ধে সীমালঙ্ঘন করতে অনুমোদিত নও। আল্লাহ সবচেয়ে উচু,সর্বোচ্চ।"],
  "4:35": ["And if you fear a split between the two, send forth an arbiter from his family and an arbiter from her family. If the two intend reconciliation, Allah will bring accord between them. Truly Allah has been knowing, aware.", "যদি একটি দম্পতি বিচ্ছেদের ভয় করে,তোমরা একজন মধ্যস্থতাকারী নিযুক্ত করবে ছেলের পরিবার থেকে এবং একজন মধ্যস্থতাকারী মেয়ের পরিবার থেকে; যদি তারা পূন:র্মিলিত হতে সিদ্ধান্ত নেয়, আল্লাহ তাদেরকে একত্রিত হতে সাহায্য করবেন। আল্লাহ সর্বজ্ঞ, জ্ঞাত।"],
  "4:36": ["Serve Allah and associate nothing with Allah. And to parents do goodness, and to near kin, the orphans, the needy, the near neighbor, the neighbor beside you, the companion beside you, the wayfarer, and what your right hands own. Truly Allah loves not whoever is conceited, vaunting.", "তোমরা একমাত্র আল্লাহর উপাসনা করবে-কোনকিছুকে তাঁর সাথে যুক্ত করো না। তোমরা পিতামাতা,আত্মীয়, এতিম, দরিদ্র, সম্পর্কযুক্ত প্রতিবেশী,সম্পর্কহীন প্রতিবেশী,ঘনিষ্ঠ সহযোগী,ভ্রমণকারী বিদেশী,এবং তোমাদের ভৃত্যদের প্রতি দৃষ্টি দিবে। আল্লাহ অহংকারী প্রদর্শন পছন্দ করে না।"],
  "4:37": ["Those who stint and bid people to stint, and hide what Allah has given them of bounty — We have prepared for the unmuminin a humiliating punishment.", "সেই ব্যক্তি যে কৃপণ, লোকদের পরামর্শ দেয় কৃপণ হবার, এবং গোপন করে যা আল্লাহ তাদের উপর অর্পণ করেছেন তাঁর দানশীলতা থেকে। আমরা অবিশ্বাসীদের জন্য প্রস্তুত করেছি একটি লজ্জাজনক শাস্তি।"],
  "4:38": ["And those who spend their wealth to be seen by people, and do not believe in Allah or the Last Day. Whoever has Shaytan as a companion — how evil a companion.", "তারা শুধুমাত্র দেখানোর জন্য অর্থ দান করে,যখন আল্লাহ এবং শেষ দিবসে অবিশ্বাসী। যদি কারো সঙ্গী হয় শয়তান, সেই সবচেয়ে মন্দ সঙ্গী।"],
  "4:39": ["What would it harm them to believe in Allah and the Last Day, and to spend of what Allah has provided them? And Allah has been knowing of them.", "কেন তারা আল্লাহ এবং শেষ দিনে বিশ্বাস করে না,এবং তাদেরকে আল্লাহর দেওয়া  জীবিকা থেকে দেয় না? আল্লাহ তাদের সম্পর্কে সম্পূর্ণ অবগত।"],
  "4:40": ["Truly Allah does not wrong the weight of a mote. And if it be a good deed, Allah doubles it and gives from Allah's presence a great reward.", "আল্লাহ একটি পরমানুর ভরের অবিচার আরোপ করেন না। পক্ষান্তরে,তিনি সৎ  কর্মের জন্য পুরুস্কার বহুগুনে বাড়িয়ে দেন, এবং তাঁর কাছ থেকে মহান প্রতিদান প্রদান করেন।"],
  "4:41": ["So how will it be when We bring from every community a witness, and We bring you as a witness against these?", "এভাবে,যখন (বিচারের) সে দিন আসবে,আমরা প্রত্যেক সম্প্রদায় থেকে একজন সাক্ষীকে ডাকব, এবং  তুমি (রাসূল) এইসব লোকদের মাঝে একজন সাক্ষী হিসেবে দায়িত্ব পালন করবে।"],
  "4:42": ["On that day, those who kafara and disobeyed the Rasul will wish the earth were leveled over them, and they will hide no saying from Allah.", "সেই দিন, যারা রাসূলকে অবিশ্বাস করেছিল এবং অমান্য করেছিল তারা ইচ্ছা করবে যে,যদি তারা ভূমির সাথে মিলিয়ে  যেত; না তারা আল্লাহ থেকে একটি কথাও লুকাতে সক্ষম হবে।"],
  "4:43": ["O muminin, do not approach the prayer while in a stupor, until you know what you are saying, nor in a state of impurity — unless merely passing along a way — until you wash. And if you are ill, or on a journey, or one of you comes from the privy, or you have touched nisa, and found no water, then aim toward good surface-soil and wipe your faces and your hands. Truly Allah has been ever-passing-over, forgiving.", "হে তোমরা যারা বিশ্বাস কর, মাতাল অবস্থায় সংযোগ প্রার্থনাসমূহ (সালাত) পালন করো না,যাতে তোমরা জান যে,তোমরা কি বলছ। না প্রচন্ড যৌন উত্তেজনার পর গোসল ছাড়া,যদি না তোমরা রাস্তায় থাক, ভ্রমনরত; যদি তোমরা অসুস্থ অথবা ভ্রমনরত থাক, অথবা তোমাদের মূত্র - সংক্রান্ত অথবা মল-সংক্রান্ত নিঃসরন থাকে (যেমন বাতাস),অথবা নারীদের সংস্পর্শে এসে থাক (যৌণ বিচারে),এবং তোমরা পানি খুঁজে না পাও, তোমরা তায়মুম (শুষ্ক ওজু) পালন করবে পরিষ্কার শুকনো মাটি স্পর্শ করে,এরপর তোমাদের মুখ এবং হাতগুলো তা দিয়ে মুছে। আল্লাহ ক্ষমাকারী,মার্জনাকারী।"],
  "4:44": ["Have you not seen those given a share of the Book buying error and wishing that you lose the way?", "তুমি কি তাদেরকে লক্ষ্য করেছ, যারা ঐশীগ্রন্থের একটি অংশ গ্রহণ করেছিল, এবং কিভাবে তারা পথভ্রষ্ট হতে পছন্দ করে,এবং চায় যে,তোমরা পথভ্রষ্ট হও?"],
  "4:45": ["Allah knows best your enemies. And sufficient is Allah as a protecting-friend, and sufficient is Allah as a helper.", "আল্লাহ সবচেয়ে ভাল জানেন, কারা তোমাদের শত্রু। আল্লাহই একমাত্র প্রভু এবং মনিব। আল্লাহই একমাত্র সমর্থনকারী।"],
  "4:46": ["Some of the Jews shift words from their places and say, \"We hear and we disobey,\" and \"Hear, without hearing,\" and \"Be our keeper\" — a twisting with their tongues and a stabbing at the faith. If only they had said, \"We hear and we obey,\" and \"Hear,\" and \"Look upon us,\" it would have been better for them and more upright. But Allah has cursed them for their unbelief, so they do not believe except a few.", "তাদের মধ্যে যারা ইহুদী,তাদের কেউ কেউ বানীকে সত্য ছাড়িয়ে বিকৃত করে,এবং তারা বলে,“আমরা শুনি,কিন্তু আমরা অমান্য করি”,এবং “তোমার কথা বধির কানে পতিত হচ্ছে,”এবং “রা'য়েনা (আমাদের রাখাল হও)”,যেভাবে তারা তাদের জিহ্বা আওড়ায় ধর্মকে উপহাস করতে। যদি তারা বলত, “আমরা শুনি,এবং আমরা মান্য করি,”এবং “আমরা তোমায় শুনি,”এবং “উনজুরনা (আমাদের প্রতি নজর রাখো),”এটা তাদের জন্য মঙ্গল, এবং অধিক ন্যায়নিষ্ঠ হতো। পরিবর্তে,তারা তাদের অবিশ্বাসের কারনে আল্লাহর থেকে দণ্ডাদেশ টেনে এনেছে। ফলস্বরূপ, তাদের অধিকাংশই বিশ্বাস করতে পারে না।"],
  "4:47": ["O you who were given the Book, believe in what We have sent down, confirming what is with you, before We blot out faces and turn them to their backs, or curse them as We cursed the people of the Sabbath. And the command of Allah has ever been done.", "হে তোমরা যারা ঐশীগ্রন্থ গ্রহণ করেছ, তোমরা বিশ্বাস করবে যা আমরা এখানে প্রকাশ করেছি, যা নিশ্চিত করে তোমাদের যা আছে,আমরা নির্দিষ্ট  মুখগুলো নির্বাসনে বিতাড়িত করার আগে, অথবা তাদের শাস্তি দেয়ার আগে যেমন আমরা শাস্তি দিয়েছিলাম তাদেরকে যারা বিশ্রামের দিনকে অপবিত্র করেছিল। আল্লাহর হুকুম হয়ে গেছে।"],
  "4:48": ["Truly Allah does not forgive that one associate with Allah, and forgives what is below that for whom Allah wills. Whoever associates with Allah has fabricated a tremendous sin.", "আল্লাহ অংশীদার সাব্যস্ত করাকে ক্ষমা করেন না,কিন্তু তিনি ক্ষমা করেন অপেক্ষাকৃত ছোট অপরাধ, যার জন্য তিনি ইচ্ছা করেন। যে কেউ আল্লাহর পাশে অংশীদার স্থাপন করে,গড়েছে এক ভয়ানক অপরাধ।"],
  "4:49": ["Have you not seen those who purify themselves? Rather, it is Allah who purifies whom Allah wills, and they are not wronged so much as a fiber.", "তুমি কি তাদেরকে লক্ষ্য করেছ যারা তাদের নিজেদের প্রশংসা করে? পরিবর্তে,আল্লাহ সেই একজন যিনি প্রশংসিত করেন যাকে তিনি ইচ্ছা করেন, সামান্যতম অবিচার ছাড়াই।"],
  "4:50": ["See how they fabricate lies upon Allah — and sufficient is that as a manifest sin.", "লক্ষ্য করো,কিভাবে তারা আল্লাহ সম্পর্কে মিথ্যা উদ্ভাবন করে,কি এক মহা অপরাধ এটা!"],
  "4:51": ["Have you not seen those given a share of the Book believing in idols and the false-arbiter, and saying of those who kafara, \"These are better guided than the muminin\" in way?", "তুমি কি তাদেরকে লক্ষ্য করেছ, যারা ঐশীগ্রন্থের একটি অংশ গ্রহণ করেছিল, এবং কিভাবে তারা শিরকীত্বে এবং মিথ্যা মতবাদে বিশ্বাস করে,এরপর বলে,“অবিশ্বাসীরা বিশ্বাসীদের চেয়ে উত্তম পথপ্রাপ্ত\"?!"],
  "4:52": ["Those are the ones Allah has cursed. And whomever Allah curses, you will never find a helper for him.", "এরা তারাই যারা আল্লাহর দন্ডাদেশ টেনে এনেছে,এবং যাকে আল্লাহ দন্ডাদেশ দেন, তুমি তার জন্য কোন সাহায্যকারী পাবে না।"],
  "4:53": ["Or do they have a share in the kingdom? If so, they would give people not so much as a speck.", "তারা কি সার্বভৌমত্বের একটি অংশ অধিকার করেছে? যদি তারা করত, তারা লোকদের একটি শস্যকণা পরিমাণও দিত না।"],
  "4:54": ["Or do they envy people for what Allah has given them of bounty? We have given the family of Ibrahim the Book and wisdom, and We have given them a great kingdom.", "তারা কি সেই লোকদের প্রতি হিংসাপরায়ন, কারণ আল্লাহ তাদেরকে তাঁর অনুগ্রহসমূহ বর্ষন করেছেন? আমরা ইব্রাহিমের পরিবারকে দিয়েছি ঐশীগ্রন্থ, এবং প্রজ্ঞা; আমরা তাদেরকে দান করেছিলাম এক মহান কর্তৃত্ব।"],
  "4:55": ["Among them are some who believed in it, and among them are some who turned away from it. And sufficient is Jahannam as a blaze.", "তাদের কেউ কেউ তাতে বিশ্বাস করেছিল, এবং তাদের কেউ কেউ তা থেকে মুখ ফিরিয়ে নিয়েছিল; এইসবের জন্য একমাত্র নরকই যথার্থ শাস্তি।"],
  "4:56": ["Truly those who disbelieve in Our signs, We shall make them enter a fire. Whenever their skins are roasted through, We will replace them with other skins, so they may taste the punishment. Truly Allah has been mighty, wise.", "নিশ্চিতরূপে,তারা যারা আমাদের প্রকাশনাসমূহকে অবিশ্বাস করে,আমরা তাদের নরকাগ্নির শাস্তি দেব। যখনই তাদের চামড়া পুড়ে যায়, আমরা তাদেরকে নতুন চামড়া দেব। এভাবে,তারা অবিরত কষ্ট ভোগ করবে। আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "4:57": ["And those who believe and do salih deeds, We shall admit them into gardens beneath which rivers flow, abiding therein forever. For them therein are purified mates, and We shall admit them into deep shade.", "তাদের বিষয়ে যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে,আমরা তাদেরকে প্রবাহিত ঝর্নাধারা সহ বাগানসমূহে প্রবেশ করাব, তারা চিরকাল সেখানে বাস করে। সেখানে তাদের বিশুদ্ধ সহধর্মী/সহধর্মীনি থাকবে। আমরা তাদেরকে প্রবেশ করাব একটি স্বর্গীয় ছায়ায়।"],
  "4:58": ["Truly Allah commands you to deliver trusts to their rightful people, and when you judge among people, that you judge with justice. How excellent is that whereby Allah admonishes you. Truly Allah has been hearing, seeing.", "আল্লাহ তোমাদের হুকুম দেন ফিরিয়ে দিতে যাকিছু লোকেরা তোমাদের কাছে গচ্ছিত রাখে। যদি তোমরা মানুষের মাঝে বিচার করো,তোমরা ন্যায়ভাবে বিচার করবে। প্রকৃতপক্ষে,সর্বোত্তম জ্ঞানালোক হলো যা আল্লাহ তোমাদের জন্য পরামর্শ দেন। আল্লাহ শ্রবণকারী,দর্শনকারী।"],
  "4:59": ["O muminin, obey Allah and obey the Rasul and those in authority among you. If you dispute over anything, refer it to Allah and the Rasul, if you believe in Allah and the Last Day. That is better and a better outcome.", "হে তোমরা যারা বিশ্বাস করো,তোমরা আল্লাহকে মান্য করবে,এবং তোমরা মান্য করবে বার্তাবাহককে  এবং তোমাদের মধ্যে যারা দায়িত্বপ্রাপ্ত। যদি তোমরা কোন বিষয়ে বিবাদ করো,তোমরা তা আল্লাহ এবং বার্তাবাহকের প্রতি ন্যস্ত করবে,যদি তোমরা আল্লাহ এবং শেষ দিবসে বিশ্বাস করো। এটা তোমাদের জন্য উত্তম, এবং তোমাদেরকে সর্বোত্তম সমাধান দেয়।"],
  "4:60": ["Have you not seen those who claim that they believe in what was sent down to you and what was sent down before you, yet wish to seek judgment from the false-arbiter when they were commanded to disbelieve in it? And Shaytan wishes to lead them far astray.", "তুমি কি তাদের লক্ষ্য করেছ, যারা দাবী করে যে,তারা বিশ্বাস করে যা তোমার প্রতি প্রকাশিত হয়েছিল, এবং যা প্রকাশিত হয়েছিল তোমার পূর্বে,তারপর তাদের উপাস্যদের অন্যায্য আইন মেনে চলে? তারা এরূপ আইন প্রত্যাখ্যান করতে আদেশপ্রাপ্ত হয়েছিল। প্রকৃতপক্ষে,এটাই শয়তানের ইচ্ছা,তাদেরকে সুদূরে পথভ্রষ্ট করা।"],
  "4:61": ["And when it is said to them, \"Come to what Allah has sent down and to the Rasul,\" you see the munafiqin turning from you in sheer aversion.", "যখন তাদেরকে বলা হয়েছিল, \"আস সে দিকে যা আল্লাহ প্রকাশ করেছেন, এবং বার্তাবাহকের দিকে,“তুমি দেখ যে ভন্ডরা তোমাকে সম্পূর্ণরূপে পরিত্যাগ করছে।"],
  "4:62": ["So how is it that when a calamity befalls them for what their hands have put forth, they come to you swearing by Allah, \"We intended only goodness and right guidance\"?", "এটি কেমন হবে যখন একটি বিপর্যয় তাদেরকে আঘাত করে,তাদের স্বীয় কর্মসমূহের একটি প্রতিফল হিসেবে? তারা এরপরে তোমার কাছে আসবে এবং আল্লাহর নামে শপথ করবে : \"আমাদের উদ্দেশ্য ভাল এবং ন্যায়নিষ্ঠ ছিল! \""],
  "4:63": ["Those are the ones whose hearts Allah knows what is in. So turn away from them, admonish them, and say to them about themselves a word that strikes home.", "আল্লাহ তাদের গভীরতম  উদ্দেশ্যসমূহ সম্পর্কে সম্পূর্ণ অবগত। তুমি তাদেরকে উপেক্ষা করবে,তাদেরকে আলোকিত করবে,এবং তাদেরকে ভাল উপদেশ দিবে,হয়ত তা তাদের আত্মাকে রক্ষা করবে।"],
  "4:64": ["We did not send any Rasul except to be obeyed, by Allah's leave. If only, when they wronged themselves, they had come to you and sought forgiveness from Allah, and the Rasul had sought forgiveness for them, they would have found Allah ever-turning, merciful.", "আমরা কোন বার্তাবাহককে আল্লাহর ইচ্ছা মান্য করা ব্যতীত পাঠাইনি। যদি তারা,তাদের আত্মার প্রতি অন্যায় করার সময়, তোমার কাছে আসতো এবং আল্লাহর কাছে ক্ষমার জন্য প্রার্থনা করত, এবং বার্তাবাহক তাদের ক্ষমার জন্য প্রার্থনা করত, তারা আল্লাহকে পেতো উদ্ধারকারী,পরম দয়ালু।"],
  "4:65": ["But no, by your Rabb, they will not believe until they make you judge in what arises between them, then find no constraint within themselves at what you decreed, and submit in full submission.", "বস্তুত কখনোই না,তোমার প্রভুর শপথ; তারা বিশ্বাসী নয় যদি না তারা তোমার কাছে তাদের বিবাদসমূহের বিচারের জন্য  আসে,তারপর তোমার রায় যাই হোক না কেন তা মেনে নিতে তাদের হৃদয়ে কোন দ্বিধা থাকে না।  তারা অবশ্যই আত্মসমর্পণ করবে,একটি পরিপূর্ণ আত্মসমর্পণ।"],
  "4:66": ["If We had decreed upon them, \"Kill yourselves,\" or \"Leave your homes,\" they would not have done it, except a few of them. If only they had done what they were admonished to, it would have been better for them and firmer in steadfastness.", "আমরা যদি তাদের জন্য হুকুম দিতামঃ “তোমরা অবশ্যই তোমাদের প্রান উৎসর্গ করবে,”অথবা “তোমাদের ঘর-বাড়ি পরিত্যাগ করবে,”তারা তা করতো না,তাদের মধ্যে কিছু লোক ব্যতিত। (এমনকি যদি এমন একটি হুকুম জারি হতো),যদি তারা করতো,যা তাদেরকে করতে আদেশ করা হয়েছিল, এটা তাদের জন্য উত্তম হতো,এবং প্রমান করতো তাদের বিশ্বাসের জোর।"],
  "4:67": ["And then We would surely have given them from Our presence a great reward.", "এবং আমরা তাদেরকে এক মহা পুরস্কার প্রদান করতাম।"],
  "4:68": ["And We would have guided them to a straight path.", "এবং আমরা তাদেরকে সঠিক পথ-প্রদর্শন করতাম।"],
  "4:69": ["Whoever obeys Allah and the Rasul, those are with the ones upon whom Allah has bestowed favor — among the nabis, the sadiqin, the shahids, and the salihin. And excellent are those as companions.", "যারা আল্লাহ এবং বার্তাবাহকে মান্য করে,তারা তাদের অন্তর্ভুক্ত যারা আশীর্বাদপ্রাপ্ত হয়েছিল আল্লাহর- নবীদের, সাধুদের, শহীদদের, এবং সৎ কর্মীদের। এরাই সর্বোত্তম সঙ্গী।"],
  "4:70": ["That is bounty from Allah, and sufficient is Allah as knower.", "এমনই আল্লাহর পক্ষ থেকে আশীর্বাদ; আল্লাহ সবচেয়ে ভালো জানেন।"],
  "4:71": ["O muminin, take your precaution, then go forth in detachments or go forth all together.", "হে তোমরা যারা বিশ্বাস কর, তোমরা সতর্ক থাকবে,আর পৃথকভাবে সংগঠিত হও, অথবা সকলে মিলে সংগঠিত হও ।"],
  "4:72": ["Among you is one who lags behind; then if a calamity befalls you, he says, \"Allah has favored me, that I was not with them as a witness.\"", "নিশ্চিতরূপে,তোমাদের মধ্যে রয়েছে তারা যারা গড়িমসি করত, এরপর, যদি কোন প্রতিবন্ধকতা তোমাদের কষ্ট দিত, তারা বলত, \"আল্লাহ আমাকে সৌভাগ্যশীল করেছেন যে,আমি তাদের সাথে শহীদ হইনি।\""],
  "4:73": ["And if a bounty from Allah befalls you, he will surely say — as if there had been no affection between you and him — \"If only I had been with them, I would have won a tremendous triumph.\"", "কিন্তু,যদি তুমি আল্লাহ থেকে একটি আশীর্বাদ অর্জন কর, তারা বলবে,যেন তোমাদের ও তাদের মধ্যে কখনোই কোন বন্ধুত্ব বিদ্যমান ছিল না,\"আমি যদি তাদের সাথে থাকতাম, তবে এমন এক মহা-বিজয়ের অংশীদার হতে পারতাম। \""],
  "4:74": ["So let those fight in the way of Allah who sell the worldly life for the Last. Whoever fights in the way of Allah, whether killed or overcoming, We shall surely give him a great reward.", "যারা আল্লাহর উদ্দেশ্যে সানন্দে যুদ্ধ করে,তারা হচ্ছে সে সব লোক যারা পরকালের জন্য এই দুনিয়াকে পরিত্যাগ করে। যেকেউ আল্লাহর উদ্দেশ্যে যুদ্ধ করে,এরপর নিহত হয়, অথবা বিজয় অর্জন করে,আমরা নিশ্চিতরূপে তাকে এক মহা-পুরষ্কার দিব।"],
  "4:75": ["What is wrong with you that you do not fight in the way of Allah and for the weak among men, nisa, and children who say, \"Our Rabb, bring us out of this town whose people are wrongdoers, and appoint for us from Your presence a protector, and appoint for us from Your presence a helper\"?", "কেন তোমাদের আল্লাহর উদ্দেশ্যে যুদ্ধ করা উচিৎ নয়, যখন দূর্বল পুরুষরা,নারীরা,এবং শিশুরা মিনতি করছে: \"আমাদের প্রভু,আমাদেরকে এই সম্প্রদায় থেকে মুক্তি দিন যার লোকেরা অত্যাচারী,এবং আপনি হোন আমাদের প্রভু এবং মনিব।\""],
  "4:76": ["Those who believe fight in the way of Allah, and those who disbelieve fight in the way of the false-arbiter. So fight the allies of Shaytan. Truly the scheme of Shaytan has been weak.", "যারা বিশ্বাস করে তারা আল্লাহর উদ্দেশ্যে যুদ্ধ করছে,যখন যারা অবিশ্বাস করে তারা উৎপীড়ন করার উদ্দেশ্যে যুদ্ধ করছে। এই কারনে,তোমরা শয়তানের মিত্রদের বিরুদ্ধে যুদ্ধ করবে; শয়তান শক্তিহীন।"],
  "4:77": ["Have you not seen those to whom it was said, \"Restrain your hands, establish the prayer, and give the purifying dues\"? Then when fighting was decreed upon them, a group of them feared people with a fear of Allah — or greater still. And they said, \"Our Rabb, why have You decreed fighting upon us? If only You had postponed us to a near term.\" Say: The enjoyment of the worldly life is little, and the Last is better for whoever is reverent — and you will not be wronged a fiber.", "তুমি কি তাদের লক্ষ্য করেছ যাদেরকে বলা হয়েছিল, “তোমাদের যুদ্ধ করতে হবে না;  যে সব তোমাদের করা প্রয়োজন তা হল (সালাত) সংযোগ প্রার্থনাসমূহ প্রতিষ্ঠা করা,এবং বাদ্ধতামূলক দান করা (যাকাত) “এরপর, যখন  তাদের জন্য যুদ্ধ করার আদেশ করা হয়েছিল, তারা লোকদের এমন ভয় করেছিল যেমন তারা আল্লাহকে ভয় করতো,অথবা এমন কি আরও অধিক? তারা বলেছিল, “আমাদের প্রভু,কেন আপনি এই যুদ্ধ আমাদের উপর জোর করে আরোপ করেছিলেন? যদি আপনি শুধু কিছু সময়ের জন্য আমাদের বিরাম দিতেন!”বল, “এই দুনিয়ার বস্তু সামগ্রী কিছুই না,যখন পরকাল সৎকর্মশীলদের জন্য অধিকতর উত্তম, এবং তোমরা কখনই সামান্যতম অবিচার ভোগ করবে না।"],
  "4:78": ["Wherever you may be, death will overtake you, even if you are in lofty towers. If good befalls them, they say, \"This is from Allah\"; if evil befalls them, they say, \"This is from you.\" Say: All is from Allah. So what is the matter with these people that they scarcely understand a saying?", "তোমরা যেখানেই থাকো না কেন, মৃত্যু তোমাদের পাকড়াও করবে,এমনকি যদি তোমরা দুর্ভেদ্য দুর্গেও বাস করো। যখন তাদের ভাল কিছু হয়, তারা বলে,“এটা আল্লাহর পক্ষ থেকে,”এবং যখন কোন মন্দকিছু তাদেরকে পীড়িত করে,তারা তোমার প্রতি দোষারোপ করে। বল, “সবকিছু আল্লাহর থেকে আসে”। কেন এই লোকেরা প্রায় সবকিছুই ভুল বোঝে?"],
  "4:79": ["Whatever good befalls you is from Allah, and whatever evil befalls you is from yourself. And We have sent you to humankind as a Rasul, and sufficient is Allah as witness.", "যা কিছু ভালো তোমাদের প্রতি ঘটে তা আল্লাহর থেকে,এবং যা কিছু মন্দ তোমাদের প্রতি ঘটে তা তোমাদের পক্ষ থেকে। আমরা লোকদের জন্য তোমাকে  বার্তাবাহক হিসাবে পাঠিয়েছি,এবং আল্লাহ সাক্ষী হিসাবে যথেষ্ট।"],
  "4:80": ["Whoever obeys the Rasul has obeyed Allah. And whoever turns away — We have not sent you as a keeper over them.", "যেকেউ বার্তাবাহককে মান্য করে,সে আল্লাহকে মান্য করছে। তাদের বিষয়ে যারা মুখ ফিরিয়ে নেয়, আমরা তোমাকে তাদের অভিভাবক করে পাঠাইনি।"],
  "4:81": ["They say, \"Obedience.\" But when they leave your presence, a band of them spends the night plotting other than what you say. And Allah records what they plot by night. So turn away from them and trust in Allah. And sufficient is Allah as disposer.", "তারা আনুগত্যের অঙ্গীকার করে,কিন্তু যখনি তারা তোমাকে ছেড়ে যায়, তাদের কেউ কেউ যা তারা বলে এর বিপরীত ইচ্ছা পোষন করে। আল্লাহ তাদের গভীরতম  ইচ্ছাগুলো রেকর্ড করেন। তোমরা তাদেরকে উপেক্ষা করবে,এবং আল্লাহর প্রতি তোমাদের আস্থা রাখ। আল্লাহ সমর্থক হিসেবে যথেষ্ট।"],
  "4:82": ["Do they not ponder the Recitation? If it had been from other than Allah, they would have found in it much contradiction.", "কেন তারা যত্নসহকারে কুরআন অধ্যয়ন করে না? যদি এটি আল্লাহ ছাড়া অন্য কারো থেকে হত, তারা এতে অসংখ্য অসংগতি পেত।"],
  "4:83": ["And when a matter of security or fear comes to them, they broadcast it. If only they had referred it to the Rasul and to those in authority among them, those who interpret it among them would have known it. Were it not for Allah's bounty upon you and mercy, you would have followed Shaytan, except a few.", "যখন একটি গুজব, তাদের সামনে আসে,যা নিরাপত্তাকে বিঘ্নিত করে,তারা তা ছড়ায়। যদি তারা তা বার্তাবাহক, এবং তাদের মধ্যকার দায়িত্বপ্রাপ্তদের কাছে ন্যস্ত করত, তবে তাদেরকে অবহিত করত তারা যারা এইসব বিষয়গুলো বুঝে। যদি এটি তোমাদের প্রতি আল্লাহর করুনা,এবং তাঁর দয়া না হত, তোমরা শয়তানকে অনুসরণ করতে,অল্পসংখ্যক ছাড়া।"],
  "4:84": ["So fight in the way of Allah; you are charged only with yourself. And urge on the muminin. Perhaps Allah will restrain the might of those who disbelieve. And Allah is stronger in might and stronger in exemplary punishment.", "তোমরা আল্লাহর উদ্দেশ্যে যুদ্ধ করবে; তোমরা শুধু তোমাদের নিজেদের আত্মার জন্যই দায়ী,এবং বিশ্বাসীদেরকে তা-ই করতে উপদেশ দিবে। আল্লাহ তাদের ক্ষমতা নিষ্ক্রয় করবেন, যারা অবিশ্বাস করে। আল্লাহ অনেক বেশি ক্ষমতাবান, এবং অনেক বেশি কার্যকরী।"],
  "4:85": ["Whoever intercedes with a good intercession shall have a share of it, and whoever intercedes with an evil intercession shall have a portion of its burden. And Allah has been over everything all-powerful.", "যেকেউ একটি ভাল কাজের মধ্যস্থতা করে,এর কৃতৃত্বের একটি অংশ গ্রহণ করে,এবং যেকেউ একটি মন্দ কাজের মধ্যস্থতা করে,এর একটি অংশ টেনে আনে। আল্লাহ সব কিছু নিয়ন্ত্রণ করেন।"],
  "4:86": ["And when you are greeted with a greeting, greet back with better than it or return it. Truly Allah has been over everything a reckoner.", "যখন শুভেচ্ছা প্রাপ্ত হবে কোন অভিবাদন দ্বারা,তোমরা সাড়া দিবে উত্তম অথবা কমপক্ষে একটি সমতুল্য অভিবাদন দিয়ে। আল্লাহ সব কিছুর হিসাব গ্রহণকারী।"],
  "4:87": ["Allah — there is no ilah but Allah. Allah will surely gather you to the Day of Standing, about which there is no doubt. And who is more sadiq than Allah in telling?", "ঈশ্বরঃ তিনি ব্যতিত কোন উপাস্য নেই। তিনি অবশ্যই তোমাদের সমবেত করবেন পুরুত্থানের সেই অনিবার্য দিনে। আল্লাহর চেয়ে কার বর্ণনা অধিক সত্য?"],
  "4:88": ["So what is the matter with you that you have become two bands over the munafiqin? Allah has cast them back for what they earned. Do you wish to guide one whom Allah has led astray? And whomever Allah leads astray, you will never find a way for him.", "(তোমাদের ভিতরের) ভণ্ডদের বিষয়ে কেন তোমাদের উচিত হবে নিজেদের দুই দলে বিভক্ত করা? আল্লাহই তাদেরকে তাদের আচরণের কারনে নিন্দিত করেছেন। তোমরা কি তাদেরকে পথ প্রদর্শন করতে চাও, যারা আল্লাহ দ্বারা পথভ্রষ্ট হয়েছে? যাদেরকে আল্লাহ পথভ্রষ্ট করেন, তুমি কখনই তাদেরকে পথপ্রদর্শন করার উপায় পাবে না।"],
  "4:89": ["They wish that you disbelieve as they kafara, so that you would be equal. So do not take allies from them until they emigrate in the way of Allah. But if they turn away, seize them and kill them wherever you find them, and do not take from them a protecting-friend or a helper.", "তারা প্রত্যাশা করে যে,তুমি অবিশ্বাস করো যেমন তারা অবিশ্বাস করেছে,তারপর তোমরা (তাদের) সমান হয়ে যাও। তাদেরকে বন্ধু ভেব না,যদি না তারা আল্লাহর উদ্দেশ্যে তোমাদের সাথে যুদ্ধের জন্য সংগঠিত হয়। যদি তারা তোমাদের শত্রু হয়ে উঠে,তোমরা তাদের বিরুদ্ধে যুদ্ধ করবে,এবং তোমাদেরকে তাদের হত্যা করতে হতে পারে,যখন যুদ্ধে তোমরা তাদের মুখোমুখি হও। তোমরা তাদেরকে বন্ধু অথবা মিত্র হিসাবে গ্রহণ করবে না।"],
  "4:90": ["Except those who join a people between whom and you there is a pact, or who come to you with hearts straitened from fighting you or fighting their own people. If Allah had willed, Allah would have set them over you, and they would have fought you. So if they hold off from you and do not fight you, and cast peace toward you, then Allah has made no way for you against them.", "তারা নিষ্কৃতি প্রাপ্ত যারা সে লোকদের সাথে যোগ দেয় যাদের সাথে তোমরা একটি শান্তি চুক্তি সাক্ষর করেছ, এবং তারা যারা তোমাদের কাছে আসে তোমাদের সাথে যুদ্ধ না করার ইচ্ছা নিয়ে,না তাদের আত্মীয়দের সাথে। আল্লাহ যদি চাইতেন, তিনি তাদেরকে অনুমতি দিতে পারতেন তোমাদের বিরুদ্ধে যুদ্ধ করার। অতএব, যদি তারা তোমাদেরকে একা ছেড়ে দেয়, তোমাদের বিরুদ্ধে যুদ্ধ করা থেকে বিরত থাকে,এবং তোমাদেরকে শান্তি প্রস্তাব দেয়, তখন আল্লাহ তোমাদেরকে তাদের বিরুদ্ধে যুদ্ধের কোন ওজর দেন না।"],
  "4:91": ["You will find others who wish to be secure from you and to be secure from their own people; whenever they are returned to sedition, they are cast down in it. So if they do not hold off from you and cast peace toward you and restrain their hands, then seize them and kill them wherever you come upon them. Those — We have made for you against them a clear warrant.", "তোমরা অন্যদেরকে পাবে যারা শান্তি স্থাপন করতে চায় তোমাদের সাথে,এবং তাদের লোকদের সাথেও। কিন্তু,যখনি যুদ্ধ ছড়িয়ে পড়ে,তারা তোমাদের বিরুদ্ধে যুদ্ধ করে। যদি না এইসব লোকেরা তোমাদের থেকে নিবৃত্ত হয়, তোমাদেরকে শান্তি প্রস্তাব দেয়, এবং তোমাদের বিরুদ্ধে যুদ্ধ বন্ধ করে,তোমাদেরকে তাদের বিরুদ্ধে যুদ্ধ করতে হতে পারে যখন তোমরা তাদের মোকাবেলা করো। এইসবের বিপক্ষে,আমরা তোমাদেরকে একটি স্পষ্ট কর্তৃত্ব প্রদান করি।"],
  "4:92": ["It is not for a mumin to kill a mumin except by error. Whoever kills a mumin by error, then the freeing of a believing neck, and compensation handed over to his family — unless they forgo it. If he belonged to a people enemy to you and he is a mumin, then the freeing of a believing neck. And if he belonged to a people between whom and you there is a pact, then compensation handed over to his family and the freeing of a believing neck. Whoever does not find means, then fasting two consecutive months — a turning from Allah. And Allah has been knowing, wise.", "কোন বিশ্বাসী অপর বিশ্বাসীকে হত্যা করবে না,যদি না তা একটি দূর্ঘটনা হয়। যদি কেউ কোন বিশ্বাসীকে দূর্ঘটনাবশত হত্যা করে,সে প্রায়শ্চিত্ত করবে একজন বিশ্বাসী দাসকে মুক্ত করে,এবং নিহতের পরিবারকে ক্ষতিপূরণ দিয়ে,যদি না তারা এরকম ক্ষতিপূরণকে দান হিসেবে ছেড়ে দেয়। যদি নিহত ব্যক্তিটি সে লোকদের অন্তর্ভূক্ত হয়, যারা তোমাদের সাথে যুদ্ধে লিপ্ত, যদিও সে একজন বিশ্বাসী ছিল, তোমরা একজন বিশ্বাসী দাসকে মুক্ত করে প্রায়শ্চিত্ত করবে। যদি সে সেই লোকদের অন্তর্ভূক্ত হয়, যাদের সাথে তোমরা একটি শান্তি চুক্তি স্বাক্ষর করেছ, তোমরা ক্ষতিপূরণ করবে সেই সাথে একজন বিশ্বাসী দাসকে মুক্ত করবে। যদি তোমরা মুক্ত করার জন্য একজন দাস খুঁজে না পাও,তোমরা পর পর দুই মাস উপবাস দ্বারা প্রায়শ্চিত্ত করবে,আল্লাহ দ্বারা উদ্ধারপ্রাপ্ত হতে। আল্লাহ জ্ঞাতা,সবচেয়ে জ্ঞানী।"],
  "4:93": ["Whoever kills a mumin deliberately, his recompense is Jahannam, abiding therein, and the wrath of Allah upon him, and Allah's curse, and Allah has prepared for him a tremendous punishment.", "যেকেউ একজন বিশ্বাসীকে উদ্দেশ্যমূলকভাবে হত্যা করে,তার শাস্তি নরক, যেখানে সে চিরকাল বসবাস করে,আল্লাহ তার প্রতি রাগান্বিত, এবং তাকে দন্ডাদেশ দেন, এবং তার জন্য প্রস্তুত রেখেছেন এক ভয়ানক শাস্তি।"],
  "4:94": ["O muminin, when you set out in the way of Allah, ascertain, and do not say to one who casts peace toward you, \"You are not a mumin,\" seeking the display of worldly life — with Allah are many gains. Thus you were before, then Allah favored you, so ascertain. Truly Allah has been aware of what you do.", "হে তোমরা যারা বিশ্বাস কর, যদি তোমরা আল্লাহর উদ্দেশ্যে আঘাত কর, তোমরা সম্পূর্নভাবে নিশ্চিত হবে। তোমাদেরকে শান্তি প্রস্তাব দেয় এমন কাউকে বলবে না যে,\"তুমি বিশ্বাসী নও, ”এই পৃথিবীর যুদ্ধলব্ধ সম্পদের খোঁজে। কারণ, আল্লাহ অফুরন্ত সম্পদের অধিকারী। স্মরণ কর যে,তোমরা তাদের মত ছিলে,এবং আল্লাহ তোমাদেরকে আশীর্বাদপুষ্ট করেছেন। সুতরাং,তোমরা সম্পূর্নভাবে নিশ্চিত হবে (আঘাত করার আগে)। তোমরা যা কিছু কর আল্লাহ সে সম্পর্কে সম্পূর্ন অবগত।"],
  "4:95": ["Not equal are those of the muminin who remain behind — other than those held back by harm — and those who strive in the way of Allah with their wealth and their lives. By bounty from Allah, the strivers with their wealth and their lives are above the ones remaining behind by a degree; and to each Allah has promised the best. And by bounty from Allah the strivers are above those remaining behind with a great reward.", "সমান নয় বিশ্বাসীদের মধ্যে বসে থাকা লোকেরা যারা বিকলাঙ্গ নয়, এবং তারা যারা আল্লাহর উদ্দেশ্যে সংগ্রাম করে তাদের অর্থ এবং জীবন দিয়ে। আল্লাহ বসে থাকাদের উপর উন্নীত করেন তাদেরকে যারা তাদের অর্থ এবং তাদের জীবন দিয়ে সংগ্রাম করে। উভয়ের জন্য, আল্লাহ পরিত্রাণের অঙ্গীকার করেন, কিন্তু আল্লাহ বসে থাকাদের উপর সংগ্রামকারীদের এক মহা প্রতিদানের সাথে উন্নীত করেন।"],
  "4:96": ["Degrees from Allah, and forgiveness, and mercy. And Allah has been forgiving, merciful.", "উচ্চতর পদমর্যাদা তাঁর থেকে আসে,একই ভাবে ক্ষমা এবং করুণা। আল্লাহ ক্ষমাশীল, পরম করুণাময়।"],
  "4:97": ["Truly those whom the malakat take in death while they wrong themselves — they say, \"In what state were you?\" They say, \"We were weak in the land.\" They say, \"Was not the land of Allah spacious, that you might have emigrated in it?\" Those — their destination is Jahannam, and evil is the arrival.", "নিজেদের আত্মার উপর অত্যাচার করা কালীন যাদের জীবন ফেরেশতা দ্বারা সমাপ্ত করা হয়, তাদেরকে ফেরেশতারা প্রশ্ন করবে,\"তোমাদের কি সমস্যা ছিল? তারা বলবে যে,“আমরা পৃথিবীতে নিপীড়িত ছিলাম”। তারা বলবে,“স্থান পরিবর্তন করতে আল্লাহর পৃথিবী কি তোমাদের জন্য যথেষ্ট প্রশস্ত ছিল না”? এদের জন্য, চূড়ান্ত বাসস্থান নরক, এবং একটি শোচনীয় নিয়তি।"],
  "4:98": ["Except the weak among men, nisa, and children who can find no means and are not guided to a way.", "নিষ্কৃতি প্রাপ্ত দুর্বল পুরুষ, নারী,এবং শিশুরা,যারা শক্তি বা সংগতি রাখে না প্রস্থান করার।"],
  "4:99": ["Those — perhaps Allah will pass over them. And Allah has been ever-passing-over, forgiving.", "হতে পারে এরা আল্লাহ দ্বারা ক্ষমাপ্রাপ্ত হবে,আল্লাহ মার্জনাকারী  ক্ষমাশীল।"],
  "4:100": ["Whoever emigrates in the way of Allah will find in the land many a refuge and spaciousness. And whoever leaves his home emigrating toward Allah and the Rasul, then death overtakes him — his reward has fallen upon Allah. And Allah has been forgiving, merciful.", "যে কেউ আল্লাহর উদ্দেশ্যে স্থান পরিবর্তন করে,সে পৃথিবীতে পাবে মহা দান এবং ঐশ্বর্য। যেকেউ আল্লাহ এবং তাঁর বার্তাবাহকের দিকে স্থান পরিবর্তন করতে তার ঘর পরিত্যাগ করে,এরপর মৃত্যু তাকে তুলে নেয়, তার পুরস্কার আল্লাহর কাছে সংরক্ষিত রয়েছে। আল্লাহ ক্ষমাশীল, পরম করুণাময়।"],
  "4:101": ["And when you travel through the land, there is no blame on you in shortening the prayer, if you fear that those who disbelieve may assail you. Truly the unmuminin have been for you a clear enemy.", "যখন তোমরা যুদ্ধের সময় ভ্রমণ কর, তখন তোমরা সংযোগ প্রার্থনাসমূহ (সালাত) সংক্ষিপ্ত করে কোন ভুল কর না,যদি তোমরা ভয় পাও যে,অবিশ্বাসীরা তোমাদেরকে আক্রমণ করতে পারে। নিশ্চিতভাবে,অবিশ্বাসীরা তোমাদের ঘোর শত্রু।"],
  "4:102": ["And when you are among them and establish the prayer for them, let a party of them stand with you and let them take their weapons. Then when they have bowed down, let them be behind you, and let another party come who have not prayed, and let them pray with you, and let them take their precaution and their weapons. Those who disbelieve wish that you be unmindful of your weapons and your gear, so that they may rush upon you in one rush. There is no blame on you if harm from rain or illness befalls you in laying down your weapons — but take your precaution. Truly Allah has prepared for the unmuminin a humiliating punishment.", "যখন তুমি তাদের সাথে থাক, এবং তাদের জন্য সংযোগ প্রার্থনা (সালাত) পরিচালনা কর, তোমাদের কিছু লোককে পাহারায় নিয়োজিত কর; তারা তাদের অস্ত্রসমূহ ধরে রাখবে,এবং তারা তোমার পিছনে দাঁড়িয়ে থাকবে যখন তুমি সেজদা করো। এরপর, অন্য দলটি,যারা প্রার্থনা করেনি,তোমার সাথে তাদের প্রার্থনার পালা সম্পন্ন করবে,যখন অন্যরা পাহারা দিবে এবং অস্ত্রসমূহ ধরে থাকবে। যারা অবিশ্বাস করে তারা তোমাদেরকে তোমাদের অস্ত্রসমূহ এবং তোমাদের যন্ত্রপাতির প্রতি অবহেলারত অবস্থায় দেখতে চায়, যাতে তোমাদেরকে চুড়ান্তভাবে আক্রমণ করা যায়। তোমরা কোন ভুল করো না তোমাদের অস্ত্রসমূহ নিচে রেখে,যদি তোমরা বৃষ্টি বা আঘাতের দ্বারা বাধাপ্রাপ্ত হও, যতক্ষণ পর্যন্ত তোমরা সতর্ক থাক। আল্লাহ অবিশ্বাসীদের জন্য এক লজ্জাকর প্রতিদান প্রস্তুত রেখেছেন।"],
  "4:103": ["Then when you have completed the prayer, remember Allah standing and sitting and on your sides. Then when you are secure, establish the prayer. Truly the prayer has been upon the muminin a timed ordinance.", "যখন তোমরা তোমাদের সংযোগ প্রার্থনা (সালাত) সম্পন্ন কর, তোমরা আল্লাহকে স্মরণ করবে দাঁড়ানো,বসা অথবা শায়িত অবস্থায়। যখন যুদ্ধ শেষ হয়, তোমরা সংযোগ প্রার্থনাসমূহ (সালাত) স্থাপন করবে; সংযোগ প্রার্থনাসমূহ (সালাত) বিশ্বাসীদের জন্য নির্দিষ্ট সময়সমূহে (সম্পন্ন করার) আদেশ করা হয়েছে।"],
  "4:104": ["And do not weaken in seeking the people. If you suffer, they suffer as you suffer, while you hope from Allah what they do not hope. And Allah has been knowing, wise.", "শত্রুদের তাড়া করতে দিধান্বিত হইও না।  যদি তোমরা কষ্ট ভোগ কর, তারাও কষ্ট ভোগ করে। কিন্তু,তোমরা আল্লাহ থেকে প্রত্যাশা কর, যা তারা কখনোই প্রত্যাশা করে না। আল্লাহ সর্বজ্ঞ, সবচেয়ে জ্ঞানী।"],
  "4:105": ["Truly We have sent down the Book to you in truth, that you may judge among people by what Allah has shown you. And do not be an advocate for the betrayers.", "আমরা তোমার কাছে ঐশীগ্রন্থ অবতীর্ণ করেছি,সত্যতার সাথে,আল্লাহ তোমাকে যা দেখিয়েছেন সে অনুসারে লোকদের মাঝে বিচার করতে। তুমি বিশ্বাসঘাতকদের পক্ষ নিবে না।"],
  "4:106": ["And seek forgiveness from Allah. Truly Allah has been forgiving, merciful.", "তোমরা আল্লাহর কাছে ক্ষমার জন্য মিনতি করবে। আল্লাহ ক্ষমাশীল পরম দয়ালু।"],
  "4:107": ["And do not dispute on behalf of those who betray themselves. Truly Allah loves not whoever is a betraying sinner.", "যারা তাদের নিজেদের আত্মার ক্ষতি করেছে তাদের পক্ষ হয়ে তর্ক করো না; আল্লাহ কোন বিশ্বাসঘাতক, অপরাধীকে ভালবাসেন না।"],
  "4:108": ["They hide from people but do not hide from Allah, though Allah is with them when they pass the night in what does not please of speech. And Allah has been encompassing what they do.", "তারা মানুষের কাছ থেকে লুকায়, আর আল্লাহর কাছ থেকে লুকানোকে পরোয়া করে না,যদিও তারা তাঁর অপছন্দনীয় ধারণাগুলো মনে পোষণ করার সময়ও তিনি তাদের সাথেই থাকেন। আল্লাহ তাদের করা সবকিছু সম্পূর্ন অবগত।"],
  "4:109": ["There you are — you disputed on their behalf in worldly life. But who will dispute with Allah on their behalf on the Day of Standing? Or who will be a guardian over them?", "এখানে,এই দুনিয়ায় তুমি তাদের পক্ষে তর্ক করছ; পুনরুত্থানের দিবসে তাদের পক্ষে কে আল্লাহর সাথে তর্ক করতে যাচ্ছে? কে হতে যাচ্ছে তাদের উকিল?"],
  "4:110": ["Whoever does evil or wrongs himself, then seeks forgiveness from Allah, will find Allah forgiving, merciful.", "যে কেউ মন্দ সম্পাদন করে,অথবা তার আত্মার ক্ষতি করে,এরপর ক্ষমার জন্য আল্লাহর কাছে মিনতি করে,সে আল্লাহকে ক্ষমাশীল, পরম দয়ালু পাবে।"],
  "4:111": ["Whoever earns a sin only earns it against himself. And Allah has been knowing, wise.", "যে কেউ পাপ অর্জন করে,তা তার নিজ আত্মার ক্ষতি করতে অর্জন করে। আল্লাহ সর্বজ্ঞ, সবচেয়ে জ্ঞানী।"],
  "4:112": ["Whoever earns an error or a sin, then casts it upon an innocent one, has borne a stunning-slander and a manifest sin.", "যে কেউ পাপ অর্জন করে,এরপর একজন নির্দোষ ব্যক্তিকে এজন্য অভিযুক্ত করে,সে মিথ্যাচার এবং এক গুরুতর অপরাধ করেছে।"],
  "4:113": ["Were it not for Allah's bounty upon you and mercy, a band of them would have resolved to lead you astray. But they lead astray only themselves, and they cannot harm you in anything. And Allah sent down upon you the Book and wisdom, and taught you what you did not know. And the bounty of Allah upon you has been tremendous.", "যদি এটি তোমার প্রতি আল্লাহর অনুগ্রহ, এবং তাঁর দয়া না হতো,তাদের কেউ কেউ তোমাকে বিপথগামী করত। তারা শুধু তাদের নিজেদেরকে বিপথগামী করে,এবং তারা কখনোই তোমার সামান্যতম ক্ষতি করতে পারে না। আল্লাহ তোমার কাছে ঐশীগ্রন্থ এবং প্রজ্ঞা অবতীর্ণ করেছেন, এবং তিনি তোমাকে শিখিছেন যা তুমি কখনোই জানতে না। প্রকৃতপক্ষে,তোমার উপর আল্লাহর আশীর্বাদসমূহ বিশাল।"],
  "4:114": ["There is no good in much of their secret talk, except one who bids charity or kindness or reconciliation between people. And whoever does that, seeking the pleasure of Allah, We shall give him a great reward.", "তাদের একান্ত সম্মেলনগুলোতে ভাল কিছু নেই, তাদেরটা ব্যতীত যারা দানের, অথবা সৎ কাজের, অথবা লোকদের মাঝে শান্তি আনয়নের উপদেশ দেয়। আল্লাহর শিক্ষাগুলোর প্রতি সাড়া দিয়ে যে কেউ তা করে,আমরা তাকে এক মহা প্রতিদান দিব।"],
  "4:115": ["Whoever opposes the Rasul after guidance has become clear to him, and follows other than the way of the muminin, We will turn him to what he turned to, and make him enter Jahannam — and evil is the arrival.", "আর যে বার্তাবাহকের বিরোধিতা করে,তাকে পথ-নির্দেশনা দেখানোর পর এবং বিশ্বাসীদের ছাড়া অন্যদের পথ অনুসরণ করে,আমরা তাকে পরিচালিত করবো সে পথে যা সে পছন্দ করেছে,এবং তাকে নরকে নিক্ষিপ্ত করবো; কি এক শোচনীয় নিয়তি!"],
  "4:116": ["Truly Allah does not forgive that one associate with Allah, and forgives what is below that for whom Allah wills. Whoever associates with Allah has gone far astray.", "আল্লাহ অংশীদার সাব্যস্ত করার পাপ ক্ষমা করেন না (যদি মৃত্যু অবধি বজায় রাখা হয়) এবং তিনি যার জন্য ইচ্ছা এর থেকে ছোট অপরাধ ক্ষমা করেন। যে কেউ আল্লাহর পাশে অন্য যে কোন উপাস্যের উপাসনা করে সে বহু দূরে পথভ্রষ্ট হয়েছে।"],
  "4:117": ["They call upon, other than Allah, only females; and they call upon only a defiant Shaytan.", "তারা এমনকি তাঁর পাশে নারী উপাস্যের উপাসনা করে; বস্তুত, তারা শুধু এক বিদ্রোহী শয়তানের উপাসনা করে।"],
  "4:118": ["Allah cursed him, and he said, \"I will surely take from Your servants an ordained portion.\"", "আল্লাহ তাকে নিন্দিত করেছেন, এবং সে বলেছিল, “আমি অবশ্যই তোমার উপাসনাকারিদের একটি নির্দিষ্ট অংশকে নিয়োজিত করবো।"],
  "4:119": ["\"I will surely mislead them, and surely grant them their wishes, and surely command them, so they will slit the ears of cattle; and I will surely command them, so they will change the creation of Allah.\" Whoever takes Shaytan as an ally other than Allah has lost a manifest loss.", "“আমি তাদেরকে পথভ্রষ্ট করবো,আমি তাদেরকে প্রলুব্ধ করবো,আমি তাদেরকে হুকুম করবো (নির্দিষ্ট কিছুর মাংস খাওয়া নিষিদ্ধ করতে) গবাদি পশুর কানে চিহ্ন প্রদানের দ্বারা,এবং আমি তাদেরকে হুকুম করবো ঈশরের সৃষ্টিকে বিকৃত করতে”। যে কেউ শয়তানকে একজন প্রভু হিসাবে গ্রহণ করে,আল্লাহর বদলে,সে টেনে এনেছে এক গভীর ক্ষতি।"],
  "4:120": ["He promises them and grants them wishes, but Shaytan promises them only deception.", "সে তাদেরকে প্রতিশ্রুতি দেয় এবং তাদেরকে প্রলুব্ধ করে; শয়তান যা প্রতিশ্রুতি দেয় তা বিভ্রম ছাড়া কিছুই নয়।"],
  "4:121": ["Those — their destination is Jahannam, and they will find no escape from it.", "এরা টেনে এনেছে নরক তাদের চুড়ান্ত আবাস হিসেবে,এবং কখনো এটি এড়াতে পারে না।"],
  "4:122": ["And those who believe and do salih deeds, We shall admit them into gardens beneath which rivers flow, abiding therein forever. Allah's promise is truth. And who is more sadiq than Allah in saying?", "আর তারা যারা বিশ্বাস করে এবং সৎকর্মশীল জীবন-যাপন করে,আমরা তাদেরকে প্রবেশ করাব প্রবাহিত ঝর্নাসহ বাগানসমূহে,যেখানে তারা চিরকাল বসবাস করে। এরকমই আল্লাহর সত্য অঙ্গীকার। আল্লাহর চেয়ে কার কথা অধিক সত্য?"],
  "4:123": ["It is not by your wishes, nor by the wishes of the people of the Book. Whoever does evil is recompensed for it, and he will not find for himself, other than Allah, a protector or a helper.", "এটি তোমাদের, অথবা ঐশীগ্রন্থের লোকদের ইচ্ছানুযায়ী নয়ঃ যেকেউ মন্দ করে এর জন্য ক্ষতিপূরণ দেয়, এবং আল্লাহর বিপক্ষে তার কোন সাহায্যকারী অথবা সমর্থক থাকবে না।"],
  "4:124": ["And whoever does salih deeds, whether male or female, and is a mumin — those will enter the Garden, and they will not be wronged a speck.", "আর তারা যারা বিশ্বাস করে এবং সৎকর্মশীল জীবন-যাপন করে বিশ্বাসী অবস্থায়, পুরুষ হোক অথবা নারী,তারা স্বর্গোদ্যানে প্রবেশ করে; সামান্যতম অবিচার ছাড়াই।"],
  "4:125": ["And who is better in way than one who submits his face to Allah while being a doer of good, and follows the creed of Ibrahim, upright? And Allah took Ibrahim as a bosom-friend.", "কে তার ধর্মে উত্তম পথপ্রাপ্ত সে ব্যক্তির চেয়ে যে আল্লাহর কাছে পরিপূর্নভাবে আত্মসমর্পন করে,সৎকর্মশীল জীবন-যাপন করে,ইব্রাহিমের ধর্মবিশ্বাস অনুসারেঃ একেশ্বরবাদ? আল্লাহ ইব্রাহিমকে অতিশয় প্রিয় বন্ধু হিসেবে পছন্দ করেছেন।"],
  "4:126": ["And to Allah belongs whatever is in the heavens and whatever is in the earth. And Allah has been encompassing everything.", "আকাশমন্ডলী এবং পৃথিবীর সবকিছু আল্লাহর। আল্লাহ সকল বস্তুর পরিপূর্ণ নিয়ন্ত্রণে আছেন।"],
  "4:127": ["They ask you for a ruling concerning the nisa. Say: Allah gives you a ruling concerning them, and concerning what is recited to you in the Book — the orphan nisa to whom you do not give what is decreed for them while you are eager to marry them; and the weak among children; and that you stand in equity for the orphans. And whatever good you do, truly Allah has been knowing of it.", "তারা নারীদের ব্যাপারে তোমার সাথে পরামর্শ করেঃ বল, “আল্লাহ তাদের ব্যাপারে তোমাদের জ্ঞান দান করেন, যেমনটি ঐশীগ্রন্থে তোমাদের জন্য আবৃত্তি করা হয়। তোমরা এতিম মেয়েদের অধিকার ফিরিয়ে দেবে যাদেরকে তোমরা তাদের প্রাপ্য দেনমোহর হতে ঠকাও, যখন তোমরা তাদেরকে বিয়ে করার ইচ্ছা করঃ তোমরা তাদের সুবিধা নেবে না। এতিম বালকদের অধিকারসমূহও অবশ্যই একই ভাবে সংরক্ষন করতে হবে। তোমরা এতিমদের সাথে ন্যায়সঙ্গত ব্যবহার করবে। যা কিছু ভালো তোমরা করো,আল্লাহ সেসব সম্পর্কে সম্পূর্ণ জ্ঞাত।"],
  "4:128": ["And if an imra'a fears from her husband estrangement or turning-away, there is no blame on the two if they reconcile between themselves a reconciliation. And reconciliation is best, though souls are summoned to stinginess. And if you do good and are reverent, truly Allah has been aware of what you do.", "যদি কোন নারী তার স্বামী থেকে নিপীড়ন অথবা উপেক্ষার আশঙ্কা করে,দম্পতিটি তাদের বিবাদগুলো মিটিয়ে ফেলার চেষ্টা করবে,কারন বিবাদ মিটিয়ে ফেলা তাদের জন্য সর্বোত্তম। স্বার্থপরতা একটি মানব বৈশিষ্ট্য, এবং যদি তুমি ভালো করো এবং সৎ জীবন-যাপন করো,তোমাদের করা সবকিছু সম্পর্কে আল্লাহ সম্পূর্ন জ্ঞাত।"],
  "4:129": ["And you will never be able to do justice between nisa, however ardently you desire it. So do not lean with the whole leaning, leaving her like one suspended. And if you reconcile and are reverent, truly Allah has been forgiving, merciful.", "তোমরা একের অধিক স্ত্রীর সাথে আচরনের বেলায কখনই ন্যায়পরায়ণ হতে পারবে না,যত কঠিন চেষ্টাই তোমরা করো না কেন। সে জন্য, এতো পক্ষপাতদুষ্ট হয়ো না যে তাদের যে কোন একজন কে ঝুলিয়ে রাখো (না বিয়ে উপভোগ করতে দিয়ে,না অন্যকাউকে বিয়ে করতে দিয়ে)। যদি তোমরা এই অবস্থা সংশোধন করো এবং সততা বজায় রাখো,আল্লাহ ক্ষমাশীল, পরম করুণাময়।"],
  "4:130": ["And if the two part, Allah will enrich each from Allah's abundance. And Allah has been all-ample, wise.", "যদি দম্পতিটি পৃথক হওয়ারই সিদ্ধান্ত নেয়, আল্লাহ তাদের প্রত্যেকের জন্যই তাঁর অনুগ্রহসমূহ থেকে দেবেন। আল্লাহ অনুগ্রহশীল, সবচেয়ে জ্ঞানী।"],
  "4:131": ["And to Allah belongs whatever is in the heavens and whatever is in the earth. We have charged those given the Book before you, and you, that you be mindful of Allah. And if you disbelieve — truly to Allah belongs whatever is in the heavens and whatever is in the earth. And Allah has been free of need, praiseworthy.", "আকাশমন্ডলী ও পৃথিবীর সবকিছু আল্লাহর, এবং আমরা আদেশ করেছি তাদের প্রতি যারা তোমাদের আগে ঐশীগ্রন্থ গ্রহন করেছিল, এবং আদেশ করেছি তোমাদেরকে যে,তোমরা আল্লাহকে ভক্তি করবে। যদি তোমরা অবিশ্বাস কর, তবে আকাশমন্ডলী ও পৃথিবীর সবকিছু আল্লাহর। আল্লাহ কোন প্রয়োজনের অধীন নন, প্রশংসনীয়।"],
  "4:132": ["And to Allah belongs whatever is in the heavens and whatever is in the earth. And sufficient is Allah as disposer.", "আকাশমন্ডলী এবং পৃথিবীর সবকিছু আল্লাহর, এবং আল্লাহই একমাত্র রক্ষাকারী।"],
  "4:133": ["If Allah wills, Allah can remove you, O humankind, and bring others. And Allah has been powerful over that.", "যদি তিনি ইচ্ছা করেন, তিনি তোমাদের নিশ্চিহ্ন করতে পারেন, হে মানুষ, এবং তোমাদের জায়গায় অন্যদের বসাতে পারেন। আল্লাহ নিশ্চিতভাবে এটি করতে সক্ষম।"],
  "4:134": ["Whoever desires the reward of the worldly life — with Allah is the reward of the worldly life and of the Last. And Allah has been hearing, seeing.", "যে কেউ এই দুনিয়ার পার্থিব বস্তুসামগ্রী খোঁজে তার জানা উচিত যে,আল্লাহ এই দুনিয়া এবং পরকাল, উভয়লোকের বস্তুসামগ্রীর অধিকারী। আল্লাহ শ্রোতা,দ্রষ্টা।"],
  "4:135": ["O muminin, be upholders in equity, witnesses for Allah, even against yourselves, or parents and near kin — whether one is rich or needy, Allah is worthier of the two. So do not follow desire, lest you swerve from justice. And if you twist aside or turn away — truly Allah has been aware of what you do.", "হে তোমরা যারা বিশ্বাস কর, তোমরা সম্পূর্নরুপে ন্যয়পরায়ন হবে,এবং আল্লাহকে মান্য করবে,যখন তোমরা সাক্ষী হিসেবে দায়িত্ব পালন কর, এমনকি তোমাদের নিজেদের বিরুদ্ধে,অথবা তোমাদের পিতা-মাতার, অথবা তোমাদের আত্মীয়দের। অভিযুক্ত ব্যক্তিটি ধনী অথবা গরীব হোক, আল্লাহ উভয়কে গুরুত্ব দেন। সেজন্য, তোমাদের ব্যক্তিগত কামনার দ্বারা পক্ষপাতদুষ্ট হইও না। যদি তোমরা বিচ্যুত হও অথবা উপেক্ষা কর (এই প্রত্যাদেশ), তবে আল্লাহ তোমাদের করা সবকিছু সম্পর্কে সম্পূর্ন অবগত।"],
  "4:136": ["O muminin, believe in Allah and the Rasul and the Book sent down upon Allah's Rasul, and the Book sent down before. Whoever disbelieves in Allah and the malakat and the Books and the Rasuls and the Last Day has gone far astray.", "হে তোমরা যারা বিশ্বাস করো,তোমরা বিশ্বাস করবে আল্লাহ এবং তাঁর বার্তাবাহককে,এবং সেই ঐশীগ্রন্থে যা তিনি তাঁর বার্তাবাহকের মাধ্যমে প্রকাশ করেছেন, এবং সেই ঐশীগ্রন্থে যা তিনি এর আগে প্রকাশ করেছেন। যে কেউ আল্লাহকে,এবং তাঁর স্বর্গ দূতদের, এবং তাঁর ঐশীগ্রন্থে,এবং তাঁর বার্তা বাহকে,এবং শেষ দিনে বিশ্বাস করতে প্রত্যাখ্যান করে,নিশ্চয়ই সে বহু দূর পথভ্রষ্ট হয়েছে।"],
  "4:137": ["Truly those who believe, then disbelieve, then believe, then disbelieve, then increase in disbelief — it is not for Allah to forgive them, nor to guide them a way.", "নিশ্চয়ই, যারা বিশ্বাস করে,এরপর অবিশ্বাস করে,এরপর আবার বিশ্বাস করে,এরপর আবার অবিশ্বাস করে,তারপর অবিশ্বাসের গভীরে নিমজ্জিত হয়, তাদেরকে আল্লাহ ক্ষমা করবেন না,না তিনি তাদেরকে কোন ভাবে পথ প্রদর্শন করবেন।"],
  "4:138": ["Give tidings to the munafiqin that for them is a painful punishment.", "ভণ্ডদের জানাও যে তারা যন্ত্রণাদায়ক শাস্তি টেনে এনেছে।"],
  "4:139": ["Those who take the unmuminin as allies other than the muminin — do they seek might with them? Truly all might belongs to Allah.", "তারা সে সব লোক যারা বিশ্বাসীদের বদলে অবিশ্বাসীদেরকে নিজেদের মিত্র বানায়। তারা কি তাদের সাথে থেকে মর্যাদা খোঁজ করেছে? সকল মর্যাদা একমাত্র আল্লাহর।"],
  "4:140": ["And it has been sent down to you in the Book that when you hear the signs of Allah being kafara and mocked, do not sit with them until they engage in other talk — or you would be like them. Truly Allah will gather the munafiqin and the unmuminin into Jahannam, all together.", "তিনি তোমাদের ঐশীগ্রন্থে নির্দেশ দিয়েছেন যেঃ যদি তোমরা শোন যে আল্লাহর প্রকাশনাবলিকে উপহাস এবং ব্যঙ্গ করা হচ্ছে,তোমরা তাদের সাথে বসবে না,যদি না তারা অন্য বিষয়ে চলে যায়। অন্যথায়, তোমরাও তাদের মত দোষী হবে। আল্লাহ ভণ্ডদের এবং অবিশ্বাসীদের একত্রে নরকে জড় করবেন।"],
  "4:141": ["Those who lie in wait against you: if a triumph from Allah comes to you, they say, \"Were we not with you?\" And if the unmuminin have a share, they say, \"Did we not gain advantage over you and shield you from the muminin?\" So Allah will judge between you on the Day of Standing, and Allah will never make for the unmuminin a way over the muminin.", "তারা তোমাদের প্রতি নজর রাখে এবং অপেক্ষা করে; যদি তোমরা আল্লাহর থেকে বিজয় অর্জন কর, তারা বলে (তোমাদেরকে), “আমরা কি তোমাদের সাথে ছিলাম না?”কিন্তু যদি অবিশ্বাসীরা একটি সুযোগ পায়, তারা (তাদেরকে) বলে,“আমরা কি তোমাদের পক্ষ নেই নি,এবং তোমাদেরকে বিশ্বাসীদের থেকে রক্ষা করিনি?”আল্লাহ পূনঃরুত্থান দিবসে তোমাদের মাঝে বিচার করবেন। আল্লাহ অবিশ্বাসীদের কখনোই বিশ্বাসীদের উপর জয়ী হতে দিবেন না।"],
  "4:142": ["Truly the munafiqin deceive Allah, and it is Allah who outwits them. And when they stand to the prayer they stand sluggish, showing off to people, and they do not remember Allah except a little.", "ভন্ডরা মনে করে যে তারা আল্লাহকে প্রতারিত করছে,কিন্তু তিনিই তাদেরকে ছেড়ে দিয়ে রাখেন। তারা যখন সংযোগ প্রার্থনার (সালাত) জন্য প্রস্তুতি নেয়, তারা অলসভাবে প্রস্তুতি নেয়। এটা এ কারনে যে তারা শুধু লোকদের সামনে প্রদর্শন করে,এবং তারা সামান্যই আল্লাহর চিন্তা করে।"],
  "4:143": ["Wavering between that — belonging neither to these nor to those. And whomever Allah leads astray, you will never find a way for him.", "তারা দুইয়ের মধ্যে দ্বিধাগ্রস্থ থাকে,না আছে এই দলে,না ঐ দলে। আল্লাহ যাকে পথভ্রষ্ট করেন, তুমি তাকে পথ-প্রদর্শিত করতে কখনোই কোন পথ খুঁজে পাবে না।"],
  "4:144": ["O muminin, do not take the unmuminin as allies other than the muminin. Do you wish to make for Allah against yourselves a clear warrant?", "হে তোমরা যারা বিশ্বাস কর, তোমরা নিজেদেরকে অবিশ্বাসীদের মিত্র করবে না,বিশ্বাসীদের পরিবর্তে। তোমরা কি নিজেদের বিরুদ্ধে আল্লাহকে সুস্পষ্ট প্রমান দিতে চাও?"],
  "4:145": ["Truly the munafiqin are in the lowest reach of the fire, and you will never find a helper for them.", "ভন্ডদের স্থান হবে নরকের সর্বনিম্ন খাঁদ, এবং তুমি তাদেরকে সাহায্য করতে কাউকে পাবে না।"],
  "4:146": ["Except those who turned, set right, held fast to Allah, and devoted their way purely to Allah — those are with the muminin, and Allah will give the muminin a great reward.", "শুধু যারা অনুশোচনা করে,সংশোধিত হয়, আল্লাহকে দৃঢ় ভাবে আকড়েঁ থাকে,এবং তাদের ধর্মকে পরিপূর্ণ ভাবে শুধু আল্লাহর প্রতি উৎসর্গ করে,তাদেরকে বিশ্বাসীদের সাথে গননা করা হবে। আল্লাহ বিশ্বাসীদের মহা প্রতিদান দিয়ে আশীর্বাদ করবেন।"],
  "4:147": ["What would Allah do with your punishment, if you give thanks and believe? And Allah has been appreciative, knowing.", "তোমাদের শাস্তি দিয়ে আল্লাহ কি অর্জন করবেন, যদি তোমরা কৃতজ্ঞ হয়ে বিশ্বাস কর? আল্লাহ সুবিবেচক, সর্বজ্ঞ।"],
  "4:148": ["Allah loves not open loudness with evil of speech, except by one who has been wronged. And Allah has been hearing, knowing.", "আল্লাহ মন্দ ভাষা উচ্চারণ করা পছন্দ করেন না,যদি না কারো সাথে মহা অন্যায় করা হয়। আল্লাহ শ্রোতা,জ্ঞাতা।"],
  "4:149": ["If you manifest good or conceal it, or pass over evil — truly Allah has been ever-passing-over, powerful.", "যদি তোমরা সৎ কাজ করো- হোক তা প্রকাশ্য অথবা গোপন- অথবা কোন সীমালঙ্ঘন ক্ষমা করো,আল্লাহ ক্ষমাশীল, সর্বশক্তিমান।"],
  "4:150": ["Truly those who disbelieve in Allah and the Rasuls, and wish to separate between Allah and the Rasuls, and say, \"We believe in some and disbelieve in some,\" wishing to take a way between that.", "যারা আল্লাহ এবং তাঁর বার্তাবাহদের অবিশ্বাস করে,এবং আল্লাহ ও তাঁর বার্তাবাহকদের মাঝে পার্থক্য করতে চায়, এবং বলে,“আমরা কাউকে বিশ্বাস করি এবং কাউকে প্রত্যাখ্যান করি,”এবং মধ্যবর্তী একটি পথ অনুসরণ করতে চায়।"],
  "4:151": ["Those are the unmuminin in truth, and We have prepared for the unmuminin a humiliating punishment.", "এরাই হচ্ছে প্রকৃত অবিশ্বাসী। আমরা অবিশ্বাসীদের জন্য প্রস্তত রেখেছি এক লজ্জাকর শাস্তি।"],
  "4:152": ["And those who believe in Allah and the Rasuls and make no separation between any of them — those Allah will surely give their rewards. And Allah has been forgiving, merciful.", "আর তাদের জন্য যারা আল্লাহ এবং তাঁর বার্তাবাহকদের বিশ্বাস করে,এবং তাদের মধ্যে কোন পার্থক্য করে না,তিনি তাদেরকে  প্রতিদান দিবেন। আল্লাহ ক্ষমাকারী,পরম দয়ালু।"],
  "4:153": ["The people of the Book ask you to send down upon them a book from the heaven. They asked Musa for greater than that; they said, \"Show us Allah openly.\" So the thunderstrike seized them for their wrong. Then they took the calf after the clear proofs had come to them — yet We passed over that, and We gave Musa a clear warrant.", "ঐশীগ্রন্থের লোকেরা তোমাকে আকাশ থেকে তাদের কাছে একটি গ্রন্থ আনার চ্যালেঞ্জ করে! তারা মূসার কাছে এর চেয়ে বেশি চেয়েছিল, এই বলে যে,\"আমাদেরকে আল্লাহ দেখাও, স্বশরীরে। “ফলস্বরুপ, বিদ্যুৎ চমক তাদের আঘাত করেছিল, তাদের দু:সাহসের একটি ফলস্বরুপ। উপরন্তু,তারা সকল অলৌকিকতা দেখার পর বাছুর পূজা করেছিল। এরপরও, আমরা এই সব ক্ষমা করেছিলাম। আমরা মূসাকে প্রগাঢ় অলৌকিকতাসমূহ দিয়ে সমর্থন করেছিলাম।"],
  "4:154": ["And We raised the Mount above them at their pact, and We said to them, \"Enter the gate bowing down,\" and We said to them, \"Do not transgress in the Sabbath,\" and We took from them a hard pact.", "এবং আমরা তাদের উপর সিনাই পর্বতকে তুলে ধরেছিলাম, যখন আমরা তাদের অঙ্গীকার নিয়েছিলাম। এবং আমারা তাদেরকে বলেছিলাম, \"বিনীতভাবে দরজায় প্রবেশ কর\"। এবং আমারা তাদেরকে বলেছিলাম, \"সাব্বাথ (বিশ্রামের দিন) কে অপবিত্র করো না।”প্রকৃতপক্ষে,আমরা তাদের থেকে একটি সুদৃঢ় অঙ্গীকার নিয়েছিলাম।"],
  "4:155": ["For their breaking of the pact, and their disbelief in the signs of Allah, and their killing of the nabis without right, and their saying, \"Our hearts are wrapped\" — rather, Allah has stamped them over for their disbelief, so they do not believe except a few.", "(তারা শাস্তি টেনে এনেছে) তাদের অঙ্গীকার লঙ্ঘন করার জন্য, আল্লাহর প্রত্যাদেশসমূহ প্রত্যাক্ষান করার জন্য, নবীদেরকে অন্যায়ভাবে হত্যা করার জন্য, এবং বলার জন্য যে,“আমাদের সিদ্ধান্ত স্থির হয়ে গেছে!”প্রকৃতপক্ষে,আল্লাহই তিনি যিনি তাদের অন্তরে মোহর এটে দিয়েছেন, তাদের অবিশ্বাসের দরুন, এবং এ কারনেই তারা বিশ্বাস করতে ব্যর্থ হয়, খুব কম সংখ্যক ছাড়া।"],
  "4:156": ["And for their disbelief, and their uttering against Maryam a great slander.", "(তারা নিন্দিত) অবিশ্বাস করার জন্য এবং মরিয়ম সম্পর্কে এক স্পষ্ট মিথ্যা বলার জন্য।"],
  "4:157": ["And their saying, \"We killed the Anointed, Isa son of Maryam, the Rasul of Allah\" — but they did not kill him, and they did not crucify him; rather, it was made unclear to them. Indeed, those who differ over it are in doubt of it; they have no knowledge of it except following conjecture, and they did not kill him with certainty.", "এবং দাবী করার জন্য যে তারা আল্লাহর বার্তাবাহক, মরিয়মের পুত্র, ঈসা,মসিহকে হত্যা করেছে। প্রকৃত পক্ষে,তারা কখনোই তাকে হত্যা করেনি,তারা কখনোই তাকে ক্রুশ বিদ্ধ করেনি- তাদেরকে মনে করানো হয়েছিল যে তারা করেছিল। সকল বিরোধী দল যারা এই নিয়ে বিবাদ করছে,তারা এই সংক্রান্ত বিষয়ে পূর্ণ সন্দেহে রয়েছে। তাদের কোন জ্ঞান নেই, তারা শুধু অনুমান করে। নিশ্চিতই, তারা কখনই তাকে হত্যা করেনি।"],
  "4:158": ["Rather, Allah raised him up to Allah. And Allah has been mighty, wise.", "বরং, আল্লাহ তাঁর কাছে তাকে উঠিয়ে নিয়েছেন; আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "4:159": ["And there is none of the people of the Book but will surely believe in him before his death, and on the Day of Standing he will be a witness over them.", "ঐশীগ্রন্থধারীদের সকলকে তার মৃত্যুর পূর্বে তার প্রতি বিশ্বাস আনা আবশ্যক ছিল। পুনরুত্থান দিবসে,সে তাদের বিরুদ্ধে সাক্ষী হবে।"],
  "4:160": ["For the wrongdoing of the Jews, We forbade them good things that had been made lawful to them, and for their turning away from the way of Allah, much.", "তাদের সীমাতিক্রমের কারনে,আমরা ইহুদীদের জন্য ভালো খাদ্য নিষিদ্ধ করেছিলাম যা তাদের জন্য আইনসিদ্ধ ছিল; অধিকন্তু অনবরত আল্লাহর পথে  বাধা প্রদান করার জন্য।"],
  "4:161": ["And their taking of usury when they had been forbidden it, and their devouring of people's wealth falsely. And We have prepared for the unmuminin among them a painful punishment.", "এবং চড়া সুদ অনুশীলনের জন্য, যা নিষিদ্ধ ছিল এবং লোকেদের অর্থ অন্যায়ভাবে ভোগ করার জন্য। আমরা তাদের মধ্যকার অবিশ্বাসীদের জন্য প্রস্তুত রেখেছি যন্ত্রনাদায়ক শাস্তি।"],
  "4:162": ["But those deeply rooted in knowledge among them, and the muminin, believe in what was sent down to you and what was sent down before you — the establishers of the prayer, the givers of the purifying dues, the muminin in Allah and the Last Day. Those We will surely give a great reward.", "আর তাদের মধ্যে যাদের জ্ঞান দৃঢ় ভিত্তির উপর প্রতিষ্ঠিত এবং বিশ্বাসীরা,তারা বিশ্বাস করে যা তোমার প্রতি অবতীর্ণ হয়েছিল এবং যা তোমার পূর্বে অবতীর্ণ হয়েছিল। তারা সংযোগ প্রার্থনাসমূহ (সালাত) পালনকারী,এবং বাধ্যতামূলক দান (যাকাত) প্রদানকারী ; তারা আল্লাহতে এবং শেয দিবসে বিশ্বাসকারী। আমরা তাদেরকে এক মহা প্রতিদান প্রদান করি।"],
  "4:163": ["Truly We revealed to you as We revealed to Nuh and the nabis after him, and We revealed to Ibrahim and Ismail and Ishaq and Yaqub and the Tribes, and Isa and Ayyub and Yunus and Harun and Sulayman, and We gave Dawud a scripture.", "আমরা তোমাকে অনুপ্রানিত করেছি,যেমন অনুপ্রানিত করেছিলাম নুহ এবং তার পরের নবীদেরকে। এবং আমরা অনুপ্রানিত করেছিলাম ইব্রাহিম, ইসমাইল, ইসহাক, ইয়াকুব, গোত্রপ্রধানদের, ঈসা,আয়ুব, ইউনুস, হারুন, এবং সোলাইমানকে। এবং আমরা দাউদকে যবুর দিয়েছিলাম।"],
  "4:164": ["And rusul We have narrated to you before, and rusul We have not narrated to you. And Allah spoke to Musa directly.", "বার্তাবাহকরা,যাদের সম্পর্কে আমরা তোমাকে বলেছি,এবং বার্তাবাহকেরা,যাদের সম্পর্কে আমরা তোমাকে কখনো বলিনি। এবং আল্লাহ মুসার সাথে সরাসরি কথা বলেছিলেন।"],
  "4:165": ["Messengers bearing glad tidings and warnings, so that humankind would have no proof against Allah after the Rasuls. And Allah has been mighty, wise.", "বার্তাবাহকেরা সুসংবাদ, একই সাথে সতর্কতা প্রদান করতে আসে। এভাবে,লোকদের কোন অজুহাত থাকবে না যখন তারা আল্লাহর সম্মুখীন হয়, তাদের কাছে এই সকল বার্তাবাহকদের আসার পর। আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "4:166": ["But Allah bears witness to what was sent down to you — Allah sent it down with Allah's knowledge — and the malakat bear witness. And sufficient is Allah as witness.", "কিন্তু আল্লাহ সাক্ষ্য দেন, সে সম্বন্ধে,যা তিনি তোমার কাছে প্রকাশ করেছেন; তিনি তাঁর জ্ঞান থেকে তা প্রকাশ করেছেন। এবং ফেরেশতারা একই রকম সাক্ষ্য দেয়, কিন্তু সাক্ষী হিসেবে আল্লাহই যথেষ্ট।"],
  "4:167": ["Truly those who kafara and turned away from the way of Allah have gone far astray.", "নিশ্চিতভাবে,যারা অবিশ্বাস করে এবং আল্লাহর পথে বাধা দেয়, তারা বহুদূর পথভ্রষ্ট হয়েছে।"],
  "4:168": ["Truly those who kafara and wronged — it is not for Allah to forgive them nor to guide them a path.", "যারা অবিশ্বাস করে এবং সীমাতিক্রম করে,আল্লাহ তাদেরকে ক্ষমা করবেন না,না তিনি তাদেরকে কোন ভাবে পথপ্রদর্শন করবেন;"],
  "4:169": ["Except the path of Jahannam, abiding therein forever. And that is easy for Allah.", "নরকের পথে ছাড়া,যেখানে তারা চিরকাল বসবাস করে। এটা আল্লাহর জন্য করা সহজ।"],
  "4:170": ["O humankind, the Rasul has come to you with truth from your Rabb, so believe — it is better for you. And if you disbelieve, then truly to Allah belongs whatever is in the heavens and the earth. And Allah has been knowing, wise.", "হে লোকেরা,বার্তাবাহক তোমাদের কাছে তোমাদের প্রভুর পক্ষ থেকে সত্য সহকারে এসেছে। সুতরাং,তোমারা তোমাদের নিজেদের ভালোর জন্য বিশ্বাস করবে। যদি তোমরা অবিশ্বাস করো; তবে আকাশ এবং পৃথিবীর সবকিছু আল্লাহর। আল্লাহ সর্বজ্ঞ, সবচেয়ে জ্ঞানী।"],
  "4:171": ["O people of the Book, do not exaggerate in your way, and do not say of Allah anything but the truth. The Anointed, Isa son of Maryam, is only the Rasul of Allah, and the word of Allah cast to Maryam, and a spirit from Allah. So believe in Allah and the Rasuls, and do not say \"Three.\" Desist — it is better for you. Truly Allah is one ilah; exalted is Allah above having a child. To Allah belongs whatever is in the heavens and whatever is in the earth, and sufficient is Allah as disposer.", "হে ঐশীগ্রন্থের লোকেরা,তোমাদের ধর্মের সীমা অতিক্রম করো না,এবং আল্লাহ সম্পর্কে সত্য ছাড়া বলবে না। মরিয়মের পুত্র, ঈসা,মসিহ ছিল আল্লাহর বার্তাবাহক, এবং তাঁর বানী যা তিনি মরিয়মের কাছে পাঠিয়েছিলেন, এবং তাঁর থেকে একটি প্রকাশনা। সুতরাং,তোমরা আল্লাহ এবং তাঁর বার্তাবাহকদের বিশ্বাস করবে। তোমরা \"ত্রিত্ব”বলবে না। তোমরা তোমাদের নিজেদের ভালোর জন্য এটি থেকে বিরত থাকবে। আল্লাহই শুধুমাত্র একক উপাস্য। তিনি মহিমান্বিত;পুত্র থাকার চেয়ে তিনি অনেক বেশি মহিমান্বিত। আসমান সমূহে যা কিছু আছে এবং পৃথিবীতে যা কিছু আছে,সব তাঁর। আল্লাহ প্রভু এবং মনিব হিসেবে যথেষ্ট।"],
  "4:172": ["The Anointed would never disdain being a servant of Allah, nor the brought-near malakat. And whoever disdains devotion to Allah and is arrogant — Allah will gather them all to Allah.", "মসিহ আল্লাহর একজন দাস হওয়াকে কখনোই ঘৃণা করত না,না করত নিকটতম ফেরেশতারা। যারা তাকে উপাসনা করতে ঘৃণা করে,এবং আত্মসমর্পণ করতে খুব অহংকারী,তিনি তাদের সবাইকে  তাঁর সামনে তলব করবেন।"],
  "4:173": ["Then as for those who believe and do salih deeds, Allah will pay them their rewards in full and increase them from Allah's bounty. And as for those who disdained and grew arrogant, Allah will punish them with a painful punishment, and they will not find for themselves, other than Allah, a protector or a helper.", "আর যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে,তিনি তাদেরকে পরিপূর্ণ প্রতিদান দিবেন, এবং তাদেরকে তাঁর করুনা বর্ষন করবেন। আর যারা ঘৃণা করে এবং অহংকারী হয়, তিনি তাদেরকে যন্ত্রনাদায়ক শাস্তি দিবেন। তারা আল্লাহর পাশে না পাবে কোন প্রভু,না কোন রক্ষাকারী।"],
  "4:174": ["O humankind, a clear proof has come to you from your Rabb, and We have sent down to you a clear light.", "হে লোকেরা,তোমাদের প্রভু হতে তোমাদের কাছে একটি প্রমান এসেছে ; আমরা তোমাদের কাছে এক প্রগাঢ় আলোকবর্তিকা অবতীর্ণ করেছি।"],
  "4:175": ["Then as for those who believe in Allah and hold fast to Allah, Allah will admit them into mercy from Allah, and bounty, and guide them to Allah along a straight path.", "তারা যারা আল্লাহকে বিশ্বাস করে,এবং তাকে আঁকড়ে ধরে থাকে,তিনি তাদেরকে তাঁর পক্ষ থেকে করুনা,এবং দয়া মঞ্জুর করবেন, এবং তাদেরকে তাঁর দিকে পথ-প্রদর্শিত করবেন, এক সরল পথে।"],
  "4:176": ["They ask you for a ruling. Say: Allah gives you a ruling concerning one who dies leaving neither parent nor child: if a man perishes having no child but having a sister, then for her is half of what he left; and he inherits from her if she has no child. If there are two sisters, then for them is two-thirds of what he left. And if there are brothers, men and nisa, then for the male is the share of two females. Allah makes clear to you, lest you go astray, and Allah is knowing of everything.", "তারা তোমার সাথে পরামর্শ করে; বল, “আল্লাহ অবিবাহিত ব্যক্তির বিষয়ে তোমাদেরকে উপদেশ দেন। যদি কেউ মৃত্যু বরণ করে এবং কোন সন্তান রেখে না যায়, এবং তার একজন বোন  থাকে,সে উত্তরাধিকারের অর্ধেক পাবে। যদি সে (বোন) পূর্বে মৃত্যুবরন করে,সে (ভাই) তার থেকে উত্তরাধিকার প্রাপ্ত হবে,যদি সে কোন সন্তান রেখে না যায়। যদি দুই বোন হয়, তারা উত্তরাধিকারের দুই তৃতীয়াংশ পাবে। যদি সহোদর পুরুষ এবং নারী হয়, পুরুষ নারীর দিগুন পাবে”। আল্লাহ এভাবে তোমাদের জন্য পরিষ্কার বর্ণনা করেন, পাছে তোমরা পথভ্রষ্ট হও। আল্লাহ সবকিছু সম্পর্কে পূর্ণ অবগত।"],
  "5:1": ["O you who believe, fulfill the pacts. Made lawful for you is the grazing livestock, except what is recited to you: hunting game is not permitted while you are in the sacred state. Allah decides what Allah wills.", "হে তোমরা যারা বিশ্বাস কর, তোমরা তোমাদের অঙ্গীকারসমূহ পরিপূর্ন করবে। তোমাদের জন্য পশু খাওয়া অনুমোদিত, সেগুলো ছাড়া যেগুলো এখানে নির্দিষ্টভাবে নিষেধ করা হয়েছে। তোমরা পুরো হজ্ব তীর্থযাত্রা জুড়ে শিকার করাকে অনুমোদন করবে না। আল্লাহ যা ইচ্ছা জারি করেন।"],
  "5:2": ["O you who believe, do not violate the rites of Allah, nor the sacred month, nor the offerings, nor the garlanded ones, nor those bound for the sacred house, seeking bounty from their Rabb and acceptance. And when you have left the sacred state, hunt. And let not the hatred of a people — because they barred you from the sacred Mosque — move you to transgress. And help one another to goodness and mindfulness, and do not help one another to sin and transgression. And be mindful of Allah; Allah is severe in punishment.", "হে যারা বিশ্বাস কর, না লঙ্ঘন করবে আল্লাহর দ্বারা প্রতিষ্ঠিত ধর্মানুষ্ঠানসমূহ, না পবিত্র মাসসমূহ, না সে পশু যেগুলো উৎসর্গ করা হবে,না মালাগুলো যা তাদের চিহ্নিত করছে,না সে লোকদেরকে যারা পবিত্র তীর্থস্থান (কাবার) অভিমুখে যায, খুঁজতে তাদের প্রভুর পক্ষ থেকে  দান এবং অনুমোদন। যখন তোমরা তীর্থযাত্রা সম্পন্ন কর, তোমরা শিকার করতে পার। আগ্রাসনে  প্ররোচিত হয়ো না,সে লোকদের প্রতি তোমাদের ঘৃনার দ্বারা,যারা এক সময় তোমাদেরকে পবিত্র মসজিদে যেতে বাধা দিয়েছিল। তোমরা সৎকর্মশীলতা এবং সৎকর্মশীলতার বিষয়ে সহযোগিতা করবে;সহযোগিতা করবে না সে বিষয়সমূহে যেগুলো পাপপূর্ন এবং মন্দ। তোমরা আল্লাহকে মান্য করবে। শাস্তি প্রয়োগে আল্লাহ কঠোর।"],
  "5:3": ["Forbidden to you are carrion, and blood, and the flesh of the pig, and what is dedicated to other than Allah, and the strangled, and the bludgeoned, and the fallen, and the gored, and what predators have eaten — except what you slaughter — and what is slaughtered upon the erected stones, and your apportioning by arrows. That is defiance. Today those who disbelieve have despaired of your religion, so do not fear them, but fear Me. Today I have completed your religion for you and completed My blessing upon you, and accepted Islam for you as religion. Whoever is compelled by hunger, not inclining to sin, then Allah is forgiving, merciful.", "তোমাদের জন্য নিষিদ্ধ সেসব পশু যেগুলো নিজে নিজে মারা যায়, রক্ত, শুকরের মাংস,এবং সেসব পশু যেগুলো আল্লাহ ছাড়া অন্য কারো প্রতি উৎসর্গীকৃত। (যেসব পশু নিজে নিজে মারা যায় অন্তর্ভূক্ত হয় সেগুলোর যেগুলো) শ্বাসরোধকৃত, কোন বস্তু দ্বারা আঘাতপ্রাপ্ত, উপর থেকে পতিত, তীক্ষ্ণ বস্তু দ্বারা বিদ্ধ, বন্য পশু দ্বারা আক্রান্ত - যদি না তোমরা তোমাদের পশুকে এটি মরার পূর্বে রক্ষা কর- এবং বেদীতে উৎসর্গীকৃত পশু। আরো নিষিদ্ধ ভাগ্যের খেলার মাধ্যমে মাংস বন্টন করা ; এটি একটি ঘৃণ্য কাজ। আজ, বিশ্বাসীরা তোমাদের ধর্ম (সমূলে উৎপাটনের) বিষয়ে আশা ছেড়ে দিয়েছে; তাদেরকে ভয় করো না এবং বদলে আমাকে ভয় করো। আজ, আমি তোমাদের ধর্ম সম্পূর্ন করেছি, তোমাদের উপর আমার আশীর্বাদ যথার্থ করেছি, এবং আমি আত্মসমর্পণকে তোমাদের জন্য ধর্ম হিসেবে নিয়ম করেছি। যদি কেউ দুর্ভিক্ষের জন্য বাধ্য হয় (নিষিদ্ধ খাদ্য খেতে), ইচ্ছাকৃতভাবে পাপপূর্ন না হয়ে, তবে আল্লাহ ক্ষমাকারী, দয়ালু।"],
  "5:4": ["They ask you what is made lawful for them. Say: the good things are made lawful for you, and the hunting beasts you train, teaching them from what Allah taught you. So eat of what they catch for you, and mention the name of Allah over it, and be mindful of Allah. Allah is swift in reckoning.", "তারা তোমার সাথে পরামর্শ করে,কি তাদের জন্য আইনসম্মত সে বিষয়ে; বল, “তোমাদের জন্য সকল ভালো জিনিস আইনসম্মত, এর মধ্যে আছে সেগুলো যা প্রশিক্ষণ প্রাপ্ত কুকুর এবং বাজপাখি তোমাদের জন্য ধরে আনে,”তোমরা তাদেরকে আল্লাহর শিক্ষা অনুসারে প্রশিক্ষণ দাও। তোমরা খেতে পারো যা তারা তোমাদের জন্য ধরে আনে,এবং সেগুলোর উপর আল্লাহর নাম বল। তোমরা আল্লাহকে মান্য করবে। আল্লাহ হিসাব গ্রহনে সবচেয়ে দক্ষ।"],
  "5:5": ["Today the good things are made lawful for you, and the food of those given the writ is lawful for you, and your food is lawful for them. And the chaste nisa of the muminin, and the chaste nisa of those given the writ before you, when you give them their dowries, in wedlock, not in license, nor taking secret lovers. And whoever disbelieves in faith — void is that one's work, and in the last world that one is among the khasirin.", "আজ, সকল ভালো খাদ্য তোমাদের জন্য আইনসম্মত করা হলো। ঐশীগ্রন্থের লোকদের খাদ্য তোমাদের জন্য আইনসম্মত। আরও, তোমরা বিশ্বাসীদের মধ্যে চরিত্রবান নারিদের বিয়ে করতে পারো,একই ভাবে পূর্ববর্তী ঐশীগ্রন্থের অনুসারিদের মধ্যে চরিত্রবান নারিদের, এই শর্তে যে তোমরা তাদেরকে তাদের প্রাপ্য মোহর প্রদান করবে। তোমরা (যৌণ) শুদ্ধতা বজায় রাখবে,ব্যভিচারে লিপ্ত না হয়ে,না গোপন প্রেমিক/প্রেমিকা রেখে। যে কেউ বিশ্বাস প্রত্যাখ্যান করে,তার সকল কর্ম নিষ্ফল হবে,এবং পরকালে সে ক্ষতিগ্রস্থদের সাথে থাকবে।"],
  "5:6": ["O you who believe, when you rise to the prayer, wash your faces and your hands up to the elbows, and wipe your heads and your feet up to the ankles. And if you are unwashed, purify yourselves. And if you are sick, or on a journey, or one of you comes from the privy, or you have touched nisa and find no water, then aim toward clean soil and wipe your faces and hands with it. Allah does not will to place any constriction upon you, but wills to purify you and to complete blessing upon you, so that you may give thanks.", "হে তোমরা যারা বিশ্বাস করো,যখন তোমরা সংযোগ প্রার্থনা (সালাত) প্রতিষ্ঠা করো,তোমরাঃ (১) তোমাদের মুখমণ্ডল ধোবে,(২) তোমাদের হাত কনুই পর্যন্ত ধোবে,(৩) তোমাদের মাথা মুছবে,এবং (৪) তোমাদের পায়ের পাতা গোড়ালি পর্যন্ত ধোবে। যদি তোমরা যৌন উত্তেজনার কারনে অপরিষ্কার থাকো,তোমরা গোসল করবে। যদি তোমরা অসুস্থ থাকো,অথবা ভ্রমনে থাকো,অথবা কোন পরিপাক ঘটিত নি:সরন থেকে থাকে (মূত্রজনিত, মলজনিত, অথবা বায়ু),অথবা নারিদের সাথে (যৌন) সংস্পর্শে এসে থাকো,এবং তোমরা পানি না পাও, তখন তোমরা শুষ্ক অজু (তায়াম্মুম) করবে পরিষ্কার শুষ্ক মাটি স্পর্শে করে,এরপর তোমাদের মুখমণ্ডল এবং হাত মুছার দ্বারা। আল্লাহ তোমাদের জন্য ধর্মকে কঠিন করতে চান না; তিনি তোমাদের পরিষ্কার করতে চান এবং তোমাদের প্রতি তাঁর আশীর্বাদ পূর্ণ করতে চান, যাতে তোমরা কৃতজ্ঞ হতে পার।"],
  "5:7": ["And remember the blessing of Allah upon you, and the covenant with which Allah bound you when you said: we hear and we obey. And be mindful of Allah. Allah knows what the breasts hold.", "তোমাদের প্রতি আল্লাহর আশীর্বাদকে স্মরণ করো,এবং তাঁর অঙ্গীকার যাতে তিনি তোমাদের সাথে অঙ্গীকারাবদ্ধঃ তোমরা বলেছিলে,“আমরা শুনি এবং আমরা মান্য করি।”তোমরা আল্লাহকে মান্য করবে; আল্লাহ অন্তরের গভীরতম চিন্তা সম্পর্কে পরিপূর্ণ অবগত।"],
  "5:8": ["O you who believe, be upholders for Allah as witnesses with equity; and let not the hatred of a people move you away from justice. Be just — that is nearer to mindfulness. And be mindful of Allah. Allah is aware of what you do.", "হে তোমরা যারা বিশ্বাস করো,তোমরা সম্পূর্ণরূপে ন্যায়পরায়ণ হবে,এবং আল্লাহকে মান্য করবে,যখন তোমরা সাক্ষী হিসাবে দায়িত্ব পালন করো। কিছু লোকের সাথে তোমাদের কলহের দরুন অবিচার করতে প্ররোচিত হইও না। তোমরা সম্পূর্ণরূপে ন্যায়পরায়ণ হবে,কারন এটা অধিকতর ন্যায়নিষ্ঠ। তোমরা আল্লাহকে মান্য করবে। আল্লাহ তোমাদের করা সবকিছু সম্পর্কে পরিপূর্ণ অবগত।"],
  "5:9": ["Allah promised those who believe and do good works: for them forgiveness and a great reward.", "যারা বিশ্বাস করে এবং সৎ জীবন-যাপন করে তাদেরকে আল্লাহ ক্ষমা এবং এক মহা প্রতিদানের অঙ্গীকার করেন।"],
  "5:10": ["And those who disbelieve and deny Our signs — those are the companions of the blaze.", "তাদের জন্য যারা অবিশ্বাস করে এবং আমাদের প্রকাশনাসমূহ প্রত্যাখ্যান করে, তারা নরকের অধিবাসী।"],
  "5:11": ["O you who believe, remember the blessing of Allah upon you, when a people resolved to stretch their hands against you, and Allah held their hands back from you. And be mindful of Allah; and in Allah let the muminin place their trust.", "হে তোমরা যারা বিশ্বাস কর, তোমাদের উপর আল্লাহর আশীর্বাদকে স্মরণ কর; যখন কিছু লোক তোমাদের বিরুদ্ধে হামলা করতে হাত বাড়িয়েছিল, তিনি তোমাদেরকে রক্ষা করেছিলেন এবং তাদের হাতগুলো আটকে রেখেছিলেন। তোমরা আল্লাহককে মান্য করবে ; বিশ্বাসীরা আল্লাহতে আস্থা রাখবে।"],
  "5:12": ["And Allah took the covenant of the children of Israel, and We raised among them twelve leaders. And Allah said: I am with you — if you uphold the prayer, and give the alms, and believe in My rusul and aid them, and lend Allah a goodly loan, I will surely blot out your evil deeds for you and enter you into gardens beneath which rivers flow. But whoever of you disbelieves after that has strayed from the even path.", "আল্লাহ ইসরাইলের সন্তানদের থেকে একটি অঙ্গীকার নিয়েছিলেন, এবং আমরা তাদের মধ্যে বার জন গোত্রপতির উত্থান করেছিলাম। এবং আল্লাহ বলেছিলেন, \"আমি তোমাদের সাথে আছি,যতক্ষণ তোমরা সংযোগ প্রার্থনাসমূহ (সালাত) পালন কর, বাধ্যতামূলক দান (যাকাত) দাও, এবং আমার বার্তাবাহকদের বিশ্বাস কর এবং তাদেরকে সম্মান কর, এবং আল্লাহকে সৎকর্মশীলতার ঋন দেয়া অব্যাহত রাখ। তাহলে আমি তোমাদের পাপসমূহ ক্ষমা করবো, এবং তোমাদেরকে প্রবাহিত ঝর্নাসহ বাগানসমূহে প্রবেশ করাব। যেকেউ এরপর অবিশ্বাস করে, অবশ্যই সঠিক পথ থেকে বিচ্যুত হয়েছে।\""],
  "5:13": ["Then, for their breaking of the pact, they were cursed, and We made their hearts hard. They shift the word from its places, and they forgot a portion of what they were reminded of. You will not cease to perceive treachery from them, except a few of them — so pass over them and pardon. Allah loves the good-doers.", "এটি ছিল তাদের সে অঙ্গীকার ভঙ্গের ফল যা আমরা তাদেরকে নিষেধ করেছিলাম, এবং আমরা তাদের অন্তরকে কঠিন হতে দিয়েছিলাম। ফলস্বরুপ, তারা কথাগুলো প্রসঙ্গের বাইরে নিয়েছিল, এবং তাদেরকে দেয়া কিছু আদেশকে অবহেলা করেছিল। তুমি অনবরত তাদের থেকে বিশ্বাসঘাতকতা প্রত্যক্ষ করবে,তাদের কিছু সংখ্যক ছাড়া। তুমি তাদেরকে মাফ করবে,এবং তাদেরকে উপেক্ষা করবে। আল্লাহ তাদেরকে ভালবাসেন যারা হিতৈষী।"],
  "5:14": ["And of those who said: we are Christians, We took their covenant, but they forgot a portion of what they were reminded of; so We cast among them enmity and hatred until the Day of Rising. And Allah will tell them what they used to do.", "আরো তাদের থেকে যারা বলেছিল, \"আমরা খ্রিষ্টান\",আমরা তাদের অঙ্গীকার নিয়েছিলাম। কিন্তু তারা তাদেরকে দেয়া কিছু হুকুম উপেক্ষা করেছিল। ফলস্বরুপ, আমরা শাস্তি হিসেবে দিয়েছিলাম তাদের নিজেদের মধ্যে শত্রুতা এবং ঘৃণা,পুনরুত্থান দিন পর্যন্ত।  আল্লাহ এরপর তাদেরকে জানাবেন সবকিছু যা তারা করেছিল।"],
  "5:15": ["O People of the Scripture, Our Rasul has come to you, making clear to you much of what you used to conceal of the writ, and passing over much. A light has come to you from Allah, and a clear writ.", "হে ঐশীগ্রন্থের লোকেরা,আমাদের বার্তাবাহক তোমাদের কাছে এসেছে তোমাদের জন্য ঘোষনা করতে অনেক বিষয় যা তোমরা ঐশীগ্রন্থে গোপন করেছ, এবং ক্ষমা করতে আরো অনেক সীমালঙ্ঘন যা তোমরা করেছ। আল্লাহ থেকে তোমাদের কাছে এক আলোকবর্তিকা এসেছে,এবং একটি  জ্ঞানগর্ভ ঐশীগ্রন্থ।"],
  "5:16": ["By it Allah guides whoever follows the acceptance into the paths of peace, and brings them out of the darkness into the light by leave, and guides them to a straight path.", "এটা দিয়ে,আল্লাহ তাদেরকে পথপ্রদর্শন করেন যারা তাঁর সম্মতি খোজ করে। তিনি তাদেরকে শান্তির পথে পথপ্রদর্শন করেন, তাঁর সম্মতিতে অন্ধকার থেকে আলোর দিকে পরিচালিত করেন, এবং একটি সরল পথে পথপ্রদর্শন করেন।"],
  "5:17": ["Truly kafara those who say: Allah is the Messiah, son of Maryam. Say: who can own anything against Allah, if Allah wills to destroy the Messiah son of Maryam and his mother and everyone on earth altogether? To Allah belongs the kingdom of the heavens and the earth and what is between them. Allah creates what Allah wills, and Allah is over everything able.", "নিশ্চয়ই তারা অংশীদার সাব্যস্তকারী যারা বলে যে,মরিয়মের পুত্র, মসিহ হচ্ছে আল্লাহ, বল, “কে আল্লাহর বিরোধিতা করতে পারে,যদি তিনি নিশ্চিহ্ন করতে চান মরিয়মের পুত্র মসিহ এবং তার মাকে,এবং পৃথিবীর উপরের সকলকে?”আকাশমন্ডলী  এবং পৃথিবীর, এবং তাদের মধ্যকার সবকিছুর সার্বভৌমত্ব আল্লাহর। তিনি সৃষ্টি করেন, যা কিছু তিনি ইচ্ছা করেন। আল্লাহ সর্বশক্তিমান।"],
  "5:18": ["And the Jews and the Christians said: we are the children of Allah and the beloved ones. Say: then why does Allah punish you for your offenses? Rather, you are humans among creation. Allah forgives whom Allah wills and punishes whom Allah wills, and to Allah belongs the kingdom of the heavens and the earth and what is between them, and to Allah is the arrival.", "ঈহুদি এবং খ্রিষ্টানরা বলেছিল, “আমরা আল্লাহর সন্তান এবং তাঁর অতিশয় প্রিয়।”বল, “তবে কেন তিনি তোমাদেরকে তোমাদের পাপের জন্য শাস্তি দেন? তোমরা শুধু তাঁর সৃষ্ট অন্যান্য মানুষদের মতই মানুষ”। তিনি যাকে ইচ্ছা ক্ষমা করেন এবং যাকে ইচ্ছা শাস্তি দেন। আকাশমন্ডলী  এবং পৃথিবীর, এবং তাদের মধ্যকার সবকিছুর সার্বভৌমত্ব আল্লাহর, এবং তাঁরই নিকট চূড়ান্ত নিয়তি।"],
  "5:19": ["O People of the Scripture, Our Rasul has come to you, making clear to you after an interval in the succession of rusul, lest you say: no bringer of good news and no warner came to us. A bringer of good news and a warner has come to you, and Allah is over everything able.", "হে ঐশীগ্রন্থের লোকেরা,আমাদের বার্তাবাহক তোমাদের কাছে এসেছে,তোমাদের কাছে বিষয়সমূহ ব্যাখ্যা করতে,বার্তাবাহকহীন একটি সময়কালের পর, পাছে তোমরা বল, “আমরা কোন ধর্মপ্রচারক অথবা সতর্ককারী পাই নি”। একজন ধর্মপ্রচারক এবং সতর্ককারী এখন তোমাদের কাছে এসেছে। আল্লাহ সর্বশক্তিমান।"],
  "5:20": ["And when Musa said to his people: O my people, remember the blessing of Allah upon you, when Allah made nabis among you and made you kings, and gave you what was given to no one of the worlds.", "স্মরণ করো, মুসা তার লোকদের বলেছিল, “হে আমার লোকেরা,তোমাদের উপর আল্লাহর আশীর্বাদকে স্মরণ করোঃ তিনি তোমাদের মধ্যে থেকে নবীদেরকে নিযুক্ত করেছিলেন, তোমাদেরকে রাজা বানিয়েছিলেন, এবং তোমাদেরকে দিয়েছিলেন, যা তিনি অন্য কোন লোকদের কখনো দেননি।"],
  "5:21": ["O my people, enter the holy land that Allah has ordained for you, and do not turn back on your heels, lest you turn back as losers.", "\"হে আমার লোকেরা,সে পবিত্র ভূমিতে প্রবেশ কর, যা আল্লাহ তোমাদের জন্য জারি করেছেন, এবং বিদ্রোহ করো না,পাছে তোমরা ক্ষতিগ্রস্ত হও\"।"],
  "5:22": ["They said: O Musa, in it is a people of overpowering tyrants; we will never enter it until they leave it. If they leave it, then we will surely enter.", "তারা বলেছিল, \"হে মুসা,এতে শক্তিশালী লোকেরা আছে,এবং আমরা এতে প্রবেশ করবো না,যদি না তারা তা থেকে বেড়িয়ে আসে। যদি তারা বের হয়, আমরা প্রবেশ করছি।\""],
  "5:23": ["Two men of those who feared, whom Allah had blessed, said: go in upon them by the gate; once you have entered it, you will be the overcomers. And in Allah place your trust, if you are muminin.", "দু'জন পুরুষ, যারা ছিল সশ্রদ্ধ এবং আল্লাহর আশীর্বাদপ্রাপ্ত, বলেছিল, \"শুধু দরজা দিয়ে প্রবেশ করো। যদি তোমরা শুধু এতে প্রবেশ কর, তোমরা নিশ্চিতভাবে জয়লাভ করবে। তোমরা অবশ্যই আল্লাহতে আস্থা রাখবে,যদি তোমরা বিশ্বাসী হও।\""],
  "5:24": ["They said: O Musa, we will never enter it so long as they are in it. Go, you and your Rabb, and fight — the two of you. We will sit right here.", "তারা বলেছিল, \"হে মুসা,আমরা কখনো এতে প্রবেশ করবো না,যতক্ষণ তারা এতে রয়েছে। সেজন্য, যাও- তুমি এবং তোমার প্রভু - এবং যুদ্ধ করো। আমরা ঠিক এখানে বসে থাকছি।\""],
  "5:25": ["Musa said: Rabb, I possess only myself and my brother — so decide between us and the defiant people.", "সে বলেছিল, \"আমার প্রভু,আমি শুধু আমাকে এবং আমার ভাইকে নিয়ন্ত্রণ করতে পারি। তাই আমাদেরকে মন্দ লোকদের সঙ্গ পরিত্যাগের অনুমতি দিন।\""],
  "5:26": ["Allah said: then it is forbidden to them for forty years, and they will wander the land. So do not grieve over the defiant people.", "তিনি বলেছিলেন, “এখন থেকে,এটা তাদেরকে চল্লিশ বছরের জন্য নিষিদ্ধ করা হলো,যে সময় তারা উদ্দেশ্যহীনভাবে পৃথিবীতে ঘুরে বেড়াবে।\""],
  "5:27": ["And recite to them the true account of the two sons of Adam: when they offered an offering, and it was accepted from one of them and not accepted from the other. The first said: I will surely kill you. The other said: Allah accepts only from the mindful.", "তাদের জন্য আদমের দুই পুত্রের সত্য ইতিহাস আবৃত্তি করো। তারা একটি উৎসর্গ নিবেদন করেছিল, এবং এটি তাদের একজন থেকে গ্রহণ করা হয়েছিল, কিন্তু অন্যজন থেকে হয়নি। সে বলেছিল, “আমি অবশ্যই তোমাকে হত্যা করবো”। সে বলেছিল, “আল্লাহ শুধুমাত্র সৎকর্মশীলদের থেকে গ্রহণ করেন।"],
  "5:28": ["If you stretch out your hand against me to kill me, I will not stretch out my hand against you to kill you. I fear Allah, Rabb of the worlds.", "“যদি তুমি আমাকে হত্যা করতে তোমার হাত বাড়াও, আমি তোমাকে হত্যা করতে আমার হাত বাড়াচ্ছি না। কারন আমি মহাবিশ্বের প্রভু,আল্লাহকে ভক্তি করি।"],
  "5:29": ["I want you to bear my sin and your own sin, and so be among the companions of the fire — and that is the recompense of the wrongdoers.", "\"আমি চাই তুমি,আমি নয়, আমার পাপ এবং তোমার পাপ বহন করো,তারপর শেষ পর্যন্ত নরকের বাসিন্দাদের সাথে অন্তর্ভুক্ত হও। সীমাতিক্রমকারীদের জন্য এমনই শাস্তি”।"],
  "5:30": ["Then his soul inclined him toward killing his brother, and he killed him, and became one of the khasirin.", "তার অহমবোধ তার ভাইকে হত্যা করতে তাকে প্ররোচিত করলো। সে তাকে হত্যা করেছিল, এবং শেষ পর্যন্ত ক্ষতিগ্রস্থদের সাথে অন্তর্ভুক্ত হয়েছিল।"],
  "5:31": ["Then Allah sent a raven searching the land, to show him how to hide his brother's nakedness. He said: woe is me! Am I unable to be like this raven and hide my brother's nakedness? And he became one of the regretful.", "আল্লাহ তখন একটি দাড় কাক পাঠিয়েছিলেন মাটি খুড়তে,তাকে শেখাতে কিভাবে তার ভাইয়ের মৃতদেহ সমাহিত করতে হবে। সে বলেছিল, \"দু:খ আমার; আমি ব্যর্থ হয়েছি এই দাড় কাকের মত বুদ্ধিমান হতে,এবং আমার ভাইয়ের মৃতদেহ সমাহিত করতে। \""],
  "5:32": ["Because of that We wrote for the children of Israel: whoever kills a soul — other than for a soul, or for corruption in the land — it is as if killed all people; and whoever gives it life, it is as if gave life to all people. And Our rusul came to them with clear proofs; yet many of them after that are exceeders in the land.", "এ কারনে,আমরা ইসরাইলের সন্তানদের জন্য জারি করেছিলাম যে,যেকেউ হত্যা করে এমন কোন ব্যক্তিকে যে হত্যা বা গুরুতর অপরাধ করেনি,এটা এমন হবে যেন সে সকল লোককে হত্যা করল। এবং যেকেউ একটি জীবন বাচায়, এটা এমন হবে যেন সে সকল লোকের জীবন বাচাল। আমাদের বার্তাবাহকরা তাদের কাছে স্পট প্রমান এবং প্রকাশনাসমূহ নিয়ে গিয়েছিল, কিন্তু তাদের অধিকাংশই, এই সবকিছুর পর, এখনও সীমালঙ্ঘন করছে।"],
  "5:33": ["The recompense of those who war against Allah and against Allah's Rasul and strive in the land for corruption is only this: that they be killed, or crucified, or that their hands and feet be cut off on opposite sides, or that they be exiled from the land. That for them is disgrace in this world, and for them in the last world is a great punishment.", "যারা আল্লাহ এবং তাঁর বার্তাবাহকের বিরুদ্ধে যুদ্ধ করে,এবং ভয়ংকর অপরাধসমূহ করে,তাদের জন্য হত্যা হওয়া,অথবা ক্রুশবিদ্ধ হওয়া,অথবা তাদের হাত এবং পাগুলো বিপরীত দিক থেকে কেটে ফেলে দেয়া,অথবা জনগন থেকে নির্বাসিত হওয়াই হবে উচিত শাস্তি। এটি তাদেরকে এই জীবনে অপদস্থ করতে,এরপর তারা পরকালে আরো অধিক মন্দ শাস্তি ভোগ করে।"],
  "5:34": ["Except those who repent before you overpower them — and know that Allah is forgiving, merciful.", "তারা নিষ্কৃতপ্রাপ্ত যারা অনুশোচনা করে,তোমরা তাদেরকে পরাস্ত করার পূর্বে। তোমাদের জানা উচিত যে,আল্লাহ ক্ষমাকারী,পরম দয়ালু।"],
  "5:35": ["O you who believe, be mindful of Allah and seek the way to Allah, and strive in the path, so that you may attain success.", "হে তোমরা যারা বিশ্বাস কর, তোমরা আল্লাহকে ভক্তি-শ্রদ্ধা করবে এবং তাঁর সান্নিধ্যের রাস্তা এবং উপায় খুজবে,এবং তাঁর উদ্দেশ্যে সংগ্রাম করবে,যাতে তোমরা সফল হতে পার।"],
  "5:36": ["Surely those who disbelieve — if they had all that is in the earth and the like of it with it, they would offer it as ransom from the punishment of the Day of Rising. It would not be accepted from them, and for them is a painful punishment.", "অবশ্যই, তারা যারা অবিশ্বাস করে,যদি তারা পৃথিবীর সবকিছুর, এমনকি এর দিগুন পরিমান অধিকার করে, এবং পুনুরুত্থান দিবসে শাস্তি থেকে তারা নিষ্কৃতি পেতে তা মুক্তিপন হিসেবে দিতে চায়, এটা তাদের থেকে গ্রহণ করা হবে না; তারা টেনে এনেছে এক যন্ত্রণাদায়ক শাস্তি।"],
  "5:37": ["They will want to come out of the fire, but they will not come out of it, and for them is a lasting punishment.", "তারা নরক থেকে বের হতে চাইবে,কিন্ত হায়, তারা কখনোই সেখান থেকে বের হতে পারবে না; তাদের শাস্তি চিরস্থায়ী।"],
  "5:38": ["And the male thief and the female thief: cut off their hands, a recompense for what they earned, a warning from Allah. And Allah is mighty, wise.", "চোর, নারী হোক অথবা পুরুষ, তোমরা তাদের হাত চিহ্নিত করে দিবে তাদের অপরাধের শাস্তি হিসাবে,এবং আল্লাহ থেকে একটি উদাহরণ দিতে। আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "5:39": ["Whoever repents after the wrong and makes amends — Allah turns to that one. Allah is forgiving, merciful.", "যদি কেউ এই অপরাধ করার পর অনুশোচনা করে,এবং সংশোধিত হয়, আল্লাহ তাকে মুক্ত করেন। আল্লাহ ক্ষমাকারী,পরম দয়ালু।"],
  "5:40": ["Do you not know that to Allah belongs the kingdom of the heavens and the earth? Allah punishes whom Allah wills and forgives whom Allah wills, and Allah is over everything able.", "তুমি কি জানো না যে,আল্লাহ আকাশমন্ডলী ও পৃথিবীর সার্বভৌমত্বের অধিকারী? তিনি যাকে ইচ্ছা শাস্তি দেন, এবং যাকে ইচ্ছা ক্ষমা করেন। আল্লাহ সর্বশক্তিমান।"],
  "5:41": ["O Messenger, let not grieve you those who hasten in disbelief — from those who say with their mouths: we believe, while their hearts do not believe, and from those who are Jews: listeners to falsehood, listeners for other people who never come to you. They shift the word from its places, saying: if you are given this, take it; if you are not given it, beware. And whoever Allah wills to test — you will own nothing for that one against Allah. Those are the ones whose hearts Allah did not will to purify. For them in this world is disgrace, and for them in the last world is a great punishment.", "হে তুমি বার্তাবাহক, যারা দ্রুত অবিশ্বাস করে তাদের মধ্যে যারা বলে,তাদের মুখ দিয়ে \"আমরা বিশ্বাস করি,\",যখন তাদের অন্তর বিশ্বাস করে না,তাদের দ্বারা দুঃখিত হইও না। ইহুদীদের মধ্যে,কেউ কেউ মিথ্যা শুনেছিল। তারা সে লোকদের কথা শুনেছিল যারা তোমার সাথে কখনো সাক্ষাত করেনি,এবং তারা বানীগুলোকে প্রসঙ্গের বাইরে বিকৃত করেছিল, এরপর বলেছিল, \"যদি তোমাদেরকে এটি দেয়া হয়, তোমরা তা গ্রহণ করবে,কিন্তু যদি তোমাদেরকে ভিন্ন কিছু দেয়া হয়, সতর্ক হবে।\"  আল্লাহ যাকে বিমুখ করতে চান, তুমি আল্লাহর বিরুদ্ধে তাকে সাহায্য করতে কিছুই করতে পার না। আল্লাহ তাদের অন্তরকে পরিশুদ্ধ করতে চান না। তারা এই দুনিয়ায় টেনে এনেছে লাঞ্চনা,এবং পরকালে,তারা এক ভয়ানক শাস্তি ভোগ করবে।"],
  "5:42": ["Listeners to falsehood, devourers of ill-gotten gain. If they come to you, judge between them or turn away from them. If you turn away from them, they cannot harm you at all; and if you judge, judge between them with equity. Allah loves the equitable.", "তারা মিথ্যা মান্যকারী,এবং অবৈধ উপার্জনসমূহের ভক্ষণকারী। যদি তারা তোমার কাছে আসে তাদের মধ্যে বিচার করে দিতে,তুমি তাদের মধ্যে বিচার করতে পার, অথবা তুমি তাদেরকে উপেক্ষা করতে পার। যদি তুমি তাদেরকে উপেক্ষা করা পছন্দ কর, তারা তোমার সামান্যতম ক্ষতিও করতে পারে না। কিন্তু যদি তুমি তাদের মধ্যে বিচার কর, তুমি ন্যায়সঙ্গতভাবে বিচার করবে। আল্লাহ তাদেরকে ভালবাসেন যারা ন্যায়পরায়ণ।"],
  "5:43": ["But how can they turn to you for judgment when they have the Torah, in which is Allah's judgment — then they turn away after that? Those are not muminin.", "কেন তারা তোমার কাছে বিচার চাইতে আসে,যখন তাদের রয়েছে তওরাত, আল্লাহর আইন সম্বলিত, এবং তারা তা উপেক্ষা করা পছন্দ করে? তারা বিশ্বাসী নয়।"],
  "5:44": ["We sent down the Torah: in it are guidance and light. By it the nabis who had submitted judged for those who are Jews, and the rabbis and the learned ones, by what they were entrusted of Allah's writ and over which they were witnesses. So do not fear people, but fear Me, and do not trade My signs for a small price. Whoever does not judge by what Allah sent down — those are the kafirin.", "আমরা তওরাত অবতীর্ণ করেছি,পথ-নির্দেশনা এবং আলো সম্বলিত। তদনুযায়ী রায় দিত ইহুদী নবীরা,একই সাথে রাবাইরা এবং পন্ডিতরা/ধর্মযাজকরা,যেভাবে আল্লাহর গ্রন্থে তাদেরকে নির্দেশ দেয়া হয়েছিল, এবং যেভাবে তারা প্রত্যক্ষ করেছিল। সেজন্য, মানব জাতিকে ভক্তি-শ্রদ্ধা করো না; বদলে আমাকে ভক্তি-শ্রদ্ধা করবে। এবং সস্তা মূল্যে আমার প্রকাশনাবলি বেচা-কেনা কর না। যার আল্লাহর প্রকাশনাবলি অনুসারে রায় দেয় না,তারা অবিশ্বাসী।"],
  "5:45": ["And We wrote for them in it: a soul for a soul, an eye for an eye, a nose for a nose, an ear for an ear, a tooth for a tooth, and for wounds — requital. Whoever gives it up in charity, it is expiation for that one. And whoever does not judge by what Allah sent down — those are the unjust.", "এবং আমরা তাদের জন্য এর মধ্যে জারি করেছিলাম যে: প্রানের বিনিময়ে প্রাণ, চোখের বিনিময়ে চোখ, নাকের বিনিময়ে নাক, কানের বিনিময়ে  কান, দাতের বিনিময়ে  দাত, এবং যেকোন আঘাতের বিনিময়ে একটি সমতুল্য আঘাত। যদি কেউ একটি দান হিসেবে তার প্রাপ্য স্বেচ্ছায় দিয়ে দেয়, এটি তার পাপসমূহের জন্য প্রায়শ্চিত্ত হবে। যারা আল্লাহর প্রকাশনাবলি অনুসারে রায় দেয় না তারা অন্যায়কারী।"],
  "5:46": ["And We tracked in their footsteps with Isa son of Maryam, confirming what was before him of the Torah; and We gave him the Gospel, in which are guidance and light, confirming what was before it of the Torah, and a guidance and admonition for the mindful.", "তাদের পরবর্তীতে, আমরা মরিয়ম পুত্র ঈসাকে পাঠিয়েছিলাম, নিশ্চিত করতে পূর্ববর্তী ঐশীগ্রন্থ, তওরাত। আমরা তাকে দিয়েছিলাম ইঞ্জিল, পথ নির্দেশনা এবং আলো সংবলিত, এবং নিশ্চিত করতে পূর্ববর্তী ঐশীগ্রন্থসমূহ, তওরাত, এবং এর পথনির্দেশনা এবং আলো বৃদ্ধি করতে, এবং সৎকর্মশীলদের আলোকিত করতে।"],
  "5:47": ["And let the people of the Gospel judge by what Allah sent down in it. Whoever does not judge by what Allah sent down — those are the defiant.", "ইঞ্জিলের অধিকারী লোকেরা তন্মধ্যে বিদ্যমান আল্লাহর প্রকাশনাবলি অনুসারে রায় দিবে। যারা আল্লাহর প্রকাশনাবলি অনুসারে রায় না দেয়, তারাই মন্দ।"],
  "5:48": ["And We sent down to you the writ in truth, confirming what is before it of the writ and a guardian over it. So judge between them by what Allah sent down, and do not follow their desires away from the truth that has come to you. For each of you We made a law and a way. Had Allah willed, Allah would have made you one community, but to test you in what was given you. So race ahead to the good things. To Allah is your return, all of you, and Allah will tell you what you differed in.", "এরপর আমরা তোমার কাছে এই ঐশীগ্রন্থ প্রকাশ করেছি, সত্যপূর্ণভাবে, যা পূর্ববর্তী ঐশীগ্রন্থসমূহ নিশ্চিত করে, এবং সেগুলোকে স্থলাভিষিক্ত হয়/ অতিক্রম করে। তুমি তাদের মাঝে রায় দিবে আল্লাহর প্রকাশনাবলি অনুসারে,এবং তাদের ইচ্ছার অনুসরণ করো না যদি তারা মতভেদ করে সেই সত্যে যা তোমার কাছে এসেছিল। তোমাদের প্রত্যেকের জন্য, আমরা আইন এবং পৃথক ধর্মীয় রীতিনীতিসমূহ জারি করেছি। আল্লাহ যদি চাইতেন, তিনি তোমাদেরকে এক ধর্মগোষ্ঠী করে দিতে পারতেন। কিন্তু তিনি এভাবে তোমাদেরকে পরীক্ষা করেন সেই প্রকাশনাবলির মাধ্যমে,যা তিনি তোমাদের প্রত্যেককে দিয়েছেন। তোমরা সৎকর্মে প্রতিযোগিতা করবে। আল্লাহর নিকট তোমাদের চূড়ান্ত নিয়তি-তোমাদের সকলের- এরপর তিনি তোমাদেরকে জানাবেন সবকিছু, যে বিষয়ে তোমরা বিতর্ক করেছিলে।"],
  "5:49": ["And judge between them by what Allah sent down, and do not follow their desires, and beware of them, that they not test you away from some of what Allah sent down to you. If they turn away, then know that Allah only wills to strike them for some of their offenses. And many of the people are defiant.", "তুমি তাদের মাঝে রায় দিবে তোমার কাছে আল্লাহর প্রকাশনাবলি অনুসারে। তাদের ইচ্ছার অনুসরণ করো না,এবং সতর্ক হও পাছে তারা তোমাকে সরিয়ে দেয় তোমার প্রতি আল্লাহর কিছু প্রকাশনাবলি থেকে। যদি তারা বিমুখ হয়, তবে জানো যে আল্লাহ তাদেরকে তাদের কিছু পাপের জন্য শাস্তি দিতে চান। প্রকৃতপক্ষে,অনেক লোক পাপী।"],
  "5:50": ["Is it the judgment of the pagan age they seek? And who is better than Allah as judge for a people who are certain?", "এটা কি অজ্ঞতার দিনের আইন যা তারা মেনে চলতে চায়? যারা নিশ্চয়তা অর্জন করেছে তাদের জন্য আল্লাহর আইনের চেয়ে কার আইন উত্তম?"],
  "5:51": ["O you who believe, do not take the Jews and the Christians as allies. Some of them are allies of each other. Whoever of you turns to them — that one is one of them. Allah does not guide the unjust people.", "হে তোমরা যারা বিশ্বাস কর, নির্দিষ্ট ইহুদী এবং খ্রিষ্টানদের মিত্র হিসেবে নিও না; এরা একে অন্যের মিত্র। তোমাদের মধ্যে যারা নিজেদেরকে তাদের মিত্র করে,তারা তাদের অন্তর্ভূক্ত। আল্লাহ সীমালঙ্ঘনকারীদের পথ-প্রদর্শন করেন না।"],
  "5:52": ["So you will see those in whose hearts is sickness hastening to them, saying: we fear a turn of fortune may strike us. Perhaps Allah will bring triumph, or a command from Allah — and then they will regret, at dawn, what they hid in themselves.", "তুমি দেখবে যারা তাদের অন্তরে সন্দেহ পোষন করে,তারা তাদের সাথে যুক্ত হতে তাড়াহুড়ো করে,এই বলে যে,\"আমাদের ভয় হয় পাছে যদি আমরা পরাজিত হই।”আল্লাহ যেন তার পক্ষ থেকে বিজয়, অথবা একটি নির্দেশ আনেন, যা তাদেরকে তাদের গোপন চিন্তাসমূহের জন্য অনুশোচনা করাবে।"],
  "5:53": ["And those who believe will say: are these the ones who swore by Allah their utmost oaths that they were with you? Void are their works, and they have become losers.", "বিশ্বাসীরা তখন বলবে,\"এরাই কি সেই লোক যারা আল্লাহর নামে দৃড়ভাবে শপথ করেছিল যে তারা তোমাদের সাথে আছে?”তাদের কাজসমূহ বাতিল হয়েছে;তারাই ক্ষতিগ্রস্থ।"],
  "5:54": ["O you who believe, whoever among you turns back from religion — Allah will bring a people whom Allah loves and who love Allah: humble toward the muminin, mighty over the kafirin, striving in the path of Allah and fearing no blamer's blame. That is Allah's bounty, given to whom Allah wills, and Allah is all-ample, all-knowing.", "হে তোমরা যারা বিশ্বাস কর, যদি তোমরা তোমাদের ধর্ম থেকে প্রত্যাবর্তন কর, তবে আল্লাহ তোমাদের জায়গায় লোকদের আনবেন যাদেরকে তিনি ভালবাসেন এবং যারা তাকে ভালবাসে। তারা বিশ্বাসীদের সাথে দয়ালু হবে,অবিশ্বাসীদের সাথে কঠোর হবে,এবং কোন ধরনের দোষী হবার ভয় ছাড়া আল্লাহর উদ্দেশ্যে সংগ্রাম করবে। এরকমই আল্লাহর আশীর্বাদ; তিনি যাকে ইচ্ছা তা প্রদান করেন। আল্লাহ উদার, সর্বজ্ঞ।"],
  "5:55": ["Your ally is only Allah and the Rasul and those who believe: those who uphold the prayer and give the alms, and they bow.", "তোমাদের সত্যিকার মিত্র হচ্ছে আল্লাহ এবং তাঁর বার্তাবাহক, এবং বিশ্বাসীরা যারা সংযোগ প্রার্থনাসমূহ (সালাত) পালন করে,এবং বাধ্যতামূলক দান (যাকাত) দেয়, এবং তারা অবনত হয়।"],
  "5:56": ["And whoever turns to Allah, and to the Rasul, and to those who believe — then the party of Allah are the victorious.", "যারা নিজেদেরকে আল্লাহ এবং তাঁর বার্তাবাহকের মিত্র করে,এবং যারা বিশ্বাস করে,তারা আল্লাহর দলের অন্তর্গত; সম্পূর্ণরূপে,তারাই বিজয়ী।"],
  "5:57": ["O you who believe, do not take as allies those who took your religion in mockery and play, from among those given the writ before you and the kafirin. And be mindful of Allah, if you are muminin.", "হে তোমরা যারা বিশ্বাস করো,পূর্ববর্তী ঐশীগ্রন্থ গ্রহণকারীদের মধ্যে তাদের সাথে বন্ধুত্ব করো না যারা তোমাদের ধর্মকে উপহাস এবং বিদ্রূপ করে,না তোমরা বন্ধুত্ব করবে অবিশ্বাসীদের সাথে। তোমরা আল্লাহকে ভক্তিশ্রদ্ধা করবে,যদি তোমরা সত্যি বিশ্বাসী হও।"],
  "5:58": ["And when you are called to the prayer, they take it in mockery and play. That is because they are a people who do not understand.", "যখন তোমরা সংযোগ প্রার্থনার (সালাতের) জন্য আহবান করো,তারা একে উপহাস এবং বিদ্রূপ করে। এটা এ কারনে যে তারা এমন লোক যারা বোঝে না।"],
  "5:59": ["Say: O People of the Scripture, do you requite us for anything except that we believe in Allah and in what was sent down to us and what was sent down before — and that most of you are defiant?", "বল, “হে ঐশীগ্রন্থের লোকেরা,তোমরা কি আমাদের এ কারনে ঘৃণা করো না যে,আমরা বিশ্বাস করি আল্লাহকে,এবং যা আমাদের কাছে প্রকাশিত হয়েছিল, এবং যা আমাদের পূর্বে প্রকাশিত হয়েছিল, এবং এ কারনে যে তোমাদের মাঝে বেশির ভাগই সৎকর্মশীল নও?”"],
  "5:60": ["Say: shall I inform you of worse than that, as recompense with Allah? Those whom Allah cursed and raged upon, and made among them monkeys and pigs, and those who serve the false arbiter. Those are worse in place, and further astray from the even path.", "বল, “আমি তোমাদেরকে বলি কারা আল্লাহর দৃষ্টিতে অধিক মন্দঃ তারা যারা আল্লাহর দ্বারা নিন্দিত হয়েছিল তার ক্রোধ টেনে আনার পর যতক্ষণ না তিনি তাদেরকে বানর এবং শুকরের মতো (ঘৃণ্য)  করে দিয়েছিলেন, এবং প্রতিমা উপাসকরা। এরা অনেক মন্দ, এবং সঠিক পথ থেকে অধিকতর দূরে।"],
  "5:61": ["And when they come to you they say: we believe — though they entered with disbelief and left with it. And Allah knows best what they were hiding.", "তারা যখন তোমার কাছে আসে,তারা বলে,\"আমরা বিশ্বাস করি,”যদিও তারা ছিল অবিশ্বাসে পূর্ন যখন তারা প্রবেশ করেছিল, এবং তারা অবিশ্বাসে পূর্ন যখন তারা চলে যায়। আল্লাহ সম্পূর্ন অবগত তাদের লুকানো সবকিছু সম্পর্কে।"],
  "5:62": ["And you see many of them hastening into sin and transgression, and devouring ill-gotten gain. Evil is what they used to do.", "তুমি তাদের অনেককে দেখো নির্দ্বিধায় মন্দ এবং সীমালঙ্ঘন করতে,আর অবৈধ উপার্জনসমূহ ভক্ষন করতে। সত্যিই দু:খজনক যা তারা করে।"],
  "5:63": ["Why do the rabbis and the learned ones not forbid them their sinful speech and their devouring of ill-gotten gain? Evil is what they used to make.", "যদি  রাবাই এবং পন্ডিতরা তাদেরকে পাপপূর্ন কথাবার্তা এবং অবৈধ উপার্জনসমূহ থেকে শুধু নিষেধ করত! সত্যিই দু:খজনক যা তারা করে।"],
  "5:64": ["And the Jews said: the hand of Allah is fettered. Fettered are their own hands, and they are cursed for what they said. Rather, both hands are spread wide, spending as Allah wills. And what your Rabb sent down to you only increases many of them in transgression and disbelief. And We cast among them enmity and hatred until the Day of Rising. Every time they kindle a fire for war, Allah puts it out. And they strive in the land for corruption, and Allah does not love the corrupters.", "ইহুদীরা এমনকি বলেছিল, \"আল্লাহর হাত বাধা!”তাদের হাতই বাধা। তারা এরকম একটি মিথ্যাচার উচ্চারণ করার জন্য নিন্দিত। বরং,তাঁর হাত সম্পূর্ন উন্মুক্ত, ব্যয় করছেন যেমন তাঁর ইচ্ছা। নিশ্চিতভাবে,তোমার প্রতি তোমার আল্লাহর প্রকাশনাবলি তাদের অনেককে সীমালঙ্ঘন এবং অবিশ্বাসের আরো গভীরে নিমজ্জিত করাবে। ফলস্বরুপ, আমরা তাদেরকে দিয়েছিলাম তাদের নিজেদের মধ্যে শত্রুতা এবং ঘৃণা,পুনরুত্থান দিন পর্যন্ত। যখনই তারা যুদ্ধের অগ্নিশিখা প্রজ্জ্বলিত করে,আল্লাহ তা নিভিয়ে দেন। তারা মন্দভাবে পৃথিবীতে ঘুরে বেড়ায়, এবং আল্লাহ মন্দকর্মীদের অপছন্দ করেন।"],
  "5:65": ["If the People of the Scripture had believed and been mindful, We would have blotted out their evil deeds for them and entered them into gardens of bliss.", "যদি শুধু ঐশীগ্রন্থের লোকেরা বিশ্বাস করে এবং একটি সৎকর্মশীল জীবন-যাপন করে,তবে আমরা তাদের পাপসমূহ ক্ষমা করবো,এবং তাদেরকে পরম সুখের বাগানে প্রবেশ করাব।"],
  "5:66": ["If they had upheld the Torah and the Gospel and what was sent down to them from their Rabb, they would have eaten from above them and from beneath their feet. Among them is a middle-course community, but many of them — evil is what they do.", "যদি শুধু তারা  মেনে চলতো তওরাত ও ইঞ্জিল, এবং যা তাদের কাছে এখানে অবতীর্ণ করা হয়েছে তাদের প্রভুর পক্ষ থেকে,তাদের প্রতি আশীর্বাদ বর্ষণ করা হতো তাদের উপর থেকে এবং তাদের পায়ের নিচ থেকে। তাদের কেউ কেউ সৎ কর্মী,কিন্তু তাদের অনেকেই মন্দ কর্মী।"],
  "5:67": ["O Messenger, deliver what was sent down to you from your Rabb; and if you do not, then you have not delivered the message. And Allah will protect you from the people. Allah does not guide the committing kufr people.", "হে তুমি বার্তাবাহক, পৌঁছে দাও যা তোমার কাছে প্রকাশ করা হয়েছে তোমার প্রভুর পক্ষ থেকে- যে পর্যন্ত তুমি তা না করো,তুমি তাঁর বার্তা পৌঁছে দাওনি- এবং আল্লাহ তোমাকে লোকদের থেকে রক্ষা করবেন। আল্লাহ অবিশ্বাসী লোকদেরকে পথপ্রদর্শন করেন না।"],
  "5:68": ["Say: O People of the Scripture, you stand on nothing until you uphold the Torah and the Gospel and what was sent down to you from your Rabb. And what your Rabb sent down to you only increases many of them in transgression and disbelief. So do not grieve over the committing kufr people.", "বল, “হে ঐশীগ্রন্থের লোকেরা,তোমাদের কোন ভিত্তি নেই যতক্ষণ না তোমরা তওরাত, এবং ইঞ্জিল, এবং এখানে তোমাদের প্রভুর পক্ষ থেকে তোমাদের কাছে যা অবতীর্ণ হয়েছে তা মেনে চলো। “অবশ্যই, তোমার প্রভুর পক্ষ থেকে এই প্রকাশনাবলি তাদের অনেককেই সীমালঙ্ঘন এবং অবিশ্বাসের গভীরে নিমজ্জিত করাবে। সুতরাং,অবিশ্বাসী লোকদের জন্য দুঃখ অনুভব করো না।"],
  "5:69": ["Surely those who believe, and those who are Jews, and the Sabians, and the Christians — whoever believes in Allah and the Last Day and does good work: no fear upon them, nor do they grieve.", "অবশ্যই, তারা যারা বিশ্বাস করে,তারা যারা ইহুদী,ধর্মান্তরিত, এবং খ্রিষ্টান; তাদের যে কেউ (১) আল্লাহতে বিশ্বাস করে এবং (২) শেষ দিনে বিশ্বাস করে,এবং (৩) সৎ জীবন যাপন করে,তাদের ভয় পাবার কিছু নেই, না তারা শোক করবে।"],
  "5:70": ["We took the covenant of the children of Israel and sent rusul to them. Whenever a Rasul came to them with what their souls did not desire, a party of them denied and a party killed.", "আমরা ইসরাইলের সন্তানদের থেকে একটি অঙ্গীকার নিয়েছিলাম, এবং আমরা তাদের কাছে বার্তাবাহকদের পাঠিয়েছিলাম। যখনি তাদের কাছে কোন বার্তাবাহক গিয়েছিলো এমনকিছু নিয়ে যা তাদের অপছন্দ, তারা তাদের কাউকে কাউকে প্রত্যাখ্যান করেছিল, এবং তাদের কাউকে কাউকে তারা হত্যা করেছিল।"],
  "5:71": ["They reckoned there would be no trial, so they became blind and deaf. Then Allah turned to them; then many of them became blind and deaf again. And Allah is seeing of what they do.", "তারা ভেবেছিল যে তাদেরকে পরীক্ষা করা হবে না,তাই তারা অন্ধ এবং বধির হয়ে পড়েছিল, এরপর আল্লাহ তাদেরকে পূনরুদ্ধার করেছিলেন, কিন্তু এরপর তাদের অনেকে আবারো অন্ধ এবং বধির হয়ে পড়েছিল। আল্লাহ তাদের করা সবকিছুর দ্রষ্টা।"],
  "5:72": ["Truly kafara those who say: Allah is the Messiah son of Maryam. And the Messiah said: O children of Israel, worship Allah, my Rabb and your Rabb. Whoever associates others with Allah — Allah has forbidden the garden to that one, shelter is the fire, and there are no helpers for the unjust.", "প্রকৃতপক্ষে তারাই অংশীদার সাব্যস্তকারী যারা বলে যে মরিয়ম পুত্র, মসিহ-ই আল্লাহ। মসিহ নিজেই বলেছিল, \"হে ইসরাইলের সন্তানেরা,তোমরা আল্লাহর উপাসনা করবে; আমার প্রভু এবং তোমাদের প্রভু।”যেকেউ আল্লাহর পাশে কোন উপাস্য স্থাপন করে,আল্লাহ তার জন্য স্বর্গ নিষিদ্ধ করেছেন, এবং তার নিয়তি নরক। মন্দদের কোন সাহায্যকারী নেই।"],
  "5:73": ["Truly kafara those who say: Allah is a third of three. There is no ilah but one ilah. If they do not cease from what they say, a painful punishment will touch those of them who disbelieve.", "প্রকৃতপক্ষে তারাই অংশীদার সাব্যস্তকারী যারা বলে যে আল্লাহ ত্রিত্বের তৃতীয় (তিনের তৃতীয়)। এক উপাস্য ছাড়া কোন উপাস্য নেই। তারা যদি এটা বলা থেকে বিরত না থাকে,তাদের মধ্যে যারা অবিশ্বাস করে টেনে আনবে এক যন্ত্রনাদায়ক শাস্তি।"],
  "5:74": ["Will they not turn to Allah and seek forgiveness? And Allah is forgiving, merciful.", "তারা কি আল্লাহর কাছে অনুশোচনা,এবং তাঁর ক্ষমা প্রার্থনা করবে না? আল্লাহ ক্ষমাকারী,পরম দয়ালু।"],
  "5:75": ["The Messiah son of Maryam is only a Rasul; rusul passed on before him, and his mother was a sadiq imra'a. Both of them used to eat food. Look how We make the signs clear to them; then look how they are turned away.", "মরিয়ম পুত্র, মসিহ তার আগের বার্তাবাহকদের মত একজন বার্তাবাহকের চেয়ে বেশি কিছু নয়, এবং তার মা ছিল একজন সাধু। তাদের উভয়েই খাবার খেত। লক্ষ্য কর কিভাবে আমরা তাদের জন্য প্রকাশনাবলি ব্যাখ্যা করি,এবং লক্ষ্য কর কিভাবে তারা এরপরও পথভ্রষ্ট হয়।"],
  "5:76": ["Say: do you worship besides Allah what owns for you neither harm nor benefit? And Allah is the all-hearing, the all-knowing.", "বল, “তোমরা কি আল্লাহর পাশে শক্তিহীন উপাস্যদের স্থাপন করবে যারা না তোমাদের ক্ষতি করতে পারে,না উপকার করতে পারে? আল্লাহ শ্রবণকারী,সর্বজ্ঞ”।"],
  "5:77": ["Say: O People of the Scripture, do not exceed in your religion beyond the truth, and do not follow the desires of a people who strayed before and led many astray, and strayed from the even path.", "বল, “হে ঐশীগ্রন্থের লোকেরা,সত্যকে ছাড়িয়ে তোমাদের ধর্মের সীমাতিক্রম করো না,এবং সে সব লোকদের মতামতসমূহ অনুসরণ করো না যারা পথভ্রষ্ট হয়েছে,এবং বহু সংখ্যক লোককে পথভ্রষ্ট করেছে; তারা সঠিক পথ থেকে বহু দূরে পথভ্রষ্ট”।"],
  "5:78": ["Cursed were those who kafara from the children of Israel, by the tongue of Dawud and Isa son of Maryam. That is because they disobeyed and used to transgress.", "ইসরাইলের সন্তানদের মধ্যে যারা অবিশ্বাস করেছিল তারা দাউদ এবং মরিয়মের পুত্র ঈসার মুখে নিন্দিত। এটা এ কারনে যে তারা অমান্য করেছিল এবং সীমা অতিক্রম করেছিল।"],
  "5:79": ["They would not restrain one another from the rejected things they did. Evil was what they used to do.", "তারা একে অন্যকে মন্দ করতে নিষেধ করেনি। তারা যা করেছিল তা সত্যিই শোচনীয়।"],
  "5:80": ["You see many of them turning to those who disbelieve. Evil is what their souls sent ahead for them — that Allah's wrath is upon them, and in the punishment they abide.", "তুমি তাদের অনেককে দেখবে নিজেদের মিত্র করতে তাদেরকে যারা অবিশ্বাস করে। সত্যিই শোচনীয় তাদের  হাত তাদের আত্মার পক্ষ থেকে যা পূর্বে পাঠিয়েছে। আল্লাহ তাদের প্রতি রাগান্বিত এবং,ফলস্বরূপ, তারা চিরকাল শাস্তির মধ্যে বসবাস করবে।"],
  "5:81": ["If they believed in Allah and the Nabi and what was sent down to him, they would not have taken them as allies — but many of them are defiant.", "যদি তারা বিশ্বাস করত আল্লাহতে,এবং নবীকে,এবং তাতে যা এখানে তার কাছে প্রকাশ করা হয়েছিল, তবে তারা তাদেরকে বন্ধু করত না। কিন্তু তাদের অনেকেই মন্দ।"],
  "5:82": ["You will surely find the most vehement of the people in enmity toward those who believe to be the Jews and those who associate others; and you will surely find the nearest of them in affection to those who believe to be those who say: we are Christians. That is because among them are priests and monks, and because they do not wax proud.", "তুমি পাবে যে বিশ্বাসীদের নিকৃষ্ট শত্রু হচ্ছে ইহুদীরা এবং প্রতিমা উপাসকেরা। এবং তুমি বন্ধুত্বে বিশ্বাসীদের সবচেয়ে কাছের লোক পাবে তাদেরকে যারা বলে,\"আমরা খ্রিস্টান।”এই কারনে যে,তাদের মধ্যে রয়েছে পন্ডিতরা এবং সন্ন্যাসীরা,এবং তারা উদ্ধত নয়।"],
  "5:83": ["And when they hear what was sent down to the Rasul, you see their eyes overflow with tears from what they recognize of the truth. They say: our Rabb, we believe — so write us down with the witnesses.", "যখন তারা শোনে যা বার্তাবাহকের কাছে প্রকাশ করা হয়েছিল, তুমি দেখতে পাও তাদের চোখগুলো অশ্রুতে ভাসছে যেহেতু তারা এর মধ্যে সত্য চিনতে পারে,এবং তারা বলে,\"আমাদের প্রভু,আমরা বিশ্বাস করেছি,তাই আমাদেরকে সাক্ষীদের মাঝে গননা করুন।"],
  "5:84": ["And why should we not believe in Allah and in what has come to us of the truth, and hope that our Rabb will enter us with the good people?", "\"কেন আমাদের বিশ্বাস করা উচিত হবে না আল্লাহকে,এবং সে সত্যে যা আমাদের কাছে এসেছে,এবং আশা করা যে আমাদের প্রভু হয়তো সৎকর্মশীল লোকদের সাথে আমাদেরকে প্রবেশ করাবেন?\""],
  "5:85": ["So Allah recompensed them for what they said: gardens beneath which rivers flow, abiding therein. And that is the recompense of the good-doers.", "আল্লাহ তাদেরকে পুরষ্কৃত করেছেন এটা বলার জন্য; তিনি তাদেরকে প্রবেশ করাবেন প্রবাহিত ঝর্নাসহ বাগানসমূহে। তারা সেখানে চিরকাল বসবাস করে। এরকমই বিশ্বাসীদের জন্য পুরষ্কার।"],
  "5:86": ["And those who disbelieve and deny Our signs — those are the companions of the blaze.", "আর তারা যারা অবিশ্বাস করে এবং আমাদের প্রকাশনাবলি প্রত্যাক্ষান করে,তারা নরকের অধিবাসী।"],
  "5:87": ["O you who believe, do not forbid the good things that Allah made lawful for you, and do not transgress. Allah does not love the transgressors.", "হে তোমরা যারা বিশ্বাস করো,আল্লাহ দ্বারা আইনসম্মত ভালো জিনিশগুলো নিষিদ্ধ করো না,এবং আক্রমন করো না; আল্লাহ আক্রমণকারীদের অপছন্দ করেন।"],
  "5:88": ["And eat of what Allah provided you, lawful and good, and be mindful of Allah, in whom you believe.", "এবং ভালো ও আইনসম্মত বস্তুসমুহ থেকে খাও যা আল্লাহ তোমাদের জন্য দিয়েছেন। তোমরা আল্লাহকে ভক্তি শ্রদ্ধা করবে,যার প্রতি তোমরা বিশ্বাসী।"],
  "5:89": ["Allah does not take you to task for the idle talk in your oaths, but takes you to task for what your oaths have bound. So its expiation is feeding ten needy ones with the middle of what you feed your families, or clothing them, or freeing one in bondage. Whoever cannot find — then a fast of three days. That is the expiation of your oaths when you swear. And guard your oaths. Thus Allah makes the signs clear to you, so that you may give thanks.", "শুধু শপথ উচ্চারনের জন্য আল্লাহ তোমাদের দায়বদ্ধ করেন না; তিনি তোমাদের প্রকৃত অভিপ্রায় সমূহের জন্য তোমাদেরকে দায়বদ্ধ করেন। যদি তোমরা একটি শপথ ভঙ্গ করো,তোমরা প্রায়শ্চিত্ত করবে দশজন গরীব লোককে একই খাবার থেকে  খাওয়ানোর দ্বারা যা তোমরা তোমাদের পরিবারকে দিয়ে থাকো,অথবা তাদেরকে বস্ত্র প্রদানের দ্বারা,অথবা একজন দাস মুক্ত করার মাধ্যমে। যদি তোমরা এগুলো করতে সমর্থ না হও, তাহলে তোমরা তিন দিন রোজা রাখবে। এটাই হচ্ছে শপথ সমূহ ভঙ্গ করার প্রায়শ্চিত্ত  যা তোমরা বজায় রাখার অঙ্গীকার করেছিলে। তোমরা তোমাদের শপথ সমূহ পূর্ণ করবে। আল্লাহ এভাবে তোমাদের কাছে তাঁর প্রকাশনা বলী ব্যখ্যা করেন, যাতে তোমরা কৃতজ্ঞ হতে পারো।"],
  "5:90": ["O you who believe, wine, and gaming, and the erected stones, and the arrows are filth from the work of Shaytan — so avoid it, so that you may attain success.", "হে তোমরা যারা বিশ্বাস করো,মাদকদ্রব্য, এবং জুয়া,এবং উপাস্যের বেদি,এবং ভাগ্যের খেলাগুলো শয়তানের ঘৃণ্য কাজ; তোমরা এগুলো এড়িয়ে চলবে,যাতে তোমরা সফল হতে পারো।"],
  "5:91": ["Shaytan only wants to cast between you enmity and hatred through the wine and the gaming, and to turn you away from the remembrance of Allah and from the prayer. Will you not cease?", "শয়তান চায় মাদকদ্রব্য এবং জুয়ার মাধ্যমে তোমাদের মাঝে শত্রুতা এবং ঘৃণার উদ্রেক করতে,এবং আল্লাহর স্মরণ থেকে,ও সংযোগ প্রার্থনাসমূহ (সালাত) পালন করা থেকে তোমাদের মনোযোগ সরিয়ে দিতে। তবে কি তোমরা বিরত হবে?"],
  "5:92": ["And obey Allah and obey the Rasul, and beware. If you turn away, then know that upon Our Rasul is only the clear delivery.", "তোমরা আল্লাহকে মান্য করবে,এবং তোমরা বার্তাবাহককে মান্য করবে,এবং সতর্ক থাক। যদি তোমরা বিমুখ হও, তবে জেনো যে আমাদের বার্তাবাহকের একমাত্র দায়িত্ব হচ্ছে বার্তা পৌঁছে দেয়া।"],
  "5:93": ["No blame rests on those who believe and do good works for what they have tasted, when they are mindful and believe and do good works; then are mindful and believe; then are mindful and do good. And Allah loves the good-doers.", "যারা বিশ্বাস করে এবং সৎকর্মশীল জীবন যাপন করে তারা কোন খাদ্য খাওয়ার দ্বারা অপরাধ বহন করে না,যতক্ষণ তারা প্রত্যাদেশাবলি মেনে চলে,বিশ্বাস করে এবং একটি সৎ জীবন-যাপন করে,এরপর তাদের সৎকর্মশীলতা এবং আস্থা বজায় রাখে,এবং সৎকর্মশীলতা ও সৎকর্মশীলতা পালন অব্যাহত রাখে। আল্লাহ সৎকর্মশীলদের ভালবাসেন।"],
  "5:94": ["O you who believe, Allah will test you with something of game that your hands and spears reach, so that Allah may know who fears Allah in the unseen. Whoever transgresses after that — for that one is a painful punishment.", "হে তোমরা যারা বিশ্বাস কর, আল্লাহ তোমাদের হাতের নাগালে মধ্যে কিছু শিকার এবং তোমাদের তীরগুলো দ্বারা তোমাদের পরীক্ষা করবেন (হজ্বের সময়)। আল্লাহ এভাবে তোমাদের মধ্যে তাদেরকে আলাদা করেন যারা তাঁকে তাদের একান্তে মেনে চলে। যারা এরপরে সীমালঙ্ঘন করে তারা এক যন্ত্রনাদায়ক শাস্তি টেনে এনেছে।"],
  "5:95": ["O you who believe, do not kill game while you are in the sacred state. Whoever of you kills it deliberately — the recompense is the like of what was killed of cattle, judged by two just ones among you, as an offering reaching the Ka'bah; or an expiation: feeding needy ones, or the equal of that as fasting, so that the heavy cost of the deed may be tasted. Allah has passed over what went before. Whoever returns — Allah will requite that one. And Allah is mighty, possessor of requital.", "হে তোমরা যারা বিশ্বাস কর, তীর্থযাত্রার সময় কোন শিকারকে বধ করো না। যেকেউ ইচ্ছাকৃতভাবে কোন শিকার বধ করে,তার জরিমানা হবে সে সংখ্যক গৃহপালিত পশু যা তার বধকৃত শিকার প্রানীগুলোর সমতুল্য। (বিচারের) রায়টি তোমাদের মধ্যে দুইজন ন্যায়পরায়ন লোকের দ্বারা ধার্য হবে। তারা নিশ্চিত করবে যে উৎসর্গগুলো কা'বায় পৌঁছায়। অন্যথায়, সে প্রায়শ্চিত্ত করতে পারে গরীব লোকদের খাওয়ানোর দ্বারা,অথবা তার অপরাধের প্রায়শ্চিত্ত করতে একটি সমতুল্য উপবাস দ্বারা। আল্লাহ অতীত অপরাধসমূহ ক্ষমা করেছেন। কিন্তু,যদি কেউ এরকম একটি অপরাধে করে বেড়ায়, আল্লাহ এর প্রতিশোধ নিবেন। আল্লাহ সর্বশক্তিমান, প্রতিশোধ গ্রহণকারী।"],
  "5:96": ["Made lawful for you is the game of the sea and its food, as provision for you and for the travelers. Forbidden to you is the game of the land while you remain in the sacred state. And be mindful of Allah, to whom you will be gathered.", "সমুদ্রের সকল মাছ তোমাদের খাওয়ার জন্য আইনসম্মত করা হল। তীর্থ যাত্রার সময়, এগুলো তোমাদের জন্য খাদ্যের যোগান হতে পারে। তোমরা তীর্থযাত্রা জুড়ে শিকার করবে না। তোমরা আল্লাহকে ভক্তি শ্রদ্ধা করবে,যার সামনে তোমাদের ডাকা হবে।"],
  "5:97": ["Allah has made the Ka'bah, the sacred house, a standing-place for people, and the sacred month, and the offerings, and the garlanded ones. That is so that you may know that Allah knows what is in the heavens and what is in the earth, and that Allah knows everything.", "আল্লাহ নির্ধারণ করেছেন পবিত্র মসজিদ কা'বাকে লোকদের জন্য একটি উপাসনার স্থান হিসেবে,এবং পবিত্র মাসগুলোও, (পবিত্র মসজিদের প্রতি) উৎসর্গগুলো,এবং  মালাগুলো যা এগুলোকে চিহ্নিত করে। তোমাদের জানা উচিৎ যে আল্লাহ আকাশমন্ডলী ও পৃথিবীর সবকিছু জানেন, এবং যে আল্লাহ সর্বশক্তিমান।"],
  "5:98": ["Know that Allah is severe in punishment, and that Allah is forgiving, merciful.", "জানো যে আল্লাহ শাস্তি প্রয়োগে কঠোর, এবং যে আল্লাহ ক্ষমাশীল, পরম দয়ালু।"],
  "5:99": ["Upon the Rasul is only the delivery. And Allah knows what you make manifest and what you hide.", "বার্তাবাহকের একমাত্র দায়িত্ব হচ্ছে বার্তা পৌঁছে দেয়া,এবং আল্লাহ  জানেন সবকিছু যা তোমরা প্রকাশ কর এবং সবকিছু যা তোমরা গোপন করো।"],
  "5:100": ["Say: the vile and the good are not equal, even if the mass of the vile impresses you. So be mindful of Allah, O people of understanding, so that you may attain success.", "ঘোষণা করঃ “মন্দ এবং ভালো এক নয়, যদিও মন্দের আধিক্য তোমাকে প্রভাবিত করতে পারে। তুমি আল্লাহকে ভক্তি শ্রদ্ধা করবে,(এমনকি যদিও তুমি সংখ্যালঘুদের মধ্যে) হে তোমরা যারা বুদ্ধিমত্তার অধিকারী,যাতে তোমরা সফল হতে পারো।"],
  "5:101": ["O you who believe, do not ask about things which, if shown to you, would displease you. And if you ask about them when the recitation is sent down, they will be shown to you. Allah has passed over them, and Allah is forgiving, forbearing.", "হে তোমরা যারা বিশ্বাস কর, জিজ্ঞেস করো না সেসব ব্যাপারসমূহ সম্পর্কে যা,যদি তোমাদের কাছে অকালেই প্রকাশিত হয়, তোমাদের আঘাত করতে পারে। যদি তোমরা কুরআনের আলোকে সেগুলো সম্পর্কে জিজ্ঞেস কর, সেগুলো তোমাদের কাছে স্পষ্ট হয়ে উঠবে। আল্লাহ উদ্দেশ্যপ্রনোদিতভাবে সেগুলো উপেক্ষা করেছেন। আল্লাহ ক্ষমাকারী,দয়াদ্র।"],
  "5:102": ["A people before you asked about them, then became kafirin in them.", "তোমাদের আগে অন্যরা একই প্রশ্নসমূহ জিজ্ঞেস করেছিল, এরপর তাতে অবিশ্বাসী হয়ে পড়েছিল।"],
  "5:103": ["Allah did not make a Bahira, nor a Sa'iba, nor a Wasila, nor a Hami — but those who disbelieve fabricate lies about Allah, and most of them do not understand.", "আল্লাহ নিষিদ্ধ করেননি গৃহপালিত পশু যা জন্ম দেয় পুরুষ জাতীয় ও নারী জাতীয় নির্দিষ্ট মিশ্রণসমূহ, না কোন শপথের দ্বারা মুক্তকৃত গৃহপালিত পশু,না সেটি যা জন্ম দেয় পর পর দুটি পুরুষ জাতীয়, না সেই ষাড় যেটি দশটির পিতা। অবিশ্বাসীরাই আল্লাহ সম্বন্ধে এরকম মিথ্যা উদ্ভাবন করেছিল। তাদের বেশির ভাগই বোঝে না।"],
  "5:104": ["And when it is said to them: come to what Allah sent down and to the Rasul, they say: sufficient for us is what we found our fathers upon. What — even if their fathers knew nothing and were not guided?", "যখন তাদের বলা হল, \"আস তাতে যা আল্লাহ প্রকাশ করেছেন, এবং বার্তাবাহকের দিকে,”তারা বলে,\"আমাদের জন্য যথেষ্ট যা আমরা আমাদের পিতা-মাতাদের করতে দেখেছিলাম।”যদি এমন হয় যে তাদের পিতা-মাতারা কিছুই না জানত, এবং না ছিল পথপ্রাপ্ত?"],
  "5:105": ["O you who believe, upon you rests your own selves. Those who stray cannot harm you if you are guided. To Allah is your return, all of you, and Allah will tell you what you used to do.", "হে তোমরা যারা বিশ্বাস কর, তোমাদের উচিত শুধু তোমাদের নিজেদের ব্যপারে ভয় করা। যদি অন্যরা পথভ্রষ্ট হয়, তারা তোমাদের আঘাত করতে পারে না,যতক্ষণ তোমরা পথপ্রাপ্ত আছ। আল্লাহর কাছে তোমাদের চুড়ান্ত নিয়তি,তোমাদের সবার, তখন তিনি তোমাদেরকে অবগত করবেন যা কিছু তোমরা করেছিল।"],
  "5:106": ["O you who believe, the testimony among you: when death comes to one of you at the time of the bequest — two just ones of you, or two others from other than you, if you are traveling in the land and the blow of death strikes you. Detain the two after the prayer, and let them both swear by Allah — if you are in doubt: we will not take any price for it, even if it is one near of kin, and we will not hide the testimony of Allah — for then we would be among the sinful.", "হে তোমরা যারা বিশ্বাস করো,তোমাদের কেউ যখন মারা যাচ্ছে,তখন অছিয়তনামার সাক্ষী হওয়ার কাজ সম্পন্ন হবে তোমাদের মাঝে দুজন ন্যায়পরায়ণ লোক দ্বারা। যদি তোমরা ভ্রমণরত থাকো,তখন অন্য দুজন সাক্ষী হওয়ার কাজ করতে পারে। সংযোগ প্রার্থনা (সালাত) সম্পন্ন করার পর, তোমাদের সন্দেহ দূর করার জন্য সাক্ষীরা আল্লাহর নামে শপথ করবেঃ “আমরা ব্যক্তিগত লাভ প্রাপ্তির জন্য এটি ব্যবহার করবো না,এমন কি যদিও অছিয়তকারী আমাদের সাথে সম্পর্কযুক্ত হয়। না আমরা আল্লাহর সাক্ষ্য গোপন করবো। অন্যথায়, আমরা পাপী হবো”।"],
  "5:107": ["Then if it is discovered that the two merited guilt, two others shall stand in their place from those entitled against the first two, and they shall both swear by Allah: our testimony is truer than their testimony, and we have not transgressed — for then we would be among the wrongdoers.", "যদি সাক্ষীগনের মধ্যে পক্ষপাতগ্রস্থ হওয়ার অপরাধ পাওয়া যায়, তখন অন্য দু'জনকে তাদের স্থান নেয়ার জন্য অনুরোধ করা হবে। পছন্দ করো দুজন ব্যক্তি যারা প্রথম সাক্ষীগনের দ্বারা ক্ষতির শিকার, এবং তাদেরকে আল্লাহর নামে শপথ করতে দাওঃ “আমাদের সাক্ষ্য তাদের চেয়ে অধিক সত্যপূর্ন;আমরা পক্ষপাতদুষ্ট হবো না। অন্যথায়, আমরা সীমাতিক্রমকারী হবো।\""],
  "5:108": ["That is nearer — that they bring the testimony in full, or that they fear oaths being returned after their oaths. And be mindful of Allah and listen. Allah does not guide the defiant people.", "তাদেরকে সৎ সাক্ষ্য দিতে উৎসাহিত করা অধিক সঙ্গত, ভয় করে যে তাদের শপথ হয়তো পূর্বের সাক্ষিদের মতো অবিবেচিত হবে। তোমরা আল্লাহকে মান্য করবে এবং শোন। আল্লাহ মন্দদের পথ প্রদর্শন করেন না।"],
  "5:109": ["The day Allah gathers the Rasuls and says: what answer were you given? They say: we have no knowledge. You alone are the knower of the unseen.", "সে দিন আসবে যখন আল্লাহ বার্তাবাহকদের আহবান করবেন এবং তাদের জিজ্ঞেস করবেন, \"তোমাদের প্রতি কেমন সাড়া দেয়া হয়েছিল?” তারা বলবে,“আমাদের কোন জ্ঞান নেই। আপনি সকল গোপন বিষয়ের জ্ঞাতা”।"],
  "5:110": ["When Allah said: O Isa son of Maryam, remember My blessing upon you and upon your mother — when I strengthened you with the holy spirit, you spoke to people in the cradle and in maturity; and when I taught you the scriptures, and wisdom, and the Torah, and the Gospel; and when you create from clay like the shape of a bird, by My leave, then breathe into it and it becomes a bird by My leave; and you heal the blind and the leper by My leave; and when you bring out the dead by My leave; and when I restrained the children of Israel from you when you came to them with clear proofs — yet those of them who kafara said: this is nothing but clear magic.", "আল্লাহ বলবেন, “হে মরিয়ম পুত্র- ঈসা,তোমার এবং তোমার মাতার প্রতি আমার অনুগ্রহ স্মরণ করো। আমি পবিত্র আত্মার দ্বারা তোমাকে সহায়তা করেছিলাম, কোলে থাকা অবস্থায় সেই সাথে একজন পূর্ন বয়স্ক অবস্থায় লোকদের সাথে কথা বলায় সক্ষম করতে। আমি তোমাকে শিখিয়েছিলাম ঐশীগ্রন্থ, প্রজ্ঞা,তওরাত, ও ইঞ্জিল। স্মরণ করো,তুমি কাদা থেকে পাখির আকৃতি তৈরি করেছিলে আমার অনুমতিতে,এরপর তাতে ফু দিয়েছিলে,এবং তা একটি জীবন্ত পাখি হয়ে গিয়েছিল আমার অনুমতিতে। তুমি অন্ধ ও কুষ্ঠ রোগীকে নিরাময় করেছিলে আমার অনুমতিতে,এবং মৃতকে পুনরুজ্জীবিত করেছিলে আমার অনুমতিতে। স্মরণ করো,আমি তোমাকে ইসরাইলের সন্তানদের থেকে রক্ষা করেছিলাম যারা তোমার ক্ষতি করতে চেয়েছিল, প্রগাড় অলৌকিকতা সত্ত্বেও যা তুমি তাদেরকে দেখিয়েছিলে। তাদের মধ্যকার অবিশ্বাসীরা বলেছিল, ‘এটি সুস্পষ্ট জাদু”।"],
  "5:111": ["And when I inspired the disciples: believe in Me and in My Rasul. They said: we believe — and bear witness that we are in submission.", "\"স্মরণ কর যে আমি অনুসারীদের অনুপ্রাণিত করেছিলাম: 'তোমরা আমাকে ও আমার বার্তাবাহককে বিশ্বাস করবে।'তারা বলেছিল, 'আমরা বিশ্বাস করেছি,এবং সাক্ষী থাকুন যে আমরা আত্মসমর্পণকারী।' \""],
  "5:112": ["When the disciples said: O Isa son of Maryam, can your Rabb send down to us a spread-table from the heaven? Isa said: be mindful of Allah, if you are muminin.", "স্মরণ কর যে অনুসারীরা বলেছিল, \"হে মরিয়ম পুত্র-ঈসা,তোমার প্রভু কি আকাশ থেকে আমাদের কাছে কোন ভোজ পাঠাতে পারেন?”সে বলেছিল, \"তোমাদের উচিত আল্লাহকে ভক্তি-শ্রদ্ধা করা,যদি তোমরা বিশ্বাসী হও।"],
  "5:113": ["They said: we want to eat of it and our hearts be settled, and to know that You have been true to us, and to be witnesses over it.", "তারা বলেছিল, \"আমরা চাই এর থেকে খেতে,এবং আমাদের অন্তরকে আশ্বস্ত করতে,এবং নিশ্চিত জানতে যে তুমি আমাদের সত্য বলেছ। আমরা এর সাক্ষী হিসেবে কাজ করবো।\""],
  "5:114": ["Isa son of Maryam said: O Allah, our Rabb, send down to us a spread-table from the heaven, to be a festival for our first and our last, and a sign from You, and provide us — and You are the best of providers.", "মরিয়ম পুত্র ঈসা বলেছিল, \"আমাদের উপাস্য, আমাদের প্রভু,আমাদের কাছে আকাশ হতে একটি ভোজ অবতীর্ণ করুন। এটি যেন আমাদের প্রত্যেকের জন্য প্রচুর হয়, এবং আপনার পক্ষ থেকে একটি নিদর্শন হয়। আমাদের জন্য প্রদান করুন; আপনি সর্বোত্তম দাতা।\""],
  "5:115": ["Allah said: I am sending it down to you. Whoever of you disbelieves after — I will punish that one with a punishment with which I punish no one of the worlds.", "আল্লাহ বলেছিলেন, \"আমি তা অবতীর্ণ করছি। তোমাদের মধ্যে যেকেউ এরপর অবিশ্বাস করে,আমি তাকে শাস্তি দিব যা আমি কখনো কাউকে দেইনি।\""],
  "5:116": ["And when Allah said: O Isa son of Maryam, did you say to the people: take me and my mother as two alihah besides Allah? Isa said: glory be to You — it is not for me to say what is not mine by truth. If I had said it, You would have known it. You know what is in my soul, and I do not know what is in Your soul. You alone are the knower of the unseen.", "আল্লাহ বলবেন, “হে মরিয়ম পুত্র-ঈসা,তুমি কি লোকদের বলেছিলে যে,‘আমাকে আর আমার মাকে আল্লাহর পাশে উপাস্য বানাও?’ সে বলবে,“আপনি মহিমান্বিত। আমি বলতে পারতাম না, যা সঠিক না। আমি যদি তা বলে থাকতাম, আপনি ইতোমধ্যে তা জেনে যেতেন। আপনি আমার চিন্তাগুলো জানেন, এবং আমি আপনার চিন্তাগুলো জানি না। আপনি সকল রহস্য জানেন।"],
  "5:117": ["I said to them only what You enjoined upon me: worship Allah, my Rabb and your Rabb. And I was a witness over them as long as I remained among them; and when You took me, You were the watcher over them, and You are witness over everything.", "আমি তাদেরকে  শুধুমাত্র তা-ই বলেছিলাম যা আপনি আমাকে বলতে হুকুম করেছিলেন, যেঃ ‘তোমরা আল্লাহর উপাসনা করবে,আমার প্রভু এবং তোমাদের প্রভু”। আমি তাদের মাঝে একজন সাক্ষী ছিলাম, যতো দিন আমি তাদের সাথে বেঁচে ছিলাম। যখন আপনি পৃথিবীতে আমার জীবন সমাপ্ত করেছিলেন, আপনি তাদের উপর পর্যবেক্ষক হলেন। আপনি সবকিছুর দ্রষ্টা।"],
  "5:118": ["If You punish them, they are Your servants; and if You forgive them, then You are the mighty, the wise.", "“যদি আপনি তাদের শাস্তি দেন, তারা আপনার দাস। যদি আপনি তাদের ক্ষমা করেন, আপনি সর্বশক্তিমান, সবচেয়ে জ্ঞানী’।"],
  "5:119": ["Allah said: this is the day the sadiqin benefit by their sadiqness. For them are gardens beneath which rivers flow, abiding therein forever. Allah is pleased with them and they are pleased with Allah. That is the great triumph.", "আল্লাহ ঘোষণা করবেন, ‘এটি এমনি এক দিন যখন সত্যবাদীরা তাদের সত্যবাদিতার দ্বারা রক্ষা পাবে’। তারা প্রবাহিত ঝর্নাসহ বাগানের উপযুক্ত হয়েছে। তারা সেখানে চিরকাল বাস করে। আল্লাহ তাদের প্রতি সন্তুষ্ট, এবং তারা তাঁর প্রতি সন্তুষ্ট। এটাই সর্বোচ্চ বিজয়।"],
  "5:120": ["To Allah belongs the kingdom of the heavens and the earth and what is in them, and Allah is over everything able.", "আকাশমন্ডলী ও পৃথিবীর, এবং এদের মধ্যকার সবকিছুর সার্বভৌম ক্ষমতা আল্লাহর, এবং তিনি সর্বশক্তিমান।"],
  "6:1": ["Praise belongs to Allah, who created the heavens and the earth and made the darkness and the light; then those who disbelieve set up equals to their Rabb.", "প্রশংসা আল্লাহর, যিনি আকাশমণ্ডলী ও পৃথিবী সৃষ্টি করেছেন, এবং বানিয়েছেন অন্ধকার ও আলো। এরপরেও, যারা তাদের রবকে অবিশ্বাস করে তারা পথচ্যুতিতেই রয়েছে।"],
  "6:2": ["It is Allah who created you from clay, then decreed a term; and a fixed term is with Allah; yet you doubt.", "তিনিই একজন যিনি কাঁদামাটি থেকে তোমাদের সৃষ্টি করেছেন, এরপর পূর্বনির্ধারণ করেছেন তোমাদের জীবনকাল, জীবনকাল যা শুধু তাঁরই জানা। এরপরও, তোমরা সন্দেহের মধ্যেই রয়েছ।"],
  "6:3": ["And Allah is in the heavens and in the earth, knows your secret and your open-loud, and knows what you earn.", "আকাশমণ্ডলী ও পৃথিবীতে তিনিই একমাত্র আল্লাহ। তিনি তোমাদের গোপন ও তোমাদের প্রকাশ্য বিষয়াদি জানেন, এবং তিনি সবকিছু জানেন যা তোমরা উপার্জন করো।"],
  "6:4": ["And no sign comes to them from the signs of their Rabb but they turn away from it.", "যে ধরনের প্রমানই তাদের প্রভুর পক্ষ থেকে তাদের কাছে আসুক না কেন, তারা তা থেকে মুখ ফিরিয়ে নেয়, বিদ্বেষে।"],
  "6:5": ["They have already denied the truth when it came to them; but soon there will come to them news of what they used to mock.", "যেহেতু তারা প্রত্যাক্ষান করেছে সত্য যখন তা তাদের কাছে এসেছিল, তারা তাদের অমনোযোগিতার প্রতিফলসমূহ টেনে এনেছে।"],
  "6:6": ["Have they not seen how many generations We destroyed before them, whom We had established in the earth in what We have not established you, and sent the sky down upon them pouring, and made rivers flow beneath them? Yet We destroyed them for their offenses, and raised up after them other generations.", "তারা কি দেখেনি, তাদের আগে আমরা কত প্রজন্মকে ধ্বংস করেছি? আমরা তাদেরকে পৃথিবীতে প্রতিষ্ঠিত করেছিলাম তোমাদেরকে যতোটা করেছিলাম তার চেয়ে বেশি,এবং আমরা তাদের প্রতি আশীর্বাদ বর্ষণ করেছিলাম, উদারভাবে,এবং আমরা তাদের দিয়েছিলাম প্রবাহিত ঝর্নাসমূহ। আমরা এরপর তাদেরকে ধ্বংস করেছিলাম তাদের পাপের কারনে,এবং আমরা প্রতিস্থাপিত করেছিলাম তাদের স্থানে অন্য প্রজন্মকে।"],
  "6:7": ["Had We sent down to you a writing on paper which they touched with their hands, those who disbelieve would have said: This is nothing but clear magic.", "এমনকি যদি আমরা তাদের প্রতি একটি বাস্তব গ্রন্থ অবতীর্ণ করতাম, কাগজে লিখিত, আর তারা তাদের হাত দিয়ে তা স্পর্শ করত, যারা অবিশ্বাস করেছে তারা বলত, “এটা সুনিপুন জাদুর চেয়ে বেশি কিছু নয়।\""],
  "6:8": ["And they said: Why has no malakat been sent down to him? And had We sent down an malakat, the matter would have been decided, and then they would be given no respite.", "তারা আরও বলেছিল, “শুধু যদি তার সাথে একজন ফেরেশতা অবতরণ করতো!” যদি আমরা কোন ফেরেশতা পাঠাতাম, পুরো ব্যাপারটির পরিসমাপ্তি ঘটতো,এবং তারা আর কোন অবকাশ পেতো না।"],
  "6:9": ["And had We made the malakat a man, We would have cast over them the very doubt they cast.", "আমরা যদি একজন ফেরেশতা পাঠাতাম, আমরা তাকে একজন মানুষের আকারে পাঠাতাম, এবং আমরা তাদেরকে একই রকম বিভ্রান্তিতে রাখতাম এখন তারা যেরকম বিভ্রান্তিতে আছে।"],
  "6:10": ["Messengers were mocked before you; so those who mocked them were encircled by what they used to mock.", "তোমার পূর্বের বার্তাবাহকদের উপহাস করা হয়েছে,যারাই তাদের উপহাস করেছিল তারা তাদের উপহাস করার প্রতিফলসমূহ ভোগ করেছিল।"],
  "6:11": ["Say: Journey in the land, then look how was the end of the mukazzibin.", "বল, \"পৃথিবীতে ভ্রমন কর এবং লক্ষ্য কর প্রত্যাক্ষানকারীদের পরিণামসমূহ।\""],
  "6:12": ["Say: To whom belongs what is in the heavens and the earth? Say: To Allah. Allah has written mercy upon the self, to gather you surely to the Day of Rising, no doubt in it. Those who lose themselves, they do not believe.", "বল, \"আকাশমন্ডলী ও পৃথিবীর সবকিছু কার?”বল, \"আল্লাহর।” দয়া হচ্ছে তাঁর গুন, যা তিনি নিয়মে পরিণত করেছেন । তিনি নিশ্চিতভাবে তোমাদের সবাইকে পুনরুত্থান দিনে ডাকবেন, যা অনিবার্য। যারাই অবিশ্বাস করে তারাই তাদের আত্মা হারায়।"],
  "6:13": ["And to Allah belongs what rests in the night and the day, and Allah is the All-Hearing, the All-Knowing.", "তাঁর অধীনেই রয়েছে সবকিছু যা বাস করে রাতে ও দিনে। তিনি শ্রোতা,জ্ঞাতা।"],
  "6:14": ["Say: Shall I take as protector other than Allah, the originator of the heavens and the earth, who feeds and is not fed? Say: I am commanded to be the first of those who submit, and: never be of those who join partners.", "বল, \"আমি কি প্রভু ও মনিব হিসেবে আল্লাহ ছাড়া অন্য কাউকে গ্রহন করবো,যখন তিনি আকাশমন্ডলী  ও পৃথিবীর সূচনাকারী,এবং তিনি খাওয়ান কিন্তু খান না?\" বল, \"আমি সবচেয়ে অনুগত আত্মসমর্পণকারী হতে আদেশপ্রাপ্ত হয়েছি,এবং,'প্রতিমা উপাসক হইও না।'\""],
  "6:15": ["Say: I fear, if I disobey my Rabb, the punishment of a great day.", "বল, \"যদি আমি আমার প্রভুকে অমান্য করে থাকি,আমি ভয় করি- এক ভয়ংকর দিনের শাস্তির।"],
  "6:16": ["Whoever is averted from it that day, then Allah has had mercy on them; and that is the clear winning.", "“যে কেউ সেদিন, (শাস্তি থেকে) নিষ্কৃতি পায়, তাঁর করুণা লাভ করেছে। আর, এটিই শ্রেষ্ঠ বিজয়।\""],
  "6:17": ["And if Allah touches you with harm, none can lift it but Allah; and if Allah touches you with good, then Allah is over all things powerful.", "যদি আল্লাহ তোমাদের দুর্দশা দেন, তিনি ব্যতিত অন্য কেউ তা লাঘব করতে পারে না। এবং তিনি যদি তোমাদেরকে সৌভাগ্য দেন, তিনি সর্বশক্তিমান।"],
  "6:18": ["And Allah is the overpowering above the servants; and Allah is the Wise, the Aware.", "তিনি তাঁর সৃষ্টির উপর পরাক্রান্ত। তিনি সবচেয়ে জ্ঞানী,জ্ঞাত।"],
  "6:19": ["Say: What thing is greatest in testimony? Say: Allah, a witness between me and you. And this Quran was revealed to me, to warn you with it and whomever it reaches. Do you indeed testify that with Allah there are other alihah? Say: I do not testify. Say: Allah is only one ilah, and I am clear of what you join as partners.", "বল, “কার সাক্ষ্য সর্বশ্রেষ্ঠ?” বল, “আল্লাহর। তিনি আমার ও তোমাদের মাঝে  সাক্ষী যে এই কুরআন আমার প্রতি প্রত্যাদিষ্ট হয়েছে, এর প্রচার করতে তোমাদের কাছে এবং যার কাছে এটি পৌঁছে। নিশ্চয়, তোমরা সাক্ষ্য দাও যে আল্লাহর পাশে অন্য উপাস্যরা আছে।” বল, “যেরকম তোমরা সাক্ষ্য দাও, আমি তেমন দেই না;উপাস্য তো কেবল একজনই রয়েছেন, এবং আমি তোমাদের অংশিবাদিতা অস্বীকার করি।\""],
  "6:20": ["Those to whom We gave the Book know it as they know their own children. Those who lose themselves, they do not believe.", "যাদেরকে আমরা ঐশীগ্রন্থ প্রদান করেছি তারা তা চেনে যেমন তারা তাদের নিজেদের সন্তানদের চেনে। যারা বিশ্বাস করে না তারাই তাদের আত্মা হারায়।"],
  "6:21": ["And who is more unjust than one who fabricates against Allah a lie, or denies Allah's signs? Indeed the unjust do not attain success.", "তার চেয়ে কে বেশি মন্দ যে আল্লাহ সম্পর্কে মিথ্যা বলে,অথবা তাঁর প্রকাশনাবলি প্রত্যাক্ষান করে? সীমালঙ্ঘনকারীরা কখনো সফল হয় না।"],
  "6:22": ["And the day We gather them all, then We say to those who joined partners: Where are your partners whom you used to claim?", "সে দিন আমরা যখন তাদের সকলকে ডাকব, আমরা প্রতিমা উপাসকদের জিজ্ঞেস করবো,\"তোমাদের স্থাপন করা উপাস্যরা কোথায়?\""],
  "6:23": ["Then their only plea will be to say: By Allah our Rabb, we were not of those who joined partners.", "তাদের দুর্ভাগ্যমূলক উত্তর হবে,\"আমাদের প্রভু আল্লাহর নামে শপথ, আমরা কখনো প্রতিমা উপাসক ছিলাম না।\""],
  "6:24": ["See how they lied against themselves, and what they used to fabricate strayed from them.", "লক্ষ্য কর কিভাবে তারা নিজেদের সাথে মিথ্যা বলেছিল, এবং কিভাবে তাদেরকে তাদের উদ্ভাবিত উপাস্যরা পরিত্যাগ করেছে।"],
  "6:25": ["Among them are those who listen to you, and We have placed coverings over their hearts so they do not understand it, and heaviness in their ears. And if they see every sign, they will not believe in it, until when they come to you disputing with you, those who disbelieve say: This is nothing but tales of the ancients.", "তাদের কেউ কেউ তোমাকে শোনে,কিন্তু আমরা তাদের অন্তরে পর্দা দিয়ে দেই যাতে তারা বুঝতে না পারে,এবং তাদের কানে বধিরতা দেই। সুতরাং,তারা যে ধরনের প্রমানই দেখুক না কেন, তারা বিশ্বাস করতে পারে না। সুতরাং যখন তারা তোমার সাথে তর্ক করতে আসে,অবিশ্বাসীরা বলে,\"এগুলো অতীতের গল্প-গুজব।\""],
  "6:26": ["And they forbid it and keep away from it; yet they ruin none but themselves, and they do not perceive.", "তারা অন্যদের এটি (কুরআন) থেকে বাধাঁ দেয়, যেমন তারা নিজেরা এটি থেকে দূরে থাকে,আর তাই, তারা না বুঝে শুধু নিজেদের ধ্বংস করে।"],
  "6:27": ["If only you could see when they stand over the Fire and say: If only we could return, and not deny the signs of our Rabb, and be among the muminin.", "যদি শুধু তোমরা তাদের দেখতে পারতে যখন তারা নরকাগ্নির মুখোমুখি হয়! তারা তখন বলবে,“আমাদের কি দুঃখ। ইশ, আমরা  যদি পিছনে ফিরে যেতে পারতাম, এবং আমাদের প্রভুর প্রকাশনাবলি কখনো প্রত্যাখ্যান না করতাম, এবং বিশ্বাসীদের সাথে যোগ দিতাম। \""],
  "6:28": ["Rather, what they used to conceal before has become manifest to them. And even if they were returned, they would go back to what they were forbidden; and they are truly liars.", "বাস্তবিকপক্ষে,(তারা শুধু তা বলে যেহেতু) তাদের গোপন বিষয়গুলো প্রকাশিত হয়েছে। যদি তারা ফিরে যায়, তারা ঠিক একই অপরাধসমূহ করবে। তারা মিথ্যাবাদী।"],
  "6:29": ["And they said: There is nothing but our life of this world, and we will not be raised.", "তারা বলে (অবচেতনভাবে),“আমরা শুধু এই জীবনেই বাঁচি;আমরা পুনরুত্থিত হবো না”।"],
  "6:30": ["If only you could see when they stand before their Rabb: Is this not the truth? They say: Yes, by our Rabb. It is said: Taste the punishment for what you used to deny.", "যদি শুধু তুমি তাদের দেখতে পেতে যখন তারা তাদের প্রভুর সামনে দাঁড়ায়! তিনি বলবেন, “এটা কি সত্য নয়?”তারা বলবে,“হ্যাঁ,আমাদের প্রভুর শপথ।” তিনি বলবেন, “তোমরা তোমাদের অবিশ্বাসে কারণে শাস্তি টেনে এনেছ”।"],
  "6:31": ["Those who denied the meeting with Allah have already lost, until when the Hour comes upon them suddenly, they say: Our regret, over what we fell short in it, while they carry their loads on their backs. How evil is what they bear.", "প্রকৃতপক্ষে তারাই ক্ষতিগ্রস্ত যারা আল্লাহর সাথে সাক্ষাতে অবিশ্বাস করে,যতক্ষণ না আকষ্মিকভাবে তাদের কাছে সেই সময় যায়, তখন বলে,\"আমরা এই দুনিয়ায় আমাদের জীবনকে অপচয় করার জন্য গভীর দু:খ প্রকাশ করি।\" তারা তাদের পাপের বোঝা তাদের পিঠে বইবে;কতই না দুর্বিষহ বোঝা!"],
  "6:32": ["And the life of this world is nothing but play and diversion; and the final home is better for those who are mindful. Will you not then reason?", "এই দুনিয়ার জীবন বিভ্রম এবং অন্তঃসারশূন্যতা ছাড়া বেশি কিছু নয়, যখন সৎকর্মশীলদের জন্য পরকালের আবাস অনেক উত্তম। তোমরা কি বুঝ না?"],
  "6:33": ["We know well that what they say grieves you. Yet it is not you they deny; rather the unjust deny the signs of Allah.", "আমরা জানি যে তারা যা বলে তাতে তুমি দু:খ পেতে পার। তোমার জানা উচিত যে, এ তো তুমি নও যাকে তারা প্রত্যাক্ষান করে; এ তো আল্লাহর প্রকাশনাবলি যা মন্দরা উপেক্ষা করে।"],
  "6:34": ["Messengers before you were denied, yet they were sabir over what they denied and were harmed, until Our help came to them. And none can change the words of Allah. And there has already come to you news of the Rasuls.", "তোমার পূর্বের বার্তাবাহকদের প্রত্যাক্ষান করা হয়েছে,এবং তারা প্রত্যাক্ষানের মুখে দৃড়তার সাথে অবিচল ছিল। তারা নিপীড়িত হয়েছিল, যে পর্যন্ত না তাদের কাছে আমাদের বিজয় এসেছিল। এরকমই আল্লাহর পদ্ধতি, যার কখনো পরিবর্তন হবে না। আমার বার্তাবাহকদের ইতিহাস এভাবে তোমাদের জন্য দৃষ্টান্ত সৃষ্টি করে।"],
  "6:35": ["And if their turning away is hard upon you, then, if you can, seek a tunnel in the earth or a ladder in the sky to bring them a sign. Had Allah willed, Allah would have gathered them upon the guidance; so never be of the ignorant.", "যদি তাদের প্রত্যাক্ষান তোমার জন্য অসহনীয় হয়ে যায়, তোমার জানা উচিত যে এমনকি যদি তুমি ভূমির মধ্য দিয়ে কোন সুরঙ্গ খুড়ঁতে,অথবা আকাশের ভিতর সিঁড়ি দিয়ে আরোহনও করতে,এবং তাদের জন্য কোন অলৌকিকতা তৈরী করতে (এরপরও তারা বিশ্বাস করতো না)। আল্লাহ যদি চাইতেন, তিনি তাদের পথ দেখাতে পারতেন, সর্বসম্মতভাবে। সেজন্য, অজ্ঞদের মতো আচরণ করো না।"],
  "6:36": ["Only those who listen respond. And the dead, Allah will raise them, then to Allah they return.", "শুধুমাত্র তারা সাড়া দেবে,যারা শোনে। আল্লাহ মৃতকে পুনর্জীবিত করেন;তারা শেষ পর্যন্ত তাঁর কাছে ফিরে আসে।"],
  "6:37": ["And they said: Why has no sign from his Rabb been sent down to him? Say: Allah is able to send down a sign, but most of them do not know.", "তারা বলেছিল, ‘যদি শুধু একটি বিশ্বাসযোগ্য নিদর্শন তার কাছে তার প্রভুর পক্ষ থেকে আসতো!” বল, “আল্লাহ একটি নিদর্শন অবতীর্ণ করতে সক্ষম, কিন্ত তাদের বেশিরভাগ জানে না”।"],
  "6:38": ["There is no creature on the earth, nor a bird flying on its two wings, but are communities like you. We have neglected nothing in the written record. Then to their Rabb they will be gathered.", "পৃথিবীর সকল সৃষ্টি,এবং সকল পাখি যা পাখা মেলে উড়ে,তোমাদের মতো সম্প্রদায়। আমরা কোন কিছুই এই গ্রন্থের বাইরে রাখিনি। তাদের প্রভুর কাছে,এই সকল সৃষ্টিকে তলব করা হবে।"],
  "6:39": ["Those who deny Our signs are deaf and dumb in darkness. Whomever Allah wills, Allah leaves astray; and whomever Allah wills, Allah sets upon a straight path.", "যারা আমাদের প্রমানাদি প্রত্যাক্ষান করে তারা বধির ও বোবা,পুরোপুরি অন্ধকারে। যাকে আল্লাহ চান, বিপথে পাঠান, এবং যাকে তিনি চান, এক সরল পথে পরিচালিত করেন।"],
  "6:40": ["Say: Tell me, if the punishment of Allah came to you, or the Hour came upon you, would you call on other than Allah, if you are sadiq?", "বল, “কি হবে যদি আল্লাহর শাস্তি তোমাদের কাছে এসে যায়, অথবা সে ঘণ্টা তোমাদের কাছে এসে যায়ঃ তোমরা কি আল্লাহ ছাড়া অন্যকারো কাছে মিনতি করবে,যদি তোমরা সত্যবাদী হও?”"],
  "6:41": ["Rather, it is Allah you call upon; and Allah lifts away what you call upon, if Allah wills, and you forget what you join as partners.", "বাস্তবতা হলো: শুধু তাঁর কাছেই তোমরা মিনতি করো,এবং তিনি তোমাদের প্রার্থনার উত্তর দেন, যদি তিনি এমনই চান, এবং তোমরা তোমাদের উপাস্যদের ভুলে যাও।"],
  "6:42": ["We sent to nations before you, and We seized them with hardship and harm, so that they might plead humbly.", "আমরা তোমাদের আগের সম্প্রদায়গুলোর কাছে (বার্তাবাহকদের) পাঠিয়েছি,এবং আমরা তাদেরকে প্রতিকূলতা ও কষ্ট দিয়ে পরীক্ষায় ফেলেছিলাম, যাতে তারা মিনতি করে।"],
  "6:43": ["Then why, when Our hardship came to them, did they not plead humbly? But their hearts hardened, and the devil made fair to them what they used to do.", "যদি শুধু তারা মিনতি করতো আমাদের পরীক্ষা যখন তাদের পীড়া দিয়েছিল! উল্টো,তাদের অন্তর কঠিন হয়ে পড়েছিল, এবং শয়তান তাদের কাজগুলোকে তাদের চোখে সুশোভিত করে রেখেছিল।"],
  "6:44": ["Then when they forgot what they were reminded of, We opened upon them the doors of everything, until when they rejoiced in what they were given, We seized them suddenly, and there they were, despair-struck.", "যখন তারা এভাবে তাদেরকে দেয়া বার্তা উপেক্ষা করে,আমরা তাদের জন্য সবকিছুর দরজা খুলে দেই। এরপর, যখনই তারা তা নিয়ে আনন্দ করে যা তাদের দেয়া হয়েছিল, আমরা অকস্মাত তাদেরকে শাস্তি দেই;তারা একেবারে হতবম্ভ হয়ে পড়ে।"],
  "6:45": ["So the remnant of the people who did wrong was cut off. And all praise belongs to Allah, Rabb of the worlds.", "মন্দরা এভাবে নিশ্চিহ্ন হয়। প্রশংসা আল্লাহর, মহাবিশ্বের প্রভু।"],
  "6:46": ["Say: Tell me, if Allah took away your hearing and your sight and sealed your hearts, which ilah other than Allah could restore it to you? See how We vary the signs; yet they turn away.", "বল, “কি হবে যদি আল্লাহ তোমাদের শ্রবণ ও দৃষ্টিশক্তি নিয়ে নেন, এবং তোমাদের অন্তরে মোহর এঁটে দেন, আল্লাহ ছাড়া কোন উপাস্য তোমাদের জন্য এগুলো ফিরিয়ে দিতে পারে?” লক্ষ্য করো কিভাবে আমরা প্রকাশনাবলি ব্যাখ্যা করি,এবং লক্ষ্য করো কিভাবে তারা এরপরেও বিপথগামী হয়।"],
  "6:47": ["Say: Tell me, if the punishment of Allah came to you suddenly or openly, would any be destroyed but the unjust people?", "বল, “কি হতো যদি আল্লাহর শাস্তি হঠাৎ করে তোমাদের কাছে আসতো,অথবা কোন ঘোষণার পর, এরা কি পাপীরা নয় যারা ধ্বংস টেনে আনে?"],
  "6:48": ["We send the Rasuls only as bearers of good news and warners. So whoever believes and sets things right, no fear upon them, nor will they grieve.", "আমরা বার্তাবাহকদের একজন সুসংবাদদাতা, আর সতর্ককারী হিসেবে ছাড়া পাঠাই না। যারা বিশ্বাস করে এবং সংশোধিত হয় তাদের ভয়ের কিছু নেই, না তারা শোক করবে।"],
  "6:49": ["And those who deny Our signs, the punishment will touch them for what they used to transgress.", "তাদের জন্য যারা আমাদের প্রকাশনাবলি প্রত্যাক্ষান করে,তারা তাদের পাপের জন্য শাস্তি টেনে আনে।"],
  "6:50": ["Say: I do not say to you that I possess the storehouses of Allah, nor do I know the unseen, nor do I say to you that I am an malakat. I follow only what is revealed to me. Say: Are the blind and the seeing equal? Will you not reflect?", "বল, “আমি তোমাদেরকে বলি না যে আমি আল্লাহর ধনভাণ্ডারগুলোর মালিক। না আমি ভবিষ্যৎ জানি। না আমি তোমাদের বলি যে,আমি একজন ফেরেশতা। আমি কেবল তা অনুসরণ করি, যা আমার কাছে প্রকাশ করা হয়। বল, “অন্ধ কি  চক্ষুষ্মানের সমান? তোমরা কি অনুধাবন করবে না?"],
  "6:51": ["And warn with it those who fear that they will be gathered to their Rabb; they have no protector besides Allah, and no intercessor, so that they may be mindful.", "এবং এটি (কুরআন) দিয়ে প্রচার করো তাদের কাছে যারা তাদের প্রভুর সামনে সমবেত হবার ভয় করে - তাদের প্রভু এবং মনিব হিসেবে তাঁর পাশে আর কেউ নেই, না কোন সুপারিশকারী - যাতে তারা পরিত্রাণ পেতে পারে।"],
  "6:52": ["And do not drive away those who call upon their Rabb at morning and evening, seeking the face of Allah. Nothing of their account is upon you, and nothing of your account is upon them; so do not drive them away, or you would be of the unjust.", "এবং তাদেরকে অগ্রাহ্য করো না যারা দিনে ও রাতে তাদের প্রভুর কাছে মিনতি করে, নিজেদেরকে একমাত্র তাঁর কাছে উৎসর্গ করে। তাদের হিসাবের জন্য তুমি দায়ী নও, না তারা তোমার হিসাবের জন্য দায়ী। যদি তুমি তাদের অগ্রাহ্য করো,তুমি একজন সীমালঙ্ঘনকারী হবে।"],
  "6:53": ["And thus We test some of them by others, so that they say: Are these the ones Allah has favored among us? Is not Allah most knowing of the shakirin?", "আমরা লোকদের এভাবে একের দ্বারা অন্যকে পরীক্ষা করি,তাদেরকে (উপহাস করে) বলতে দিতে,\"এরাই কি আমাদের মধ্যকার সেসব লোক যারা আল্লাহর  আশীর্বাদপ্রাপ্ত?” আল্লাহ কি কৃতজ্ঞ ব্যক্তিদের সম্পর্কে অবগত নন?"],
  "6:54": ["And when those who believe in Our signs come to you, say: Peace be upon you. Your Rabb has written mercy upon the self, that whoever among you does wrong in ignorance, then turns back after it and sets right, then Allah is forgiving, merciful.", "যখন তারা তোমার কাছে আসে,যারা আমাদের প্রকাশনাবলি বিশ্বাস করে,তুমি বলবে,\"সালামুন আলাইকুম (আপনার উপর শান্তি বর্ষিত হোক)। এটা তোমার প্রভুর নিয়ম যে, দয়া করা তাঁর গুন। তাই, তোমাদের মধ্যে যেকেউ অজ্ঞতাবশত একটি সীমালঙ্ঘন করে,এবং এরপরে অনুশোচনা করে এবং সংশোধিত হয়, তবে তিনি ক্ষমাশীল, পরম দয়ালু। \""],
  "6:55": ["And thus We spell out the signs, and so the way of the guilty becomes clear.", "আমরা এভাবে প্রকাশনাবলি ব্যাখ্যা করি,আর পাপীদের পথগুলো দেখিয়ে দেই।"],
  "6:56": ["Say: I am forbidden to serve those you call upon besides Allah. Say: I will not follow your desires; then I would be astray, and not of the guided.", "বল, “তোমরা আল্লাহর পাশে যার উপাসনা করো আমাকে তার উপাসনা করতে নিষেধ করা হয়”। বল, “আমি তোমাদের মতের অনুসরণ করবো না। অন্যথায়, আমি বিপথে যাব, এবং পথপ্রাপ্ত হবো না”।"],
  "6:57": ["Say: I am upon clear proof from my Rabb, and you have denied it. I do not have what you hurry toward. The decision belongs only to Allah; Allah speaks the truth and is the best of deciders.", "বল, “আমার কাছে আমার প্রভুর পক্ষ থেকে দৃঢ় প্রমান আছে,এবং তোমরা তা প্রত্যাক্ষান করেছ। তোমরা আমাকে যে শাস্তি আনতে চ্যালেঞ্জ করো, সে শাস্তির নিয়ন্ত্রন আমি করি না। বিচার একমাত্র আল্লাহর অধীনে। তিনি সত্য বর্ণনা করেন, এবং তিনি সর্বোত্তম বিচারক।"],
  "6:58": ["Say: If I had what you hurry toward, the matter between me and you would already be decided. And Allah knows best the unjust.", "বল, “ তোমরা আমাকে যে শাস্তি আনার চ্যালেঞ্জ করো আমি যদি সে শাস্তির নিয়ন্ত্রন করতাম, পুরো ব্যাপারটি বহু আগেই সমাপ্ত হতো। আল্লাহ সবচেয়ে ভালো জানেন কারা সেই পাপী”।"],
  "6:59": ["And with Allah are the keys of the unseen; none knows them but Allah. And Allah knows what is in the land and the sea; and no leaf falls but Allah knows it, and no grain in the darkness of the earth, nothing fresh nor dry, but it is in a clear record.", "তাঁর কাছে সকল রহস্যের চাবি আছে;তিনি ছাড়া সেগুলো কেউ জানে না। তিনি ভূমির উপরের এবং সাগরের ভেতরের সবকিছু জানেন। তাঁর জ্ঞানের বাইরে একটি পাতাও পড়ে না। না আছে মাটির গভীরে কোন শস্যকনা। না আছে কোন আদ্র বা শুকনো কিছু,যা একটি প্রগাঢ় নথিতে নথিভুক্ত নেই।"],
  "6:60": ["And Allah is the one who takes you in death by night, and knows what you do by day, then raises you in it, so that a fixed term may be fulfilled. Then to Allah is your return; then Allah will inform you of what you used to do.", "তিনিই সে সত্ত্বা যিনি তোমাদেরকে রাতের বেলায় মৃত করেন, এবং দিনের বেলায় তোমাদের করা ক্ষুদ্রতম কাজগুলোও জানেন। তিনি প্রত্যেক সকালে তোমাদের পুনুরুত্থিত করেন, যতক্ষণ না তোমাদের জীবনকাল পূর্ণ হয়, এরপর তার কাছে তোমাদের চুড়ান্ত প্রত্যাবর্তন। তখন তিনি তোমাদের সবকিছু জানাবেন যা তোমরা করেছিলে।"],
  "6:61": ["And Allah is the overpowering above the servants, and sends guardians over you, until when death comes to one of you, Our rusul take the soul, and they never fall short.", "তিনি তাঁর সৃষ্টিজগতের  উপর সর্বপ্রধান, এবং তিনি তোমাদের রক্ষা করতে প্রহরী নিযুক্ত করেন। যখন মৃত্যুর নির্ধারিত সময় তোমাদের কারো কাছে আসে,আমাদের বার্তাবাহকেরা অনতিবিলম্বে তার মৃত্যু ঘটায়।"],
  "6:62": ["Then they are returned to Allah, their true protector. Indeed the judgment belongs to Allah alone, and Allah is the swiftest of reckoners.", "তাদের ন্যয়সঙ্গত প্রভু ও মনিব, আল্লাহর কাছে প্রত্যেকে এরপর ফিরে আসে। নি:সন্দেহে,তিনি চুড়ান্ত বিচারক;তিনি সবচেয়ে নির্ভুল হিসাব গ্রহনকারী।"],
  "6:63": ["Say: Who rescues you from the darkness of the land and the sea? You call upon Allah in humble pleading and in secret: If You rescue us from this, we will surely be among the shakirin.", "বল, \"স্থল বা সাগরের অন্ধকার থেকে কে তোমাদের রক্ষা করতে পারে?” তোমরা তাঁর কাছে মিনতি করো উচ্চস্বরে এবং গোপনে: \"যদি তিনি এবারের মতো আমাদের রক্ষা করেন, আমরা চিরদিন কৃতজ্ঞ থাকব।\""],
  "6:64": ["Say: Allah rescues you from it and from every distress; yet you join partners.", "বল, \"আল্লাহ এবারের মতো তোমাদের রক্ষা করেন, এবং সাথে সাথে অন্যবারও, তা সত্তেও তোমরা এরপরে তাঁর পাশে উপাস্যদের স্থাপন করো।\""],
  "6:65": ["Say: Allah is able to send upon you punishment from above you or from beneath your feet, or to divide you into parties and let some of you taste the violence of others. See how We vary the signs, so that they may understand.", "বল, \"তিনি নি:সন্দেহে তোমাদেরকে শাস্তি দিতে সক্ষম তোমাদের উপর থেকে,অথবা তোমাদের পায়ের নিচ থেকে। অথবা তিনি তোমাদেরকে দলে-উপদলে বিভক্ত করে একে অন্যের নিপীড়ন আস্বাদন করাতে পারেন। লক্ষ্য করো কিভাবে আমরা প্রকাশনাবলি ব্যাখ্যা করি,যাতে তারা বুঝতে পারে।\""],
  "6:66": ["And your people denied it, while it is the truth. Say: I am not a guardian over you.", "তোমার লোকেরা এটা প্রত্যাক্ষান করেছে,যদিও এটা সত্য। বল, “আমি তোমাদের অভিভাবক নই”"],
  "6:67": ["Every report has its appointed place, and soon you will know.", "এর মধ্যকার প্রত্যেকটি ভবিষ্যদ্বাণী ঘটবে,এবং তোমরা অবশ্যই দেখতে পাবে।"],
  "6:68": ["And when you see those who wade idly into Our signs, turn away from them until they wade into some other talk. And if the devil makes you forget, do not sit, after the reminder, with the unjust people.", "তুমি যদি তাদেরকে দেখ যারা আমাদের প্রকাশনাবলীকে উপহাস করে,তুমি তাদেরকে এড়িয়ে যাবে যতক্ষণ না তারা অন্য বিষয়ে প্রবৃত্ত হয়। যদি শয়তান তোমাকে ভুলিয়ে দেয়, এরপর, তোমার স্মরণ হওয়া মাত্র, এমন মন্দ লোকদের সাথে বসো না।"],
  "6:69": ["And nothing of their account is upon those who are mindful; but a reminder, so that they too may be mindful.", "ঐসব লোকদের কথার জন্য সৎকর্মশীলরা দায়ী নয়, তবে এটা তাদেরকে স্মরণ করিয়ে দিতে সাহায্য করতে পারে; হয়তো তারা রক্ষা পাবে ।"],
  "6:70": ["And leave those who took their religion as play and diversion, and whom the life of this world deceived. And remind with it, lest a soul be plunged in ruin for what it has earned, having, besides Allah, no protector and no intercessor; and though it offer every compensation, none will be taken from it. Those are the ones plunged in ruin for what they earned; for them is a drink of scalding water and a painful punishment, for what they used to deny.", "তুমি তাদেরকে উপেক্ষা করবে যারা তাদের ধর্মকে নিরর্থক নেয়, যেন এটি কোন সামাজিক অনুষ্ঠান, এবং এই দুনিয়ার জীবনে সম্পূর্ণ নিমগ্ন। স্মরণ করিয়ে দাও এই (কুরআন) দিয়ে,পাছে কোন আত্মা এর মন্দ অর্জনের পরিণাম ভোগ করতে পারে। প্রভু এবং মনিব হিসাবে আল্লাহর পাশে এর আর কেউ নেই, না কোন সুপারিশকারি। যদি এটি কোন প্রকারের মুক্তিপন প্রদান করতে চায়, তা গ্রহণ করা হবেনা। তারা ভোগ করে তাদের অর্জন করা মন্দ কাজের ফল;তারা অর্জন করেছে নারকীয় পানীয়, এবং এক যন্ত্রণাদায়ক শাস্তি তাদের অবিশ্বাসের কারনে।"],
  "6:71": ["Say: Shall we call upon, besides Allah, what can neither benefit nor harm us, and be turned back on our heels after Allah has guided us, like one whom the devils lure in the land, bewildered, who has companions calling to guidance, Come to us? Say: The guidance of Allah is the true guidance. And we are commanded to submit to the Rabb of the worlds.", "বল, \"আমরা কি তার কাছে মিনতি করবো,আল্লাহর পাশে, যার ক্ষমতা নেই আমাদের উপকার করার অথবা আমাদের ক্ষতি করার, এবং আল্লাহ আমাদের পথ দেখানোর পর আমরা পূর্বের অবস্থায় ফিরে যাব? সেক্ষেত্রে,আমরা তাদের সাথে যোগ দিবো যারা শয়তানদের দ্বারা আবিষ্ট, এবং একেবারে বিভ্রান্ত হয়ে পড়েছে,যখন তাদের বন্ধুরা তাদেরকে রক্ষা করার চেষ্টা করে বলে: “আমাদের সাথে সঠিক পথে থাকো।\" বলো,\"আল্লাহর পথ-প্রদর্শনই সঠিক। আমরা আদিষ্ট হই মহাবিশ্বের প্রভুর নিকট আত্মসমর্পণ করতে।"],
  "6:72": ["And to establish the prayer and be mindful of Allah; and it is to Allah you will be gathered.", "\"এবং সংযোগ প্রার্থনাসমূহ (সালাত) পালন করতে,এবং তাঁকে ভয়-শ্রদ্ধা করতে। তিনিই সে সত্ত্বা যাঁর সামনে তোমাদের ডাকা হবে (বিচারের জন্য)।\""],
  "6:73": ["And Allah is the one who created the heavens and the earth in truth. And the day Allah says Be, and it is. Allah's word is the truth, and to Allah belongs the kingdom the day the trumpet is blown. Knower of the unseen and the witnessed; and Allah is the Wise, the Aware.", "তিনিই সে সত্ত্বা যিনি আকাশমন্ডলী  ও পৃথিবী সৃষ্টি করেছিলেন, সত্যতার সাথে। যখনই তিনি বলেন, \"হও, ” তা হয়ে যায়। তাঁর বানী পরম সত্য। সে দিন সকল সার্বভৌমত্ব তাঁর, যখন শিঙ্গাঁয় ফুঁ দেয়া হয়। সকল গোপন ও প্রকাশ্য বিষয়ের জ্ঞাতা,তিনি পরম জ্ঞানী,জ্ঞাত।"],
  "6:74": ["And when Ibrahim said to his father Azar: Do you take idols as alihah? I see you and your people in clear error.", "স্মরণ করো যে ইব্রাহিম তার পিতা আযরকে বলেছিল, \"কেমন করে তুমি প্রতিমূর্তিগুলোকে উপাস্য হিসেবে উপাসনা করো? আমি দেখি যে তুমি এবং তোমার লোকেরা অনেক পথভ্রষ্ট হয়েছ।\""],
  "6:75": ["And thus We showed Ibrahim the kingdom of the heavens and the earth, so that he might be of those certain.", "আমরা ইব্রাহীমকে আকাশমন্ডলী ও পৃথিবীর বিস্ময়সমূহ দেখিয়েছিলাম, এবং তাকে নিশ্চিতভাবে ধন্য করেছিলাম।"],
  "6:76": ["So when night fell over him, he saw a star and said: This is my Rabb. But when it set, he said: I do not love the setting ones.", "যখন রাত নেমেছিল, সে একটি জ্বলজ্বলে গ্রহ দেখলো। “হতে পারে এটি আমার প্রভু,” সে বলেছিল। যখন এটি অদৃশ্য হলো,সে বললো, “আমি পছন্দ করি না (উপাস্যদের) যারা অদৃশ্য হয়ে যায়”।"],
  "6:77": ["Then when he saw the moon rising, he said: This is my Rabb. But when it set, he said: If my Rabb does not guide me, I will surely be of the dallin people.", "যখন সে চাঁদকে উদীয়মান দেখেছিল, সে বলেছিল, “হতে পারে এটাই আমার প্রভু!”যখন এটি অদৃশ্য হয়েছিল, সে বলেছিল, “যদি না আমার প্রভু আমাকে পথপ্রদর্শন করেন, আমি পথভ্রষ্টদের আন্তরগত হবো”।"],
  "6:78": ["Then when he saw the sun rising, he said: This is my Rabb; this is greater. But when it set, he said: O my people, I am clear of what you join as partners.", "যখন সে সূর্যকে উদীয়মান দেখেছিল, সে বলেছিল, “এটি অবশ্যই আমার প্রভু হবে। এটাই সবচেয়ে বড়”। কিন্তু যখন এটি অস্ত গেল, সে বলেছিল, “হে আমার লোকেরা,আমি তোমাদের শিরককে নিন্দা করি।"],
  "6:79": ["Indeed I have set my face, upright, to the one who originated the heavens and the earth, and I am not of those who join partners.", "“আমি আমার নিজেকে পুরোপুরি উৎসর্গ করেছি সে সত্ত্বার কাছে যিনি আকাশমন্ডলী ও পৃথিবীর সূচনা করেছিলেন; আমি কখনো একজন প্রতিমা উপাসক হবো না”।"],
  "6:80": ["And his people disputed with him. He said: Do you dispute with me about Allah, when Allah has guided me? I do not fear what you join with Allah, unless my Rabb wills something. My Rabb's knowledge encompasses all things. Will you not then remember?", "তার লোকেরা তার সাথে তর্ক করেছিল। সে বলেছিল, “তোমরা কি আমার সাথে আল্লাহ সম্পর্কে তর্ক করো,তিনি আমাকে পথপ্রদর্শনের পর? তোমাদের স্থাপন করা উপাস্যদের আমি ভয় করি না। আমার কিছুই হতে পারে না,যদি না আমার প্রভু তা ইচ্ছা করেন। আমার প্রভুর জ্ঞান সবকিছু পরিবেষ্টন করে আছে। তোমরা কি সতর্ক হবে না?”"],
  "6:81": ["And how should I fear what you have joined, when you do not fear joining with Allah what Allah has sent down no warrant for upon you? So which of the two parties has more right to security, if you know?", "\"আমার কেন তোমাদের অংশীদারদের ভয় পাওয়া উচিত? তোমাদেরই তো ভয় পাওয়া উচিত, যেহেতু তোমরা আল্লাহর পরিবর্তে অংশীদারদের উপাসনা করো যেগুলো তোমাদেরকে সাহায্য করতে একদম ক্ষমতাহীন। কোন দল নিরাপত্তা পাবার অধিক যোগ্য, যদি তোমরা জানতে?\""],
  "6:82": ["Those who believe and do not clothe their belief with injustice, those have security, and they are the guided.", "যারা বিশ্বাস করে,এবং তাদের বিশ্বাসকে অংশীদার উপাসনা দ্বারা কলূষিত করে না,তারা নিশ্ছিদ্র নিরাপত্তা পাবার যোগ্য, এবং তারা সত্যিকারের পথ-প্রদর্শিত।"],
  "6:83": ["And that was Our proof, which We gave Ibrahim against his people. We raise in degree whomever We will. Indeed your Rabb is wise, knowing.", "এরকমই ছিল আমাদের যুক্তি,যা দিয়ে আমরা ইব্রাহীমকে তার লোকদের বিপক্ষে সমর্থন করেছিলাম। আমরা উচ্চতর পদসমূহে অধিষ্ঠিত করি,যাকেই আমরা চাই। তোমার প্রভু সবচেয়ে জ্ঞানী,সর্বজ্ঞ।"],
  "6:84": ["And We granted him Ishaq and Ya'qub, each We guided. And Nuh We guided before. And among his descendants: Dawud, Sulaiman, Ayyub, Yusuf, Musa and Harun. And thus We repay the doers of good.", "\"এবং আমরা তাকে দিয়েছিলাম ইসহাক ও ইয়াকুব, এবং আমরা তাদের উভয়কে পথ-প্রদর্শন করেছিলাম। একইভাবে,আমরা এর আগে নুহকে পথ-প্রদর্শন করেছিলাম, এবং তার বংশধরদের থেকে (আমরা পথ-প্রদর্শন করেছিলাম) দাউদ, সোলাইমান, আইয়ুব,"],
  "6:85": ["And Zakaria, Yahya, Isa and Ilyas, each was of the salihin.", "এছাড়াও, জাকারিয়া,ইয়াহিয়া,ঈসা,এবং ইলিয়াস;সকলে ছিল সৎকর্মশীল।"],
  "6:86": ["And Ismail, Al-Yasa', Yunus and Lut, and each We favored over the worlds.", "এবং ইসমাইল, আল-ইয়াসা,ইউনুস ও লুত;এদের প্রত্যেককে আমরা সকল অন্য লোকদের থেকে আলাদা করেছিলাম।"],
  "6:87": ["And among their fathers, and their descendants, and their brothers, We chose them and guided them to a straight path.", "তাদের পূর্বপুরুষ, তাদের বংশধর, এবং তাদের সহোদরদের মধ্যে থেকে আমরা অনেককে পছন্দ করেছিলাম, এবং আমরা তাদেরকে একটি সরল পথ প্রদর্শন করেছিলাম।"],
  "6:88": ["That is the guidance of Allah; by it Allah guides whomever Allah wills of the servants. And had they joined partners, all they used to do would be voided from them.", "এমনই আল্লাহর পথনির্দেশনা,যা দিয়ে তিনি পথপ্রদর্শন করেন তাঁর দাসদের মধ্যে থেকে যাকে তিনি পছন্দ করেন। তাদের কেউ যদি শিরকীত্বে পতিত হতো,তাদের কাজগুলো বাতিল হয়ে  যেতো।"],
  "6:89": ["Those are the ones to whom We gave the Book, and the judgment, and the Nabihood. So if these disbelieve in it, We have already entrusted it to a people who do not disbelieve in it.", "তারাই ছিল সে লোক যাদেরকে আমরা ঐশীগ্রন্থ, প্রজ্ঞা এবং নবুওয়ত দিয়েছিলাম।  যদি এইসব লোকেরা অবিশ্বাস করে,আমরা তাদের স্থানে অন্যদের প্রতিস্থাপিত করবো,এবং নতুন লোকেরা অবিশ্বাসী হবে না।"],
  "6:90": ["Those are the ones whom Allah guided; so follow their guidance. Say: I ask of you no wage for it. It is nothing but a reminder for the worlds.", "এরাই হলো আল্লাহর দ্বারা পথপ্রদর্শিত; তোমরা তাদের পদচিহ্ন অনুসরণ করবে। বল, “আমি তোমাদের কাছে কোন পারিশ্রমিক চাই না। এটা সকল লোকদের জন্যে একটি বার্তা মাত্র।"],
  "6:91": ["They did not value Allah with the valuation due, when they said: Allah has sent down nothing to a human being. Say: Who sent down the Book that Musa brought, a light and guidance for the people, which you make into papers you show openly and conceal much of? And you were taught what you did not know, neither you nor your fathers. Say: Allah. Then leave them in their idle wading, playing.", "তারা কখনো আল্লাহকে মূল্য দেয়নি যেমন তাঁকে মূল্য দেয়া উচিত। তাই, তারা বলেছিল, \"আল্লাহ কোন মানুষের কাছে কোনকিছু প্রকাশ করেন না।\" বল, \"কে তাহলে সে ঐশীগ্রন্থ প্রকাশ করেছিলেন যা মুসা এনেছিল, লোকদের জন্য আলো এবং পথ-প্রদর্শন নিয়ে?\" তোমরা কাগজে লিখে রাখো তার কিছু ঘোষনা করতে,যখন এর অনেক কিছুই গোপন করো। তোমাদের শেখানো হয়েছিল যা তোমরা কখনো জানতে না- তোমাদের এবং তোমাদের পিতা-মাতাদের। বল, \"আল্লাহই (সে সত্ত্বা যিনি এটা প্রকাশ করেছিলেন),”এরপর তাদেরকে তাদের অমনোযোগিতায় ছেড়ে দেন, খেলাছলে।"],
  "6:92": ["And this is a blessed Book We have sent down, confirming what is before it, and to warn the mother of towns and those around it. And those who believe in the hereafter believe in it, and they keep watch over their prayers.", "এটিও একটি পবিত্র ঐশীগ্রন্থ যা আমরা প্রকাশ করেছি,যা পূর্ববর্তী ঐশীগ্রন্থসমূহ নিশ্চিত করছে,যাতে তুমি সতর্ক করতে পারো সবচেয়ে গুরুত্বপূর্ণ সম্প্রদায়কে এবং এর চারপাশের সকলকে। যারা পরকালে বিশ্বাস করে তারা এই (ঐশীগ্রন্থে) বিশ্বাস করবে,এবং সংযোগ প্রার্থনাসমূহ (সালাত) পালন করবে।"],
  "6:93": ["And who is more unjust than one who fabricates a lie against Allah, or says: It was revealed to me, when nothing was revealed to them, or says: I will send down the like of what Allah sent down? If only you could see when the unjust are in the throes of death, and the malakat stretch out their hands: Bring out your souls. Today you are repaid the humiliating punishment for what you used to say about Allah other than the truth, and you were arrogant toward Allah's signs.", "তার চেয়ে কে বেশি মন্দ যে মিথ্যা উদ্ভাবন করে এবং সেগুলো আল্লাহর প্রতি আরোপ করে,অথবা বলে,\"আমি ঐশ্বরিক অনুপ্রেরণা পেয়েছি,” যখন এরকম কোন অনুপ্রেরণা তাকে দেয়া হয়নি,অথবা বলে,\"আমি আল্লাহর প্রকাশনাবলির মতো লিখতে পারি\"? যদি শুধু তুমি সীমালঙ্ঘনকারীদের দেখতে পেতে মৃত্যুর সময়! ফেরেশতারা তাদের নিকট হাত বাড়ায়, এই বলে যে,\"তোমাদের আত্মাগুলোকে যেতে দাও। আজ, তোমরা আল্লাহ সম্পর্কে সত্য ব্যতীত অন্যকিছু বলে,এবং তাঁর প্রকাশনাবলি গ্রহন করতে অত্যধিক উদ্ধত হয়ে এক লজ্জাকর শাস্তি টেনে এনেছ।"],
  "6:94": ["You have come to Us one by one, as We created you the first time, and you have left behind your backs what We bestowed on you. And We do not see with you your intercessors whom you claimed were partners to you. The bond between you has been cut off, and what you used to claim has strayed from you.", "\"তোমরা আমাদের কাছে ফিরে এসেছো একাকী,ঠিক যেরকম আমরা তোমাদের প্রথমবার সৃষ্টি করেছিলাম, এবং তোমরা পিছনে ফেলে এসেছ যা আমরা তোমাদের জন্য দিয়েছিলাম। আমরা তোমাদের সাথে সুপারিশকারীদের দেখি না যাদের তোমরা উপাস্যসম করেছিলে এবং দাবী করেছিলে যে তারা তোমাদের সাহায্য করবে। তোমাদের মধ্যকার সকল বাঁধন ছিন্ন হয়েছে; তোমাদের স্থাপন করা উপাস্যরা তোমাদের পরিত্যাগ করেছে।\""],
  "6:95": ["Indeed Allah splits the grain and the kernel, bringing forth the living from the dead, and bringing forth the dead from the living. That is Allah; so how are you turned away?", "আল্লাহই সে সত্ত্বা যিনি শস্যকণা ও বীজগুলোতে ফাটল এবং অঙ্কুরোদ্গম ঘটান। তিনি মৃত থেকে জীবিতকে,এবং জীবিত থেকে মৃতকে উৎপন্ন করেন। এমনই আল্লাহ;কিভাবে তোমরা বিচ্যুত হতে পারো!"],
  "6:96": ["The splitter of the daybreak, and maker of the night as rest, and the sun and the moon as a reckoning. That is the ordaining of the Mighty, the Knowing.", "দিনের সূচনায়, তিনি প্রভাত আবির্ভূত হতে দেন। তিনি রাতকে করেছেন প্রশান্ত, এবং তিনি সূর্য ও চাঁদকে গননা যন্ত্র হিসেবে কাজ করতে নিয়োজিত করেছেন। সর্বশক্তিমান, সর্বজ্ঞের এমনই নকশা।"],
  "6:97": ["And Allah is the one who made for you the stars, so that you may be guided by them through the darkness of the land and the sea. We have spelled out the signs for people who know.", "এবং তিনিই সে সত্ত্বা যিনি তৈরি করেছিলেন নক্ষত্ররাজি অন্ধকারে তোমাদেরকে পথ দেখাতে, স্থলে এবং সাগরে। আমরা এভাবে লোকদের জন্য প্রকাশনাবলী সুস্পষ্ট করি,যারা জানে।"],
  "6:98": ["And Allah is the one who raised you from a single soul; then a lodging and a depository. We have spelled out the signs for people who understand.", "তিনি তোমাদের সূচনা করেছেন এক ব্যক্তি থেকে,এবং নির্ধারণ করেছেন তোমাদের পথ, সেই সাথে তোমাদের চূড়ান্ত নিয়তি। আমরা এভাবে লোকদের জন্য প্রকাশনাবলী সুস্পষ্ট করি,যারা বুঝে।"],
  "6:99": ["And Allah is the one who sends down water from the sky, and with it We bring forth growth of every kind; We bring forth from it greenery, from which We bring forth grain stacked in layers, and from the palm, from its spathe, hanging clusters near at hand, and gardens of grapes, and the olive and the pomegranate, alike and unlike. Look at its fruit when it bears fruit and ripens. Indeed in that are signs for people who believe.", "তিনিই সে সত্ত্বা যিনি আকাশ থেকে পানি বর্ষণ করেন, যার দ্বারা আমরা সকল প্রকার উদ্ভিদ জন্মাই। আমরা সবুজ অংশ থেকে উৎপন্ন করি জটিল শস্যের সমাহার, ঝুলন্ত থোকা বিশিষ্ট খেঁজুর গাছ, এবং আঙুরের বাগান, জলপাই এবং আনার; ফল যেগুলো সাদৃশ্যযুক্ত, তথাপি সাদৃশ্যহীন। লক্ষ্য করো সেগুলোর ফল যখন তারা বড় হয় এবং পরিপক্ক হয়। এগুলো লোকদের জন্য নিদর্শন যারা বিশ্বাস করে।"],
  "6:100": ["Yet they made for Allah partners, the jinn, though Allah created them. And they fabricated for Allah sons and daughters without knowledge. Glory be to Allah, and exalted above what they describe.", "এরপরও, তারা আল্লাহর পাশে অংশীদারদের স্থাপন করে জীনদের মধ্যে থেকে,যদিও তিনিই সে সত্ত্বা যিনি তাদের সৃষ্টি করেছিলেন। তারা এমনকি পুত্র ও কন্যা থাকাকে তাঁর গুন হিসেবে চালায়, কোন জ্ঞান ছাড়াই। মহিমা তো তাঁরই। তিনি সর্বাধিক উচ্চ, তাদের দাবীর অনেক উর্ধ্বে।"],
  "6:101": ["Originator of the heavens and the earth, how could there be a child when there is no companion? And Allah created all things, and Allah is knowing of all things.", "আকাশমন্ডলী ও পৃথিবীর সূচনাকারী। কি করে তাঁর কোন পুত্র থাকতে পারে,যখন তাঁর কখনো কোন সঙ্গী ছিল না? তিনি সবকিছু সৃষ্টি করেছিলেন, এবং তিনি সবকিছু সম্পর্কে সম্পূর্ন সচেতন।"],
  "6:102": ["That is Allah, your Rabb; there is no ilah but Allah. Creator of all things, so serve Allah. And Allah is guardian over all things.", "এরকমই তোমাদের প্রভু আল্লাহ, তিনি ছাড়া কোন উপাস্য নেই, সবকিছুর সৃষ্টিকর্তা। তোমরা একমাত্র তাঁরই উপাসনা করবে। তিনি সবকিছুর নিয়ন্ত্রন করেন।"],
  "6:103": ["Sights do not overtake Allah, yet Allah overtakes the sights; and Allah is the subtle, the aware.", "কোন দৃষ্টি তাকে পরিবেষ্টন করতে পারে না,কিন্তু তিনি সকল দৃষ্টি পরিবেষ্টন করেন। তিনি করুনাময়, জ্ঞাত।"],
  "6:104": ["Clear insights have come to you from your Rabb. So whoever sees, it is for the self; and whoever is unseeing, it is upon it. And I am not a keeper over you.", "তোমাদের প্রভুর কাছ থেকে তোমাদের কাছে জ্ঞানালোক এসেছে। যারা দেখতে পারে তাদের ক্ষেত্রে,তারা তাদের নিজের ভালোর জন্যই দেখে,এবং যারা অন্ধত্বে ফিরে যায়, তারা তাদের নিজের ক্ষতির জন্যই তা করে। আমি তোমাদের অভিভাবক নই।"],
  "6:105": ["And thus We vary the signs, so that they say: You have merely studied; and so that We may make it clear to people who know.", "আমরা এভাবে প্রকাশনাবলি ব্যাখ্যা করি,প্রমান করতে যে, তোমরা জ্ঞান পেয়েছ, এবং সেগুলো লোকদের জন্য সুস্পষ্ট করতে,যারা জানে।"],
  "6:106": ["Follow what has been revealed to you from your Rabb; there is no ilah but Allah. And turn away from those who join partners.", "অনুসরণ করো যা তোমার প্রভুর পক্ষ থেকে তোমার কাছে প্রকাশ করা হয়, তিনি ব্যতিত কোন উপাস্য নেই, এবং প্রতিমা উপাসকদের উপেক্ষা করো।"],
  "6:107": ["Had Allah willed, they would not have joined partners. And We have not made you a keeper over them, nor are you a guardian over them.", "আল্লাহ যদি চাইতেন, তারা অংশীদার উপাসনা করতো না। আমরা তোমাকে তাদের অভিভাবক নিযুক্ত করিনি,না তুমি তদের উকিল।"],
  "6:108": ["And do not insult those they call upon besides Allah, lest they insult Allah in enmity without knowledge. Thus We have made fair to every nation their deeds; then to their Rabb is their return, and Allah will inform them of what they used to do.", "আল্লাহর পাশে তাদের স্থাপন করা অংশীদারদের অভিশাপ দিওনা,পাছে তারা অজ্ঞতাবশত আল্লাহকে গালমন্দ করবে এবং অভিশাপ দেবে। আমরা প্রত্যেক দলের কাজকে তাদের চোখে সুশোভিত করে দিয়েছি। অবশেষে,তারা তাদের প্রভুর কাছে ফিরে যায়, তখন তিনি তাদেরকে জানান সবকিছু যা তারা করেছিল।"],
  "6:109": ["And they swore by Allah with their utmost oaths that if a sign came to them they would surely believe in it. Say: The signs are only with Allah. And what will make you perceive that when they come, they will not believe?", "তারা আল্লাহর নামে শপথ করেছিল, দৃড়ভাবে যে, যদি একটি অলৌকিকতা তাদের কাছে আসতো,তারা অবশ্যই বিশ্বাস করতো। বল, “অলৌকিকতা শুধু আল্লাহ থেকে আসে”। যতদূর তোমরা জানো,যদি একটি অলৌকিকতা তাদের কাছে আসত, তারা অবিশ্বাসই রইতো”।"],
  "6:110": ["And We turn their hearts and their sights, as they did not believe in it the first time, and We leave them in their transgression, wandering blindly.", "আমরা তাদের মন এবং তাদের হৃদয় নিয়ন্ত্রন করি। এভাবে,যেহেতু অবিশ্বাস করাই তাদের সিদ্ধান্ত, আমরা তাদেরকে তাদের সীমালঙ্ঘনে, বিভ্রান্তিতে ছেড়ে দেই।"],
  "6:111": ["And even if We sent the malakat down to them, and the dead spoke to them, and We mustered all things before them, they would not believe unless Allah wills; yet most of them are ignorant.", "এমনকি যদি আমরা তাদের নিকট ফেরেশতাদের পাঠাতাম; এমনকি যদি মৃতরা তাদের সাথে কথা বলত; এমনকি যদি তাদের সামনে আমরা প্রত্যেক অলৌকিকতা একত্রিত করতাম; তারা বিশ্বাস করতে পারে না যদি না আল্লাহ তা ইচ্ছা করেন। প্রকৃতপক্ষে,তাদের বেশির ভাগই অজ্ঞ।"],
  "6:112": ["And thus We have made for every Nabi an enemy, devils of humankind and jinn, inspiring one another with varnished speech, by way of deception. And had your Rabb willed, they would not have done it. So leave them and what they fabricate.", "আমরা অনুমোদন দিয়েছি প্রত্যেক নবীর শত্রু- মানুষ এবং জীন শয়তানদের- একে অন্যকে কল্পিত কথা দিয়ে অনুপ্রানিত করতে,প্রতারিত করার জন্য। যদি তোমার প্রভু ইচ্ছা করতেন, তারা এটা করত না। তুমি তাদেরকে এবং তাদের মিথ্যা উদ্ভাবনসমূহকে উপেক্ষা করবে।"],
  "6:113": ["And so the hearts of those who do not believe in the hereafter may incline to it and be pleased with it, and may keep committing what they are committing.", "এটা একারনে যে, যারা পরকালে বিশ্বাস করে না, তাদের মনকে এরকম মিথ্যা উদ্ভাবন শুনানো,এবং সেগুলো গ্রহন করানো,এবং এভাবে তাদের প্রকৃত অভিপ্রায়কে প্রকাশ করানো হয়।"],
  "6:114": ["Shall I seek a judge other than Allah, when Allah is the one who sent down to you the Book spelled out? And those to whom We gave the Book know that it is sent down from your Rabb in truth. So never be of the doubters.", "আমি কি আল্লাহ ছাড়া অন্য কাউকে আইনের উৎস হিসেবে খুজঁবো,যখন তিনি তোমাদের কাছে এই গ্রন্থ পূর্ণ বিস্তারিতরুপে প্রকাশ করেছেন? যারা এই ঐশীগ্রন্থ গ্রহন করেছিল, তারা চিনতে পারে যে,এটি তোমার প্রভুর কাছ থেকে প্রকাশিত হয়েছে,সত্যতার সাথে। তোমরা কোন সন্দেহ পোষন করবে না।"],
  "6:115": ["And the word of your Rabb is complete, in truth and justice; none can change Allah's words. And Allah is the All-Hearing, the All-Knowing.", "তোমার প্রভুর বানী পরিপূর্ণ, সত্যে এবং সুবিচারে। কোন কিছুই তাঁর বানী রহিত করবে না। তিনি শ্রবণকারী,সর্বজ্ঞ।"],
  "6:116": ["And if you obey most of those on the earth, they will lead you astray from Allah's path. They follow only conjecture, and they do nothing but guess.", "যদি তুমি পৃথিবীর বেশিরভাগ মানুষকে মান্য করো,তারা তোমাকে আল্লাহর পথ থেকে সরিয়ে দেবে। তারা শুধু মিথ্যা ধারনার অনুসরন করে; তারা শুধু অনুমান করে।"],
  "6:117": ["Indeed your Rabb knows best who strays from the path, and knows best the guided.", "তোমার প্রভু তাদের ব্যাপারে সম্পূর্ণ সচেতন  যারা তাঁর পথ থেকে বিপথগামী হয়, এবং তিনি তাদের ব্যপারে সম্পূর্ণ অবগত, যারা সুপথপ্রাপ্ত।"],
  "6:118": ["So eat of that over which the name of Allah has been mentioned, if you are muminin in Allah's signs.", "তুমি খাবে তা থেকে, যেটার উপর আল্লাহর নাম উচ্চারণ করা হয়েছে,যদি তুমি সত্যই তাঁর প্রকাশনাবলিতে বিশ্বাস করো।"],
  "6:119": ["And what is it with you that you do not eat of that over which the name of Allah has been mentioned, when Allah has spelled out for you what is forbidden to you, unless you are compelled to it? Indeed many lead astray by their desires, without knowledge. Indeed your Rabb knows best the transgressors.", "কেন তোমারা খাবেনা তা থেকে, যাতে আল্লাহর নাম উচ্চারণ করা হয়েছে? তিনি তোমাদের জন্য বিশদ বর্ণনা করেছেন যা তোমাদের জন্য নিষিদ্ধ, যদি না তোমাদেরকে জোর করা হয়। প্রকৃতপক্ষে, অনেক লোক অন্যদের বিপথগামী করে তাদের ব্যক্তিগত মতামত দিয়ে, জ্ঞান ছাড়াই। তোমার প্রভু সীমাতিক্রমকারীদের ব্যাপারে পূর্ণ অবগত।"],
  "6:120": ["And leave the outward and the inward of sin. Indeed those who earn sin will be repaid for what they used to commit.", "তোমরা প্রকাশ্য পাপ পরিহার করবে,সেই সাথে গোপনগুলো। যারা পাপ উপার্জন করেছে,তারা অবশ্যই তাদের সীমাতিক্রমের জন্য মূল্য দেবে।"],
  "6:121": ["And do not eat of that over which the name of Allah has not been mentioned, for indeed it is transgression. And indeed the devils inspire their allies to dispute with you. And if you obey them, you are indeed those who join partners.", "আল্লাহর নাম যেটাতে নেয়া হয়নি তা থেকে খেও না,কারণ এটি অত্যন্ত ঘৃণ্য কাজ। তোমাদের সাথে তর্ক করতে শয়তানরা তাদের মিত্রদের অনুপ্রানিত করে;যদি তোমরা তাদের মান্য করো,তোমরা প্রতিমা উপাসক হবে।"],
  "6:122": ["Is one who was dead, and We gave life, and made a light by which to walk among people, like one whose likeness is in darkness, with no way out of it? Thus has been made fair to the kafirin what they used to do.", "যে লোক ছিল মৃত, তারপর আমরা তাকে জীবন দিলাম, এবং তাকে আলো দিলাম, যা লোকদের মাঝে তাকে চলতে সক্ষম করে, কি সেই লোকের সমান যে সম্পূর্ন অন্ধকারে রয়েছে যা থেকে সে কখনো বের হতে পারে না? অবিশ্বাসীদের কাজগুলোকে এভাবেই তাদের চোখে সুসজ্জিত করা হয়।"],
  "6:123": ["And thus We have made in every town the greatest of its mujrimin, so that they scheme there. Yet they scheme only against themselves, and they do not perceive.", "আমরা প্রত্যেক সম্প্রদায়ের নেতৃত্বস্থানীয় অপরাধীদেরকে চক্রান্ত এবং পরিকল্পনা করতে দেই। কিন্তু তারা কেবল তাদের নিজেদের আত্মার বিরুদ্ধে চক্রান্ত এবং পরিকল্পনা করে,অনুধাবন না করে।"],
  "6:124": ["And when a sign comes to them, they say: We will not believe until we are given the like of what was given to the rusul of Allah. Allah knows best where to place the message. Humiliation before Allah and a severe punishment will strike those who commit crimes, for what they used to scheme.", "যখন একটি শক্তিশালী প্রমান তাদের কাছে আসে,তারা বলে,\"আমরা বিশ্বাস করবো না,যদি না আমাদের তা দেয়া হয় যা আল্লাহর বার্তাবাহকদের দেয়া হয়!”আল্লাহ যথাযথভাবে জানেন, কে তাঁর বার্তা পৌঁছে দিতে সর্বোত্তম যোগ্য। এরকম অপরাধীরা তাদের মন্দ পরিকল্পনার একটি ফল হিসেবে আল্লাহর কাছে লাঞ্চনা,এবং ভয়ানক শাস্তি ভোগ করবে।"],
  "6:125": ["So whomever Allah wills to guide, Allah opens the chest to submission; and whomever Allah wills to leave astray, Allah makes the chest tight and constricted, as if climbing up into the sky. Thus does Allah place filth upon those who do not believe.", "যাকেই আল্লাহ পথ-প্রদর্শন করতে চান, তিনি তার বক্ষকে আত্মসমর্পণে সুপ্রসারিত উন্মুক্ত করেন। এবং যাকেই তিনি পথভ্রষ্ট করতে চান, তিনি তার বক্ষকে অসহিষ্ণু এবং সংকীর্ণ করেন, সে লোকের মতো যে আকাশের দিকে আরোহন করে। আল্লাহ এভাবে তাদের উপর অভিশাপ ন্যস্ত করেন, যারা বিশ্বাস করতে অসম্মত।"],
  "6:126": ["And this is the straight path of your Rabb. We have spelled out the signs for people who remember.", "এটাই তোমার প্রভুর দিকে সরল পথ। আমরা প্রকাশনাবলি ব্যাখ্যা করেছি লোকদের জন্য যারা মনোযোগী হয়।"],
  "6:127": ["Theirs is the home of peace, with their Rabb; and Allah is their protector for what they used to do.", "তারা তাদের প্রভুর কাছে শান্তিময় আবাসের যোগ্য; তিনি তাদের প্রভু এবং মনিব, তাদের কাজের পুরুস্কার হিসাবে।"],
  "6:128": ["And the day Allah gathers them all: O assembly of jinn, you have taken much among humankind. And their allies from humankind say: Our Rabb, we took enjoyment in one another, and we reached our term which You appointed for us. Allah says: The Fire is your lodging, to abide in it forever, except what Allah wills. Indeed your Rabb is wise, knowing.", "সেদিন আসবে যখন তিনি তাদের সকলকে ডাকেন (এবং বলেন) “হে তোমরা জীন, তোমরা বহুসংখ্যক মানুষকে দাবী করেছ”। তাদের মানব সঙ্গীরা বলবে,“আমাদের প্রভু,আমরা একে অন্যের সঙ্গ উপভোগ করেছিলাম, যতক্ষণ না আমরা সে জীবনকাল অপচয় করেছিলাম যা আপনি আমাদের জন্য স্থির করেছিলেন”।  তিনি বলবেন, “তোমাদের নিয়তি নরক”। তারা সেখানে চিরকাল বাস করে,আল্লাহর ইচ্ছা অনুযায়ী। তোমার প্রভু বিজ্ঞ, সর্বজ্ঞ।"],
  "6:129": ["And thus We make some of the unjust prevail over others, for what they used to earn.", "আমরা এভাবে একে অন্যের সঙ্গী হিসেবে পাপীদের মিলিয়ে দেই, তাদের সীমাতিক্রমের শাস্তি হিসাবে।"],
  "6:130": ["O assembly of jinn and humankind, did rusul not come to you from among you, recounting My signs to you and warning you of the meeting of this day of yours? They say: We bear witness against ourselves. The life of this world deceived them, and they bore witness against themselves that they were deniers.", "হে তোমরা জীন ও মানুষ, তোমরা কি তোমাদের মধ্য থেকে বার্তাবাহকদের পাওনি, যারা তোমাদের কাছে আমার প্রকাশনাবলি বর্ণনা করেছিল, এবং এই দিনের সাক্ষাতের ব্যাপারে তোমাদের সতর্ক করেছিল? তারা বলবে, “আমরা আমাদের নিজেদের বিরুদ্ধে সাক্ষী দেই”। তারা দুনিয়ার জীবন নিয়ে সম্পূর্ণ আচ্ছন্ন ছিল, এবং তারা তাদের নিজেদের বিরুদ্ধে সাক্ষী দেবে যে তারা অবিশ্বাসী ছিল।"],
  "6:131": ["That is because your Rabb would never destroy towns unjustly while their people were unmindful.", "এটি দেখাতে যে তোমাদের প্রভু কখনো কোন সম্প্রদায়কে অন্যায়ভাবে ধংস করেন না,যখন এর লোকেরা অনবগত।"],
  "6:132": ["And for each is a degree according to what they did; and your Rabb is not unmindful of what they do.", "প্রত্যেকেই তাদের কর্মের সমানুপাতিক পদমর্যাদা অর্জন করবে। তোমাদের প্রভু কখনো অনবগত নন, যা কিছু তারা করে।"],
  "6:133": ["And your Rabb is the Self-Sufficient, possessor of mercy. If Allah wills, Allah can remove you and bring successors after you, just as Allah raised you from the offspring of other people.", "তোমাদের প্রভুই একমাত্র স্ব-সমৃদ্ধ; সকল করুনার অধিকারী। যদি তিনি চান, তিনি তোমাদের সরিয়ে দিতে, এবং তোমাদের জায়গায় যাকে ইচ্ছা প্রতিস্থাপন করতে পারেন, ঠিক যেমন তিনি তোমাদেরকে অন্য লোকদের বংশধর থেকে বানিয়েছিলেন।"],
  "6:134": ["Indeed what you are promised is coming, and you cannot escape.", "যা তোমাদেরকে অঙ্গীকার করা হয় তা ঘটবে,এবং তোমরা কখনো তা এড়াতে পার না।"],
  "6:135": ["Say: O my people, work according to your standing; I too am working. Soon you will know to whom the final home belongs. Indeed the unjust do not attain success.", "বল, \"হে আমার লোকেরা , তোমাদের সেরাটা করো, এবং আমিও তা-ই করবো। তোমরা অবশ্যই জানতে পারবে কারা চুড়ান্ত বিজয়ী।” নিশ্চিতভাবে, মন্দরা কখনো সফল হবে না।"],
  "6:136": ["And they assign to Allah a portion of what Allah spread forth of tillage and livestock, and say by their claim: This is for Allah, and this is for our partners. But what is for their partners never reaches Allah, and what is for Allah reaches their partners. Evil is what they judge.", "তারা এমনকি আল্লাহর দেয়া শস্য এবং গবাদিপশুর একটি অংশ সরিয়ে রাখে, এই বলে, “এই অংশ আল্লাহর, ” , “এবং এই অংশ আমাদের উপাস্যদের”, তাদের দাবী অনুসারে। কিন্তু, যা তাদের উপাস্যদের জন্য সরিয়ে রেখেছিল তা কখনো আল্লাহর কাছে পৌঁছেনি, যখন আল্লাহর জন্য সরিয়ে রাখা অংশ সবসময় তাদের উপাস্যদের কাছে গিয়েছিল। তাদের সিদ্ধান্ত প্রকৃতপক্ষে দুঃখদায়ক।"],
  "6:137": ["And thus has the joining of partners made fair to many the killing of their children, in order to plunge them and to confuse their religion for them. And had Allah willed, they would not have done it. So leave them and what they fabricate.", "এভাবে প্রতিমা উপাসকরা তাদের উপাস্যদের দ্বারা প্রতারিত হয়েছিল, এমনকি তাদের নিজেদের সন্তানদেরকে হত্যা করার পর্যন্ত।  আসলে, তাদের উপাস্যরা তাদের উপর অত্যধিক যন্ত্রণা আরোপ করে, এবং তাদের জন্য তাদের ধর্মকে বিভ্রান্ত করে দেয়। আল্লাহ যদি চাইতেন, তারা এটা করতো না। তোমরা তাদের এবং তাদের মিথ্যা উদ্ভাবনকে উপেক্ষা করবে।"],
  "6:138": ["And they said: These livestock and tillage are restricted, none may eat them but whom we will, by their claim. And livestock whose backs are forbidden, and livestock over which they do not mention the name of Allah, fabricating against Allah. Allah will repay them for what they used to fabricate.", "তারা বলেছিল, ‘এইসব গৃহপালিত পশু এবং শস্য, যেগুলো নিষিদ্ধ; আমরা যাদেরকে অনুমতি দেই তারা ব্যতিত কেউ এগুলো খাবে না,” তা-ই তারা দাবি করেছিল। তারা এছাড়াও নির্দিষ্ট কিছু গৃহপালিত পশুর উপর চড়া নিষিদ্ধ করেছিল। এমনকি যে গৃহপালিত পশু তারা খেতো, যখন সেগুলো উৎসর্গ করতো তারা কখনো আল্লাহর নাম উচ্চারণ করতো না। এমন নতুন রীতিনীতি তাঁর প্রতি আরোপ করা হতো। তিনি অবশ্যই তাদের নতুন উদ্ভাবনের জন্য তাদের প্রতিশোধ নেবেন।"],
  "6:139": ["And they said: What is in the bellies of these livestock is exclusively for our males and forbidden to our nisa. But if it is born dead, then they share in it. Allah will repay them for their describing. Indeed Allah is wise, knowing.", "তারা আরও বলেছিল, “এই গৃহপালিত পশুগুলোর পেটে যা আছে তা কেবলমাত্র আমাদের মধ্যকার পুরুষদের জন্য সংরক্ষিত, এবং আমাদের স্ত্রীদের জন্য নিষিদ্ধ।” কিন্তু যদি এটা (গর্ভে জীবিত কিন্তু প্রসবের পর) মৃত হতো, তারা তাদের স্ত্রীদের তাতে অংশ নিতে অনুমতি দিত। তিনি অবশ্যই তাদের নতুন উদ্ভাবনের জন্য তাদের প্রতিশোধ নেবেন। তিনি সবচেয়ে জ্ঞানী,সর্বজ্ঞ।"],
  "6:140": ["Losers are those who killed their children in folly, without knowledge, and forbade what Allah provided them, fabricating against Allah. They have gone astray, and they were not guided.", "প্রকৃতপক্ষে তারাই ক্ষতিগ্রস্ত যারা মূর্খের মতো তাদের সন্তানদের হত্যা করে, তাদের জ্ঞানের ঘাটতির কারনে, এবং নিষিদ্ধ করে যা আল্লাহ তাদেরকে দিয়েছেন, এবং আল্লাহর প্রতি আরোপিত নতুন রীতিনীতি অনুসরণ করে। তারা বিপথে গিয়েছে; তারা পথপ্রাপ্ত নয়।"],
  "6:141": ["And Allah is the one who raised gardens, trellised and untrellised, and the palm and crops of varied produce, and the olive and pomegranate, alike and unlike. Eat of its fruit when it bears, and give its due on the day of its harvest, and do not exceed. Indeed Allah does not love the exceeders.", "তিনিই সে সত্ত্বা যিনি বাগানসমূহ স্থাপন করেছিলেন, মাচাবিশিষ্ট এবং মাচাবিহীন, এবং তাল গাছ এবং বিভিন্ন স্বাদবিশিষ্ট শস্যাদি, এবং জলপাই, এবং আনার- ফল যেগুলো একই রকম, তথাপি অন্যরকম। এদের ফল থেকে খাও, এবং ফসল সংগ্রহের দিন অবশ্য পরিশোধনীয় দান দিয়ে দাও, এবং কোন কিছু অপচয় করো না। তিনি অপচয়কারীদের ভালবাসেন না।"],
  "6:142": ["And among the livestock are carriers and ones spread out for you. Eat of what Allah has provided you, and do not follow the footsteps of the devil; indeed the devil is a clear enemy to you.", "কিছু গৃহপালিত পশু তোমাদের পরিবহনের কাজ করে, একই সাথে বিছানাপত্রের উপকরণ হিসেবে। তোমাদেরকে দেয়া আল্লাহর খাদ্যসামগ্রী থেকে খাও, এবং শয়তানের পদাঙ্ক অনুসরণ করো না; সে তোমাদের সবচেয়ে ঘোর শত্রু।"],
  "6:143": ["Eight pairs: two of sheep, and two of goats. Say: Has Allah forbidden the two males, or the two females, or what the wombs of the two females enclose? Inform me with knowledge, if you are sadiq.", "আট রকমের গৃহপালিত পশু: দুই রকমের ভেড়া, এবং দুই রকমের ছাগল সম্পর্কে,বলো, \"এটি কি দু'টি পুরুষ-জাতীয়, নাকি দু'টি নারী-জাতীয়, নাকি দু'টি নারী-জাতির জরায়ুর অভ্যন্তরস্থ বস্তু যা তিনি নিষেধ করেছিলেন? আমাকে বলো তোমরা কি জানো, যদি তোমরা সত্যবাদী হও?"],
  "6:144": ["And two of camels and two of cattle. Say: Has Allah forbidden the two males, or the two females, or what the wombs of the two females enclose? Or were you witnesses when Allah charged you with this? So who is more unjust than one who fabricates a lie against Allah to lead people astray without knowledge? Indeed Allah does not guide the unjust people.", "দুই রকমের উট, এবং দুই রকমের গবাদিপশু সম্পর্কে, বলো, \"এটি কি সে দুইটি পুরুষ-জাতীয়, অথবা সে দু'টি নারী-জাতীয়, অথবা সে দু'টি নারী-জাতির জরায়ুর অভ্যন্তরস্থ বস্তু, যা তিনি নিষেধ করেছিলেন? তোমরা কি সাক্ষী ছিলে, যখন আল্লাহ তোমাদের জন্য এরকম নিষেধাজ্ঞা জারি করেছিলেন? তাদের চেয়ে কে বেশি মন্দ যে এরকম মিথ্যা উদ্ভাবন করে এবং সেগুলো আল্লাহর প্রতি আরোপ করে? তারা এভাবে লোকদের বিপথগামী করে জ্ঞান ছাড়া। আল্লাহ এরকম মন্দ লোকদের পথ-প্রদর্শন করেন না।\""],
  "6:145": ["Say: I find in what has been revealed to me nothing forbidden to one who partakes of it, except it be carrion, or poured-out blood, or the flesh of swine, for that is filth, or an obscenity dedicated to other than Allah. But whoever is compelled, neither craving nor transgressing, then your Rabb is forgiving, merciful.", "বল, আমাকে দেয়া প্রকাশনাবলিতে আমি কোন ভক্ষনকারীর জন্য কোন খাদ্যের নিষেধ খুঁজে পাই না, এগুলো ব্যতীত: (১) মৃত প্রানীর গলিত মাংস, (২) প্রবাহিত রক্ত, (৩) শুকরের মাংস, কারন তা সংক্রামিত, এবং (৪) প্রানীর মাংস যা বানানো মিথ্যা ধর্মানুসারে আল্লাহ ছাড়া অন্য কারো প্রতি উৎসর্গকৃত।” যদি কেউ (এগুলো খেতে) বাধ্য  হয়, ইচ্ছাকৃত বা বিদ্বেষপরায়ন না হয়ে, তবে আল্লাহ ক্ষমাকারী, পরম দয়ালু।"],
  "6:146": ["And upon those who took the rival way We forbade every hoofed creature; and of cattle and sheep We forbade them their fats, except what their backs carry, or the entrails, or what is mixed with bone. That is how We repaid them for their exceeding. And indeed We are sadiq.", "যারা ইহুদী তাদের জন্য আমরা অবিভক্ত খুরওয়ালা পশু নিষিদ্ধ করেছিলাম; এবং গবাদিপশু ও ভেড়ার চর্বি নিষিদ্ধ করেছিলাম, শুধু সেগুলো ছাড়া যা তাদের পিঠে বহন করে, অথবা অন্ত:স্থিত অঙ্গে  অথবা হাড়ের সাথে মিশ্রিত থাকে। এটা ছিল তাদের সীমাতিক্রমের একটি শাস্তি, এবং আমরা সত্যবাদী।"],
  "6:147": ["So if they deny you, say: Your Rabb is possessor of vast mercy, yet the force will not be turned back from the mujrim people.", "যদি তারা তোমাকে অবিশ্বাস করে, তাহলে বল, “তোমাদের প্রভু অসীম দয়ার অধিকারী,কিন্তু তাঁর শাস্তি দোষী লোকদের জন্য অনিবার্য”।"],
  "6:148": ["Those who joined partners will say: If Allah had willed, we would not have joined partners, nor our fathers, nor would we have forbidden anything. Thus those before them denied, until they tasted Our force. Say: Do you have any knowledge you could bring out for us? You follow only conjecture, and you do nothing but guess.", "প্রতিমা উপাসকেরা বলে, “আল্লাহ যদি চাইতেন, আমরা শিরক চর্চা করতাম না, না আমাদের পিতামাতারা, না আমরা কোনকিছু নিষিদ্ধ করতাম”। এভাবে তাদের পূর্বে যারা ছিল অবিশ্বাস করেছিল, যতক্ষণ না আমাদের শাস্তি তাদের উপর এসে যায়। বল, “তোমাদের কি কোন প্রমানিত জ্ঞান আছে যা তোমরা আমাদের দেখাতে পারো? তোমরা মিথ্যা ধারনা ছাড়া অন্যকিছুর অনুসরণ করো না; তোমরা শুধু অনুমান করো”।"],
  "6:149": ["Say: To Allah belongs the decisive proof. So had Allah willed, Allah would have guided you all.", "বল, “আল্লাহ সবচেয়ে শক্তিশালী যুক্তির অধিকারী; তিনি যদি চান তিনি তোমাদের সকলকে পথপ্রদর্শন করতে পারেন”"],
  "6:150": ["Say: Bring your witnesses who testify that Allah has forbidden this. Then if they testify, do not testify with them. And do not follow the desires of those who deny Our signs, and those who do not believe in the hereafter, and set up equals to their Rabb.", "বল, “তোমাদের সাক্ষিদের আনো যারা সাক্ষ্য দেবে যে আল্লাহ এটা অথবা ঐটা নিষিদ্ধ করেছেন”। যদি তারা সাক্ষী দেয়, তাদের সাথে সাক্ষী দেবে না। না তোমরা তাদের মতামত অনুসরণ করবে যারা আমার প্রকাশনাবলী প্রত্যক্ষান করে, এবং যারা পরকালে অবিশ্বাস করে,এবং যারা তাদের প্রভু থেকে দূরে পপথভ্রষ্ট হয়।"],
  "6:151": ["Say: Come, I will recite what your Rabb has forbidden you: that you join nothing with Allah; and goodness to parents; and do not kill your children from want, We provide for you and for them; and do not approach obscenitys, outward and inward; and do not kill the soul which Allah has forbidden except by right. That is what Allah has charged you with, so that you may reason.", "বল, \"আসো তোমাদেরকে আমি বলি তোমাদের প্রভু তোমাদের জন্য প্রকৃতপক্ষে কি নিষিদ্ধ করেছেন: তোমরা তাঁর পাশে উপাস্য স্থাপন করবে না। তোমরা তোমাদের পিতা-মাতাকে সম্মান করবে। দারিদ্র্যতার ভয়ে তোমরা তোমাদের সন্তানদের হত্যা করবে না- আমরা তোমাদের জন্য এবং তাদের জন্য প্রদান করি। তোমরা গুরুতর পাপসমূহ করবে না, প্রকাশিত অথবা গোপন। তোমরা হত্যা করবে না- আল্লাহ জীবনকে পবিত্র করেছেন- বিচার প্রক্রিয়া ছাড়া। এগুলো তোমাদের প্রতি তাঁর প্রত্যাদেশ, যাতে তোমরা বুঝতে পারো।\""],
  "6:152": ["And do not approach the orphan's wealth except in the best manner, until the orphan reaches full strength. And give full measure and weight with equity. We charge no soul beyond its capacity. And when you speak, be just, even if it is a near relative. And fulfill the pledge of Allah. That is what Allah has charged you with, so that you may remember.", "তোমরা সর্বোচ্চ ন্যায়পরায়ণ পন্থা ছাড়া এতিমদের অর্থ স্পর্শ করবে না, যতক্ষণ না তারা পরিপক্বতায় পৌঁছায়। যখন তোমরা ব্যবসা করো, তোমরা পূর্ণ ওজন এবং একটি পূর্ণ মাপ দিবে, ন্যয়সঙ্গতভাবে। আমরা কোন আত্মাকে এর ক্ষমতার অতিরিক্ত বোঝা চাপাই না। তোমরা পুরোপুরি ন্যায়পরায়ণ হবে যখন তোমরা সাক্ষ্য দাও, এমনকি তোমাদের আত্মীয় -স্বজনদের বিরুদ্ধে। তোমরা আল্লাহর সাথে তোমাদের অংগীকার পরিপূর্ণ করবে। এগুলো তোমাদের প্রতি তাঁর প্রত্যাদেশ, যাতে তোমরা সতর্ক হতে পারো।"],
  "6:153": ["And that this is My straight path, so follow it; and do not follow the paths, for they would scatter you from the path. That is what Allah has charged you with, so that you may be mindful.", "এটি আমার পথ - সরল। তোমরা এটি অনুসরণ করবে, এবং অন্যকোন পথ অনুসরণ করো না, পাছে তারা তোমাদেরকে তাঁর পথ থেকে বিচ্যুত করে ফেলে। এগুলো তোমাদের প্রতি তাঁর প্রত্যাদেশ, যাতে তোমরা রক্ষা পেতে পারো।"],
  "6:154": ["Then We gave Musa the Book, complete for the one who does good, a detailing of all things, and a guidance and a mercy, so that they might believe in the meeting with their Rabb.", "এবং আমরা মুসাকে ঐশীগ্রন্থ দিয়েছিলাম, সর্বোত্তম প্রত্যাদেশাবলি দিয়ে পূর্ন, এবং সবকিছু সবিস্তারে বর্ননা করে, এবং একটি আলোকবর্তিকা এবং দয়া, যাতে তারা তাদের প্রভুর সাথে সাক্ষাতে বিশ্বাস করতে পারে।"],
  "6:155": ["And this is a blessed Book We have sent down; so follow it and be mindful, so that you may be shown mercy.", "এটিও একটি মহিমান্বিত ঐশীগ্রন্থ যা আমরা প্রকাশিত করেছি ; তোমরা এটি অনুসরণ করবে এবং একটি সৎকর্মশীল জীবন যাপন করবে, যাতে তোমরা ক্ষমা অর্জন করতে পারো।"],
  "6:156": ["Lest you say: The Book was only sent down to two parties before us, and we were indeed unmindful of their study.", "তোমরা এখন আর বলতে পারবে না,“আমাদের পূর্বের দুই দলের কাছে ঐশীগ্রন্থ অবতীর্ণ হয়েছিল, এবং আমরা সেগুলোর শিক্ষাসমূহে অনবগত ছিলাম।"],
  "6:157": ["Or lest you say: If only the Book had been sent down to us, we would have been better guided than they. A clear proof has come to you from your Rabb, and a guidance and a mercy. So who is more unjust than one who denies the signs of Allah and turns away from them? We will repay those who turn away from Our signs with the evil of punishment, for what they used to turn away from.", "না তোমরা বলতে পারো, “যদি শুধু একটি ঐশীগ্রন্থ আমাদের কাছে অবতীর্ণ হতো, আমরা তাদের থেকে উত্তম পথপ্রদর্শিত হতাম”। “তোমাদের প্রভুর পক্ষ থেকে এখন তোমাদের কাছে এসেছে একটি প্রমানিত ঐশীগ্রন্থ, এবং একটি আলোকবর্তিকা, এবং একটি দয়া। এখন, কে তার চেয়ে অধিক মন্দ যে আল্লাহর পক্ষ থেকে আসা এই প্রমানাদি প্রত্যাক্ষান করে, এবং সেগুলো উপেক্ষা করে? যারা আমাদের প্রমানাদি উপেক্ষা করে আমরা তাদের নিকৃষ্টতম শাস্তি দেব, তাদের অমনোযোগিতার কারনে।"],
  "6:158": ["Do they wait for anything but that the malakat come to them, or your Rabb comes, or some of your Rabb's signs come? On the day some of your Rabb's signs come, no soul will benefit from its faith that had not believed before or earned good in its faith. Say: Wait, indeed we too are waiting.", "তারা কি অপেক্ষা করছে ফেরেশতাদের, অথবা তোমার প্রভুর, অথবা তোমার প্রভুর কিছু শারীরিক প্রকাশ তাদের কাছে আসার? যেদিন এটা ঘটবে, কোন আত্মার বিশ্বাস করায় লাভ হবে না, যদি আগে থেকে এটি বিশ্বাস না করে, এবং একটি সৎ জীবন যাপনের দ্বারা বিশ্বাসের উপকারিতা সমূহের ফল লাভ না করে থাকে। বল, “অপেক্ষা করতেই থাকো, আমরাও অপেক্ষা করছি”।"],
  "6:159": ["Indeed those who split their religion and became parties, you have nothing to do with them. Their affair is only with Allah; then Allah will inform them of what they used to do.", "যারা নিজেদেরকে বিভিন্ন বর্ণে বিভক্ত করে তারা তোমার অন্তর্ভূক্ত নয়। তাদের বিচার আল্লাহর কাছে রয়েছে, তখন তিনি তাদেরকে জানাবেন সবকিছু যা তারা করেছিল।"],
  "6:160": ["Whoever brings a good deed will have ten times its like; and whoever brings an evil deed will be repaid only its like; and they will not be wronged.", "যে কেউ একটি সৎকর্ম করে সে দশটির পুরুস্কার লাভ করে, এবং যে একটি পাপ করে,  শুধু মাত্র একটির জন্য প্রতিফল ভোগ করে। কেউই সামান্যতম অবিচার ভোগ করে না।"],
  "6:161": ["Say: Indeed my Rabb has guided me to a straight path, an upright religion, the way of Ibrahim, upright; and he was not of those who join partners.", "বল, \"আমার প্রভু আমাকে প্রদর্শন করেছেন একটি সরল পথ - ইব্রাহিমের সঠিক ধর্ম, একেশ্বরবাদ। সে কখনো প্রতিমা উপাসক ছিল না।\""],
  "6:162": ["Say: Indeed my prayer and my rites and my living and my dying are for Allah, Rabb of the worlds.", "বল, \"আমার সংযোগ প্রার্থনাসমূহ (সালাত), আমার উপাসনা চর্চাসমূহ, আমার জীবন এবং আমার মৃত্যু, সবকিছু উৎসর্গকৃত একমাত্র আল্লাহর প্রতি, মহাবিশ্বের প্রভু।"],
  "6:163": ["No partner has Allah; and with that I have been commanded, and I am the first of those who submit.", "\"তাঁর কোন অংশীদার নেই। এটিই আমাকে বিশ্বাস করতে আদেশ করা হয়েছে এবং আমি প্রথমেই আত্মসমর্পণ করি।\""],
  "6:164": ["Say: Shall I seek a Rabb other than Allah, when Allah is Rabb of all things? And no soul earns except against itself; and no laden soul bears the load of another. Then to your Rabb is your return, and Allah will inform you of what you used to differ about.", "বল, \"আমি কি প্রভু হিসেবে আল্লাহ ছাড়া অন্য কাউকে খুঁজবো, যখন তিনি সবকিছুর প্রভু? কোন আত্মাই লাভবান হয় না এর নিজের কর্ম থেকে ছাড়া, এবং কেউই অন্যের বোঝা বহন করে না। অবশেষে, তোমরা তোমাদের প্রভুর কাছে ফিরে আসো, এরপর তিনি তোমাদের সকল বিবাদের বিষয়ে তোমাদেরকে জানান।\""],
  "6:165": ["And Allah is the one who made you successors of the earth, and raised some of you above others in degrees, to test you in what Allah has given you. Indeed your Rabb is swift in requital, and indeed Allah is forgiving, merciful.", "তিনিই সে সত্ত্বা যিনি তোমাদেরকে পৃথিবীর উত্তরাধিকারী করেছেন, এবং তিনি তোমাদের কাউকে কাউকে পদমর্যাদায় অন্যদের উপর উন্নীত করেছিলেন, তিনি তোমাদেরকে যা দিয়েছেন সে অনুসারে তোমাদেরকে পরীক্ষা করার জন্য। নিশ্চিতভাবে, তোমাদের প্রভু শাস্তি প্রয়োগে দক্ষ, এবং তিনি ক্ষমাকারী,পরম দয়ালু।"],
  "7:1": ["Alif Lam Mim Sad", "অ, ল, ম, স"],
  "7:2": ["A writing sent down to you — so let there be no constriction in your breast about it — that you may warn with it, and a reminder for the muminin.", "এই ঐশীগ্রন্থ তোমার কাছে প্রকাশিত হয়েছে- এটি সম্পর্কে তুমি তোমার হৃদয়ে সন্ধেহ পোষণ করবে না- যাতে তুমি এটি দিয়ে সতর্ক করতে পারো,এবং বিশ্বাসীদের জন্য স্মরণ করার একটি মাধ্যম প্রদান করতে পার।"],
  "7:3": ["Follow what has been sent down to you from your Rabb, and do not follow protectors besides Allah. Little do you remember.", "তোমরা সকলে অনুসরণ করবে তোমাদের প্রভুর পক্ষ থেকে তোমাদের কাছে যা প্রকাশিত হয়েছে;তাঁর পাশে কোন উপাস্য অনুসরণ করো না। তোমরা খুব কমই মনোযোগ দাও।"],
  "7:4": ["How many a town We destroyed: Our might came upon it by night, or while it rested at midday.", "অনেক জনপদ আমরা ধ্বংস করেছিলাম; তারা আমাদের শাস্তি পেয়েছিল যখন তারা ঘুমন্ত ছিল, অথবা জেগে ছিল।"],
  "7:5": ["Their cry, when Our might came upon them, was only to say: \"Indeed we were wrongdoers.\"", "যখন আমাদের শাস্তি তাদের কাছে এসেছিল, তাদের উক্তি ছিলঃ “প্রকৃতপক্ষে, আমরা সীমালংঘনকারী হয়েছি”।"],
  "7:6": ["We shall surely question those to whom the Rasuls were sent, and We shall surely question the Rasuls.", "আমরা অবশ্যই তাদেরকে প্রশ্ন করবো যারা বার্তা পেয়েছিল, এবং আমরা  প্রশ্ন করবো বার্তাবাহকদের।"],
  "7:7": ["Then We shall relate to them with knowledge; and We were not absent.", "আমরা তাদেরকে প্রমান সহকারে জানাব, যেহেতু আমরা কখনো অনুপস্থিত ছিলাম না।"],
  "7:8": ["The weighing on that day is the truth. Those whose scales weigh heavy — those are the ones who attain success.", "সে দিন মাপযন্ত্র স্থাপন করা হবে, ন্যায়পরায়ণভাবে। যাদের ওজন ভারী হবে, তারা বিজয়ী হবে।"],
  "7:9": ["And those whose scales weigh light — those are the ones who lost themselves, for they were wronging Our signs.", "তাদের জন্য যাদের ওজন হাল্কা হবে, তারা হবে সেই লোক যারা তাদের আত্মা হারিয়েছে, আমাদের প্রকাশনাবলী উপেক্ষা করার ফলে,অন্যায়ভাবে।"],
  "7:10": ["We have established you in the earth and made for you livings in it. Little do you thank.", "আমরা তোমাদেরকে পৃথিবীর উপর প্রতিষ্ঠিত করেছি, এবং আমরা সেখানে তোমাদের ভরন-পোষনের জন্য উপায় দিয়েছি। তোমরা খুব কমই কৃতজ্ঞ হও।"],
  "7:11": ["We created you, then We formed you; then We said to the assembly: \"Prostrate before Adam.\" So they prostrated, except Iblis — he was not of those who prostrate.", "আমরা তোমাদেরকে সৃষ্টি করেছিলাম, এরপর আমরা তোমাদের আকার দিয়েছিলাম, এরপর আমরা ফেরেশতাদের বলেছিলাম, \"আদমের সামনে সেজদাবনত হও।” তারা সেজদাবনত হয়েছিল, ই বলিস (শয়তান) ব্যতীত; সে সেজদাকারীদের সাথে ছিল না।"],
  "7:12": ["Allah said: \"What prevented you from prostrating when I commanded you?\" He said: \"I am better than him; You created me from fire and created him from clay.\"", "তিনি বলেছিলেন, \"কিসে তোমাকে সেজদা করা থেকে বিরত রেখেছিল, যখন আমি তোমাকে আদেশ করেছিলাম?” সে বলেছিল, \"আমি তার চেয়ে উত্তম; আপনি আমাকে আগুন থেকে সৃষ্টি করেছিলেন, এবং তাকে কাদামাটি থেকে সৃষ্টি করেছিলেন।\""],
  "7:13": ["Allah said: \"Descend from it! It is not for you to show pride in it. Get out — you are among the belittled.\"", "তিনি বলেছিলেন, \"এজন্য, তুমি অবশ্যই নিচে চলে যাবে, কারন তুমি এখানে উদ্ধত হবে না। বের হয়ে যাও; তুমি অধ:পতিত।\""],
  "7:14": ["He said: \"Give me respite until the day they are raised.\"", "সে বলেছিল, \"আমাকে একটি অবকাশ মঞ্জুর করুন, পুন:রুত্থান দিবস পর্যন্ত।\""],
  "7:15": ["Allah said: \"You are among the respited.\"", "তিনি বলেছিলেন, \"তোমাকে একটি অবকাশ মঞ্জুর করা হলো।\""],
  "7:16": ["He said: \"Because You have misled me, I will sit in wait for them on Your straight path.\"", "সে বলেছিল, “যেহেতু আপনি চেয়েছেন যে আমি বিপথে যাই,  আমি তাদের জন্য আপনার সরল পথের উপর গাপটি মেরে থাকব।"],
  "7:17": ["Then I will come upon them from before them and from behind them, and from their right hands and from their left hands; and You will not find most of them thankful.\"", "“আমি তাদের কাছে আসব তাদের সামনে থেকে, এবং তাদের পেছন থেকে, এবং তাদের ডান দিক থেকে,এবং তাদের বাম দিক থেকে, এবং আপনি তাদের বেশির ভাগকে অকৃতজ্ঞ পাবেন”।"],
  "7:18": ["Allah said: \"Get out from it, rejected and driven away. Whoever of them follows you — I will surely fill Gehenna with all of you.\"", "তিনি বলেছিলেন, “সেখান থেকে বেরিয়ে যাও, ঘৃণিত এবং পরাজিত হয়ে। তাদের মধ্যে যারা তোমাকে অনুসরণ করে, আমি তোমাদের সকলকে দিয়ে নরক পূর্ণ করবো।"],
  "7:19": ["\"Adam, dwell, you and your spouse, in the Garden, and eat from wherever you wish; but do not approach this tree, lest you be among the wrongdoers.\"", "“তোমার ক্ষেত্রে, আদম, তোমার স্ত্রীর সাথে স্বর্গে বাস করো, এবং তা থেকে খাও যেমন তোমরা পছন্দ করো, কিন্তু এই একটি গাছের কাছে যেও না, পাছে তোমরা পাপে পতিত হও”।"],
  "7:20": ["So Shaytan whispered to them, to show them what had been concealed from them of their shame; and he said: \"Your Rabb only forbade you this tree lest you become malakat, or become of the immortal.\"", "শয়তান তাদের কাছে ফিসফিস করেছিল, তাদের শরীর প্রকাশ করার জন্য, যা তাদের কাছে অদৃশ্য ছিল। সে বলেছিল, “ফেরেশতা হয়ে যাওয়া থেকে,এবং চিরস্থায়ী অস্তিত্ব অর্জন করা থেকে তোমাদের বিরত করা ছাড়া, অন্য কোন কারনে তোমাদের প্রভু তোমাদেরকে এই গাছ নিষেধ করেননি।"],
  "7:21": ["And he swore to them: \"Indeed I am to you both one of the nasihin.\"", "সে তাদের কাছে শপথ করেছিল, \"আমি তোমাদেরকে ভাল উপদেশ দিচ্ছি।\""],
  "7:22": ["So he led them both astray by deception. When they tasted the tree, their shame became manifest to them, and they began to stitch over themselves leaves of the Garden. Their Rabb called to them: \"Did I not forbid you that tree, and say to you: Shaytan is to you both an open enemy?\"", "সে এভাবে তাদেরকে মিথ্যা বলে প্রতারিত করেছিল। যখনই তারা সে গাছের স্বাদ নিয়েছিল, তাদের দেহ তাদের কাছে দৃশ্যমান হয়ে পড়েছিল, এবং তারা তাদের নিজেদেরকে স্বর্গোদ্যানের পাতা দিয়ে ঢাকার চেষ্টা করেছিল। তাদের প্রভু তাদেরকে ডাকলেন: \"আমি কি তোমাদেরকে ঐ গাছ থেকে বিরত থাকার আদেশ দেইনি, এবং সতর্ক করিনি যে শয়তান তোমাদের সবচেয়ে ঘোর শত্রু?\""],
  "7:23": ["They said: \"Our Rabb, we wronged ourselves; and if You do not forgive us and have mercy on us, we shall surely be among the khasirin.\"", "তারা বলেছিল, \"আমাদের প্রভু,আমরা আমাদের আত্মার ক্ষতি করেছি, এবং যদি না আপনি আমাদের ক্ষমা করেন ও আমাদের উপর দয়া করেন, আমরা ক্ষতিগ্রস্ত হবো।\""],
  "7:24": ["Allah said: \"Descend, some of you to others as enemies; and for you in the earth is a resting-place and provision until a time.\"", "তিনি বলেছিলেন, \"একে অন্যের শত্রু হিসেবে নিচে নেমে যাও। পৃথিবীর উপর হবে তোমাদের বাসস্থান এবং জীবিকা কিছু কালের জন্য।\""],
  "7:25": ["Allah said: \"In it you live, and in it you die, and from it you are brought forth.\"", "তিনি বলেছিলেন, \"এর উপর তোমরা বাচবে, এর উপর তোমরা মরবে, এবং এর থেকে তোমাদের বের করে আনা হবে।\""],
  "7:26": ["Children of Adam, We have sent down upon you a garment that covers your shame, and an adornment; and the garment of mindfulness — that is better. That is of Allah's signs, so that they may remember.", "হে আদম সন্তানেরা, আমরা তোমাদেরকে পোশাক দিয়েছি তোমাদের শরীর আবৃত করতে, পাশাপাশি বিলাসিতার জন্য। কিন্তু সর্বোত্তম পোশাক হলো সৎকর্মশীলতার পোশাক। এগুলো আল্লাহর কিছু নিদর্শন, যাতে তারা মনোযোগ দিতে পারে।"],
  "7:27": ["Children of Adam, do not let Shaytan tempt you, as he brought your parents out of the Garden, stripping from them their garment to show them their shame. He sees you, he and his tribe, from where you do not see them. We have made the satans protectors of those who do not believe.", "হে আদম সন্তানেরা, শয়তানকে তোমাদের ক্ষেত্রে তা করতে দিও না যেরকম সে করেছিল যখন সে স্বর্গোদ্যান থেকে তোমাদের পিতামাতার উচ্ছেদ ঘটিয়েছিল, এবং তাদের দেহ প্রকাশ করতে তাদের পোশাকের অপসারণ ঘটিয়েছিল। সে এবং তার জাতি তোমাদের দেখে, যখন তোমরা তাদেরকে দেখো না। আমরা শয়তানদের নিযুক্ত করি তাদের সঙ্গী হিসেবে যারা বিশ্বাস করে না।"],
  "7:28": ["When they commit an obscenity they say: \"We found our fathers upon it, and Allah commanded us to it.\" Say: \"Allah does not command obscenity. Do you say of Allah what you do not know?\"", "তারা একটি মহা পাপ করে, এরপর বলে, “আমরা আমাদের পিতামাতাকে এগুলো করতে দেখেছি,এবং আল্লাহ আমাদেরকে এটা করতে আদেশ করেছেন”। বল, “আল্লাহ কখনো পাপের উকালতি করেন না। তোমরা কি আল্লাহ সম্পর্কে বলছ যা তোমরা জানো না?”"],
  "7:29": ["Say: \"My Rabb has commanded equity. Set your faces at every place of prostration, and call on Allah, devoting the religion sincerely to Allah. As Allah began you, so you return.\"", "বল, “আমার প্রভু উকালতি করেন ন্যায়পরায়ণতার, এবং প্রত্যেক উপাসনার স্থানে একমাত্র তাঁর প্রতি উৎসর্গকৃত হয়ে দাড়ানোর। তোমরা সম্পূর্ণরূপে একমাত্র তাঁর প্রতি তোমাদের উপাসনা উৎসর্গ করবে। ঠিক যেমন তিনি তোমাদের সূচনা করেছিলেন, তোমরা সবশেষে তাঁর কাছেই ফিরে যাবে”।"],
  "7:30": ["A party Allah guided, and a party the straying befell rightly. They took the satans as protectors instead of Allah, and they suppose that they are guided.", "কাউকে কাউকে তিনি পথপ্রদর্শন করেছিলেন, যখন অন্যরা পথভ্রষ্টতায় লিপ্ত। তারা শয়তানদেরকে তাদের মনিব হিসাবে নিয়েছে, আল্লাহর বদলে, তা সত্ত্বেও তারা বিশ্বাস করে যে তারা পথপ্রাপ্ত।"],
  "7:31": ["Children of Adam, take your adornment at every place of prostration, and eat and drink, and do not exceed. Allah does not love the exceeders.", "হে আদম সন্তানেরা, তোমরা পরিষ্কার হবে এবং সুন্দরভাবে পোষাক পরিধান করবে, যখন তোমরা মসজিদে যাও। এবং খাও ও পান করো পরিমিতভাবে। নিশ্চয়, তিনি অতিভোজীদের ভালোবাসেন না।"],
  "7:32": ["Say: \"Who has forbidden the adornment of Allah that Allah brought forth for servants, and the wholesome things of provision?\" Say: \"They are for those who believed in the life of this world, exclusive on the Day of Resurrection.\" Thus We detail the signs for a people who know.", "বল, \"কে নিষিদ্ধ করে সুন্দর জিনিসগুলো যা আল্লাহ সৃষ্টি করেছেন তাঁর সৃষ্ট জীবের জন্য, এবং উত্তম জীবিকা?\" বল, \"এরকম জীবিকা এই জীবনে তাদের উপভোগ্য হবে, যারা বিশ্বাস করে। অধিকন্তু, ভালো জীবিকা সমূহ পুন:রুত্থান দিবসে কেবলমাত্র তাদের হবে।\" আমরা এভাবে লোকদের জন্য প্রকাশনাবলি ব্যাখ্যা করি, যারা জানে।"],
  "7:33": ["Say: \"My Rabb has only forbidden obscenitys, their open and their hidden, and sin, and wrongful aggression without right, and that you associate with Allah that for which Allah sent down no warrant, and that you say of Allah what you do not know.\"", "বল, \"আমার প্রভু নিষেধ করেন শুধু মন্দ কাজগুলো, সেগুলো প্রকাশ্য হোক অথবা গোপন, এবং পাপ, এবং অযৌক্তিক আগ্রাসন, এবং আল্লাহর পাশে ক্ষমতাহীন উপাস্য স্থাপন করা, এবং আল্লাহ সম্পর্কে বলা যা তোমরা জানো না।\""],
  "7:34": ["Every nation has a term; and when its term comes, they cannot delay an hour, nor can they advance it.", "প্রত্যেক সম্প্রদায়ের জন্য, একটি পূর্বনির্ধারিত সময়কাল রয়েছে। যখনই তাদের অন্তবর্তী সময়কাল শেষ হয়ে আসে, তারা একে এক ঘন্টার জন্যও বিলম্ব করাতে পারে না, না তা আগাতে পারে।"],
  "7:35": ["Children of Adam, when rusul from among you come to you relating My signs, whoever keeps his duty and sets right — no fear is upon them, nor do they grieve.", "হে আদম সন্তানেরা, যখন বার্তাবাহকরা তোমাদের কাছে আসে তোমাদের মধ্য থেকে, এবং আমার প্রকাশনাবলি তোমাদের কাছে আবৃতি করে, যারা মনোযোগ দেয় এবং একটি সৎকর্মশীল জীবন যাপন করে, তাদের ভয়ের কিছু থাকবে না, না তারা শোক করবে।"],
  "7:36": ["Those who deny Our signs and turn away from them in pride — those are the companions of the Fire. In it they abide.", "তাদের জন্য যারা আমাদের প্রকাশনাবলী প্রত্যাখ্যান করে, এবং সেগুলো মেনে চলতে খুব দাম্ভিক হয়, তারা নরক টেনে এনেছে,যেখানে তারা চিরকাল বাস করে।"],
  "7:37": ["Who is more unjust than one who fabricates against Allah a lie, or denies Allah's signs? Those will reach their allotted portion of the Book, until Our malakat come to them to take them, saying: \"Where is that which you used to call upon besides Allah?\" They say: \"They have strayed from us,\" and they bear witness against themselves that they were deniers.", "তাদের থেকে কে বেশি মন্দ যে আল্লাহ সম্বন্ধে মিথ্যা উদ্ভাবন করে, অথবা তাঁর প্রকাশনাবলী প্রত্যাখ্যান করে? এরা তাদের অংশ পাবে, ঐশীগ্রন্থ অনুসারে, এরপর, যখন আমাদের বার্তাবাহকরা তাদের জীবন সমাপ্ত করতে আসে, তারা বলবে, “কোথায় সেই উপাস্যরা, আল্লাহর পাশে যাদের কাছে তোমরা মিনতি করতে?” তারা বলবে, “তারা আমাদের পরিত্যাগ করেছে”। তারা নিজেদের বিরুদ্ধে সাক্ষ্য দিবে যে, তারা অবিশ্বাসী ছিল।"],
  "7:38": ["Allah says: \"Enter into nations that passed away before you of jinn and humankind into the Fire.\" Every time a nation enters, it curses its sister, until when they have all overtaken one another in it, the last of them say to the first of them: \"Our Rabb, these led us astray, so give them a double punishment of the Fire.\" Allah says: \"For each is double — but you do not know.\"", "তিনি বলবেন, “পূর্ববর্তী সম্প্রদায়ের জিন এবং মানুষদের সাথে নরকে প্রবেশ করো”। প্রত্যেকবার যখন একটি দল প্রবেশ করে, তারা তাদের পূর্বপুরুষের দলকে অভিশাপ দেবে। যখন তাদের সকলে এর ভিতর থাকবে, সর্বশেষ দলটি পূর্ববর্তী দল সম্পর্কে বলবে, “আমাদের প্রভু, এরা তারাই যারা আমাদের পথভ্রষ্ট করেছিল। তাদেরকে নরকের দিগুন শাস্তি দিন”। তিনি বলবেন, “প্রত্যেকে দিগুন পায়, কিন্তু তোমরা জানো না”।"],
  "7:39": ["The first of them say to the last of them: \"You have no superiority over us, so taste the punishment for what you earned.\"", "পূর্বপুরুষের দল পরবর্তী দলকে বলবে, “যেহেতু আমাদের চেয়ে তোমাদের সুবিধা বেশি ছিল , তোমাদের নিজেদের পাপের জন্য শাস্তি আস্বাদন করো”।"],
  "7:40": ["Those who deny Our signs and turn away from them in pride — the gates of heaven will not be opened for them, nor will they enter the Garden until a camel passes through the eye of a needle. Thus We requite the mujrimin.", "নিশ্চয়, যারা আমাদের প্রকাশনাবলী প্রত্যাখ্যান করে এবং সেগুলো মেনে চলতে খুব উদ্ধত হয়, আকাশের দরজাগুলো কখনো তাদের জন্য খোলা হবে না, না তারা স্বর্গে প্রবেশ করবে যতক্ষণ না সূচের ছিদ্র দিয়ে উট প্রবেশ করে। আমরা এভাবে অপরাধিদের থেকে প্রতিশোধ গ্রহন করি।"],
  "7:41": ["For them is a couch of Gehenma, and coverings above them. Thus We requite the wrongdoers.", "তারা একটি আবাস হিসেবে নরক টেনে এনেছে; তাদের উপরে  সীমানা সমূহ থাকবে। আমরা এভাবে সীমালঙ্ঘনকারীদের থেকে প্রতিশোধ গ্রহন করি।"],
  "7:42": ["Those who believed and did salih deeds — We charge no soul beyond its capacity. Those are the companions of the Garden; in it they abide.", "তাদের জন্য যারা বিশ্বাস করে এবং একটি সৎকর্মশীল জীবন যাপন করে- আমরা কখনো কোন আত্মাকে এর ক্ষমতার অতিরিক্ত বোঝা চাপাই না- এরা হবে স্বর্গোদ্যানের বাসিন্দা। তারা এতে চিরকাল বাস করে।"],
  "7:43": ["We will pull out whatever rancor is in their breasts; rivers flow beneath them. They say: \"Praise belongs to Allah, who guided us to this; and we would not have been guided had Allah not guided us. The rusul of our Rabb came with the truth.\" And they are called: \"That is the Garden you have inherited for what you did.\"", "আমরা তাদের অন্তর থেকে সকল ঈর্সা সরিয়ে নেবো। তাদের নিচ থেকে নদীসমূহ প্রবাহিত হবে,এবং তারা বলবে, \"আমাদের পথ-প্রদর্শনের জন্য প্রশংসা আল্লাহর। আমরা সম্ভবত পথপ্রাপ্ত হতে পারতাম না, যদি এটি না হতো যে আল্লাহ আমাদের পথপ্রদর্শন করেছেন। আমাদের প্রভুর বার্তাবাহকরা সত্য এনেছিল।” তাদেরকে ডাকা হবে: \"এটি তোমাদের স্বর্গোদ্যান। তোমরা এর উত্তরাধিকারী হয়েছ, তোমাদের কর্মসমূহের প্রতিদানে।\""],
  "7:44": ["The companions of the Garden call to the companions of the Fire: \"We have found what our Rabb promised us true. Have you found what your Rabb promised true?\" They say: \"Yes.\" Then a crier proclaims between them: \"The curse of Allah is upon the wrongdoers,\"", "স্বর্গোদ্যানের অধিবাসীরা নরকের অধিবাসীদের ডাকবে: \"আমরা আমাদের প্রভুর অংগীকার সত্য পেয়েছি, তোমরা কি তোমাদের প্রভুর অংগীকার সত্য পেয়েছ?\" তারা বলবে, \"হ্যা\"। তাদের মধ্যে একজন ঘোষনাকারী ঘোষনা করবে : \"আল্লাহর শাস্তি সীমালঙ্ঘনকারীদের উপর পড়েছে;"],
  "7:45": ["\"who turn away from the way of Allah and seek to make it crooked, and of the Hereafter they are deniers.\"", "\"যারা আল্লাহর পথে বাধা দেয়, এবং একে বক্র করতে কঠোর চেষ্টা করে,এবং, পরকাল সম্পর্কে, তারা অবিশ্বাসী।\""],
  "7:46": ["Between them is a veil, and on the heights are men who know each by their marks. They call to the companions of the Garden: \"Peace upon you.\" They have not entered it, yet they hope.", "একটি সীমানা তাদেরকে আলাদা করে, যখন শুদ্ধিস্থান (আরাফ)  এমন লোকেদের দখলে থাকে যারা তাদের চেহারা দ্বারা প্রতিটি পক্ষকে চিনতে পারে। তারা স্বর্গের বাসিন্দাদের ডাকবেঃ “তোমাদের উপর শান্তি হোক”। তারা মনোমতো চিন্তার ছলে (স্বর্গোদ্যানে) প্রবেশ করেনি।"],
  "7:47": ["And when their eyes are turned toward the companions of the Fire, they say: \"Our Rabb, do not place us with the wrongdoing people.\"", "যখন তারা তাদের চোখ নরকের বাসিন্দাদের দিকে ফেরায়, তারা বলবে, “আমাদের প্রভু, আমাদেরকে এই পাপপূর্ন লোকদের সাথে রেখো না”।"],
  "7:48": ["The companions of the Heights call to men whom they know by their marks, saying: \"Your gatherings availed you nothing, nor your pride.\"", "শুদ্ধিস্থানের বাসিন্দারা জিজ্ঞেস করবে লোকদের, যাদেরকে তাদের চাহনি দেখে চিনবে, এই বলে যে, “তোমাদের বিশাল সংখ্যা কোন ভাবেই তোমাদের উপকারে আসেনি, না তোমাদের ঔদ্ধত্য।"],
  "7:49": ["\"Are these the ones you swore Allah would not reach with mercy?\" \"Enter the Garden; no fear is upon you, nor do you grieve.\"", "ওরাই কি সেই লোক তোমরা শপথ করতে যে আল্লাহ কখনো তাদের দয়া করবেন না?”(শুদ্ধিস্থানের লোকদের তখন বলা হবে,) “স্বর্গোদ্যানে প্রবেশ করো; তোমাদের ভয়ের কিছু নেই, না তোমরা শোক করবে”।"],
  "7:50": ["The companions of the Fire call to the companions of the Garden: \"Pour down upon us some water, or some of what Allah provided you.\" They say: \"Allah has forbidden both to the kafirin,\"", "নরকের বাসিন্দারা স্বর্গোদ্যানের বাসিন্দাদের সাথে সাক্ষাতে বলবেঃ “তোমাদের কিছু পানি, অথবা তোমাদেরকে আল্লাহর দেয়া কিছু জীবিকা আমাদের দিকে সরবরাহ করো”। তারা বলবে, “আল্লাহ সেগুলো অবিশ্বাসীদের জন্য নিষিদ্ধ করেছেন”।"],
  "7:51": ["\"who took their religion as diversion and play, and whom the life of this world deceived.\" Today We forget them as they forgot the meeting of this day of theirs, and they used to deny Our signs.", "যারা তাদের ধর্মকে গুরুত্বের সাথে নেয় না, এবং দুনিয়ার জীবনে সম্পূর্ণ আচ্ছন্ন, আমরা তাদেরকে ঐ দিন ভুলে যাই, কারণ তারা ঐ দিনকে ভুলে গিয়েছিল, এবং কারণ তারা আমাদের প্রকাশনাবলি অবজ্ঞার সাথে প্রত্যাক্ষান করেছিল।"],
  "7:52": ["We brought them a Book that We detailed with knowledge — guidance and mercy for a people who believe.", "আমরা তাদেরকে একটি ঐশীগ্রন্থ দিয়েছি যা সম্পূর্ন বিস্তারিত, জ্ঞানে, পথ-প্রদর্শনে,এবং দয়ায়, সে লোকদের জন্য যারা বিশ্বাস করে।"],
  "7:53": ["Do they look for anything but its interpretation? On the day its interpretation comes, those who forgot it before will say: \"The rusul of our Rabb came with the truth. Do we have any intercessors to intercede for us, or can we be returned so that we may do other than what we did?\" They lost themselves, and what they fabricated has strayed away from them.", "তারা কি অপেক্ষা করছে যতক্ষণ না সকল (ভবিষ্যৎবানী) পরিপূর্ণ হয়? সে দিন যখন এরকম পরিপূর্ণতা ঘটে, যারা অতীতে এটি উপেক্ষা করেছিল তারা বলবে, \"আমাদের প্রভুর বার্তাবাহকরা সত্য এনেছে। আমাদের পক্ষে সুপারিশ করতে কোন সুপারীশকারী আছে কি? আপনি কি আমাদের ফেরত পাঠাবেন, যাতে আমরা আমাদের ব্যবহার পরিবর্তন করি, এবং উত্তম কাজ করি তার চেয়ে যা আমরা করেছিলাম?” তারা তাদের আত্মা হারিয়েছে, এবং তাদের নিজেদের উদ্ভাবন তাদের ধ্বংসের কারণ হয়েছে।"],
  "7:54": ["Your Rabb is Allah, who created the heavens and the earth in six days, then set over the raised frame, covering the day with the night. It seeks it swiftly, and the sun, the moon and the stars are subjected by Allah's command. Beware — to Allah belong creation and command. Blessed be Allah, Rabb of the worlds.", "তোমাদের প্রভু এক আল্লাহ; যিনি আকাশমন্ডলী  ও পৃথিবী ছয় দিনে সৃষ্টি করেছিলেন,  এরপর সকল কর্তৃত্ব গ্রহন করেছিলেন। রাত নাগাল পায় দিনের, যেহেতু এটি নিরবচ্ছিন্নভাবে এর পেছনে ছোটে, এবং সূর্য, চন্দ্র, ও তারকারাজি তাঁর আদেশে চলতে নিয়োজিত। নি:সন্দেহে, তিনি সকল সৃষ্টি এবং সকল আদেশ নিয়ন্ত্রন করেন। আল্লাহ সবচেয়ে মর্যাদাসম্পন্ন, মহাবিশ্বের প্রভু।"],
  "7:55": ["Call on your Rabb humbly and secretly. Allah does not love the transgressors.", "তোমরা তোমাদের প্রভুকে প্রকাশ্যে এবং গোপনে উপাসনা করবে; তিনি সীমালঙ্ঘনকারীদের ভালোবাসেন না।"],
  "7:56": ["Do not work corruption in the earth after its setting right, and call on Allah in fear and in hope. The mercy of Allah is near to those who do good.", "পৃথিবীকে কলুষিত করো না, এটিকে পরিশুদ্ধ করার পর এবং তাঁর উপাসনা করো ভক্তি-শ্রদ্ধা থেকে,এবং আশা নিয়ে। নিশ্চয়, আল্লাহর দয়া সৎ কর্মীদের দ্বারা অর্জনীয়।"],
  "7:57": ["It is Allah who sends the winds as good tidings ahead of Allah's mercy, until when they bear heavy clouds, We drive them to a dead land and send down the water with it, and bring forth with it every fruit. Thus We bring forth the dead, so that you may remember.", "তিনিই একজন যিনি শুভ ইঙ্গিত সহ বায়ু পাঠান, তাঁর হাত থেকে একটি দয়া হিসাবে। একবার যখন তারা ভারী মেঘ জড়ো করে, আমরা এগুলোকে মৃত ভূমির দিকে চালনা করি,এবং তা থেকে পানি বর্ষন করি, তা দিয়ে সব রকমের ফল উৎপাদন করতে। আমরা এভাবে মৃতকে পুনরূজ্জীবিত করি, যাতে তোমরা খেয়াল করতে পার।"],
  "7:58": ["The good land brings forth its vegetation by the leave of its Rabb; but the vile brings forth nothing except scant and vile growth. Thus We turn the signs about for a people who give thanks.", "ভালো জমি সহজে এর উদ্ভিদ উৎপাদন করে এর প্রভুর অনুমতিতে, যখন মন্দ জমি নামেমাত্র প্রয়োজনীয় কিছু উৎপাদন করে। আমরা এভাবে প্রকাশনাবলী ব্যাখ্যা করি লোকদের জন্য যারা কৃতজ্ঞ।"],
  "7:59": ["We sent Nuh to his people, and he said: \"O my people, serve Allah — you have no ilah other than Allah. I fear for you the punishment of a tremendous day.\"", "আমরা নুহকে তার লোকদের কাছে পাঠিয়েছিলাম, এই বলে,“হে আমার লোকেরা,আল্লাহর উপাসনা করো; তাঁর পাশে তোমাদের অন্য কোন উপাস্য নেই। আমি তোমাদের জন্য একটি ভয়াবহ দিনের শাস্তির ভয় করি”।"],
  "7:60": ["The chiefs of his people said: \"We see you in clear error.\"", "তার লোকদের নেতারা বলেছিল, “আমরা দেখি যে তুমি বহুদূর পথভ্রষ্ট”।"],
  "7:61": ["He said: \"O my people, there is no error in me, but I am a Rasul from the Rabb of the worlds.\"", "সে বলেছিল, \"হে আমার লোকেরা,আমি পথভ্রষ্ট নই; আমি মহাবিশ্বের প্রভুর পক্ষ থেকে একজন বার্তাবাহক।"],
  "7:62": ["\"I deliver to you the messages of my Rabb, and I am a sincere adviser to you, and I know from Allah what you do not know.\"", "\"আমি তোমাদের কাছে আমার প্রভুর বার্তা পৌঁছে দেই, এবং আমি তোমাদেরকে উপদেশ দেই, এবং আমি আল্লাহ থেকে জানি যা তোমরা জানো না।"],
  "7:63": ["\"Do you marvel that a reminder from your Rabb has come to you upon a man from among you, to warn you and that you may keep your duty, and that you may receive mercy?\"", "\"এটি কি খুব বেশি বিস্ময়ের যে স্মরণ করার একটি মাধ্যম তোমাদের প্রভুর পক্ষ থেকে আসা উচিত, তোমাদের মতো একজন মানুষের মাধ্যমে, তোমাদেরকে সতর্ক করতে, এবং তোমাদেরকে সৎকর্মশীলতার দিকে পরিচালিত করতে, যাতে তোমরা দয়া অর্জন করতে পারো?\""],
  "7:64": ["They denied him, so We saved him and those with him in the ship, and We drowned those who denied Our signs. They were a people unseeing.", "তারা তাকে প্রত্যাক্ষান করেছিল। ফলস্বরুপ, আমরা রক্ষা করেছিলাম তাকে এবং যারা তার সাথে নৌকায় ছিল এবং আমরা তাদেরকে ডুবিয়ে ছিলাম যারা আমাদের প্রকাশনাবলি প্রত্যাক্ষান করেছিল; তারা ছিল অন্ধ ।"],
  "7:65": ["And to Ad, their brother Hud: \"O my people, serve Allah — you have no ilah other than Allah. Will you not keep your duty?\"", "আ'দের কাছে আমরা তাদের ভাই হুদকে পাঠিয়েছিলাম। সে বলেছিল, \"হে আমার লোকেরা, আল্লাহর উপাসনা করো ; তাঁর পাশে তোমাদের অন্য উপাস্য নেই। তবে কি তোমরা সৎকর্মশীল হবে?"],
  "7:66": ["The chiefs who kafara among his people said: \"We see you in folly, and we think you are one of the kazibin.\"", "তার লোকেদের মধ্যে নেতারা যারা অবিশ্বাস করেছিল তারা বলেছিল, “আমরা দেখি যে তুমি বোকার মতো আচরণ করছ, এবং আমরা মনে করি যে তুমি একজন মিথ্যুক”।"],
  "7:67": ["He said: \"O my people, there is no folly in me, but I am a Rasul from the Rabb of the worlds.\"", "সে বলেছিল, “হে আমার লোকেরা, আমার মধ্যে কোন বোকামি নেই; আমি মহাবিশ্বের প্রভুর পক্ষ থেকে একজন বার্তাবাহক”।"],
  "7:68": ["\"I deliver to you the message of my Rabb, and I am a sincere, faithful adviser to you.\"", "“আমি তোমাদের কাছে আমার প্রভুর বার্তা পৌঁছে দিই, এবং আমি সততার সাথে তোমাদের উপদেশ দিচ্ছি।"],
  "7:69": ["\"Do you marvel that a reminder from your Rabb has come to you upon a man from among you, to warn you? Remember when Allah made you successors after the people of Nuh, and increased you abundantly in creation. Remember Allah's bounties, so that you may attain success.\"", "“এটি কি খুব বেশি বিস্ময়ের যে একটি বার্তা তোমাদের প্রভুর পক্ষ থেকে এসেছে, তোমাদের মতো একজন মানুষের মাধ্যমে, তোমাদেরকে সতর্ক করতে? স্মরণ করো যে তিনি তোমাদেরকে নুহের লোকদের পর উত্তরাধিকারী করেছিলেন, এবং তোমাদের সংখ্যা বৃদ্ধি করেছিলেন। স্মরণ করো, আল্লাহর কৃপা, যাতে তোমরা সফলকাম হতে পারো।"],
  "7:70": ["They said: \"Have you come to us that we should serve Allah alone, and leave what our fathers served? Bring us what you promise us, if you are of the sadiqin.\"", "তারা বলেছিল, “তুমি কি এসেছ আমাদেরকে একমাত্র আল্লাহর উপাসনা করাতে,এ বং আমাদের মাতাপিতারা যা উপাসনা করতো তা পরিত্যাগ করাতে? আমরা তোমাকে সে অনিবার্য ধ্বংস চ্যালেঞ্জ করি যা দিয়ে তুমি আমাদের ভয় দেখাও, যদি তুমি সত্যবাদী হও।"],
  "7:71": ["He said: \"Ruin and wrath from your Rabb have befallen you. Do you dispute with me over names that you and your fathers named, for which Allah sent down no warrant? Wait then — I am with you among those waiting.\"", "সে বলেছিল, \"তোমরা তোমাদের প্রভুর পক্ষ থেকে শাস্তি এবং ক্রোধ টেনে এনেছ। তোমরা কি আমার সাথে তর্ক করো তোমাদের বানানো বিষয় সমূহের সমর্থনে যা তোমরা মিথ্যা ভাবে গড়েছো- তোমরা এবং তোমাদের পিতা-মাতারা - যা কখনোই আল্লাহ দ্বারা অনুমোদিত ছিল না? সুতরাং, অপেক্ষা করো এবং আমি তোমাদের সাথে অপেক্ষা করবো।\""],
  "7:72": ["So We saved him and those with him by a mercy from Us, and We cut off the remnant of those who denied Our signs; and they were not muminin.", "আমরা তখন রক্ষা করেছিলাম তাকে এবং যারা তার সাথে ছিল, আমাদের পক্ষ থেকে দয়ার দ্বারা, এবং আমরা তাদেরকে ধ্বংস করেছিলাম যারা আমাদের প্রকাশনাবলি প্রত্যাক্ষান করেছিল এবং বিশ্বাসী হতে অস্বীকার করেছিল।"],
  "7:73": ["And to Thamud, their brother Salih: \"O my people, serve Allah — you have no ilah other than Allah. Clear proof has come to you from your Rabb: this is Allah's naqah, a sign for you. Leave her to eat in Allah's land, and do not harm her, lest a painful punishment take you.\"", "সামুদের কাছে আমরা তাদের ভাই সালেহকে পাঠিয়েছিলাম। সে বলেছিল, \"হে আমার লোকেরা, আল্লাহর উপাসনা করো ; আল্লাহর পাশে তোমাদের অন্য কোন উপাস্য নেই।  তোমাদের জন্য তোমাদের প্রভুর পক্ষ থেকে প্রমান দেয়া হয়েছে: এই যে আল্লাহর উট, তোমাদের জন্য একটি নিদর্শন। একে আল্লাহর দেয়া জমি থেকে খেতে দাও, এবং কোনো ক্ষতির উদ্দেশ্যে একে স্পর্শ করো না, পাছে তোমরা এক যন্ত্রনাদায়ক শাস্তি টেনে আনো।"],
  "7:74": ["\"Remember when Allah made you successors after Ad, and settled you in the land: you take palaces from its plains, and hew houses from the mountains. Remember Allah's bounties, and do not ravage in the earth as corrupters.\"", "\"স্মরন করো যে, তিনি আদের পর তোমাদের উত্তরাধিকারী করেছিলেন, এবং পৃথিবীর উপর তোমাদেরকে প্রতিষ্ঠিত করেছিলেন, এর উপত্যকায় অট্রালিকা তৈরী করে, এবং এর পাহাড়ে বাড়ি খোদাই করে। তোমরা আল্লাহর আশীর্বাদকে স্মরণ করবে, এবং পৃথিবীতে দূর্নীতি করে বেড়িও না।\""],
  "7:75": ["The chiefs who showed pride among his people said to those they had weakened, to those who believed among them: \"Do you know that Salih is a Rasul from his Rabb?\" They said: \"Indeed we believe in what he was sent with.\"", "তার লোকদের মধ্যে উদ্ধত নেতারা সেসব সাধারন লোকদের বলেছিল যারা বিশ্বাস করেছিল, \"তোমরা কিভাবে জানো যে সালেহ তার প্রভুর পক্ষ থেকে প্রেরিত?” তারা বলেছিল, \"যে বার্তা সে এনেছিল, তা আমাদেরকে বিশ্বাসী করেছে।\""],
  "7:76": ["Those who showed pride said: \"Indeed we disbelieve in what you believed in.\"", "উদ্ধত লোকেরা বলেছিল, “তোমরা যা বিশ্বাস করো  তা আমরা অবিশ্বাস করি”।"],
  "7:77": ["So they hamstrung the naqah, and insolently defied their Rabb's command, and said: \"Salih, bring us what you promise us, if you are of the Rasuls.\"", "ফলস্বরূপ, তারা উটটি হত্যা করেছিল, তাদের প্রভুর হুকুমের বিরুদ্ধে বিদ্রোহ করেছিল, এবং বলেছিল, \"হে সালেহ, নিয়ে আসো সেই অনিবার্য ধ্বংস যা দিয়ে তুমি আমাদের ভয় দেখাও, যদি সত্যি তুমি একজন বার্তাবাহক হও”।"],
  "7:78": ["So the earthquake seized them, and they became, in their home, sprawled.", "ফলস্বরূপ, ভূমিকম্প তাদের নির্মূল করেছিল, তাদেরকে তাদের বাড়িতে মৃত ফেলে রেখে।"],
  "7:79": ["He turned away from them and said: \"O my people, I have delivered to you the message of my Rabb and advised you sincerely, but you do not love sincere advisers.\"", "সে তাদের থেকে মুখ ফিরিয়ে নিয়েছিল, এই বলে, “হে আমার লোকেরা, আমি আমার প্রভুর বার্তা তোমাদের কাছে পৌঁছিয়েছি, এবং তোমাদের উপদেশ দিয়েছি, কিন্তু তোমরা কোন উপদেশ প্রদানকারী পছন্দ করো না”।"],
  "7:80": ["And Lut, when he said to his people: \"Do you commit the obscenity that no one in the worlds has done before you?\"", "লুত তার লোকদের বলেছিল, “তোমরা এমন নিদারুন ঘৃণ্য কাজে লিপ্ত; বিশ্বে কেউ আগে এটা করেনি!”"],
  "7:81": ["\"You approach the males of the worlds and abandon what your Rabb made for you of mates. Indeed you are a people transgressing.\"", "\"তোমরা মহিলাদের বদলে পুরুষদের সাথে যৌণ চর্চা করো। প্রকৃতপক্ষে, তোমরা একটি সীমালঙ্ঘনকারী সম্প্রদায়।"],
  "7:82": ["The answer of his people was only to say: \"Drive them out of your town — they are people who keep themselves pure.\"", "তার লোকেরা এই বলে সাড়া দিয়েছিল যে, \"তাদেরকে তোমার শহর থেকে তাড়াও। তারা এমন লোক যারা সচ্চরিত্রবান হতে চায়।\""],
  "7:83": ["So We saved him and his family, except his imra'a — she was among those left behind.", "ফলস্বরুপ, আমরা তাকে এবং তার পরিবারকে রক্ষা করেছিলাম, কিন্তু তার স্ত্রীকে নয়;  সে ধ্বংসপ্রাপ্তদের সাথে ছিল।"],
  "7:84": ["And We rained upon them a rain. See how the end of the mujrimin was.", "আমরা একটি নির্দিষ্ট বর্ষন তাদের উপর বর্ষিত করেছিলাম; সেসব অপরাধীর পরিণতি লক্ষ্য করো।"],
  "7:85": ["And to Midian, their brother Shu'ayb: \"O my people, serve Allah — you have no ilah other than Allah. Clear proof has come to you from your Rabb. Give full measure and weight, do not diminish people their goods, and do not work corruption in the earth after its setting right. That is better for you, if you are muminin.\"", "মাদিয়ানবাসীর কাছে আমরা তাদের ভাই শোয়েবকে পাঠিয়েছিলাম। সে বলেছিল, \"হে আমার লোকেরা, আল্লাহর উপাসনা করো; তাঁর পাশে তোমাদের অন্য কোন উপাস্য নেই। তোমাদের প্রভুর পক্ষ থেকে তোমাদের কাছে প্রমান এসেছে। তোমরা পূর্ণ ওজন এবং পূর্ণ মাপ দিবে, যখন তোমরা ব্যবসা করো। লোকদেরকে তাদের অধিকার থেকে ঠকিও না। পৃথিবীকে কলুষিত করো না, এটি পরিশুদ্ধ করার পর। এটি তোমাদের জন্য উত্তম, যদি তোমরা বিশ্বাসী হও।"],
  "7:86": ["\"Do not sit in wait on every path, threatening, and turning away from the way of Allah those who believe in Allah, and seeking to make it crooked. Remember when you were few, and Allah multiplied you. See how the end of the corrupters was.\"", "“বিরত হও প্রত্যেক পথে বাঁধা দেয়া হতে , আল্লাহর পথ থেকে তাদেরকে তাড়িয়ে দেয়ার প্রয়াসে যারা বিশ্বাস করে, এবং একে বক্র করো না। স্মরণ করো যে, তোমরা সংখ্যায় কম ছিলে এবং তিনি তোমাদের সংখ্যা বৃদ্ধি করেছিলেন। স্মরণ করো, পাপীদের পরিণতি।"],
  "7:87": ["\"If a party of you has believed in what I was sent with, and a party has not believed, be of the sabirin until Allah judges between us; and Allah is the best of judges.\"", "“এখন যেহেতু তোমাদের কেউ কেউ বিশ্বাস করেছ তাতে যা নিয়ে আমি প্রেরিত  হয়েছি, এবং কেউ কেউ অবিশ্বাস করেছ, অপেক্ষা করো  যতক্ষণ পর্যন্ত না আল্লাহ আমাদের মধ্যে তাঁর রায় দেন; তিনি সর্বোত্তম বিচারক।"],
  "7:88": ["The chiefs who showed pride among his people said: \"We will surely drive you out, Shu'ayb, and those who believed with you, from our town, or you shall return to our way.\" He said: \"Even if we are unwilling?\"", "তার লোকদের মধ্যে উদ্ধত নেতারা বলেছিল, “আমরা তোমাকে উচ্ছেদ করবো, হে সোয়েব, তাদের সাথে একত্রে যারা তোমার সাথে বিশ্বাস করেছিল, আমাদের শহর থেকে, যদি না তোমরা আমাদের ধর্মে ফিরে আসো। “সে বলেছিল, “তোমরা কি আমাদের জোর করতে যাচ্ছ?"],
  "7:89": ["\"We would have fabricated against Allah a lie if we returned to your way after Allah saved us from it. It is not for us to return into it unless Allah our Rabb wills. Our Rabb encompasses all things in knowledge. Upon Allah we have placed our trust. Our Rabb, decide between us and our people with the truth — and You are the best of deciders.\"", "“আমরা আল্লাহর বিরুদ্ধে মিথ্যা আরোপকারী হয়ে যাব, যদি আমরা তোমাদের ধর্মে প্রত্যাবর্তন করি, আল্লাহ আমাদেরকে তা থেকে রক্ষা করার পর। আমাদের প্রভু আল্লাহর ইচ্ছার বিরুদ্ধে কেমন করে আমরা পুনরায় এতে প্রত্যাবর্তন করতে পারি? আমাদের প্রভুর জ্ঞান সকল বস্তুকে বেষ্টন করে আছে। আমরা আল্লাহর প্রতি আমাদের আস্থা রেখেছি। আমাদের প্রভু, আমাদেরকে আমাদের লোকদের উপর চূড়ান্ত বিজয় দিন। আপনি সর্বোত্তম সমর্থনকারী”।"],
  "7:90": ["The chiefs who kafara among his people said: \"If you follow Shu'ayb, you are surely losers.\"", "তার লোকদের মধ্যে অবিশ্বাসী নেতারা বলেছিল, “যদি তোমরা সোয়েবকে অনুসরণ করো, তোমরা ক্ষতিগ্রস্ত হবে”।"],
  "7:91": ["So the earthquake seized them, and they became, in their home, sprawled.", "ভূমিকম্প তাদেরকে নির্মূল করেছিল, তাদেরকে তাদের বাড়িতে মৃত ফেলে রেখে।"],
  "7:92": ["Those who denied Shu'ayb became as if they had never flourished in it. Those who denied Shu'ayb — it was they who were the khasirin.", "যারা শোয়েবকে প্রত্যাক্ষান করেছিল তারা বিলুপ্ত হয়েছিল, যেন কখনোই তাদের অস্তিত্ব ছিল না। যারা শোয়েবকে প্রত্যাক্ষান করেছিল তারা ছিল ক্ষতিগ্রস্ত।"],
  "7:93": ["He turned away from them and said: \"O my people, I have delivered to you the messages of my Rabb and advised you sincerely. How shall I grieve for a people who denied?\"", "সে তাদের থেকে মুখ ফিরিয়ে নিয়েছিল, এই বলে, \"হে আমার লোকেরা, আমি আমার প্রভুর বার্তা তোমাদের কাছে পৌছিঁয়েছি, এবং আমি তোমাদেরকে উপদেশ দিয়েছি। কিভাবে আমি অবিশ্বাসী লোকদের জন্য দু:খ করতে পারি।\""],
  "7:94": ["We sent no Nabi to any town but We seized its people with hardship and harm, so that they might plead humbly.", "যখনই আমরা কোন সম্প্রদায়ের কাছে কোন নবী পাঠিয়েছিলাম, আমরা এর লোকদেরকে প্রতিকূলতা এবং কষ্ট দিয়ে দূর্দশাগ্রস্থ করেছিলাম, যাতে তারা মিনতি করে।"],
  "7:95": ["Then We substituted in place of the bad the good, until they multiplied and said: \"Hardship and ease touched our fathers before.\" So We seized them suddenly, while they were unaware.", "এরপর আমরা ঐ কষ্টের জায়গায় শান্তি এবং সমৃদ্ধি প্রতিস্থাপিত করেছিলাম। কিন্তু হায়, তারা অমনোযোগী হয়ে পড়েছিল এবং বলেছিল, \"আমাদের মাতাপিতারাও সমৃদ্ধির পূর্বে ঐ কষ্ট ভোগ করেছিল।” ফলস্বরুপ, আমরা তাদের শাস্তি দিয়েছিলাম আকষ্মিকভাবে, যখন তারা খুব অল্পই এমনটা ভেবেছিল।"],
  "7:96": ["If the people of the towns had believed and kept their duty, We would have opened upon them blessings from the heaven and the earth. But they denied, so We seized them for what they earned.", "ঐসব সম্প্রদায়ের লোকরা যদি বিশ্বাস করতো এবং সৎকর্মশীলতে পরিনত হতো, আমরা আকাশ এবং পৃথিবী থেকে তাদের আশীর্বাদ বর্ষণ করতাম। যেহেতু তারা অবিশ্বাস করার সিদ্ধান্ত নিয়েছিল, আমরা তাদেরকে শাস্তি দিয়েছিলাম তার জন্য, যা তারা অর্জন করেছিল।"],
  "7:97": ["Do the people of the towns feel secure that Our might will come to them by night while they sleep?", "বর্তমান সম্প্রদায়ের লোকেরা কি নিশ্চয়তা দেয় যে, আমাদের শাস্তি রাতে তাদের কাছে আসবে না, যখন তারা ঘুমন্ত?"],
  "7:98": ["Or do the people of the towns feel secure that Our might will come to them in the forenoon while they play?", "বর্তমান সম্প্রদায়ের লোকেরা কি নিশ্চয়তা দেয় যে আমাদের শাস্তি দিনে তাদের কাছে আসবে না, যখন তারা খেলায় মগ্ন?"],
  "7:99": ["Do they feel secure from Allah's plan? None feels secure from Allah's plan except the losing people.", "তারা কি আল্লাহর পরিকল্পনাকে আবজ্ঞা করেছে? দুর্ভাগারা ছাড়া কেউ আল্লাহর পরিকল্পনাকে আবজ্ঞা করে না।"],
  "7:100": ["Is it not clear to those who inherit the earth after its people, that if We willed We could strike them for their offenses, and stamp upon their hearts so that they do not hear?", "যারা পূর্ববর্তী প্রজন্মের পর পৃথিবীকে উত্তরাধিকার করে কখনো কি এটা তাদের উপলব্ধি হয় যে, আমরা যদি চাই, আমরা তাদের পাপের জন্য তাদের শাস্তি দিতে পারি, এবং তাদের হৃদয়ে মোহর মেরে দিতে পারি, তাদেরকে বধির করে দিয়ে?"],
  "7:101": ["Those are the towns whose tidings We relate to you. Their rusul came to them with clear proofs, but they could not believe in what they had denied before. Thus does Allah stamp upon the hearts of those who deny.", "আমরা তোমার কাছে সেসব সম্প্রদায়ের ইতিহাস বর্ননা করি: তাদের কাছে তাদের বার্তাবাহকেরা সুস্পষ্ট প্রমানাদি নিয়ে গিয়েছিল, কিন্তু তারা বিশ্বাস করার ছিল না তাতে, যা তারা পূর্বেই প্রত্যাক্ষান করেছিল। আল্লাহ এভাবে অবিশ্বাসীদের অন্তরে মোহর এটে দেন।"],
  "7:102": ["We found most of them without pact, and We found most of them defiant.", "আমরা পেয়েছিলাম যে,তাদের বেশির ভাগ তাদের অংগীকার উপেক্ষা করে; আমরা তাদের বেশির ভাগকে পাপী পেয়েছিলাম।"],
  "7:103": ["Then We raised after them Musa, with Our signs, to Fir'awn and his chiefs, but they wronged with them. See how the end of the corrupters was.", "সেসব বার্তাবাহকদের) পর, আমরা ফেরাউন এবং তার লোকদের কাছে আমাদের নিদর্শনাবলি দিয়ে মুসাকে পাঠিয়েছিলাম, কিন্তু তারা সীমালঙ্ঘন করেছিল। লক্ষ্য করো,পাপীদের পরিণতি।"],
  "7:104": ["And Musa said: \"Fir'awn, I am a Rasul from the Rabb of the worlds,\"", "মূসা বলেছিল, \"হে ফেরাউন, আমি মহাবিশ্বের প্রভুর পক্ষ থেকে একজন বার্তাবাহক।"],
  "7:105": ["\"obligated to say nothing of Allah except the truth. I have come to you with clear proof from your Rabb, so send with me the Children of Israel.\"", "\"এটি আমার উপর অবশ্য পালনীয় যে,আমি আল্লাহ সম্পর্কে সত্য ছাড়া বলি না। আমি তোমাদের প্রভুর পক্ষ থেকে একটি নিদর্শন নিয়ে এসেছি; ইসরাইলের সন্তানদের যেতে দাও।"],
  "7:106": ["He said: \"If you have come with a sign, then bring it, if you are of the sadiqin.\"", "সে বলেছিল, “যদি তোমার একটি নিদর্শন থাকে,তাহলে তা উপস্থাপন করো,যদি তুমি সত্যবাদী হও”।"],
  "7:107": ["So he threw down his staff, and behold — it was a clear serpent.", "সে তার লাঠি নিক্ষেপ করেছিল, এবং এটি এক ভয়ানক সাপে পরিনত হয়েছিল।"],
  "7:108": ["And he drew out his hand, and behold — it was white to the onlookers.", "সে তার হাত বের করেছিল, এবং এটি ছিল দর্শকদের কাছে সাদা।"],
  "7:109": ["The chiefs of Fir'awn's people said: \"This is a master sorcerer,\"", "ফেরাউনের লোকদের নেতারা বলেছিল, \"সে একজন চতুর যাদুকর ছাড়া বেশি কিছু নয়।"],
  "7:110": ["\"who wants to drive you out of your land. What do you command?\"", "“সে তোমাদেরকে তোমাদের দেশ থেকে বের করে নিয়ে যেতে চায়; তোমরা কি পরামর্শ দাও?”"],
  "7:111": ["They said: \"Put him off, and his brother, and send into the cities summoners\"", "তারা বলেছিল, \"তাকে এবং তার ভাইকে অবকাশ দিন, এবং আহ্বানকারীদেরকে প্রত্যেক শহরে পাঠান।"],
  "7:112": ["\"to bring you every cunning sorcerer.\"", "\"তাদেরকে সকল অভিজ্ঞ যাদুকরদের একত্র করতে দিন।\""],
  "7:113": ["The sorcerers came to Fir'awn. They said: \"We shall surely have a reward if we are the ones who prevail?\"", "যাদুকররা ফেরাউনের কাছে এসেছিল এবং বলেছিল, \"যদি আমরা জয়ী হই, আমরা কি পারিশ্রমিক পাবো?\""],
  "7:114": ["He said: \"Yes — and you shall be among those brought near.\"", "সে বলেছিল, \"হ্যা নিশ্চয়ই; তোমরা এমনকি আমার নিকটবর্তী হবে।\""],
  "7:115": ["They said: \"Musa, either you cast, or we shall be the ones to cast.\"", "তারা বলেছিল, \"হে মূসা, হয় তুমি ছোড়ো, অথবা আমরা ছুড়ছি।\""],
  "7:116": ["He said: \"Cast.\" So when they cast, they bewitched the people's eyes and struck terror into them, and brought mighty sorcery.", "সে বলল, “তোমরা ছোড়ো”। যখন তারা ছুঁড়ল, তারা লোকদের চোখকে ধোঁকা দিলো, তাদেরকে ভয় দেখালো, এবং একটি বিশাল যাদু উপস্থাপন করলো।"],
  "7:117": ["And We revealed to Musa: \"Throw your staff.\" And behold — it swallowed what they fabricated.", "আমরা তখন মুসাকে উদ্বুদ্ধ করলামঃ “তোমার লাঠি ছোড়ে ফেলো,” যার ফলে তা গিলে ফেললো, যা কিছু তারা মিথ্যা বানিয়েছিল।"],
  "7:118": ["So the truth came to pass, and what they were doing proved false.", "এভাবে, সত্য জয়ী হলো, এবং যা তারা করেছিল, তা অকার্যকর হলো।"],
  "7:119": ["Thus they were overcome there, and turned back, humbled.", "তারা তৎক্ষণাৎ পরাজিত হলো; তারা অপদস্ত হলো।"],
  "7:120": ["And the sorcerers fell down prostrating.", "যাদুকরেরা সেজদায় পড়লো।"],
  "7:121": ["They said: \"We believe in the Rabb of the worlds,\"", "তারা বলল, \"আমরা মহাবিশ্বের প্রভুকে বিশ্বাস করি।"],
  "7:122": ["\"the Rabb of Musa and Harun.\"", "\"মূসা এবং হারুনের প্রভুকে।\""],
  "7:123": ["Fir'awn said: \"You believed in him before I gave you leave. This is a scheme you schemed in the city, to drive its people out. You shall soon know.\"", "ফেরাউন বলল, \"তোমরা কি আমার অনুমতি ছাড়া তাকে বিশ্বাস করলে? এটি অবশ্যই একটি ষড়যন্ত্র হবে, যা তোমরা শহরে পরিকল্পনা করেছিলে, এর লোকদেরকে সরিয়ে নিয়ে যেতে। তোমরা অবশ্যই দেখতে পাবে।"],
  "7:124": ["\"I will surely cut off your hands and your feet on opposite sides, then I will surely crucify you all together.\"", "“আমি তোমাদের হাত এবং পা বিপরীত দিক থেকে কাটবো, এরপর আমি তোমাদের সবাইকে ক্রুশবিদ্ধ করবো।\""],
  "7:125": ["They said: \"Indeed to our Rabb we shall return.\"", "তারা বলল, \"আমরা এরপর আমাদের প্রভুর নিকট ফিরে যাবো।"],
  "7:126": ["\"Why do you requite us except that we believed in the signs of our Rabb when they came to us? Our Rabb, pour upon us patience, and take us to Yourself as those who submit.\"", "“তুমি আমাদেরকে শুধুমাত্র এ কারনে নির্যাতন করো যে আমরা আমাদের প্রভুর প্রমানে বিশ্বাস করেছি, যখন সেগুলো আমাদের কাছে এসেছে। “আমাদের প্রভু, আমাদের দৃড়তা প্রদান করুন, এবং আমাদেরকে আত্মসমর্পণকারী হিসেবে মৃত্যু দিন”।"],
  "7:127": ["The chiefs of Fir'awn's people said: \"Will you leave Musa and his people to work corruption in the land, and leave you and your ilahs?\" He said: \"We shall kill their sons and spare their nisa, and we are triumphant over them.\"", "ফেরাউনের লোকদের নেতারা বলল, “আপনি কি মুসা এবং তার লোকদের পৃথিবীকে কলুষিত করতে দেবেন, এবং আপনাকে এবং আপনার উপাস্যদেরকে পরিত্যাগ করতে দেবেন?” সে বলল, “আমরা তাদের পুত্রদের হত্যা করবো, এবং কন্যাদের নিষ্কৃতি দেবো। আমরা তাদের থেকে অনেক বেশি শক্তিশালী”।"],
  "7:128": ["Musa said to his people: \"Seek help from Allah and be of the sabirin. The earth belongs to Allah — Allah gives it as inheritance to whom Allah wills of the servants; and the final outcome is for the mindful.\"", "মুসা তার লোকদের বলল, “আল্লাহর সাহায্য প্রার্থনা করো, এবং দৃড়তার সাথে অধ্যবসায়ী হও। পৃথিবী আল্লাহর, এবং তিনি এটি প্রদান করেন তাঁর দাসদের মধ্যে থেকে যাকে তিনি পছন্দ করেন। চূড়ান্ত বিজয় সৎকর্মশীলদের।"],
  "7:129": ["They said: \"We were harmed before you came to us, and after you came to us.\" He said: \"Perhaps your Rabb will destroy your enemy and make you successors in the land, to see how you act.\"", "তারা বলল, “আমরা নির্যাতিত ছিলাম - তুমি আমাদের কাছে আসার আগে, এবং তুমি আমাদের কাছে আসার পরে”। সে বলল, “তোমাদের প্রভু তোমাদের শত্রুকে সম্পূর্ন ধ্বংস করবেন এবং তোমাদেরকে পৃথিবীতে প্রতিষ্ঠিত করবেন, এরপর তিনি দেখবেন - তোমরা কেমন আচরণ করো”।"],
  "7:130": ["We seized the family of Fir'awn with years, and diminished fruits, so that they might remember.", "আমরা এরপর ফেরাউনের লোকদের খরা, এবং ফসলের ঘাটতি দিয়ে দুর্দশাগ্রস্থ করলাম, যাতে তারা সতর্ক হয়।"],
  "7:131": ["When good came to them they said: \"This is ours.\" And if evil befell them, they took it as an omen through Musa and those with him. Beware — their omen was only with Allah; but most of them do not know.", "যখন তাদের সামনে শুভ লক্ষনসমূহ আসতো, তারা বলতো, “আমরা এর উপযুক্ত হয়েছি,” কিন্তু যখন কোন কষ্ট তাদেরকে পীড়া দিতো, তারা মূসাকে এবং তার সাথে যারা ছিল তাদেরকে দোষী করতো। প্রকৃতপক্ষে, তাদের লক্ষনসমূহ শুধুমাত্র আল্লাহর দ্বারা সিদ্ধান্তকৃত, কিন্তু তাদের বেশির ভাগ জানে না।"],
  "7:132": ["They said: \"Whatever sign you bring us to bewitch us with it — we shall not believe in you.\"", "তারা বলল, “তুমি আমাদেরকে যে রকমের নিদর্শনই দেখাও না কেন, তোমার যাদু দিয়ে আমাদেরকে প্রতারিত করতে, আমরা বিশ্বাস করবো না।’’"],
  "7:133": ["So We sent upon them the flood, and the locusts, and the lice, and the frogs, and the blood — detailed signs. But they showed pride, and were a mujrim people.", "ফলস্বরূপ, আমরা তাদের উপর পাঠিয়েছিলাম বন্যা, পঙ্গপাল, উকুন, ব্যাঙ, এবং রক্ত- প্রগাড় নিদর্শনাবলি। কিন্তু তারা তাদের দাম্ভিকতা বজায় রাখলো। তারা মন্দ লোক ছিল।"],
  "7:134": ["And when the affliction fell upon them, they said: \"Musa, call on your Rabb for us by the pledge that is with you. If you remove from us the affliction, we will surely believe you, and we will surely send with you the Children of Israel.\"", "যখনই কোন মহামারি তাদের দূর্দশাগ্রস্থ করতো, তারা বলতো “হে মূসা, তোমার প্রভুর কাছে মিনতি করো- তুমি তাঁর নিকটবর্তী। যদি তুমি এই মহামারি দূর করো, আমরা তোমার সাথে বিশ্বাস করবো, এবং ইসরাইলের সন্তানদের তোমার সাথে পাঠাব।”"],
  "7:135": ["Then when We removed from them the affliction, to an appointed term that they reached, at once they broke their pledge.", "এরপরও, যখন কিছু সময়ের জন্য আমরা মহামারী দূর করতাম, তারা তাদের অংগীকার ভঙ্গ করতো।"],
  "7:136": ["So We requited them, and drowned them in the sea, for they denied Our signs and were heedless of them.", "ফলস্বরূপ, আমরা তাদের কাজের প্রতিশোধ গ্রহণ করলাম, এবং তাদের সাগরে ডুবিয়ে দিলাম। এটা এ কারনে যে তারা আমাদের নিদর্শন প্রত্যাখ্যান করেছিল, এবং তা হতে পুরোপুরি অমনোযোগী ছিল।"],
  "7:137": ["And We made the people who had been weakened inherit the eastern parts of the land and its western parts, which We had blessed. And the fairest word of your Rabb was completed for the Children of Israel, for their patience. And We destroyed what Fir'awn and his people made, and what they raised.", "আমরা নির্যাতিত লোকদের ভূমির উত্তরাধিকারী করলাম, পূর্ব এবং পশ্চিম, এবং আমরা একে মহিমান্বিত করলাম। তোমার প্রভুর পবিত্র হুকুম এভাবে ইসরাইলের সন্তানদের জন্য পরিপূর্ণ হয়েছিল, তাদেরকে তাদের ধৈর্য্যশীলতার জন্য পুরস্কৃত করতে, এবং আমরা নির্মূল করেছিলাম ফেরাউন ও তার লোকদের কাজ এবং তাদের ফলানো সবকিছু।"],
  "7:138": ["And We brought the Children of Israel across the sea, and they came upon a people cleaving to idols they had. They said: \"Musa, make for us a ilah as they have alihah.\" He said: \"You are an ignorant people.\"", "আমরা ইসরাইলের সন্তানদের সাগর পার করালাম। যখন তারা পাশ দিয়ে যাচ্ছিলো সেই লোকদের, যারা মূর্তি পুজা করছিল, তারা বলল, “হে মুসা,তাদের উপাস্যের মতো আমাদের জন্য একটি উপাস্য বানাও”। সে বলল, “নিশ্চয়, তোমরা অজ্ঞ লোক।"],
  "7:139": ["\"These are ruined in what they are in, and void is what they were doing.\"", "“এইসব  লোকেরা এক মিথ্যাচারে লিপ্ত, তারা যা করছে এর ফল  তাদের জন্য ধ্বংসাত্মক।"],
  "7:140": ["He said: \"Shall I seek for you a ilah other than Allah, when Allah has favored you above the worlds?\"", "“আমি কি তোমাদের উপাস্য হতে আল্লাহ ছাড়া অন্য কাউকে খুঁজবো, যখন তিনি তোমাদেরকে বিশ্বের অন্য যে কারোর চেয়ে সৌভাগ্যবান করেছেন?”"],
  "7:141": ["And when We saved you from the family of Fir'awn, who were afflicting you with the worst of punishment, killing your sons and sparing your nisa. In that was a tremendous trial from your Rabb.", "স্মরণ করো যে আমরা তোমাদেরকে ফেরাউনের লোকদের থেকে রক্ষা করেছিলাম, যারা তোমাদের উপর নির্মম অত্যাচার চালাতো,তোমাদের পূত্রদের হত্যা করতো আর কন্যাদের ছেড়ে দিতো। তোমাদের প্রভুর পক্ষ থেকে সেটা ছিল তোমাদের জন্য একটি কঠিন পরীক্ষা।"],
  "7:142": ["We appointed Musa thirty nights, and completed them with ten, so the appointed time of his Rabb was completed at forty nights. And Musa said to his brother Harun: \"Take my place among my people, set things right, and do not follow the way of the corrupters.\"", "আমরা মুসাকে ডেকেছিলাম ত্রিশ রাতের জন্য, এবং সেগুলোকে পূর্ন করেছিলাম দশ যোগ করে। এভাবে, তার প্রভুর সাথে শ্রবন চল্লিশ  রাতের জন্য স্থায়ী হয়েছিল। মূসা তার ভাই হারুনকে বলল, \"এখানে আমার লোকদের সাথে থাকো, সৎকর্মশীলতা বজায় রাখো, এবং দূর্নীতিগ্রস্থ লোকদের পথ অনুসরণ করো না।\""],
  "7:143": ["And when Musa came to Our appointed time, and his Rabb spoke to him, he said: \"My Rabb, show me, that I may look upon You.\" Allah said: \"You will never see Me; but look at the mountain — if it remains firm in its place, then you will see Me.\" So when his Rabb unveiled glory to the mountain, Allah leveled it to dust, and Musa fell down thunderstruck. When he recovered, he said: \"Glory be to You — I turn to You in repentance, and I am the first of the muminin.\"", "যখন মুসা আমাদের নির্ধারিত সময়ে আসল, এবং তার প্রভু তার সাথে কথা বললেন, সে বলেছিল, \"আমার প্রভু,আমাকে আপনার দিকে তাকাতে এবং দেখতে দিন।” তিনি বললেন, \"তুমি আমাকে দেখতে পারো না। ঐ পাহাড়ের দিকে তাকাও; যদি এটি এর জায়গায় স্থির থাকে, তাহলে তুমি আমাকে দেখতে পারো।\" এরপর, তার প্রভু নিজেকে পাহাড়ে স্পষ্ট প্রকাশ করলেন, এবং এটি একে ভেঙ্গে গুঁড়িয়ে দিলো। মুসা অচেতন হয়ে পড়লো। যখন সে চেতনা ফিরে পেল, সে বলল, \"আপনি মহিমান্বিত। আমি আপনার নিকট অনুশোচনা করি, এবং আমি সর্বোচ্চ প্রমানপ্রাপ্ত বিশ্বাসী।\""],
  "7:144": ["Allah said: \"Musa, I have chosen you above people by My messages and by My word. So take what I have given you, and be among the thankful.\"", "তিনি বললেন, \"হে মুসা,আমি তোমাকে পছন্দ করেছি,সব লোকের মধ্য থেকে, আমার বার্তা দিয়ে এবং তোমার সঙ্গে কথা বলার মাধ্যমে। সুতরাং, আমি তোমাকে যা দিয়েছি তা গ্রহন করো এবং কৃতজ্ঞ হও।\""],
  "7:145": ["And We wrote for him on the tablets an admonition and a detailing of everything: \"Take them firmly, and command your people to take the best of them. I will show you the abode of the unilahly.\"", "আমরা তার জন্য ফলকের উপর সব ধরনের শিক্ষা এবং সকল কিছু বিস্তারিত লিখলাম: \"তুমি দৃড়ভাবে এইসব শিক্ষা ধারণ করবে, এবং তোমার লোকদের সেগুলো ধারণ করতে উদ্বুদ্ধ করবে- এগুলো সর্বোত্তম শিক্ষা। আমি তোমাকে মন্দদের পরিণতি দেখাবো।"],
  "7:146": ["I will turn away from My signs those who show pride in the earth without right. If they see every sign, they will not believe in it; and if they see the way of right guidance, they will not take it as a way; and if they see the way of error, they will take it as a way. That is because they denied Our signs and were heedless of them.", "আমার প্রকাশনাবলী থেকে আমি তাদেরকে সরিয়ে রাখবো যারা যথার্থ কারণ ছাড়া পৃথিবীতে উদ্ধত। ফলস্বরূপ, যখন তারা সব রকমের প্রমান দেখবে,তারা বিশ্বাস করবে না। এবং যখন তারা পথপ্রাপ্তির রাস্তা দেখবে তারা তাদের পথ হিসেবে এটি অবলম্বন করবে না,কিন্তু যখন তারা পথভ্রষ্টতার রাস্তা দেখবে তারা তাদের পথ হিসেবে এর অবলম্বন করবে। এটি হচ্ছে আমাদের প্রমানগুলোকে তাদের প্রত্যাক্ষান করার, এবং এতে সম্পূর্ণ অমনোযোগী থাকার ফল।"],
  "7:147": ["Those who deny Our signs and the meeting of the Hereafter — their deeds are void. Are they requited except for what they did?", "যারা প্রত্যাখ্যান করে আমাদের প্রকাশনাবলী এবং পরকালের সাক্ষাত, তাদের কাজ নিষ্ফল হয়। তারা যা করেছিল তারা কি শুধু তার জন্য প্রতিদানপ্রাপ্ত?"],
  "7:148": ["And the people of Musa took, after him, from their ornaments a calf — a body with a lowing sound. Did they not see that it did not speak to them, nor guide them to a way? They took it, and were wrongdoers.", "তার অনুপস্থিতিতে, মুসার লোকেরা তাদের অলঙ্কার থেকে তৈরি করল একটি বাছুরের মূর্তি, যা একটি বাছুরের ডাক করতে সক্ষম। তারা কি দেখেনি যে,এ টা তাদের সাথে কথা বলতে পারে না,অথবা তাদেরকে কোন রাস্তায় পথপ্রদর্শন করে না? তারা এর উপাসনা করল, এবং এভাবে মন্দে পরিণত হলো।"],
  "7:149": ["And when the truth fell into their hands and they saw that they had gone astray, they said: \"If our Rabb does not have mercy on us and forgive us, we shall surely be among the khasirin.\"", "অবশেষে,যখন তারা তাদের কাজের জন্য অনুতাপ করলো,এবং উপলব্ধি করলো যে তারা বিপথে গিয়েছে,তারা বলল, “যদি না আমাদের প্রভু আমাদের উদ্ধার করেন তাঁর দয়া দিয়ে,এবং ক্ষমা করেন, আমরা ক্ষতিগ্রস্ত হব”।"],
  "7:150": ["And when Musa returned to his people, angry and grieving, he said: \"How evil is what you did after me! Did you hasten your Rabb's command?\" And he threw down the tablets, and seized his brother by the head, dragging him. He said: \"Son of my mother, the people overpowered me and nearly killed me. Do not let the enemy gloat over me, and do not count me among the wrongdoing people.\"", "যখন মুসা তার লোকদের কাছে ফিরে আসল, রাগান্বিত ও হতাশ হল, সে বলল, “আমার অনুপস্থিতিতে তোমরা কি এক ভয়ানক জিনিস করেছ!” তোমরা কি তোমাদের প্রভুর প্রত্যাদেশের জন্য অপেক্ষা করতে পারনি?”সে ফলকগুলো ছুড়ে ফেলল, এবং তার ভাইয়ের মাথা ধরল, তাকে নিজের দিকে টেনে ধরে। (হারুন) বলল, “আমার মায়ের পুত্র, লোকেরা আমার দুর্বলতার সুযোগ নিয়েছিল, এবং প্রায় আমাকে মেরে ফেলেছিল। আমার শত্রুদের আনন্দিত হতে দিয়ো না, এবং আমাকে সীমাতিক্রমকারী লোকদের সাথে গণনা করো না”।"],
  "7:151": ["He said: \"My Rabb, forgive me and my brother, and bring us into Your mercy — and You are the most merciful of the merciful.\"", "(মূসা) বলল, \"আমার প্রভু,আমাকে এবং আমার ভাইকে ক্ষমা করুন, এবং আমাদেরকে প্রবেশ করান আপনার দয়ায়। সকল দয়াবানদের মধ্যে,আপনি সবচেয়ে দয়াবান।"],
  "7:152": ["Those who took the calf — wrath from their Rabb will reach them, and abasement in the life of this world. Thus We requite the fabricators.", "অবশ্যই, যারা বাছুরটির উপাসনা করলো তারা টেনে এনেছে তাদের প্রভুর তীব্র ক্রোধ, এবং এই জীবনে অবমাননা।  আমরা এভাবে নব-উদ্ভাবকদের থেকে প্রতিশোধ নেই।"],
  "7:153": ["And those who did evil deeds, then repented after them and believed — indeed your Rabb thereafter is forgiving, merciful.", "আর যারা পাপ করে,এরপর অনুশোচনা করে এবং বিশ্বাস করে, তোমাদের প্রভু - এরপর - ক্ষমাকারী,পরম দয়ালু।"],
  "7:154": ["And when the anger stilled upon Musa, he took up the tablets; and in their transcript was guidance and mercy for those who hold their Rabb in awe.", "যখন মুসার রাগ প্রশমিত হলো,সে  তুলে নিলো ফলকগুলো,যা পথ-প্রদর্শন ও দয়া সমৃদ্ধ- তাদের জন্য যারা তাদের প্রভুকে ভক্তি-শ্রদ্ধা করে।"],
  "7:155": ["And Musa chose from his people seventy men for Our appointed time. So when the earthquake seized them, he said: \"My Rabb, had You willed, You could have destroyed them before, and me too. Will You destroy us for what the foolish ones among us did? It is only Your trial, by which You lead astray whom You will and guide whom You will. You are our protecting friend, so forgive us and have mercy on us — and You are the best of forgivers.\"", "মুসা এরপর তার লোকেদের মধ্য থেকে সত্তর জনকে নির্বাচন করলো,আমাদের নির্ধারিত বৈঠকে আসতে। যখন ভূ-কম্পন তাদেরকে কম্পিত করলো,সে বলল, \"আমার প্রভু,অতীতে আপনি তাদেরকে ধ্বংস করতে পারতেন, একই সাথে আমাকেও, যদি আপনি এমনই ইচ্ছা করতেন। আপনি কি আমাদেরকে ধ্বংস করবেন আমাদের মধ্যকার তাদের কাজের জন্য যারা বোকা? এটি অবশ্যই একটি পরীক্ষা যা আপনি আমাদের জন্য প্রবর্তন করেছেন। এটি দিয়ে,আপনি দন্ড বিধান করেন যাকে আপনি ইচ্ছা করেন, এবং পথ- প্রদর্শন করেন যাকে আপনি ইচ্ছা করেন। আপনি আমাদের প্রভু এবং মনিব, তাই আমাদেরকে ক্ষমা করুন, আমাদেরকে আপনার দয়া বর্ষন করুন; আপনি সর্বোত্তম ক্ষমাকারী।"],
  "7:156": ["\"And write for us good in this world and in the Hereafter; indeed we have turned to You.\" Allah said: \"My punishment — I strike with it whom I will; and My mercy has encompassed all things. So I will write it for those who keep their duty, and give the due, and those who believe in Our signs,\"", "“এবং আমাদের জন্য সৎকর্মশীলতা জারী করুন, এই দুনিয়ায়, এবং পরকালে। আমরা আপনার কাছে অনুশোচনা করেছি”। তিনি বললেন, “আমার শাস্তি পতিত হয় যার উপর আমি চাই । কিন্তু আমার দয়া সবকিছুকে পরিবেষ্টন করে আছে। তা সত্ত্বেও, আমি তা নির্দিষ্ট করবো তাদের জন্য যারা (১) সৎকর্মশীল জীবন যাপন করে,(২)বাধ্যতামূলক দান (যাকাত) দেয়, (৩) আমাদের প্রকাশনাবলিতে বিশ্বাস করে,এবং"],
  "7:157": ["\"those who follow the Rasul, the unlettered Nabi, whom they find written with them in the Torah and the Gospel. He commands them the recognized, and forbids them the rejected, and makes wholesome things lawful for them, and forbids them the vile, and lifts from them their burdens and the fetters that were upon them. Those who believe in him, and support him, and help him, and follow the light sent down with him — those are the ones who attain success.\"", "“(৪) অনুসরণ করে বার্তাবাহককে,সেই উম্মী (যারা আগের ঐশীগ্রন্থ অনুসরণ করেনি) নবীকে(মুহাম্মাদ),যার ব্যাপারে তাদের তওরাত এবং ইঞ্জিলে লিখা আছে। সে তাদেরকে উৎসাহিত করে সৎকর্মশীল হতে,তাদেরকে মন্দ থেকে নিষেধ করে,সকল ভালো খাদ্য তাদের জন্য অনুমোদন করে,এবং নিষিদ্ধ করে যা কিছু মন্দ, এবং তাদের উপর আরোপিত বোঝা ও শৃঙ্খলসমূহের ভার মুক্ত করে। যারা তাকে বিশ্বাস করে,তাকে সন্মান করে,তাকে সমর্থন করে,এবং অনুসরণ করে সে আলো যা তার সাথে এসেছিল তারাই সফলকাম ব্যক্তি।"],
  "7:158": ["Say: \"O people, I am Allah's Rasul to you all — to whom belongs the kingdom of the heavens and the earth. There is no ilah but Allah; Allah gives life and death. So believe in Allah and the Rasul, the unlettered Nabi, who believes in Allah and Allah's word, and follow him, so that you may be guided.\"", "বল, “হে লোকেরা,আমি তোমাদের সকলের নিকট আল্লাহর বার্তাবাহক। আকাশমন্ডলী ও পৃথিবীর সার্বভৌম ক্ষমতা তাঁর। তিনি ব্যতিত কোন উপাস্য নেই। তিনি জীবন এবং মৃত্যু নিয়ন্ত্রন করেন”। অতএব, তোমরা বিশ্বাস করবে আল্লাহ এবং তাঁর বার্তাবাহককে,সেই উম্মী(যারা আগের ঐশীগ্রন্থ অনুসরণ করেনি) নবীকে,যে আল্লাহ এবং তাঁর বানী বিশ্বাস করে। তাকে অনুসরণ করো,যাতে তোমরা পথ প্রাপ্ত হতে পারো।"],
  "7:159": ["Among the people of Musa is a community guided by the truth, and by it they do justice.", "মুসার অনুসারীদের মধ্যে রয়েছে তারা যারা সত্য অনুসারে পথ প্রদর্শন করে,এবং সত্য তাদের সৎকর্মশীলতে পরিণত করে।"],
  "7:160": ["We divided them into twelve tribes, as communities. And We revealed to Musa, when his people asked him for drink: \"Strike the rock with your staff.\" So twelve springs gushed forth from it; each people knew its drinking place. We shaded them with the cloud canopy, and sent down upon them manna and quails: \"Eat of the good things We provided you.\" They did not wrong Us, but they were wronging themselves.", "আমরা তাদেরকে বারটি গোত্রীয় সম্প্রদায়ে ভাগ করলাম, এবং আমরা মুসাকে অনুপ্রাণিত করলাম যখন তার লোকেরা তার কাছে পানি চেয়েছিলঃ “তোমার লাঠি দিয়ে পাথরটিতে আঘাত করো,”যার ফলে,সেখান থেকে বারটি ঝর্না প্রবলবেগে বের হয়ে এলো। এরুপে,প্রত্যেক সম্প্রদায় এর পানি চিনলো। এবং আমরা তাদেরকে মেঘমালা দিয়ে ছায়া দিয়েছিলাম, এবং তাদের কাছে নাজিল করেছিলাম মান্না ও কয়েলঃ “তোমাদের জন্য আমাদের দেয়া ভালো জিনিস থেকে খাও।’’ তারা আমাদের ক্ষতি করেনি; তারা তাদের নিজেদেরেই আত্মার ক্ষতি করেছিল।"],
  "7:161": ["And when it was said to them: \"Dwell in this town, and eat from it wherever you wish, and say 'Pardon,' and enter the gate bowing — We will forgive you your misdeeds; We will increase the doers of good.\"", "স্মরণ করো যে তাদেরকে বলা হয়েছিল, \"বসবাস করতে এই শহরে ঢোক, এবং তোমাদের খুশিমতো তা থেকে খাও, লোকদের সাথে অমায়িক ব্যবহার করো,এবং দরজা দিয়ে বিনীতভাবে প্রবেশ করো। আমরা তাহলে তোমাদের সীমালঙ্ঘনগুলো ক্ষমা করবো। আমরা সৎকর্মশীলদের জন্য প্রতিদান বহুগুনে বৃদ্ধি করবো।\""],
  "7:162": ["But those who wronged among them substituted a word other than what was said to them. So We sent down upon them an affliction from the sky, for the wrong they were doing.", "কিন্তু,তাদের মধ্যকার মন্দ লোকেরা তাদেরকে দেয়া নির্দেশাবলিকে অন্য  নির্দেশাবলি দিয়ে প্রতিস্থাপন করলো। ফলস্বরুপ, আমরা আকাশ থেকে তাদের উপর দন্ডাদেশ পাঠালাম, তাদের অপকর্মের কারণে।"],
  "7:163": ["And ask them about the town that was present at the sea, when they transgressed the Sabbath: their fish came to them openly on their Sabbath day, and on the day they did not keep Sabbath they did not come. Thus We tried them for their defiance.", "তাদেরকে সাগর ধারের সম্প্রদায়ের বিষয়ে স্মরণ করাও, যারা সাব্বাথ (বিশ্রামের দিনকে) অপবিত্র করেছিল।  যখন তারা সাব্বাথ (বিশ্রামের দিন) পালন করতো,তাদের কাছে প্রচুর মাছ আসতো। এবং যখন তারা সাব্বাথ (বিশ্রামের দিন) লঙ্ঘন করতো,মাছ আসতো না। আমরা এভাবে তাদেরকে দুর্দশাগ্রস্থ করলাম, তাদের সীমালঙ্ঘনের ফলস্বরুপ।"],
  "7:164": ["And when a community among them said: \"Why do you admonish a people Allah is about to destroy, or punish with a severe punishment?\" They said: \"An excuse to your Rabb, and that perhaps they may keep their duty.\"", "স্মরণ করো যে তাদের এক দল বলল, “কেন তোমাদের সে লোকদের কাছে ধর্ম-প্রচার করা উচিত যাদের আল্লাহ অবশ্যই ধ্বংস করবেন বা কঠোর শাস্তি দিবেন?”তারা উত্তর দিলো,“তোমাদের প্রভুর কাছে ক্ষমা চাও, ”যাতে তারা রক্ষা পেতে পারে।"],
  "7:165": ["So when they forgot what they had been reminded of, We saved those who forbade the evil, and We seized those who wronged with a painful punishment, for their defiance.", "যখন তারা উপেক্ষা করলো যা তাদের স্মরণ করানো হয়েছিল, আমরা তাদের রক্ষা করলাম যারা মন্দ থেকে নিষিদ্ধ করেছিল, এবং মন্দকর্মীদের এক ভয়ানক শাস্তি দিয়ে দুদর্শাগ্রস্থ করলাম তাদের অপকর্মের জন্য।"],
  "7:166": ["So when they insolently defied what they had been forbidden, We said to them: \"Be apes, rejected.\"", "যখন তারা প্রত্যাদেশসমূহের বিরোধিতা করা অব্যাহত রাখলো,আমরা তাদের বললাম, “তোমরা ঘৃণ্য বানর হয়ে যাও”।"],
  "7:167": ["And when your Rabb declared that those would surely be raised against them until the Day of Resurrection, people who would inflict upon them the worst of punishment. Your Rabb is swift in requital — and indeed is forgiving, merciful.", "এছাড়াও, তোমার প্রভু হুকুম করেছেন যে তিনি তাদের বিপক্ষে সে লোকদের উথিত করবেন যারা তাদের উপর কঠিন নির্যাতন আরোপ করবে,পুনুরুত্থান দিবস পর্যন্ত। তোমাদের প্রভু শাস্তি জোরদারে সবচেয়ে দক্ষ, এবং তিনি নিঃসন্দেহে ক্ষমাশীল, পরম দয়ালু।"],
  "7:168": ["And We dispersed them through the lands as communities: among them are salih, and among them are otherwise. We tried them with good and with evil, so that they might return.", "আমরা তাদেরকে সমগ্র স্থলের অনেক সম্প্রদায়ের মধ্যে ছড়িয়ে দিলাম। তাদের কেউ কেউ সৎকর্মশীল ছিল, এবং কেউ কেউ কম সৎকর্মশীল ছিল। আমরা তাদেরকে পরীক্ষা করেছিলাম সমৃদ্ধি এবং অসচ্ছলতা দিয়ে,যাতে তারা ফিরে আসতে পারে।"],
  "7:169": ["Successors came after them who inherited the Book, taking the goods of this lower world and saying: \"We will be forgiven.\" And if goods like them come to them, they take them. Was not the pact of the Book taken upon them, that they should say of Allah nothing but the truth, and they studied what is in it? The abode of the Hereafter is better for those who keep their duty. Will you not reason?", "তাদের পরবর্তীতে,তিনি প্রতিস্থাপিত করেছিলেন নতুন প্রজন্ম যারা  ঐশীগ্রন্থ উত্তরাধিকার করেছিল। কিন্তু উলটো তারা দুনিয়ার জীবন পছন্দ করেছিল, এই বলে যে,“আমাদের ক্ষমা করা হবে”। কিন্তু তারা তখন এই দুনিয়ার বস্তু পছন্দ করাই অব্যাহত রেখেছিল। তারা কি ঐশীগ্রন্থ মেনে চলার, এবং আল্লাহ সম্পর্কে সত্য ছাড়া না বলার অঙ্গীকার করেনি? তারা কি ঐশীগ্রন্থ অধ্যয়ন করেনি? নিশ্চিতভাবে,যারা সৎকর্মশীলতা বজায় রাখে তাদের জন্য পরকালের বাসস্থান অনেক উত্তম। তোমরা কি বুঝো না?"],
  "7:170": ["And those who hold fast to the Book, and establish the prayer — indeed We do not lose the wage of those who set things right.", "তারা যারা ঐশীগ্রন্থ মেনে চলে,এবং সংযোগ প্রার্থনা (সালাত) প্রতিষ্ঠা করে,আমরা কখনো সৎকর্মশীলদের প্রতিদান দিতে ব্যর্থ হই না।"],
  "7:171": ["And when We wrenched the mountain above them as if it were a canopy, and they thought it would fall upon them: \"Take what We have given you with strength, and remember what is in it, so that you may keep your duty.\"", "আমরা একটি ছাতার মতো তাদের উপর পাহাড়টি তুলে ধরলাম, এবং তারা মনে করলো এটি তাদের উপর পড়তে যাচ্ছে  : “তোমরা মেনে চলবে যা আমরা তোমাদেরকে দিয়েছি,দৃঢভাবে এবং এর অভ্যন্তরস্থ বস্তু স্মরণ রাখবে,যাতে তোমরা রক্ষা পেতে পারো।”"],
  "7:172": ["And when your Rabb took from the children of Adam, from their backs, their offspring, and made them testify concerning themselves: \"Am I not your Rabb?\" They said: \"Yes, we testify\" — lest you say on the Day of Resurrection: \"We were unaware of this,\"", "স্মরণ করো যে তোমার প্রভু আদমের সকল সন্তানদের একত্র করলেন, এবং তাদেরকে তাদের নিজেদের জন্য সাক্ষী করলেন: \"আমি কি তোমাদের প্রভু নই?”তারা সকলে বলল, \"হ্যা,আমরা সাক্ষ্য দিচ্ছি।”এভাবে,তোমরা পুনরুত্থান দিবসে বলতে পারবে না,\"আমরা এ বিষয়ে অবহিত ছিলাম না।\""],
  "7:173": ["or lest you say: \"It was only our fathers who associated before, and we were descendants after them. Will You destroy us for what the void-doers did?\"", "না তোমরা বলতে পারবে,\"আমাদের মাতাপিতারাই তো শিরক চর্চা করতো,এবং আমরা শুধু তাদের পদাঙ্ক অনুসরণ করেছিলাম। আপনি কি অন্যরা যা প্রবর্তণ করেছে তার কারনে আমাদেরকে শাস্তি দিবেন?"],
  "7:174": ["Thus We detail the signs, and perhaps they will return.", "আমরা এভাবে প্রত্যাদেশাবলি ব্যাখ্যা করি,লোকদের উদ্ধারপ্রাপ্ত হতে তাদের নিজেদের সক্ষম করতে।"],
  "7:175": ["Relate to them the account of the one to whom We gave Our signs, and he stripped away from them, so Shaytan followed him, and he became one of the misled.", "তাদের জন্য আবৃত্তি করো সে ব্যক্তির সংবাদ যাকে আমাদের প্রমানাদি দেয়া হয়েছিল, কিন্তু সেগুলো উপেক্ষা করা পছন্দ করল। ফলস্বরুপ, শয়তান তার পিছনে লাগল, যতক্ষন না সে একজন পথভ্রষ্ট হলো।"],
  "7:176": ["Had We willed, We would have raised him by them; but he clung to the earth and followed his desire. His likeness is the likeness of a dog: if you burden it, it pants, and if you leave it, it pants. That is the likeness of a people who deny Our signs. So relate the narratives, so that they may reflect.", "আমরা যদি ইচ্ছা করতাম, আমরা তাকে ঐ অবস্থা সত্ত্বেও তুলে আনতে পারতাম, কিন্তু সে নীচে এঁটে থাকাতেই অনঁড় রইল, এবং তার নিজের মত অনুসরণ করলো। এরূপে,সে ঐ কুকুরের মতো; তুমি তাকে আদর করো অথবা বকুনী দাও, সে হাঁপায়। এমনই লোকদের উদাহরন যারা আমাদের প্রমানাদি প্রত্যাখ্যান করে। বর্ননা করো এসব কাহিনী,যাতে তারা অনুধাবন করতে পারে।"],
  "7:177": ["Evil indeed is the likeness of a people who denied Our signs while they were wronging themselves.", "মন্দ নিশ্চয়ই সেই লোকদের উদাহরণ যারা আমাদের প্রমানাদি প্রত্যাখ্যান করে; তারা শুধু তাদের নিজের আত্মারই ক্ষতি করে।"],
  "7:178": ["Whomever Allah guides — that is the one guided; and whomever Allah leads astray, those are the khasirin.", "যাকে আল্লাহ পথপ্রদর্শন করেন সেই সত্যিকার পথপ্রাপ্ত ব্যক্তি,এবং যাকে তিনি পথভ্রষ্ট করেন, এরাই ক্ষতিগ্রস্ত।"],
  "7:179": ["We have spread forth for Gehenna many of the jinn and humankind. They have hearts with which they do not understand, and eyes with which they do not see, and ears with which they do not hear. Those are like cattle — rather, they are more astray. Those are the unmindful.", "আমরা বহু সংখ্যক জীন এবং মানুষকে নরকে সোপর্দ করেছি। তাদের আছে মন যা দিয়ে তারা বোঝে না,চোখ যা দিয়ে তারা দেখে না,এবং কান যা দিয়ে তারা শোনে না। তারা পশুর মতো,না,তারা আরও অধিক মন্দ- তারা সম্পূর্ণ অসচেতন।"],
  "7:180": ["To Allah belong the most beautiful names, so call on Allah thereby. And leave those who deviate in the names — they will be requited for what they did.", "সবচেয়ে সুন্দর নামগুলো আল্লাহর; তাঁকে সেগুলো ধরে ডাকো,এবং তাদেরকে উপেক্ষা করো যারা তাঁর নাম বিকৃত করে। তারা তাদের পাপের জন্য প্রতিফল প্রাপ্ত হবে।"],
  "7:181": ["Among those We created is a community guided by the truth, and by it they do justice.", "আমাদের সৃষ্টির মধ্যে,রয়েছে তারা যারা সত্য দিয়ে পথ-প্রদর্শন করে,এবং সত্য তাদের সৎকর্মশীলতে পরিনত করে।"],
  "7:182": ["Those who deny Our signs — We will draw them on gradually from where they do not know.", "আর তাদের জন্য যারা আমাদের প্রকাশনাবলি প্রত্যাক্ষান করে,আমরা তাদের পরিচালনা করি তাদেরকে কখনো তা বুঝতে না দিয়ে।"],
  "7:183": ["I grant them respite. My scheme is firm.", "আমি এমনকি তাদের উৎসাহিত করবো,আমার পরিকল্পনা অজেয়।"],
  "7:184": ["Have they not reflected: their companion has no madness — he is only a clear warner.", "কেন তারা তাদের বন্ধুর বিষয়ে (বার্তাবাহক) চিন্তা-ভাবনা করে না? সে উন্মাদ নয়। সে শুধু একজন স্পষ্ট সতর্ককারী।"],
  "7:185": ["Have they not looked into the dominion of the heavens and the earth, and whatever Allah created of anything, and that perhaps their term has drawn near? In what account after it will they believe?", "তারা কি দেখে নি আকাশমন্ডলী  ও পৃথিবীর রাজত্য, এবং সে সবকিছু যা আল্লাহ সৃষ্টি করেছেন? এটা কখনো তাদের মনে হয় কী যে তাদের জীবনের সমাপ্তি হয়তো খুবই নিকটে? কোন হাদীস, এর পাশে,তারা বিশ্বাস করে?"],
  "7:186": ["Whomever Allah leads astray — there is no guide for that one; and Allah leaves them blundering in their transgression.", "যাকে আল্লাহ পথভ্রষ্টতায় লিপ্ত করেন, কারো জন্য কোন পথ নেই তাকে পথপ্রদর্শন করার। তিনি তাদেরকে তাদের পাপে ছেড়ে দেন, ঘুরপাকরত অবস্থায়।"],
  "7:187": ["They ask you about the Hour: \"When will it anchor?\" Say: \"Its knowledge is only with my Rabb. None unveils it at its time but Allah. It weighs heavily in the heavens and the earth. It comes to you only suddenly.\" They ask you as though you were intimate with it. Say: \"Its knowledge is only with Allah — but most people do not know.\"", "তারা তোমাকে জিজ্ঞাসা করে দুনিয়ার সমাপ্তি (সেই সময়) সম্পর্কে,এবং কখন তা সংঘটিত হবে। বল, “এর জ্ঞান আমার প্রভুর নিকট আছে। একমাত্র তিনি এর সময় প্রকাশ করেন। আকাশমন্ডলী  এবং পৃথিবীতে,এটি গুরুতর। হঠাৎ করে ছাড়া এটি তোমাদের কাছে আসবে না। তারা তোমাকে জিজ্ঞাসা করে,যেন তুমি এর নিয়ন্ত্রনে রয়েছ। বল, “এর জ্ঞান আল্লাহর নিকট আছে”,কিন্তু বেশির ভাগ মানুষ তা জানে না।"],
  "7:188": ["Say: \"I have no power over benefit or harm for myself, except what Allah wills. Had I known the unseen, I would have multiplied good for myself, and no evil would have touched me. I am only a warner and a bearer of glad tidings for a people who believe.\"", "বল, “আমার কোন ক্ষমতা নেই আমার নিজের উপকার করার, অথবা আমার নিজের ক্ষতি করার। শুধু আল্লাহ যা ইচ্ছা করেন তা আমার সাথে ঘটে। যদি আমি ভবিষ্যৎ জানতাম, আমি আমার সম্পদ বৃদ্ধি করতাম, এবং কোন ক্ষতি আমাকে দুর্দশাগ্রস্ত করতো না। আমি একজন সতর্ককারীর চেয়ে বেশি কিছু নই, এবং তাদের জন্য একজন সুসংবাদ বহনকারী যারা বিশ্বাস করে”।"],
  "7:189": ["It is Allah who created you from a single soul, and made from it its spouse, that he might settle to her. So when he covered her, she bore a light burden and passed with it; and when it grew heavy, they both called Allah, their Rabb: \"If You give us a sound one, we shall surely be among the thankful.\"", "তিনি তোমাদের সৃষ্টি করেছেন এক ব্যক্তি (আদম) থেকে। পরবর্তীতে,তিনি প্রত্যেক  মানুষকে একজন সঙ্গীনী দিয়েছেন তার  সাথে শান্তি পেতে। সে (স্ত্রী) তখন একটি হালকা বোঝা বহন করে যা সে কমই  খেয়াল করতে পারে। যখন বোঝা ভারী হয়, তারা তাদের প্রভু আল্লাহর কাছে মিনতি করেঃ “যদি আপনি আমাদেরকে একটি ভালো শিশু দেন, আমরা কৃতজ্ঞ হব”।"],
  "7:190": ["So when Allah gave them a sound one, they assigned partners to Allah in what Allah had given them. Exalted is Allah above what they associate.", "কিন্তু যখন তিনি তাদের একটি ভালো শিশু  দেন, তারা তাঁর দানকে উপাস্যে পরিণত করে যা তাঁর প্রতিদ্বন্দ্বি হয়। আল্লাহ উচ্চপ্রশংসিত, কোন অংশীদারিত্বের অনেক উর্ধে।"],
  "7:191": ["Do they associate what creates nothing, when they themselves create?", "এটা কি বাস্তব বিষয় নয় যে তারা উপাস্যদের উপাসনা করছে যারা কিছুই সৃষ্টি করে না,এবং নিজেরাই সৃষ্ট?"],
  "7:192": ["They cannot help them, nor can they help themselves.", "উপাস্যরা যারা না পারে তাদেরকে সাহায্য করতে,না পারে নিজেদেরকে সাহায্য করতে?"],
  "7:193": ["If you call them to guidance, they do not follow you. It is the same to you whether you call them, or you are silent.", "যখন তুমি তাদেরকে পথপ্রাপ্তির দিকে আমন্ত্রন করো,তারা তোমাকে অনুসরণ করে না। এভাবে,তুমি তাদেরকে আমন্ত্রন করো,অথবা নীরব থাকো তা তাদের জন্য একই।"],
  "7:194": ["Those you call upon besides Allah are servants like you — so call them, and let them answer you, if you are sadiq.", "আল্লাহর পাশে যে উপাস্যদের কাছে তোমরা সাহায্য প্রার্থনা করো তারা তোমাদের মতোই সৃষ্ট। তৎপর হও এবং তাদেরকে আহবান করো; তাদেরকে তোমাদের প্রতি সাড়া দিতে দাও, যদি তোমরা সঠিক হও।"],
  "7:195": ["Do they have legs to walk with? Or hands to seize with? Or eyes to see with? Or ears to hear with? Say: \"Call on your partners, then scheme against me, and give me no respite.\"", "তাদের কি পা আছে যার উপর তারা হাঁটে? তাদের কি হাত আছে যা দিয়ে তারা নিজেদের রক্ষা করে? তাদের কি চোখ আছে যা দিয়ে তারা দেখে? তাদের কি কান আছে যা দিয়ে তারা শোনে? বল, “তোমাদের উপাস্যদের আহবান করো,এবং তাদেরকে অনতিবিলম্বে আমাকে আক্রমন করতে বলো।"],
  "7:196": ["Indeed my protecting friend is Allah, who sent down the Book; and Allah takes charge of the salihin.", "আল্লাহ আমার একমাত্র প্রভু এবং মনিব; সেই সত্বা যিনি এই ঐশীগ্রন্থ প্রকাশ করেছিলেন। তিনি সৎকর্মশীলদের রক্ষা করেন।"],
  "7:197": ["Those you call upon besides Allah cannot help you, nor can they help themselves.", "“তাঁর পাশে তোমরা যে উপাস্যদের স্থাপন করেছ, তারা তোমাদের সাহায্য করতে পারে না,না তারা নিজেদের সাহায্য করতে পারে।”"],
  "7:198": ["If you call them to guidance, they do not hear; and you see them looking at you, while they do not see.", "যখন তুমি তাদেরকে সুপথে আহবান করো,তারা শোনে না। এবং তুমি তাদেরকে তোমার দিকে তাকাতে দেখো,কিন্তু তারা দেখে না।"],
  "7:199": ["Take the surplus, and command the recognized, and turn away from the ignorant.", "তুমি ক্ষমা অবলম্বন করবে,সহিষ্ণুতার উপদেশ দেবে,এবং অজ্ঞদের উপেক্ষা করবে।"],
  "7:200": ["If a sting from Shaytan stings you, seek refuge with Allah. Allah is hearing, knowing.", "যখন শয়তান তোমার কাছে ফিস ফিস করে কোন প্ররোচনা,আল্লাহর আশ্রয় খোঁজ, তিনি শ্রবণকারী,সর্বজ্ঞ।"],
  "7:201": ["Those who keep their duty — when a visitation from Shaytan touches them, they remember, and at once they see clearly.", "তারা যারা সৎকর্মশীল, যখনই শয়তান কোন ধারনা নিয়ে তাদের কাছে আসে,তারা স্মরণ করে,যার ফলে তারা অন্তর্দৃষ্টি সম্পন্ন হয়।"],
  "7:202": ["But their brothers draw them on into error, and do not fall short.", "তাদের ভাইয়েরা বিরামহীনভাবে তাদেরকে পথভ্রষ্টতায় প্ররোচিত করে।"],
  "7:203": ["And when you do not bring them a sign, they say: \"Why have you not chosen one?\" Say: \"I follow only what is revealed to me from my Rabb. These are insights from your Rabb, and guidance and mercy for a people who believe.\"", "যদি তুমি একটি অলৌকিকতা না দেখাও যা তারা দাবি করে,তারা বলে,“কেন এটি চাও না?’’ বল, “আমি কেবলমাত্র অনুসরন করি যা আমার প্রভুর পক্ষ থেকে আমার কাছে প্রকাশিত হয়েছে।” এগুলো তোমার প্রভুর পক্ষ থেকে জ্ঞানালোক, এবং পথপ্রদর্শন, এবং লোকদের জন্য দয়া যারা বিশ্বাস করে।"],
  "7:204": ["And when the Recitation is recited, listen to it and be silent, so that you may receive mercy.", "যখন কুরআন আবৃত্তি করা হয়, তোমরা তা শুনবে এবং মনোযোগ দিবে,যাতে তোমরা দয়া অর্জন করতে পারো।"],
  "7:205": ["And remember your Rabb within yourself, humbly and in awe, without loudness in speech, morning and evening; and do not be among the unmindful.", "তোমরা তোমাদের প্রভুর স্মরণ করবে নিজেদের অন্তরে,জনসমক্ষে,একান্তে,এবং প্রশান্তভাবে,দিনে ও রাতে;অসচেতন হইও না।"],
  "7:206": ["Those who are with your Rabb are not too proud to serve Allah, and they glorify Allah, and to Allah they prostrate.", "তোমার প্রভুর সান্নিধ্যে যারা রয়েছে তারা তাঁর উপাসনায় কখনো অহংকারী নয়। তারা তাঁর গুনকীর্তন করে এবং তাঁর সামনে সেজদাবনত হয়।"],
  "8:1": ["They ask you about the gains. Say: The gains are for Allah and the Rasul. So be mindful of Allah and set right what is between you, and obey Allah and Allah's Rasul, if you are muminin.", "তারা তোমার সাথে পরামর্শ করে যুদ্ধলব্ধ মালের ব্যাপারে। বল, “যুদ্ধলব্ধ মাল আল্লাহ এবং তাঁর বার্তাবাহকের।”তোমরা আল্লাহকে মান্য করবে, একে অন্যকে সৎকর্মশীল হতে উৎসাহিত করবে, এবং আল্লাহ ও তাঁর বার্তাবাহকে মান্য করবে, যদি তোমরা বিশ্বাসী হও।"],
  "8:2": ["The muminin are only those who, when Allah is mentioned, their hearts tremble with awe, and when Allah's signs are recited to them they increase them in belief, and upon their Rabb they rely.", "সত্যিকার বিশ্বাসী তারা যাদের হৃদয় কম্পিত হয় যখন আল্লাহর উল্লেখ করা হয়, এবং যখন তাঁর প্রকাশনাবলি তাদের কাছে পাঠ করা হয়, তাদের বিশ্বাস জোরদার হয়, এবং তারা তাদের প্রভুর প্রতি আস্থা রাখে।"],
  "8:3": ["Those who keep up the prayer and spend from what We have provided them.", "তারা সংযোগ প্রার্থনা (সালাত) প্রতিষ্ঠা করে, এবং তাদেরকে দেয়া আমাদের জীবিকা থেকে, তারা দান করে।"],
  "8:4": ["Those are the muminin in truth. For them are degrees with their Rabb, and forgiveness, and a generous provision.", "সত্যিকার বিশ্বাসীরা এমনই। তারা তাদের প্রভুর কাছে উচ্চ পদসমূহ অর্জন করে, সেই সাথে ক্ষমা এবং এক উদার জীবিকা।"],
  "8:5": ["Just as your Rabb brought you out from your home with the truth, while a faction of the muminin were unwilling.", "যখন তোমার প্রভু ইচ্ছা করলেন যে তোমরা তোমাদের ঘর ত্যাগ করো, একটি বিশেষ পরিকল্পনা পূর্ণ করতে, কিছু বিশ্বাসী অনিচ্ছুক বিশ্বাসী হিসাবে প্রকাশিত/আবির্ভূত হলো।"],
  "8:6": ["They dispute with you about the truth after it became clear, as if they were being driven to death while they watched.", "তারা সত্যের বিরুদ্ধে তোমার সাথে তর্ক করলো, এমনকি সবকিছু তাদের কাছে ব্যাখ্যা করার পরও। তারা  আচরণ করলো যেন তারা নিশ্চিত মৃত্যুর দিকে চালিত হচ্ছে।"],
  "8:7": ["When Allah promised you one of the two parties, that it would be yours, and you wished that the one without the thorn would be yours. And Allah wills to establish the truth with words, and to cut off the remnant of the kafirin.", "স্মরণ করো যে আল্লাহ তোমাদেরকে একটি নির্দিষ্ট দলের উপর বিজয়ের অঙ্গীকার করেছিলেন, কিন্তু তোমরা তবুও দুর্বল দলের মুখোমুখি হতে চাইলে। এটা ছিল আল্লাহর পরিকল্পনা সত্যকে প্রতিষ্ঠিত করা তাঁর বানী দিয়ে, এবং অবিশ্বাসীদের পরাজিত করা।"],
  "8:8": ["To establish the truth and nullify the falsehood, even if the guilty disliked it.", "তিনি জারি করেছেন যে সত্য জয়ী হবে, এবং মিথ্যা বিলুপ্ত হবে, মন্দকর্মীদের সত্ত্বেও।"],
  "8:9": ["When you cried for help to your Rabb, and the answer came to you: I am supplying you with a thousand malakat following one another.", "এভাবে, যখন তোমরা তোমাদের প্রভুর কাছে সহায়তা প্রদান করতে মিনতি করেছিলে, তিনি তোমাদের প্রতি সাড়া দিলেনঃ “আমি ধারাবাহিকভাবে এক হাজার স্বর্গদুত দিয়ে তোমাদের সমর্থন করছি”।"],
  "8:10": ["And Allah made it only as glad tidings, and so that your hearts would be settled by it. And help is only from Allah. Truly Allah is mighty, wise.", "আল্লাহ এই সুসংবাদ তোমাদেরকে দেন তোমাদের হৃদয়কে শক্তিশালী করতে। বিজয় শুধুমাত্র আল্লাহ থেকে আসে। আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "8:11": ["When drowsiness covered you, a security from it, and sent down upon you water from the sky, to purify you with it and to take away from you the affliction of the devil, and to bind your hearts and to steady your feet with it.", "তিনি শান্তিময় তন্দ্রা দিলেন তোমাদের আচ্ছন্ন করতে এবং  তোমাদেরকে প্রশান্ত করতে, এবং তিনি আকাশ থেকে পানি পাঠালেন তোমাদের তা দিয়ে পরিষ্কার করতে। তিনি শয়তানের অভিশাপ থেকে তোমাদের রক্ষা করলেন, তোমাদের অন্তরকে পূনঃ আশ্বস্ত করলেন এবং তোমাদের অবস্থানকে সুদৃড় করলেন।"],
  "8:12": ["When your Rabb inspired the malakat: I am with you, so steady those who believe. I will cast terror into the hearts of those who deny. So strike above the necks, and strike from them every fingertip.", "স্মরণ করো যে তোমাদের প্রভু ফেরেশতাদের অনুপ্রানিত করেছিলেন, \"আমি তোমাদের সাথে রয়েছি; সুতরাং তাদেরকে সমর্থন করো যারা বিশ্বাস করেছে। আমি তাদের অন্তরে আতঙ্ক ছুঁড়ে দিবো যারা অবিশ্বাস করেছে। তোমরা তাদের আঘাত করতে পারো ঘারের উপর,  এবং তোমরা এমনকি তাদের প্রত্যেক আঙ্গুলে আঘাত করতে পারো।"],
  "8:13": ["That is because they opposed Allah and Allah's Rasul. And whoever opposes Allah and Allah's Rasul — truly Allah is severe in punishment.", "এটা হচ্ছে যা তারা আল্লাহ এবং তাঁর বার্তাবাহকের সাথে যুদ্ধ করে যথার্থই অর্জন করেছে। তাদের জন্য যারা আল্লাহ এবং তাঁর বার্তাবাহকের বিরুদ্ধে যুদ্ধ করে, আল্লাহর শাস্তি কঠোর।"],
  "8:14": ["That is yours, so taste it. And the kafirin have the punishment of the fire.", "এটি অবিশ্বাসীদেরকে শাস্তি দিতে; তারা নরকের শাস্তি টেনে এনেছে।"],
  "8:15": ["O you who believe, when you meet those who deny advancing, do not turn your backs to them.", "হে তোমরা যারা বিশ্বাস করো, যদি তোমরা অবিশ্বাসীদের মুখোমুখি হও যারা তোমাদের বিরুদ্ধে একত্রিত হয়েছে, পিছু হটবে না এবং পালাবে না।"],
  "8:16": ["And whoever turns his back to them that day, unless shifting for battle or joining a band, has met with wrath from Allah, and his shelter is hell — and evil is the arrival.", "যেকেউ ঐ দিন পেছনে ফিরে আসে, কোন যুদ্ধ পরিকল্পনা সম্পন্ন করা, অথবা তার দলের সাথে যোগ দেয়া ছাড়া, সে টেনে এনেছে আল্লাহর ক্রোধ, এবং তার বাসস্থান নরক; কি এক শোচনীয় ভাগ্য!"],
  "8:17": ["So you did not kill them, but Allah killed them. And you did not hurl when you hurled, but Allah hurled. And to test the muminin from it with a good test. Truly Allah is all-hearing, all-knowing.", "এটা তুমি নও যে তাদের হত্যা করেছিল; আল্লাহই তাদেরকে হত্যা করেছিলেন। এটা তুমি নও যে ছুঁড়েছিল; আল্লাহই ছুঁড়েছিলেন। কিন্তু তিনি এভাবে বিশ্বাসীদের অনেক কৃতিত্ব অর্জন করার একটি সুযোগ দেন। আল্লাহ শ্রোতা, সর্বজ্ঞ।"],
  "8:18": ["That is yours, and that Allah is the weakener of the scheme of the kafirin.", "উপরন্তু, আল্লাহ এভাবে অবিশ্বাসীদের চক্রান্ত নস্যাৎ করে দেন।"],
  "8:19": ["If you seek triumph, the triumph has already come to you. And if you desist, it is better for you. And if you return, We will return, and your band will never avail you anything, even if numerous. And Allah is with the muminin.", "(হে অবিশ্বাসীরা) তোমরা বিজয় চেয়েছিলে, এবং বিজয় এসেছিল; এটি ছিল বিশ্বাসীদের। যদি তোমরা (আগ্রাসন থেকে) বিরত হও এটা তোমাদের জন্য উত্তম হবে, কিন্তু যদি তোমরা ফিরে আসো, আমরা তা-ই করবো। তোমাদের সেনাবাহিনী কখনোই তোমাদের সাহায্য করবে না, যতো বিশালই হোক না কেন। কারন আল্লাহ বিশ্বাসীদের পাশে রয়েছেন।"],
  "8:20": ["O you who believe, obey Allah and Allah's Rasul, and do not turn away from him while you hear.", "হে তোমরা যারা বিশ্বাস করো, আল্লাহ এবং তাঁর বার্তাবাহককে মান্য করো, এবং তাকে উপেক্ষা করো না যেহেতু তোমরা শোন।"],
  "8:21": ["And do not be like those who said we heard, while they do not hear.", "তাদের মতো হইও না যারা বলে, “আমরা শুনি,” যদিও তারা শুনে না।"],
  "8:22": ["Truly the worst of creatures with Allah are the deaf, the dumb, those who do not reason.", "আল্লাহর দৃষ্টিতে সবচেয়ে নিকৃষ্ট সৃষ্টি হচ্ছে বধির এবং বোবারা, যারা বুঝে না।"],
  "8:23": ["And if Allah knew any good in them, Allah would have made them hear. And if Allah were to make them hear, they would turn away, turning aside.", "যদি আল্লাহ তাদের মধ্যে কোন ভাল জানতেন, তিনি তাদের শ্রোতা বানাতেন। এমনকি তিনি যদি তাদের শ্রোতা করতেন, এরপরও তারা বিদ্বেষে মুখ ফিরিয়ে নিতো।"],
  "8:24": ["O you who believe, respond to Allah and to the Rasul when the call comes to you for what gives you life. And know that Allah comes between a person and his heart, and that to Allah you will be gathered.", "হে তোমরা যারা বিশ্বাস করো, তোমরা সাড়া দেবে আল্লাহ এবং বার্তাবাহকের প্রতি যখন সে তোমাদেরকে আমন্ত্রন করে তার প্রতি যা তোমাদেরকে প্রান দেয়। তোমাদের জানা উচিত যে আল্লাহ তোমাদের হ্রদয়ের চেয়েও তোমাদের নিকটবর্তী, এবং এটা যে তাঁর সামনে তোমরা একত্রিত হবে।"],
  "8:25": ["And be mindful of a trial that will not strike only those who wronged among you exclusively. And know that Allah is severe in punishment.", "সতর্ক হও একটি শাস্তির বিষয়ে যা হয়তো সীমাবদ্ধ থাকবে না তোমাদের মধ্যকার মন্দকর্মীদের মাঝে। তোমাদের জানা উচিত যে, আল্লাহর শাস্তি কঠোর।"],
  "8:26": ["And remember when you were few, weakened in the land, fearing that the people would snatch you; then Allah sheltered you and strengthened you with Allah's help, and provided you from the good things, so that you may be thankful.", "স্মরণ করো যে তোমরা অল্পসংখ্যক এবং নির্যাতিত ছিলে, ভয় করতে যে লোকেরা হয়তো তোমাদের ছিনিয়ে নিতে পারে, এবং তিনি তোমাদেরকে প্রদান করলেন একটি নিরাপদ আশ্রয়স্থল, তাঁর বিজয় দিয়ে তোমাদের সমর্থন করলেন, এবং তোমাদেরকে দিলেন ভালো জীবিকা, যাতে তোমরা কৃতজ্ঞ হতে পারো।"],
  "8:27": ["O you who believe, do not betray Allah and the Rasul, and betray your trusts while you know.", "হে তোমরা যারা বিশ্বাস করো,আল্লাহ এবং তাঁর বার্তাবাহককের সাথে প্রতারণা করো না, এবং তাদের সাথে প্রতারণা করো না যারা তোমাদের প্রতি আস্থা রাখে,এখন যেহেতু তোমরা জানো।"],
  "8:28": ["And know that your wealth and your children are only a trial, and that with Allah is a great reward.", "তোমাদের জানা উচিত যে তোমাদের অর্থ এবং তোমাদের সন্তানরা একটি পরীক্ষা, এবং এটা যে আল্লাহর অধীনে আছে এক মহা প্রতিদান।"],
  "8:29": ["O you who believe, if you are mindful of Allah, Allah will make for you a criterion, and wipe away your bad deeds for you, and forgive you. And Allah is the possessor of great bounty.", "হে তোমরা যারা বিশ্বাস করো, যদি তোমরা আল্লাহকে ভক্তি শ্রদ্ধা করো, তিনি তোমাদেরকে আলোকিত করবেন, তোমাদের পাপ মার্জনা করবেন, এবং তোমাদের ক্ষমা করবেন। আল্লাহ অসীম অনুগ্রহের অধিকারী।"],
  "8:30": ["And when those who deny scheme against you to hold you fast, or kill you, or expel you — and they scheme, and Allah schemes, and Allah is the best of planners.", "অবিশ্বাসীরা চক্রান্ত এবং ফন্দী আঁটে তোমাকে নিষ্ক্রিয় করতে, অথবা তোমাকে হত্যা করতে, অথবা তোমাকে নির্বাসিত করতে।  যাই হোক, তারা চক্রান্ত এবং ফন্দী আঁটে, কিন্তু আল্লাহও তা-ই করেন, আল্লাহ শ্রেষ্ঠ পরিকল্পনাকারী।"],
  "8:31": ["And when Our signs are recited to them, they say: We have heard; if we wished we could say the like of this. This is only tales of the ancients.", "যখন আমাদের প্রকাশনাবলি তাদের কাছে আবৃতি করা হয়, তারা বলে, “আমরা শুনেছি। যদি আমরা করতে চাইতাম, আমরা একই জিনিস বলতে পারতাম। এগুলো অতীতের গল্প ছাড়া বেশি কিছু নয়।!”"],
  "8:32": ["And when they said: O Allah, if this is the truth from You, then rain down upon us stones from the sky, or bring us a painful punishment.", "তারা আরোও বলেছিল, “আমাদের উপাস্য, যদি এটি বাস্তবিকই আপনার পক্ষ থেকে সত্য হয়, তবে আকাশ থেকে আমাদের উপর পাথর বর্ষন করুন, অথবা আমাদের উপর একটি যন্ত্রনাদায়ক শাস্তি পতিত করুন।”"],
  "8:33": ["And Allah was not to punish them while you are among them, and Allah was not to punish them while they seek forgiveness.", "তা সত্ত্বেও, আল্লাহ তাদের শাস্তি দেয়ার নয় যতক্ষন তুমি তাদের মধ্যে রয়েছ;  আল্লাহ তাদের শাস্তি দেয়ার নয় যতক্ষন তারা ক্ষমা প্রার্থনা করছে।"],
  "8:34": ["And why should Allah not punish them, when they bar from the sacred mosque and were not its keepers? Its keepers are only the mindful. But most of them do not know.", "তারা কি আল্লাহর শাস্তির উপযুক্ত হয় নি, অন্যদেরকে পবিত্র মসজিদ থেকে বাঁধা দানের দ্বারা, যদিও তারা সেখানকার তত্ত্বাবধায়ক নয়? সেখানকার প্রকৃত তত্ত্বাবধায়ক হচ্ছে সৎকর্মশীলরা, কিন্তু তাদের অধিকাংশ জানে না।"],
  "8:35": ["And their prayer at the House was only whistling and clapping. So taste the punishment for what you used to deny.", "পূন্যস্থানে (কা’বা) তাদের সংযোগ প্রার্থনাসমূহ (সালাত) একটি উপহাস এবং (ভিড় করে বাইরে রেখে) লোকদের  বাধা দেয়ার একটি মাধ্যমের চেয়ে বেশি কিছু নয়। অতএব, তোমাদের অবিশ্বাসের জন্য শাস্তি ভোগ করো।"],
  "8:36": ["Truly those who deny spend their wealth to bar from the way of Allah. They will spend it, then it will be regret upon them, then they will be overcome. And those who deny — to hell they will be gathered.", "যারা অবিশ্বাস করে তারা তাদের অর্থ ব্যয় করে অন্যদেরকে আল্লাহর পথ থেকে প্রতিহত করতে। তারা তা ব্যয় করবে, এরপর এটা তাদের জন্য দুঃখ ও অনুতাপে পরিণত হবে। সব শেষে, তারা পরাজিত হবে, এবং সব অবিশ্বাসীদের নরকে ডাকা হবে।"],
  "8:37": ["So that Allah distinguishes the vile from the good, and makes the vile some upon some, then piles it all together, and puts it in hell. Those are the khasirin.", "আল্লাহ মন্দকে ভালো থেকে আলাদা করবেন, এরপর মন্দকে একে অন্যের উপর স্তুপ করবেন, সকলকে এক স্তুপের ভিতর, তারপর একে নরকে নিক্ষেপ করবেন। ক্ষতিগ্রস্থরা এমনই।"],
  "8:38": ["Say to those who deny: if they desist, what has passed will be forgiven them. And if they return, the way of the ancients has already passed.", "যারা অবিশ্বাস করেছে তাদেরকে বলঃ যদি তারা ক্ষান্ত হয়, তাদের সকল অতীত ক্ষমা করে দেয়া হবে। কিন্তু যদি তারা ফিরে যায়, তারা সেই একই ভাগ্য টেনে আনবে যেমন এনেছিল তাদের পূর্ববর্তী প্রতিরূপরা।"],
  "8:39": ["And fight them until there is no trial, and the religion is all for Allah. Then if they desist, truly Allah is all-seeing of what they do.", "তুমি তাদের সাথে লড়াই করবে নিপীড়ন বন্ধ করতে, এবং তোমাদের ধর্ম একমাত্র আল্লাহকে উৎসর্গ করে চর্চা করতে। যদি তারা আগ্রাসন থেকে বিরত হয়, তবে আল্লাহ সবকিছুর পূর্ণ দ্রষ্টা যা তারা করে।"],
  "8:40": ["And if they turn away, know that Allah is your protector — an excellent protector, and an excellent helper.", "যদি তারা মুখ ফিরিয়ে নেয়, তবে তোমাদের জানা উচিত যে আল্লাহ তোমাদের প্রভু এবং মনিব; সর্বশ্রেষ্ঠ প্রভু এবং মনিব, সর্বশ্রেষ্ঠ সহায়তাকারী।"],
  "8:41": ["And know that whatever you take as gain, a fifth of it is for Allah and for the Rasul and for the near kin, and the orphans, and the poor, and the son of the way, if you believe in Allah and what We sent down upon Our servant on the day of the criterion, the day the two hosts met. And Allah is able over all things.", "তোমাদের জানা উচিত যে যদি তোমরা যুদ্ধে কোন যুদ্ধলব্ধ মাল অর্জন করো, এক-পঞ্চমাংশ আল্লাহ এবং বার্তাবাহকের নিকট যাবে, আত্মীয়, এতিম, গরিব, এবং ভ্রমনরত ভিনদেশীকে দিতে। তোমরা এটি করবে যদি তোমরা বিশ্বাস করো আল্লাহতে এবং তাতে যা আমরা আমাদের দাসের নিকট প্রকাশ করেছি সিদ্ধান্তের দিনে, দুই সৈন্যবাহিনীর সংঘর্ষের দিন। আল্লাহ সর্বশক্তিমান।"],
  "8:42": ["When you were on the near shore and they were on the far shore, and the caravan was below you. And if you had agreed on an appointment, you would have differed about the appointment. But so that Allah decrees a matter that was to be done: so that whoever perishes perishes by clear proof, and whoever lives lives by clear proof. And truly Allah is all-hearing, all-knowing.", "Recall that you were on this side of the valley, while they were on the other side. Then their caravan had to move to lower ground. Had you planned it this way, you could not have done it. But GOD was to carry out a predetermined matter, whereby those destined to be annihilated were annihilated for an obvious reason, and those destined to be saved were saved for an obvious reason. GOD is Hearer, Omniscient."],
  "8:43": ["When Allah showed them to you in your dream as few. And if shown to you as many, you would have faltered and contended about the matter. But Allah granted safety. Truly Allah is knowing of what is in the breasts.", "আল্লাহ তোমার (হে মুহাম্মদ) স্বপ্নে তাদেরকে অল্প সংখ্যক দেখিয়েছিলেন।  যদি তিনি তাদেরকে অধিকতর সংখ্যক দেখাতেন, তোমরা ব্যর্থ হতে, এবং তোমরা নিজেদের মধ্য বিবাদ করতে। কিন্তু আল্লাহ পরিস্থিতিটি নিয়ন্ত্রন করলেন। তিনি গভীরতম চিন্তাগুলো জানেন।"],
  "8:44": ["And when Allah showed them to you, when you met, as few in your eyes, and made you few in their eyes, so that Allah decrees a matter that was to be done. And to Allah all matters are returned.", "এবং যখন সে সময় আসলো ও তোমরা তাদের সম্মুখীন হলে, তিনি তোমাদের চোখে তাদের অল্প সংখ্যক দেখালেন, এবং তোমাদেরকেও তাদের চোখে অল্প সংখ্যক দেখালেন। কারণ আল্লাহ একটি নির্দিষ্ট পরিকল্পনা সম্পন্ন করার ইচ্ছা করেছিলেন। সকল সিদ্ধান্ত আল্লাহর প্রনীত।"],
  "8:45": ["O you who believe, when you meet a band, stand firm and remember Allah much, so that you may succeed.", "হে যারা বিশ্বাস করো, যখন তোমরা কোন সৈন্য বাহিনীর মুখোমুখি হও, তোমরা সুদৃড় থাকবে এবং আল্লাহকে অনবরত স্মরণ করবে, যাতে তোমরা সফল হতে পারো।"],
  "8:46": ["And obey Allah and Allah's Rasul, and do not contend with one another, lest you falter and lose your wind. And be of the sabirin — truly Allah is with the sabirin.", "তোমরা আল্লাহ এবং তাঁর বার্তাবাহককে মান্য করবে, এবং নিজেদের মধ্যে বিবাদ করবে না, পাছে তোমরা ব্যর্থ হও এবং তোমাদের শক্তি ছিন্ন হয়। তোমরা দৃঢ়তার সাথে অধ্যবসায়ী হবে। আল্লাহ তাদের সাথে রয়েছেন যারা দৃঢ়তার সাথে অধ্যবসায়ী।"],
  "8:47": ["And do not be like those who went out from their homes exultantly and for show before the people, and bar from the way of Allah. And Allah is all-encompassing of what they do.", "তাদের মতো হইও না যারা অনিচ্ছায় তাদের ঘর ছেড়েছিল, শুধুমাত্র লোক দেখাতে, এবং বাস্তবিকপক্ষে অন্যদেরকে আল্লাহর পথ অনুসরণ করা থেকে অনুৎসাহিত করতো। তারা যা করে আল্লাহ সে সবকিছু সম্পর্কে সম্পূর্ণ অবগত।"],
  "8:48": ["And when the devil adorned their deeds for them and said: No one among the people will overcome you today, and I am a protector for you. But when the two bands saw each other, he turned back on his heels and said: I am free of you; I see what you do not see; I fear Allah. And Allah is severe in punishment.", "শয়তান তাদের কাজকে তাদের চোখে সাজিয়ে দিল, এবং বলল, “তোমরা আজ কোন দল দ্বারা পরাজিত হতে পারো না”, এবং “আমি তোমাদের সাথে যুদ্ধ করতে থাকবো”কিন্তু যে মুহূর্তে দুই সৈন্যদল একে অন্যের মুখোমুখি হলো, সে পেছনে ফিরে গেল এবং পালাল, এই বলে যে, “আমি তোমাদের পরিত্যাগ করি। আমি দেখি যা তোমরা দেখো না। আমি আল্লাহকে ভয় করি। আল্লাহর শাস্তি ভয়াবহ।”"],
  "8:49": ["When the munafiqin say, and those in whose hearts is sickness: These people were deceived by their religion. And whoever relies upon Allah — truly Allah is mighty, wise.", "ভণ্ডরা এবং যারা তাদের হৃদয়ে সন্দেহ পোষণ করেছিল তারা বলল, “এই লোকেরা তাদের ধর্মের মাধ্যমে প্রতারিত”। কিন্তু, কেউ যদি তার আস্থা আল্লাহর প্রতি রাখে, তবে আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "8:50": ["And if you could see, when the malakat take away those who deny, striking their faces and their backs: Taste the punishment of the burning.", "যদি তুমি শুধু দেখতে পারতে তাদেরকে যারা অবিশ্বাস করেছিল যখন ফেরেশতারা তাদের হত্যা করে! তারা তাদের প্রহার করবে তাদের মুখে এবং তাদের পশ্চাৎপ্রান্তে “নরকের শাস্তি আস্বাদন করো।"],
  "8:51": ["That is for what your hands sent ahead, and that Allah is never a wrongdoer to the servants.", "“যা তাদের হাত পুর্বে পাঠিয়েছে এটি তার একটি ফল। আল্লাহ সৃষ্টিজগতের  প্রতি কখনো অবিবেচক নন।”"],
  "8:52": ["Like the practice of Fir'awn's clan and those before them: they denied the signs of Allah, so Allah seized them for their sins. Truly Allah is strong, severe in punishment.", "ফেরাউনের লোক এবং তাদের পূর্বে যারা অবিশ্বাস করেছিল এটি তাদের মতো সে একই পরিনতি। তারা আল্লাহর প্রকাশনাবলি প্রত্যাক্ষান করেছিল, এবং আল্লাহ তাদেরকে তাদের পাপের জন্য শাস্তি দিয়েছিলেন। আল্লাহ ক্ষমতাবান, এবং তাঁর শাস্তি কঠোর।"],
  "8:53": ["That is because Allah would never change a blessing Allah bestowed upon a people until they change what is in themselves. And that Allah is all-hearing, all-knowing.", "আল্লাহ কোন আশীর্বাদ পরিবর্তন করেন না যা তিনি কোন লোকের উপর আরোপ করেছেন যদি না তারা নিজেরা পরিবর্তনের সিদ্ধান্ত নেয়। আল্লাহ শ্রোতা, সর্বজ্ঞ।"],
  "8:54": ["Like the practice of Fir'awn's clan and those before them: they denied the signs of their Rabb, so We destroyed them for their sins, and We drowned Fir'awn's clan. And all were wrongdoers.", "ফেরাউনের লোক এবং তাদের পূর্বের অন্যদের সাথে বিষয়টি এরকমই ছিল। তারা প্রথমে তাদের প্রভুর নিদর্শনাবলি প্রত্যাক্ষান করেছিল। ফলস্বরুপ, আমরা তাদেরকে তাদের পাপের জন্য ধ্বংস করলাম। আমরা ফেরাউনের লোকদের ডুবালাম; মন্দদেরকে উপযুক্তভাবে শাস্তি দেয়া হয়েছিল।"],
  "8:55": ["Truly the worst of creatures with Allah are those who deny — so they will not believe.", "আল্লাহর দৃষ্টিতে তারা সবচেয়ে নিকৃষ্ট সৃষ্টি যারা অবিশ্বাস করে; তারা বিশ্বাস করতে পারে না।"],
  "8:56": ["Those of them with whom you made a pledge, then they break their pledge every time, and they are not mindful.", "তোমরা তাদের সাথে চুক্তিতে পৌঁছাও, কিন্তু প্রতিবারই তারা তাদের চুক্তি ভাঙ্গে; এরা সৎকর্মশীল নয়।"],
  "8:57": ["So if you overtake them in war, scatter by them those behind them, so that they may take heed.", "অতএব, তোমরা যদি তাদের সাথে যুদ্ধে মুখোমুখি হও, তোমরা তাদের পরবর্তীদের জন্য একটি প্রতিরোধমূলক উদাহরণ হিসাবে স্থাপন করবে, যাতে তারা উপদেশ গ্রহণ করতে পারে।"],
  "8:58": ["And if you fear betrayal from a people, cast away to them on equal terms. Truly Allah does not love the betrayers.", "যখন তোমরা এক দল লোক দ্বারা প্রতারিত হয়েছ, তাদের বিরুদ্ধে তোমরা একই পন্থায় যুদ্ধের জন্য প্রস্তুত হবে।"],
  "8:59": ["And let not those who deny think they have outstripped. Truly they cannot escape.", "যারা অবিশ্বাস করে তাদেরকে ভাবতে দিওনা যে তারা এটি করে পার পেয়ে যাবে; তারা কখনো পালাতে পারে না।"],
  "8:60": ["And prepare against them whatever you are able of strength, and of tethered horses, to strike dread by them into the enemy of Allah and your enemy, and others besides them whom you do not know — Allah knows them. And whatever you spend of anything in the way of Allah will be repaid to you, and you will not be wronged.", "তোমরা তাদের জন্য সকল শক্তি প্রস্তুত করবে যা তোমরা সমবেত করতে পারো, এবং সকল সরঞ্জাম যা তোমরা একত্রিত করতে পারো, যাতে তোমরা আল্লাহর শত্রুদের ভয় দেখাতে পারো, তোমাদের শত্রু, একই সাথে অন্যদের যারা তোমাদের কাছে পরিচিত নয়; আল্লাহ তাদের জানেন।তোমরা আল্লাহর উদ্দেশ্যে যা কিছু ব্যয় করো তোমাদেরকে পুনরায় ফিরিয়ে দেয়া হবে উদারভাবে সামান্যতম অবিচার ছাড়াই।"],
  "8:61": ["And if they incline to peace, then incline to it, and rely upon Allah. Truly Allah is the all-hearing, the all-knowing.", "যদি তারা শান্তি অবলম্বন করে, তোমরাও তা-ই করবে, এবং আল্লাহর প্রতি তোমাদের আস্থা রাখো। তিনি শ্রোতা, সর্বজ্ঞ।"],
  "8:62": ["And if they intend to deceive you, Allah is sufficient for you. Allah is the one who strengthened you with help and with the muminin.", "যদি তারা তোমাদের প্রতারিত করতে চায়, তবে আল্লাহ তোমাদের জন্য যথেষ্ট হবেন। তিনি তাঁর সমর্থণ দিয়ে, এবং বিশ্বাসীদের দিয়ে তোমাদের সাহায্য করবেন।"],
  "8:63": ["And Allah united their hearts: if you had spent all that is in the earth, you would not have united their hearts. But Allah united them. Truly Allah is mighty, wise.", "তিনি (বিশ্বাসীদের) অন্তর পূনর্মিলিত করেছেন। যদি তুমি পৃথিবীর সমস্ত অর্থ ব্যয় করতে, তুমি তাদের অন্তরকে পূনর্মিলিত করাতে পারতে না। কিন্তু আল্লাহ তাদের পূনর্মিলিত করলেন। তিনি সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "8:64": ["O Nabi, Allah is sufficient for you, and whoever among the muminin followed you.", "হে নবী, তোমার জন্য যথেষ্ট আল্লাহ এবং বিশ্বাসীরা যারা তোমার অনুসরণ করেছে।"],
  "8:65": ["O Nabi, urge the muminin to fight. If there are twenty steadfast among you, they will overcome two hundred. And if there are a hundred among you, they will overcome a thousand of those who deny, because they are a people who do not understand.", "হে নবী, তুমি বিশ্বাসীদের যুদ্ধ করতে উৎসাহিত করবে। যদি তোমাদের বিশ জন থাকে যারা দৃড়, তারা দুই শত লোককে পরাজিত করতে পারে, এবং তোমাদের একশত জন পরাজিত করতে পারে তাদের এক হাজার জনকে যারা অবিশ্বাস করে। এর কারন হচ্ছে তারা এমন লোক যারা বোঝে না।"],
  "8:66": ["Now Allah has lightened for you and knows that there is weakness in you. So if there are a hundred steadfast among you, they will overcome two hundred. And if there are a thousand among you, they will overcome two thousand, by Allah's leave. And Allah is with the steadfast.", "এখন (যেহেতু অনেক নতুন লোক তোমাদের সাথে যুক্ত হয়েছে) আল্লাহ এটি তোমাদের জন্য সহজ করেছেন, কারন তিনি জানেন যে তোমরা ততটা শক্তিশালী নও যেমন তোমরা থাকতে। এখন থেকে, আল্লাহর অনুমতিক্রমে একশ দৃঢ় বিশ্বাসী দু’শ জনকে পরাজিত করতে পারবে, এবং তোমাদের এক হাজার জন দু’হাজার জনকে পরাজিত করতে পারবে। আল্লাহ তাদের সাথে রয়েছেন যারা দৃঢ়তার সাথে অধ্যবসায়ী।"],
  "8:67": ["It is not for a Nabi to have captives until firmly subduing in the land. You want the goods of the worldly life, and Allah wills the Hereafter. And Allah is mighty, wise.", "কোন নবী বন্দীদের পাবে না, যদি না সে লড়াইয়ে অংশ নেয়। তোমরা লোকেরা এই দুনিয়ার বস্তুসামগ্রী খুঁজছ, যখন আল্লাহ পরকালের উকালতি করেন। আল্লাহ সর্ব শক্তিমান, সব থেকে জ্ঞানী।"],
  "8:68": ["Were it not for a decree from Allah that came before, a great punishment would have touched you for what you took.", "যদি এটি আল্লাহর পক্ষ থেকে একটি পূর্ব নির্ধারিত হুকুম না হতো, তোমরা হয়তো ভুগতে, যা তোমরা নিয়েছিলে তার ফল হিসাবে, এক ভয়ানক শাস্তি।"],
  "8:69": ["So eat of what you gained, lawful and good, and be mindful of Allah. Truly Allah is forgiving, merciful.", "অতএব, যুদ্ধলব্ধ মালের থেকে খাও যা তোমরা উপার্জন করেছ যা আইনসিদ্ধ এবং ভালো, এবং আল্লাহকে মান্য করো। আল্লাহ ক্ষমাশীল, সব থেকে দয়াময়।"],
  "8:70": ["O Nabi, say to those among the captives in your hands: If Allah knows good in your hearts, Allah will give you better than what was taken from you, and will forgive you. And Allah is forgiving, merciful.", "হে নবী, তোমাদের হাতে থাকা যুদ্ধ বন্দীদের বল, “যদি আল্লাহ তোমাদের হৃদয়ের এমন কিছু ভাল জানতেন, তিনি তোমাদেরকে দিতেন তোমরা যা কিছু হারিয়েছ তার চেয়ে উত্তম, এবং তোমাদের ক্ষমা করে দিতেন। আল্লাহ ক্ষমাকারী, সব থেকে দয়ালু।”"],
  "8:71": ["And if they intend to betray you, they already betrayed Allah before. So Allah has given you firm hold over them. And Allah is knowing, wise.", "এবং যদি তারা তোমাদের প্রতারিত করতে চায়, তারা ইতোমধ্যেই আল্লাহকে প্রতারনা করেছে। এ কারনেই তিনি তাদের পরাজিত করালেন। আল্লাহ সর্বজ্ঞ, সবচেয়ে জ্ঞানী।"],
  "8:72": ["Truly those who believe and emigrate and strive with their wealth and themselves in the way of Allah, and those who sheltered and helped — those are allies of one another. And those who believe and did not emigrate: you have no alliance with them in anything until they emigrate. And if they ask your help in the religion, help is due from you, except against a people between you and whom there is a pact. And Allah is all-seeing of what you do.", "নিশ্চিতভাবে, যারা বিশ্বাস করেছে, এবং দেশত্যাগ করেছে, এবং আল্লাহর উদ্দেশ্যে সংগ্রাম করেছে তাদের অর্থ এবং তাদের জীবন দিয়ে, একই সাথে যারা তাদেরকে আতিথিয়তা করেছে এবং তাদেরকে আশ্রয় দিয়েছে, এবং তাদেরকে সমর্থন করেছে, তারা একে অন্যের মিত্র। তাদের জন্য যারা বিশ্বাস করে, কিন্তু তোমাদের সাথে দেশত্যাগ করে না, তোমরা তাদেরকে কোন সমর্থন দিতে বাধ্য নও, যতক্ষন পর্যন্ত না তারা দেশত্যাগ করে। যাহোক, যদি তোমাদের সাহায্য তাদের দরকার হয়, বিশ্বাসী ভ্রাতা হিসেবে, তোমরা তাদের সাহায্য করবে, সে লোকদের বিরুদ্ধে না গিয়ে যারা তোমাদের সাথে একটি শান্তি চুক্তিতে সাক্ষর করেছে। আল্লাহ সবকিছুর দ্রষ্টা যা তোমরা করো।"],
  "8:73": ["And those who deny — some of them are allies of one another. If you do not do so, there will be trial in the land and great corruption.", "যারা অবিশ্বাস করেছে তারা একে অন্যের মিত্র। যদি না তোমরা এই প্রত্যাদেশাবলি রক্ষা করো, পৃথিবীতে বিশৃঙ্খলা, এবং ভয়ানক দূর্নীতি হবে।"],
  "8:74": ["And those who believe and emigrate and strive in the way of Allah, and those who sheltered and helped — those are the muminin in truth. For them is forgiveness and a generous provision.", "যারা বিশ্বাস করেছে এবং দেশত্যাগ করেছে, এবং আল্লাহর উদ্দেশ্যে সংগ্রাম করেছে, একই সাথে যারা তাদেরকে আতিথিয়তা করেছে এবং তাদেরকে আশ্রয় দিয়েছে, এবং তাদেরকে সমর্থন করেছে, এরাই প্রকৃত বিশ্বাসী। তারা ক্ষমা এবং এক উদার প্রতিদানের উপযুক্ত হয়েছে।"],
  "8:75": ["And those who believed afterward and emigrated and strove with you — those are of you. And blood-kin: some have closer claim than others in the decree of Allah. Truly Allah is knowing of all things.", "যারা এরপর বিশ্বাস করেছে, এবং দেশত্যাগ করেছে, এবং তোমাদের সাথে সংগ্রাম করেছে, তারা তোমাদের অন্তর্ভূক্ত। যারা একে অন্যের সাথে সম্পর্কিত সমর্থণ করার ক্ষেত্রে তারা একে অন্যকে  প্রাধান্য দিবে, আল্লাহর প্রত্যাদেশাবলি অনুসারে। আল্লাহ সবকিছুর বিষয়েই পূর্ন সচেতন।"],
  "9:1": ["A disavowal from Allah and Allah's Rasul to those of the mushrikin with whom you made a pledge.", "আল্লাহ এবং তাঁর বার্তাবাহকের পক্ষ থেকে এখানে একটি চুড়ান্ত শর্ত জারি করা হলো প্রতিমা উপাসকদের প্রতি যারা তোমাদের সাথে একটি চুক্তিতে আসে।"],
  "9:2": ["Move freely in the land for four months, and know that you cannot frustrate Allah, and that Allah disgraces the kafirin.", "অতএব, চার মাসের জন্য পৃথিবীতে মুক্তভাবে ঘুড়ে বেড়াও, এবং জানো যে তোমরা আল্লাহ থেকে পালাতে পারো না, এবং যে আল্লাহ অবিশ্বাসীদের লাঞ্ছিত করেন।"],
  "9:3": ["And a proclamation from Allah and Allah's Rasul to the people, on the day of the greater pilgrimage, that Allah disavows the mushrikin, and so does Allah's Rasul. If you repent, that is better for you; but if you turn away, know that you cannot frustrate Allah — and give tidings to the kafirin of a painful punishment.", "আল্লাহ এবং তাঁর বার্তাবাহকের পক্ষ থেকে সকল লোকদের প্রতি এখানে একটি ঘোষণা জারি করা হলো তীর্থযাত্রার সেই মহান দিনে, যে আল্লাহ প্রতিমা উপাসকদের পরিত্যাগ করেছেন, এবং তাঁর বার্তাবাহকও তা-ই করেছে। সুতরাং, যদি তোমরা অনুশোচনা করো, এটা তোমাদের জন্য উত্তম হবে। কিন্তু যদি তোমরা মুখ ফিরিয়ে নাও, তবে জানো যে তোমরা কখনোই আল্লাহ থেকে পালাতে পারো না। যারা অবিশ্বাস করে তাদেরকে একটি যন্ত্রণাদায়ক শাস্তির অঙ্গীকার করো।"],
  "9:4": ["Except those of the mushrikin with whom you made a pledge, and who then did not diminish anything toward you and backed no one against you: fulfill for them their pledge to its full term. Allah loves the reverent.", "যদি প্রতিমা উপাসকেরা তোমাদের সাথে একটি শান্তি চুক্তিতে সাক্ষর করে, এবং না এর লঙ্ঘন করে, না সংঘবদ্ধ হয় অন্যদের সাথে তোমাদের বিরুদ্ধে, তোমরা তাদের সাথে তোমাদের চুক্তি পরিপূর্ণ করবে, মেয়াদ উত্তির্ণের তারিখ পর্যন্ত।"],
  "9:5": ["Then, when the sacred months have passed, slay the mushrikin wherever you find them, seize them, confine them, and lie in wait for them at every watch-post. But if they repent, establish the prayer, and give the purifying-dues, then leave them their way. Allah is forgiving, merciful.", "একবার পবিত্র মাসসমূহ পার হলে, (এবং তারা শান্তি স্থাপন করা প্রত্যাখ্যান করলে) তোমরা প্রতিমা উপাসকদের হত্যা করতে পারো যখন তোমরা তাদের সম্মুখিন হও, তাদের শাস্তি দিতে পারো, এবং তাদের তৈরী করা প্রত্যেক পদক্ষেপ প্রতিহত করতে পারো। যদি তারা অনুশোচনা করে এবং সংযোগ প্রার্থনাসমূহ (সালাত) প্রতিষ্ঠা করে এবং বাদ্ধতামূলক দান (যাকাত) দেয়, তোমরা তাদের ছেড়ে দেবে। আল্লাহ ক্ষমাশীল, পরম দয়ালু।"],
  "9:6": ["And if one of the mushrikin seeks your protection, grant him protection so that he may hear the word of Allah; then deliver him to his place of safety. That is because they are a people who do not know.", "যদি কোন প্রতিমা উপাসক তোমাদের সাথে নিরাপদে অবস্থান করতে চায়, তোমরা তাকে নিরাপদ প্রস্থান করতে দিবে, যাতে সে আল্লাহর বানী শুনতে পারে, এরপর তাকে তার নিরাপত্তার স্থানে ফেরত পাঠাও। এটা এ কারনে যে তারা এমন লোক যারা জানে না।"],
  "9:7": ["How can the mushrikin have a pledge with Allah and with Allah's Rasul — except those with whom you pledged at the Sacred Mosque? So long as they remain straight with you, remain straight with them. Allah loves the reverent.", "কেমন করে প্রতিমা উপাসকরা আল্লাহ থেকে এবং তাঁর বার্তাবাহক থেকে কোন অঙ্গীকার দাবী করতে পারে? তারা নিষ্কৃতিপ্রাপ্ত যারা পবিত্র মসজিদে তোমাদের সাথে একটি শান্তি চুক্তি স্বাক্ষর করেছে। যদি তারা এরকম একটি চুক্তিকে সম্মান করে এবং বহাল রাখে, তোমরাও একই ভাবে তা বহাল রাখবে। আল্লাহ সৎকর্মশীলদের ভালোবাসেন।"],
  "9:8": ["How? If they gain the upper hand over you, they observe toward you no kinship and no protection-bond. They please you with their mouths while their hearts refuse — and most of them are rebellious.", "কেমন করে তারা (একটি প্রতিশ্রুতি দাবী করতে) পারে যখন তারা  কখনোই তোমাদের এবং তাদের মাঝে কোন আত্মীয়তার অধিকার পালন করতো না, না কোন অঙ্গীকার, যদি কখনো তাদের জয়ী হবার সুযোগ থাকতো। তারা মুখের কথা দিয়ে তোমাকে প্রশান্ত করলো, যখন তাদের হৃদয়ে বিরোধিতা ছিল, এবং তাদের বেশির ভাগ মন্দ।"],
  "9:9": ["They exchanged the signs of Allah for a paltry price and turned others away from the way of Allah. Evil indeed is what they used to do.", "তারা সস্তা মূল্যে আল্লাহর প্রকাশনাবলির বিকিয়ে দিলো। পরিনামে, তারা লোকদেরকে তাঁর পথ থেকে বিতাড়িত করলো। নিশ্চয়ই শোচনীয় যা তারা করেছিল।"],
  "9:10": ["They observe toward a mumin no kinship and no protection-bond — and those are the aggressors.", "তারা কখনোই কোন বিশ্বাসীর প্রতি আত্মীয়তার কোন অধিকার পালন করেনি, না তারা মেনে চলে তাদের অঙ্গীকারগুলো; এরাই আসল সীমালঙ্ঘনকারী।"],
  "9:11": ["But if they repent, establish the prayer, and give the purifying-dues, then they are your brothers in the faith. And We set out the signs in detail for a people who know.", "যদি তারা অনুশোচনা করে এবং সংযোগ প্রার্থনা (সালাত) প্রতিষ্ঠা করে ও বাদ্ধতামুলক (যাকাত)দান করে, তবে তারা তোমাদের ধর্ম ভাই। আমরা এভাবে লোকদের জন্য প্রকাশনাবলী ব্যাখ্যা করি যারা জানে।"],
  "9:12": ["But if they break their oaths after their pledge and attack your religion, then slay the leaders of disbelief — they have no oaths to bind them — so that perhaps they may desist.", "যদি তারা তাদের শপথ ভঙ্গ করে তাদের অঙ্গীকার রাখার প্রতিশ্রুতি দেবার পর, এবং তোমাদের ধর্মকে আক্রমণ করে, তোমরা পৌত্তলিকতার নেতাদের সাথে লড়াই করতে পারো- তোমরা তাদের সাথে তোমাদের অঙ্গীকার দ্বারা আর আবদ্ধ নও-যাতে তারা বিরত থাকতে পারে।"],
  "9:13": ["Will you not slay a people who broke their oaths and resolved to drive out the Rasul — and it was they who began against you the first time? Do you fear them? Allah is more worthy of being feared, if you are muminin.", "তোমরা কি সে লোকদের সাথে লড়াই করবে না যারা তাদের চুক্তি সমূহ ভঙ্গ করেছে, বার্তাবাহককে বিতাড়িত করার চেষ্টা করেছে, এবং তারাই তো সেই লোক যারা প্রথমে যুদ্ধ শুরু করেছে? তোমরা কি তাদেরকে ভয় করো? একমাত্র আল্লাহকে ভয় করাই তোমাদের কাছে প্রত্যাশিত, যদি তোমরা বিশ্বাসী হও।"],
  "9:14": ["Slay them — Allah will punish them at your hands, disgrace them, give you victory over them, and heal the hearts of a believing people.", "তোমরা তাদের সাথে যুদ্ধ করবে, কারন আল্লাহ তোমাদের হাতে তাদের শাস্তি দেবেন, তাদেরকে অপদস্ত করবেন, তাদের উপর তোমাদের বিজয় দেবেন, এবং বিশ্বাসীদের বক্ষ শীতল করবেন।"],
  "9:15": ["And remove the rage from their hearts. And Allah turns in mercy toward whomever Allah wills — and Allah is knowing, wise.", "তিনি এছাড়াও বিশ্বাসীদের হৃদয় থেকে ক্রোধ অপসারণ করবেন। আল্লাহ উদ্ধার করেন যাকে তিনি ইচ্ছা করেন। আল্লাহ সর্বজ্ঞ, সব থেকে জ্ঞানী।"],
  "9:16": ["Or did you reckon that you would be left alone, before Allah knows those of you who strive and take no intimate protector besides Allah, Allah's Rasul, and the muminin? And Allah is fully aware of what you do.", "তোমরা কি ভেবেছে যে তোমাদেরকে এমনি এমনি ছেড়ে দেয়া হবে আল্লাহ তোমাদের মধ্যে তাদেরকে আলাদা না করেই যারা সংগ্রাম করে, এবং কখনো নিজেদেরকে মিত্র করে না আল্লাহর শত্রুদের সাথে, অথবা তাঁর বার্তাবাহকের শত্রুদের সাথে, অথবা বিশ্বাসীদের শত্রুদের সাথে? আল্লাহ পূর্ণ জ্ঞাত সবকিছু সম্পর্কে যা তোমরা করো।"],
  "9:17": ["It is not for the mushrikin to tend the mosque of Allah while witnessing against themselves with disbelief. Those — their deeds are void, and in the fire they abide forever.", "প্রতিমা উপাসকরা আল্লাহর মসজিদে নিয়মিত হয় না, যখন তাদের অবিশ্বাস স্বীকার করছে। এরা তাদের কাজ বিনষ্ট করেছে, এবং তারা চিরকাল নরকে বাস করবে।"],
  "9:18": ["Only those tend the mosque of Allah who believe in Allah and the Last Day, establish the prayer, give the purifying-dues, and fear none but Allah. Those — perhaps they will be among the guided.", "শুধু সেই লোকেরা আল্লাহর মসজিদে নিয়মিত হয় যারা আল্লাহতে এবং শেষ দিনে বিশ্বাস করে, এবং সংযোগ প্রার্থনাসমূহ (সালাত) প্রতিষ্ঠা করে, এবং বাদ্ধতামূলক (যাকাত) দান করে, এবং আল্লাহ ছাড়া কাউকে ভয় করে না। এরা অবশ্যই পথপ্রাপ্তদের অন্তর্ভুক্ত হবে।"],
  "9:19": ["Do you count the watering of pilgrims and the tending of the Sacred Mosque as equal to one who believes in Allah and the Last Day and strives in the way of Allah? They are not equal with Allah — and Allah does not guide the unjust people.", "তোমরা কি তীর্থযাত্রীদের পানি পান করানো এবং পবিত্র মসজিদের পরিচর্যা করাকে আল্লাহ এবং শেষ দিনে বিশ্বাস করার, এবং আল্লাহর পথে সংগ্রাম করার বিকল্প বিবেচনা করো? তারা আল্লাহর দৃষ্টিতে সমান নয়।  আল্লাহ মন্দ লোকদের পথ প্রদর্শন করেন না।"],
  "9:20": ["Those who believe and emigrate and strive in the way of Allah with their wealth and their lives — greater in degree are they with Allah, and those are the triumphant.", "যারা বিশ্বাস করে,এবং দেশ ত্যাগ করে, এবং তাদের অর্থ এবং তাদের জীবন দিয়ে আল্লাহর পথে সংগ্রাম করে, তারা পদমর্যাদায় আল্লাহর দৃষ্টিতে অনেক বড়। এরাই বিজয়ী।"],
  "9:21": ["Their Rabb gives them glad tidings of mercy from Allah, and approval, and gardens for them in which is lasting bliss.", "তাদের প্রভু তাদের সু-সংবাদ দেনঃ তার পক্ষ থেকে দয়া এবং অনুমোদন, এবং বাগানসমূহ যেখানে তারা চিরস্থায়ী স্বর্গসুখে আনন্দ করে।"],
  "9:22": ["Abiding therein forever. Indeed, with Allah is a great reward.", "চিরদিন তারা সেখানে বসবাস করে। আল্লাহ এক মহা প্রতিদানের অধিকারী।"],
  "9:23": ["O you who believe, do not take your fathers and your brothers as allies if they prefer disbelief over belief — and whoever of you takes them as allies, those are the unjust.", "হে তোমরা যারা বিশ্বাস করো, নিজেদেরকে তোমাদের মাতা-পিতা এবং তোমাদের ভাই-বোনদের মিত্র করো না, যদি তারা বিশ্বাসের উপর অবিশ্বাসকে পছন্দ করে। তোমাদের মধ্যে যারা নিজেদেরকে তাদের মিত্র করে তারা সীমালঙ্গনকারী।"],
  "9:24": ["Say: If your fathers, your sons, your brothers, your spouses, your clans, wealth you have amassed, a trade you fear may slump, and dwellings you are pleased with — are dearer to you than Allah, Allah's Rasul, and striving in the way of Allah, then wait until Allah brings about the command of Allah. And Allah does not guide the rebellious people.", "ঘোষনা করঃ “যদি তোমাদের পিতা-মাতারা, তোমাদের সন্তানেরা, তোমাদের ভাই-বোনেরা, তোমাদের পতি-পত্নীরা, তোমাদের পরিবার, অর্থ যা তোমরা উপার্জন করেছ, ব্যবসা যা নিয়ে তোমরা শঙ্কা করো, এবং ঘর যা তোমরা যত্নে আগলে রাখো আল্লাহ ও তাঁর বার্তাবাহকের চেয়ে প্রিয় হয়, এবং তার উদ্দেশ্যে সংগ্রাম করার চেয়ে, তবে শুধু অপেক্ষা করো যতক্ষণ না আল্লাহ তার রায় দেন।”আল্লাহ মন্দ লোকদের পথপ্রদর্শন করেন না।"],
  "9:25": ["Allah has given you victory in many sites — and on the day of Hunayn, when your great number amazed you but availed you nothing, and the earth, for all its breadth, was straitened for you; then you turned away, fleeing.", "আল্লাহ অনেক পরিস্থিতিতে তোমাদের বিজয় দিয়েছেন। কিন্তু হুনাইনের দিনে, তোমরা তোমাদের বিশাল সংখ্যা নিয়ে অতিরিক্ত গর্বিত হয়ে পড়লে। ফলস্বরুপ, এটি তোমাদের কোন কাজেই আসেনি। প্রশস্ত পৃথিবী তোমাদের চারপাশে এতো সংকীর্ণ হয়ে পড়লো, যে তোমরা ঘুরে দাঁড়ালে এবং পলায়ন করলে।"],
  "9:26": ["Then Allah sent down tranquility upon Allah's Rasul and upon the muminin, and sent down hosts you did not see, and punished those who kafara. And that is the recompense of the kafirin.", "এরপর আল্লাহ অবতীর্ণ করলেন সন্তুষ্টি তাঁর বার্তাবাহকের উপর এবং বিশ্বাসীদের উপর। এবং তিনি অবতীর্ণ করলেন অদৃশ্য সৈন্যদের; তিনি এভাবে তাদেরকে শাস্তি দেন যারা অবিশ্বাস করে। এটা অবিশ্বাসীদের জন্য প্রতিফল।"],
  "9:27": ["Then Allah turns in mercy, after that, toward whomever Allah wills — and Allah is forgiving, merciful.", "চূড়ান্তপর্যায়ে, আল্লাহ উদ্ধার করেন যাকে তিনি ইচ্ছা করেন। আল্লাহ ক্ষমাকারী, সবথেকে দয়ালু।"],
  "9:28": ["O you who believe, the mushrikin are nothing but unclean, so let them not approach the Sacred Mosque after this year of theirs. And if you fear poverty, Allah will enrich you from the bounty of Allah, if Allah wills. Allah is knowing, wise.", "হে তোমরা যারা বিশ্বাস করো, প্রতিমা উপাসকরা দূষিত; তারা এই বছরের পর পবিত্র মসজিদের নিকট আসতে অনুমতি প্রাপ্ত হবে না। যদি তোমরা উপার্জন হারানোর ভয় করো, আল্লাহ তোমাদেরকে তাঁর অফুরন্ত জীবিকা থেকে দেবেন, তাঁর ইচ্ছা অনুসারে। আল্লাহ সর্বজ্ঞ, সবচেয়ে জ্ঞানী।"],
  "9:29": ["Fight those who do not believe in Allah or the Last Day, do not hold sacred what Allah and Allah's Rasul have declared inviolable, and do not profess the religion of truth — among those given the scripture — until they give the levy out of hand, humbled.", "তোমরা তাদের বিরুদ্ধে পালটা লড়াই করবে যারা না বিশ্বাস করে আল্লাহতে, না শেষ দিনে, না তারা নিষেধ করে যা আল্লাহ এবং তাঁর বার্তাবাহক নিষিদ্ধ করেছেন, না তারা সত্য ধর্ম মেনে চলে যারা তাদের মধ্যে ঐশীগ্রন্থ গ্রহণ করেছে, যতক্ষণ না তারা পরিশোধনীয় কর দেয়, ইচ্ছায় অথবা অনিচ্ছায়।"],
  "9:30": ["The Jews say: \"Uzair is the son of Allah,\" and the Christians say: \"The Messiah is the son of Allah.\" That is their saying with their mouths, matching the saying of those who kafara before. May Allah destroy them! How are they turned away?", "ইহুদিরা বলেছিল, “ওজাইর আল্লাহর পুত্র”,যখন খ্রিষ্টানরা বলেছিল, “যীশু আল্লাহর পুত্র!”এগুলো তাদের মুখে উচ্চারিত আল্লাহ নিন্দা। তারা এভাবে আল্লাহনিন্দাগুলো ওদের সাথে মিলিয়ে নেয় যারা অতীতে অবিশ্বাস করেছিল। আল্লাহ তাদের নিন্দা করেন। তারা অবশ্যই পথচ্যুত হয়েছে।"],
  "9:31": ["They have taken their learned ones and their monks as rabbs besides Allah, and the Messiah son of Mary — though they were commanded only to worship one ilah; there is no ilah but Allah. Glorified is Allah above what they associate.", "তারা তাদের ধর্মীয় নেতা এবং পন্ডিতদেরকে প্রভু হিসেবে স্থাপন করেছে, আল্লাহর বদলে। অন্যরা মরিয়মের পুত্র, মূসার প্রতি আল্লাহত্ব আরোপ করলো। তাদের সকলকে আদেশ দেয়া হয়েছিল শুধু এক উপাস্যের উপাসনা করতে। তিনি ছাড়া অন্য কোন উপাস্য নেই। তিনি মহিমান্বিত, কোন অংশীদার থাকা থেকে অনেক উর্ধ্বে।"],
  "9:32": ["They want to extinguish the light of Allah with their mouths — but Allah refuses except to complete the light, even though the kafirin are averse.", "তারা তাদের মুখ দিয়ে আল্লাহর আলো নিভিয়ে দিতে চায়, কিন্তু আল্লাহ তাঁর আলো যথার্থ করানোয়় জোড় দেন, অবিশ্বাসীদের সত্ত্বেও।"],
  "9:33": ["It is Allah who has sent the Rasul with the guidance and the religion of truth, to make it prevail over all religion — even though the mushrikin are averse.", "তিনিই সে সত্ত্বা যিনি তাঁর বার্তাবাহককে  পথনির্দেশনা এবং সত্য ধর্ম দিয়ে পাঠালেন, এবং একে সকল ধর্মের উপর আধিপত্যশীল করবেন, প্রতিমা উপাসকদের সত্তেও।"],
  "9:34": ["O you who believe, many of the learned ones and the monks indeed devour people's wealth by falsehood and turn others away from the way of Allah — and those who hoard gold and silver and do not spend it in the way of Allah: give them tidings of a painful punishment.", "হে তোমরা যারা বিশ্বাস করো, অনেক ধর্মীয় নেতা এবং প্রচারকরা লোকদের অর্থ অবৈধভাবে নেয়, এবং আল্লাহর পথ থেকে প্রতিহত করে। যারা স্বর্ন ও রূপা জমা করে, এবং সেগুলো আল্লাহর উদ্দেশ্যে ব্যয় না করে, তাদেরকে এক যন্ত্রনাদায়ক শাস্তির প্রতিশ্রুতি দাও।"],
  "9:35": ["On the day it is heated in the fire of Jahannam, and their foreheads, sides, and backs are branded with it: \"This is what you hoarded for yourselves — so taste what you used to hoard.\"", "সে দিন আসবে যখন তাদের স্বর্ন ও রূপা নরকের আগুনে উত্তপ্ত করা হবে, এরপর তাদের কপাল, তাদের পার্শ্ব, এবং তাদের পশ্চাৎভাগ পোড়ানো হবেঃ “এটা হচ্ছে যা তোমরা নিজেদের জন্য জমা করেছিলে, সুতরাং স্বাদ নাও যা তোমরা জমা করেছ।”"],
  "9:36": ["Indeed, the count of months with Allah is twelve months, in the book of Allah, the day Allah created the skies and the earth; of them, four are inviolable. That is the upright religion — so do not wrong yourselves in them, and fight the mushrikin all together, just as they fight you all together, and know that Allah is with the reverent.", "আল্লাহর দৃষ্টিভঙ্গি থেকে গননায় মাস বারটি। এটি আল্লাহর আইন, যেদিন থেকে তিনি আকাশমন্ডলী  ও পৃথিবী সৃষ্টি করেছেন। এগুলোর চারটি পবিত্র। এটাই যথার্থ ধর্ম; তোমরা পবিত্র মাসগুলোতে (লড়াই করে) তোমাদের আত্মার ক্ষতি করবে না। কিন্তু, তোমরা প্রতিমা উপাসকদের বিরুদ্ধে পূর্ণমাত্রায় যুদ্ধ ঘোষণা করতে পারো (এমনকি পবিত্র মাসগুলোতেও), যখন তারা পূর্ণমাত্রায় তোমাদের বিরুদ্ধে যুদ্ধ ঘোষণা করে, এবং জানো যে আল্লাহ সৎকর্মশীলদের পাশে রয়েছেন।"],
  "9:37": ["Indeed, the postponement is but an increase in disbelief, by which those who disbelieve are led astray: they declare it lawful one year and inviolable another year, to match the count of what Allah made inviolable — thus making lawful what Allah made inviolable. Their evil deeds are made fair to them, and Allah does not guide the committing kufr people.", "পবিত্র মাসগুলোর পরিবর্তন করা অত্যধিক অবিশ্বাসের একটি চিহ্ন; এটি তাদের পথভ্রষ্টতা বাড়িয়ে দেয় যারা অবিশ্বাস করেছে। তারা পবিত্র মাসগুলো এবং সাধারন মাসগুলোতে অদল-বদল করে, যদিও আল্লাহর পবিত্র করা মাসগুলোর সংখ্যা ঠিক রাখে। তারা এভাবে তা ভঙ্গ করে যা আল্লাহ পবিত্র করেছেন। তাদের মন্দ কাজগুলো তাদের চোখে সু-সজ্জিত করা হয়েছে। আল্লাহ অবিশ্বাসী লোকদের পথ দেখান না।"],
  "9:38": ["O you who believe, what is the matter with you that, when it is said to you, \"Go forth in the way of Allah,\" you hang back heavily toward the earth? Are you content with the nearer life over the Last? Yet the enjoyment of the nearer life compared to the Last is nothing but little.", "হে তোমরা যারা বিশ্বাস করো, যখন তোমাদের বলা হয়, “আল্লাহর উদ্দেশ্যে যুদ্ধের জন্য একত্রিত হও, ”কেন তোমরা তীব্রভাবে মাটির সাথে আঁকড়ে থাকো? তোমরা কি পরকালের জায়গায় এই দুনিয়াবি জীবন পছন্দ করেছ? এই দুনিয়ার উপকরন, পরকালের তুলনায়, শূন্য।"],
  "9:39": ["If you do not go forth, Allah will punish you with a painful punishment and will substitute another people in your place — and you will not harm Allah in anything. Allah is powerful over all things.", "যদি না তোমরা যুদ্ধের জন্য একত্রিত হও, তিনি তোমাদেরকে যন্ত্রণাদায়ক শাস্তিতে পতিত করবেন এবং তোমাদের জায়গায় অন্য লোকদের প্রতিস্থাপন করবেন; তোমরা কখনো তাঁর সামান্যতম ক্ষতিও করতে পারো না। আল্লাহ সর্বশক্তিমান।"],
  "9:40": ["If you do not help that one — Allah has already helped, when those who disbelieve drove the Rasul out, the second of two, when the two were in the cave, when the Rasul said to the companion: \"Do not grieve — Allah is with us.\" Then Allah sent down tranquility upon the Rasul and strengthened the Rasul with hosts you did not see, and made the word of those who disbelieve the lowest, while the word of Allah is the highest. And Allah is mighty, wise.", "যদি তোমরা তাকে (বার্তাবাহককে) সমর্থন দিতে ব্যর্থ হও, আল্লাহ তাকে ইতোমধ্যেই সমর্থন দিয়েছেন। তাই, যখন অবিশ্বাসীরা তাকে ধাওয়া করলো, এবং গুহায় সে দুজনের একজন ছিল, সে তার বন্ধুকে বলল, “দুশ্চিন্তা করো না; আল্লাহ আমাদের সাথে আছেন।”আল্লাহ তখন তার উপর সন্তুষ্টি এবং নিরাপত্তা অবতীর্ণ করলেন, এবং অদৃশ্য সৈন্য দিয়ে তাকে সমর্থন করলেন। তিনি অবিশ্বাসীদের কথার অবমূল্যায়ন করলেন। আল্লাহর বানী সর্বোচ্চ প্রভাব বিস্তার করে। আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "9:41": ["Go forth, light and heavy, and strive with your wealth and your souls in the way of Allah. That is better for you, if only you knew.", "তোমরা তৎক্ষনাৎ যুদ্ধের জন্য একত্রিত হবে, অল্প অথবা অধিক (সজ্জিত), এবং আল্লাহর উদ্দেশ্যে সংগ্রাম করো তোমাদের অর্থ এবং তোমাদের জীবন দিয়ে। এটা তোমাদের জন্য উত্তম, যদি শুধু তোমরা জানতে।"],
  "9:42": ["Had it been a near gain and a moderate journey, they would have followed you — but the distance was too far for them. And they will swear by Allah: \"If we could, we would have gone out with you.\" They destroy themselves — and Allah knows that they are liars.", "যদি কোন আশু পার্থিব অর্জন, এবং কোন সংক্ষিপ্ত যাত্রা থাকতো, তারা তোমার অনুসরণ করতো। কিন্তু সংগ্রাম করাটাই তাদের জন্য অত্যধিক। তারা আল্লাহর নামে শপথ করবেঃ “যদি আমরা পারতাম, আমরা তোমাদের সাথে যুদ্ধের জন্য একত্রিত হতাম।”তারা এভাবে নিজেদের আঘাত করে, এবং আল্লাহ জানেন যে তারা মিথ্যাবাদী।"],
  "9:43": ["Allah has pardoned you. Why did you give them leave, before it became clear to you which of them were sadiq, and you knew the kazibin?", "আল্লাহ তোমাকে ক্ষমা করেছেনঃ কেন তুমি তাদেরকে (পিছনে থাকার) অনুমতি দিলে, তুমি আগে মিথ্যাবাদীদের থেকে যারা সত্যবাদী তাদেরকে আলাদা করতে পারতে?"],
  "9:44": ["Those who believe in Allah and the Last Day do not ask your leave to strive with their wealth and their souls — and Allah is knowing of the reverent.", "যারা প্রকৃতই আল্লাহ এবং শেষ দিনে বিশ্বাস করে তারা তাদের অর্থ এবং তাদের জীবন দিয়ে সংগ্রাম করার সুযোগটি এড়াতে তোমার কাছে অনুমতি চায় না। আল্লাহ সৎকর্মশীলদের সম্পর্কে পূর্ন সচেতন।"],
  "9:45": ["Only those ask your leave who do not believe in Allah and the Last Day, whose hearts are in doubt — and in their doubt they waver.", "একমাত্র সে লোকেরাই অব্যহতি পেতে চায় যারা প্রকৃতই আল্লাহ এবং শেষ দিনে বিশ্বাস করে না। তাদের হৃদয় সন্দেহে পূর্ন, এবং তাদের সন্দেহ তাদেরকে দ্বিধাগ্রস্থ করে।"],
  "9:46": ["Had they wanted to go out, they would have prepared equipment for it — but Allah disliked their setting out, so held them back, and it was said: \"Sit with those who sit.\"", "তারা যদি সত্যিই যুদ্ধের জন্য একত্রিত হতে চাইতো, তারা পুরোপুরিভাবে এরজন্য প্রস্তুত হতো। কিন্তু আল্লাহ তাদের অংশগ্রহণ অপছন্দ করলেন, তাই তিনি তাদের নিরুৎসাহিত করলেন; তাদেরকে বলা হলো, “তাদের সাথে পেছনে থাকো যারা পেছনে থাকছে”।"],
  "9:47": ["Had they gone out among you, they would have added nothing for you but corruption, and they would have plunged into your midst seeking discord for you — and among you are listeners to them. And Allah is knowing of the unjust.", "তারা যদি তোমাদের সাথে যুদ্ধের জন্য একত্রিত হতো, তারা বিভ্রান্তি সৃষ্টি করতো, এবং তোমাদের মাঝে দ্বন্দ এবং বিভাজনের কারন ঘটাতো। তোমাদের কারো কারো মধ্যে তাদের কথা শুনার প্রতি প্রবনতা ছিল। আল্লাহ সীমালঙ্ঘনকারীদের ব্যাপারে সম্পূর্ণ অবগত।"],
  "9:48": ["They had sought discord before, and overturned affairs for you — until the truth came and the command of Allah prevailed, while they were unwilling.", "অতীতে তারা তোমাদের মাঝে বিভ্রান্তি ছড়ানোর সুযোগ খুঁজত, এবং তোমাদের জন্য বিষয়গুলোকে বিভ্রান্তিময় করতো, কিন্তু, সত্য সবশেষে বিজয়ী হয়, এবং আল্লাহর পরিকল্পনা বাস্তবায়িত হয়, তাদের সত্ত্বেও।"],
  "9:49": ["And among them is one who says: \"Give me leave, and do not put me to trial.\" Surely into trial they have fallen — and indeed, Jahannam encompasses the kafirin.", "তাদের কেউ কেউ বলবে, “আমাকে (থেকে যাওয়ার) অনুমতি দিন; আমার উপর এরকম একটি কষ্ট আরোপ করবেন না”। আসলে, তারা এভাবে এক ভয়াবহ কষ্ট টেনে এনেছে; নরক অবিশ্বাসীদের ঘিরে ফেলছে।"],
  "9:50": ["If good befalls you, it grieves them; and if a calamity befalls you, they say: \"We took our affair in hand beforehand\" — and they turn away, rejoicing.", "যদি তোমাদের ভালোকিছু হয়, তারা কষ্ট পায়, এবং যদি কোন দুর্দশা তোমাদের উপর আসে, তারা বলে, “আমরা তোমাদেরকে এটাই বলেছিলাম, ”যদিও তারা আনন্দে পিছনে চলে যায়।"],
  "9:51": ["Say: \"Nothing will befall us except what Allah has decreed for us. Allah is our protector — and upon Allah let the muminin place their trust.\"", "বল, \"আমাদের কিছুই হয় না, আল্লাহ আমাদের জন্য যা জারি করেছেন তা ছাড়া। তিনি আমাদের প্রভু এবং মনিব। বিশ্বাসীরা আল্লাহর প্রতি আস্থা রাখবে।\""],
  "9:52": ["Say: \"Do you wait for us anything but one of the two fair ends? We, for our part, wait for you — that Allah strike you with a punishment from the divine presence or at our hands. So wait — we are waiting with you.\"", "বল, \"তোমরা আমাদের জন্য কেবল দু’টো ভাল জিনিস (বিজয় অথবা শহীদত্ব) থেকে একটি আশা করতে পারো, পক্ষান্তরে আমরা তোমাদের জন্য আশা করি আল্লাহর পক্ষ থেকে নিন্দা এবং তাঁর পক্ষ থেকে অথবা আমাদের হাতে শাস্তি। অতএব, অপেক্ষা করো, এবং আমরাও তোমাদের সাথে অপেক্ষা করবো।"],
  "9:53": ["Say: \"Spend, willingly or unwillingly — it will never be accepted from you. You have been a rebellious people.\"", "বল, “ব্যয় করো,ইচ্ছায় অথবা অনিচ্ছায়। তোমাদের কাছ থেকে কিছুই গ্রহন করা হবে না, কারণ তোমরা মন্দ লোক।”"],
  "9:54": ["And nothing withholds that their spending be accepted from them except that they disbelieve in Allah and in Allah's Rasul, and they come to the prayer only sluggishly, and they spend only unwillingly.", "তাদের ব্যয় গ্রহনযোগ্য হতে যা বাধা দিয়েছিল তা হচ্ছে তারা আল্লাহ এবং তাঁর বার্তাবাহককে অবিশ্বাস করেছে, এবং যখন তারা সংযোগ প্রার্থনাসমূহ (সালাত) পালন করতো, তারা সেগুলো অলসতার সাথে পালন করতো, এবং যখন তারা দান করতো, তারা তা করতো অনিচ্ছায়।"],
  "9:55": ["Let neither their wealth nor their children amaze you — Allah only wants, by means of them, to punish them in the nearer life, and that their souls perish while they are kafirin.", "তাদের অর্থ, অথবা তাদের সন্তানাদি দ্বারা অভিভূত হইও না। আল্লাহ এই জীবনে এগুলোকে তাদের জন্য শাস্তির উৎস করেছেন, এবং (যখন তারা মারা যায়) তাদের আত্মা বেড়িয়ে যায় যে সময় তারা অবিশ্বাসী।"],
  "9:56": ["They swear by Allah that they are indeed of you — but they are not of you; rather, they are a people who sow division.", "তারা আল্লাহর নামে শপথ করে যে তারা তোমাদের সাথে আছে, যদিও তারা তোমাদের সাথে নেই; তারা বিভেদকারী লোক।"],
  "9:57": ["If they could find a refuge, or caves, or any way in, they would turn to it, rushing headlong.", "যদি তারা কোন আশ্রয়, অথবা গুহা, অথবা কোন লুকানোর স্থান পেতো, তারা তাতে যেতো, দ্রুতবেগে।"],
  "9:58": ["And among them are those who find fault with you concerning the alms: if they are given from them they are pleased, but if they are not given from them, at once they are angry.", "তাদের কেউ কেউ তোমার দান বণ্টনের সমালোচনা করে; যদি তাদেরকে তা থেকে দেয়া হয়, তারা সন্তুষ্ট হয়, কিন্তু তাদেরকে যদি তা থেকে না দেয়া হয়, তারা অভিযোগকারী হয়।"],
  "9:59": ["If only they had been content with what Allah and Allah's Rasul gave them, and had said: \"Allah is enough for us — Allah will give us from the bounty, and so will the Rasul. To Allah we turn eagerly.\"", "তাদের উচিত আল্লাহ এবং তাঁর বার্তাবাহক তাদেরকে যা দিয়েছেন তাতে সন্তুষ্ট হওয়া। তাদের বলা উচিত ছিল, “আল্লাহ আমাদের জন্য যথেষ্ট। আল্লাহ তাঁর অনুগ্রহ থেকে আমাদের জন্য দেবেন, এবং তাঁর বার্তাবাহকও তা-ই করবেন। আমরা একমাত্র আল্লাহর অন্বেষণ করছি”।"],
  "9:60": ["The alms are only for the poor, the destitute, those working on them, those whose hearts are to be joined, for freeing necks, for those burdened with liability, in the way of Allah, and for the wayfarer — an ordinance from Allah. And Allah is knowing, wise.", "দানসমূহ যাবে দরিদ্র, অভাবী, সে শ্রমিকদের কাছে যারা এগুলো সংগ্রহ করে, নতুন ধর্মান্তরিতদের কাছে, দাসদের মুক্ত করতে, তাদের কাছে যারা ভারগ্রস্ত অপ্রত্যাশিত খরচ দ্বারা, আল্লাহর উদ্দেশ্যে, এবং ভ্রমণকারী ভিনদেশীদের জন্য। এমনই আল্লাহর প্রত্যাদেশ। আল্লাহ সর্বজ্ঞ, সব থেকে জ্ঞানী।"],
  "9:61": ["And among them are those who harm the Nabi and say: \"That one is all ears.\" Say: \"An ear of good for you — one who believes in Allah and believes for the muminin, and a mercy for those of you who believe.\" And those who harm the Rasul of Allah — for them is a painful punishment.", "তাদের কেউ কেউ নবীকে এই বলে আঘাত করে, “সে সবকিছুতে কান দেয়!”বল, “এটা তোমাদের জন্য উত্তম যে সে তোমাদের কথা শোনে। সে আল্লাহতে বিশ্বাস করে, এবং বিশ্বাসীদের প্রতি আস্থা রাখে। সে তোমাদের মধ্যে যারা বিশ্বাস করে তাদের জন্য একটি দয়া।”যারা আল্লাহর বার্তাবাহককে আঘাত করে তারা এক যন্ত্রনাদায়ক শাস্তি টেনে এনেছে।"],
  "9:62": ["They swear to you by Allah to please you — but Allah and Allah's Rasul are more worthy to be pleased by them, if they are muminin.", "তারা তোমাদের কাছে আল্লাহর নামে শপথ করে, তোমাদেরকে সন্তুষ্ট করতে, যখন আল্লাহ এবং তাঁর বার্তাবাহককে সন্তুষ্ট করা অধিক উপযুক্ত, যদি তারা সত্যিই বিশ্বাসী হয়।"],
  "9:63": ["Do they not know that whoever opposes Allah and Allah's Rasul — for such is the fire of Jahannam, abiding therein forever? That is the great disgrace.", "তারা কি জানে না যে যেকেউ আল্লাহ এবং তাঁর বার্তাবাহকের বিরোধিতা করে সে অনন্তকালের জন্য নরকের আগুন টেনে এনেছে? এটি হচ্ছে নিকৃষ্টতম অবমাননা।"],
  "9:64": ["The munafiqin dread that a chapter be sent down upon them informing them of what is in their hearts. Say: \"Go on mocking — Allah will bring out what you dread.\"", "ভন্ডরা আশঙ্কা করে যে তাদের হৃদয়ের ভেতরে যা আছে তা প্রকাশ করে একটি সূরা প্রকাশিত হতে পারে। বল, “চালিয়ে যাও এবং উপহাস করো। আল্লাহ ঠিক সে বিষয়টিই প্রকাশ করবেন যাতে তোমরা ভীত।"],
  "9:65": ["And if you ask them, they will surely say: \"We were only wading in idle talk and playing.\" Say: \"Was it Allah, and the signs of Allah, and the Rasul of Allah, that you were mocking?\"", "যদি তুমি তাদেরকে জিজ্ঞাসা করো, তারা বলবে, \"আমরা শুধু ব্যঙ্গ এবং মজা করছিলাম।”বল, \"তোমরা কি উপলব্ধি করো যে তোমরা ব্যঙ্গ করছো আল্লাহকে, এবং তাঁর প্রকাশনাবলিকে, এবং তাঁর বার্তাবাহককে?”"],
  "9:66": ["Make no excuses — you have kafara after your belief. If We pass over a party of you, We punish a party, because they were mujrimin.", "ক্ষমা  চে-ও না। তোমরা অবিশ্বাস করেছো বিশ্বাস করার পর। যদি আমরা তোমাদের কাউকে কাউকে ক্ষমা করি, আমরা তোমাদের ভেতর অন্যদের শাস্তি দেবো, তাদের পাপের ফলস্বরূপ।"],
  "9:67": ["The munafiqin, men and nisa, are of one another: they command the rejected, forbid the recognized, and draw in their hands. They forgot Allah, so Allah forgot them — indeed, the munafiqin are the rebellious.", "ভণ্ড পুরুষ এবং ভণ্ড নারীরা একে অপরের সাথে রয়েছে- তারা মন্দের ওকালতি করে এবং নিষেধ করে সৎকর্মশীলতা, এবং তারা কৃপণ। তারা আল্লাহকে ভুলে গিয়েছে, তাই তিনি তাদের ভুলে গিয়েছেন। ভণ্ডরা সত্যই মন্দ।"],
  "9:68": ["Allah has promised the munafiqin, men and nisa, and the kafirin, the fire of Jahannam, abiding therein forever — it is enough for them. And Allah has cursed them, and for them is a lasting punishment.", "আল্লাহ ভণ্ড পুরুষ এবং ভণ্ড নারীদের, একই সাথে অবিশ্বাসীদের অঙ্গীকার দেন, নরকাগ্নির, যেখানে তারা চিরকাল বাস করবে। এটা তাদের জন্য যথেষ্ট। আল্লাহ তাদের নিন্দা করেন; তারা টেনে এনেছে চিরস্থায়ী শাস্তি।"],
  "9:69": ["Like those before you — they were stronger than you in strength and greater in wealth and children; they enjoyed their life-terms, and you have enjoyed your life-terms as those before you enjoyed theirs, and you waded in idle talk as they waded. Those — their deeds are void in the nearer life and the Last, and those are the khasirin.", "তোমাদের আগে তাদের কেউ কেউ তোমাদের চেয়ে শক্তিশালী ছিল, এবং অধিক অর্থ ও সন্তানের অধিকারী ছিল। তারা তাদের পার্থিব সম্পদে আচ্ছন্ন হয়েছিল। একইভাবে, তোমরা তোমাদের পার্থিব সম্পদে আচ্ছন্ন হয়ে পড়েছো, তোমাদের পূর্বের ঠিক তাদের মতো যারা আচ্ছন্ন হয়ে পড়েছিল। তোমরা সম্পূর্ণ অমনোযোগী হয়ে পড়েছো, ঠিক যেমন তারা  অমনোযোগী  ছিল। এমনই হচ্ছে সেসব লোক যারা তাদের কাজগুলো নষ্ট করেছে, এই দুনিয়া এবং পরকাল উভয় স্থানে; তারাই ক্ষতিগ্রস্থ।"],
  "9:70": ["Has the news not come to them of those before them — the people of Nuh, and Ad, and Thamud, and the people of Ibrahim, and the people of Midian, and the Overturned ones? Their rusul came to them with clear proofs; and it was not for Allah to wrong them, but it was themselves they wronged.", "তারা কি পূর্ববর্তী প্রজন্মগুলো থেকে কিছুই শেখেনি; নূহ, আদ সামুদের লোক, ইবরাহীমের লোক, মাদিয়ানের অধিবাসী, এবং (সদম ও গমরার) সেই মন্দকর্মীদের থেকে? তাদের বার্তাবাহকরা তাদের কাছে সুস্পষ্ট প্রমান নিয়ে গিয়েছিলো। আল্লাহ কখনো তাদের প্রতি অন্যায় করেননি, তারাই তাদের নিজেদের আত্মার প্রতি অন্যায় করেছিল।"],
  "9:71": ["And the muminin, men and nisa, are allies of one another: they command the recognized, forbid the rejected, establish the prayer, give the purifying-dues, and obey Allah and Allah's Rasul. Those — Allah will have mercy on them. Allah is mighty, wise.", "বিশ্বাসী পুরুষ এবং নারীরা একে অন্যের মিত্র। তারা সৎকর্মশীলতার ওকালতি করে এবং মন্দে নিষেধ করে, তারা সংযোগ প্রার্থনা (সালাত) পালন করে এবং বাধ্যতামূলক দান (যাকাত) দেয়, এবং তারা আল্লাহ ও তাঁর বার্তাবাহককে মান্য করে। এদের প্রতি আল্লাহর দয়া বর্ষিত হবে। আল্লাহ সর্বশক্তিমান, সবচেয়ে জ্ঞানী।"],
  "9:72": ["Allah has promised the muminin, men and nisa, gardens through which rivers flow, abiding therein forever, and pleasant dwellings in the gardens of Eden — and approval from Allah is greater. That is the great triumph.", "আল্লাহ বিশ্বাসী পুরুষ এবং বিশ্বাসী নারীদের প্রবাহিত ঝর্নাসহ বাগানসমূহের প্রতিশ্রুতি দেন, যেখানে তারা চিরকাল বসবাস করে, এবং ইডেনের বাগানগুলোর জাঁকজমকময় অট্রালিকাসমূহ। এবং আল্লাহর আশীর্বাদ ও অনুমোদন আরো বড়। এটি শ্রেষ্ঠ বিজয়।"],
  "9:73": ["O Nabi, strive against the kafirin and the munafiqin, and be hard upon them. Their refuge is Jahannam — and wretched is the destination.", "হে নবী, অবিশ্বাসী এবং ভন্ডদের বিরুদ্ধে সংগ্রাম করো, এবং তাদের সাথে কার্যকলাপে কঠোর হও। তাদের নিয়তি নরক; কি এক শোচনীয় আবাস!"],
  "9:74": ["They swear by Allah that they did not say — yet they said the word of disbelief, and kafara after their submission, and resolved what they could not attain. And they resented nothing except that Allah and Allah's Rasul enriched them from the bounty. So if they repent, it will be better for them; but if they turn away, Allah will punish them with a painful punishment in the nearer life and the Last — and for them in the earth is neither protector nor helper.", "তারা আল্লাহর নামে শপথ করে যে তারা কখনো তা বলেনি, যদিও তারা অবিশ্বাসমূলক শব্দ উচ্চারণ করেছে; তারা আত্মসমর্পণকারী হবার পর অবিশ্বাস করেছে।  আসলে, তারা ত্যাগ করলো  যা তাদের কখনো ছিল না। তারা বিদ্রোহ করেছে যদিও আল্লাহ এবং তাঁর বার্তাবাহক তাদেরকে তাঁর দয়া ও জীবিকা বর্ষণ করেছেন।  যদি তারা অনুতপ্ত হয়, এটি হবে তাদের জন্য সর্বোত্তম।  কিন্তু যদি তারা মুখ ফিরিয়ে নেয়, আল্লাহ তাদেরকে এই জীবনে এবং পরকালে যন্ত্রনাদায়ক শাস্তি দিবেন।  তারা পৃথিবীতে তাদের প্রভু ও মনিব হিসেবে কাউকে পাবে না।"],
  "9:75": ["And among them are those who pledged to Allah: \"If Allah gives us of the bounty, we will surely give alms and be among the salihin.\"", "তাদের কেউ কেউ এমনকি অঙ্গীকার করেছিলঃ “যদি আল্লাহ আমাদেরকে তাঁর দয়া বর্ষণ করেন, আমরা দানশীল হবো, এবং সৎকর্মশীল জীবন-যাপন করবো।”"],
  "9:76": ["But when Allah gave them of the bounty, they stinted with it, turned away, and they were averse.", "কিন্তু যখন তিনি তাদেরকে তাঁর জীবিকা বর্ষণ করলেন, তারা কৃপণ হয়ে গেলো, এবং অনীহায় মুখ ফিরিয়ে নিল।"],
  "9:77": ["So hypocrisy rebounded upon them in their hearts, until the day they meet it — because they failed Allah in what they promised, and because they used to lie.", "ফলস্বরূপ, তিনি তাদের হৃদয়ে ভন্ডামী দিয়ে তাদেরকে করলেন মহামারীগ্রস্থ, তাঁর সাথে সাক্ষাতের দিন পর্যন্ত। এটা এ কারনে যে তারা আল্লাহর সাথে করা অঙ্গীকার ভঙ্গ করলো, এবং তাদের মিথ্যা বলার কারনে।"],
  "9:78": ["Do they not know that Allah knows their secrets and their private counsels, and that Allah is the knower of the unseen?", "তারা কি উপলব্ধি করে না যে, আল্লাহ জানেন তাদের গোপন বিষয়গুলো, এবং তাদের চক্রান্তগুলো, এবং যে আল্লাহ সকল গোপন বিষয়ই জানেন।"],
  "9:79": ["Those who find fault with the willing givers among the muminin in the alms, and with those who find nothing but their utmost — and so they mock them: Allah has mocked them, and for them is a painful punishment.", "যারা উদার বিশ্বাসীদের সমালোচনা করে খুব বেশি দেয়ার জন্য, এবং গরিব বিশ্বাসীদের উপহাস করে খুব কম দেয়ার জন্য, আল্লাহ তাদেরকে ঘৃণা করেন। তারা টেনে এনেছে একটি যন্ত্রণাদায়ক শাস্তি।"],
  "9:80": ["Ask forgiveness for them or do not ask forgiveness for them — if you ask forgiveness for them seventy times, Allah will never forgive them. That is because they kafara in Allah and Allah's Rasul, and Allah does not guide the rebellious people.", "তুমি তাদের জন্য ক্ষমা প্রার্থনা করো, অথবা ক্ষমা প্রার্থনা না করো- এমনকি যদি তুমি সত্তর বার তাদের জন্য ক্ষমা প্রার্থনা করো- আল্লাহ তাদেরকে ক্ষমা করবেন না। এটা এ কারনে যে তারা আল্লাহ এবং তাঁর বার্তাবাহককে অবিশ্বাস করে। আল্লাহ মন্দ লোকদের পথ-প্রদর্শন করেন না।"],
  "9:81": ["Those left behind rejoiced in their sitting-place behind the Rasul of Allah, and disliked striving with their wealth and their souls in the way of Allah, and said: \"Do not go forth in the heat.\" Say: \"The fire of Jahannam is more severe in heat\" — if only they understood.", "বসে থাকা লোকেরা আল্লাহর বার্তাবাহকের পিছনে থেকে যাওয়ায় আনন্দ করেছিলো, এবং আল্লাহর উদ্দেশ্যে তাদের অর্থ ও তাদের জীবন দিয়ে সংগ্রাম করাকে ঘৃনা করেছিল। তারা বলেছিল, “আমাদেরকে এই উত্তাপে যুদ্ধের জন্য একত্রিত করো না!”বল, “নরকের আগুন অধিক উত্তপ্ত, ”যদি তারা শুধু অনুধাবন করতে পারতো।"],
  "9:82": ["So let them laugh a little and weep much — as recompense for what they used to earn.", "তাদেরকে একটু হাসতে দাও, এবং অনেক কাঁদতে দাও। এটি হচ্ছে তাদের অর্জন করা পাপের প্রতিদান।"],
  "9:83": ["Then, if Allah returns you to a party of them and they ask your leave to go out, say: \"You shall never go out with me, and never fight an enemy with me. You were content with sitting the first time — so sit with those who stay behind.\"", "যদি আল্লাহ তোমাকে এমন অবস্থায় ফিরিয়ে নেন যেখানে তারা তোমার সাথে যুদ্ধের জন্য একত্রিত হতে অনুমতি চায়। তুমি বলবে, \"তোমরা আবার কখনো আমার সাথে যুদ্ধের জন্য একত্রিত হবে না, না তোমরা কখনো কোন শত্রুর বিরুদ্ধ্বে আমার সাথে লড়াই করবে। কারণ তোমরাই প্রথমে বসে থাকা লোকদের সাথে থাকা পছন্দ করেছো। সেজন্য, তোমরা অবশ্যই বসে থাকা লোকদের সাথে থাকবে।”"],
  "9:84": ["And never pray over any of them who dies, nor stand at that one's grave — they kafara in Allah and Allah's Rasul and died while they were rebellious.", "তুমি তাদের কারো জন্য দাফনপূর্ব প্রার্থনা করবে না যখন সে মারা যায়, না তুমি তার কবরে দাঁড়াবে। তারা আল্লাহ ও তাঁর বার্তাবাহককে অবিশ্বাস করেছে, এবং মরেছে পাপী অবস্থায়।"],
  "9:85": ["Let neither their wealth nor their children amaze you — Allah only wants to punish them thereby in the nearer life, and that their souls perish while they are kafirin.", "তাদের অর্থ অথবা তাদের সন্তানদের দ্বারা অভিভূত হইও না। এই দুনিয়াতে আল্লাহ এগুলোকে তাদের জন্য দুর্দশার উৎস করেন, এবং তাদের আত্মা অবিশ্বাসী হিসেবে বেরিয়ে যায়।"],
  "9:86": ["And when a chapter is sent down: \"Believe in Allah and strive with Allah's Rasul,\" the ones of means among them ask your leave and say: \"Leave us — let us be with those who sit.\"", "যখন কোন সুরা প্রকাশিত হয়, বলে যেঃ “আল্লাহতে বিশ্বাস করো, এবং তাঁর বার্তাবাহকের সাথে সংগ্রাম করো”তখন এমনকি তাদের মধ্যকার বলবানরা বলে, “আমাদের থাকতে দিন”।"],
  "9:87": ["They were content to be with the stay-behinds, and their hearts were sealed — so they do not understand.", "তারা বসে থাকাদের সাথে থাকতে পছন্দ করলো। পরিনামে, তাদের হৃদয়ে মোহর এঁটে দেয়া হয়েছিল, এবং এ কারনে, তারা হৃদয়ঙ্গম করতে পারে না।"],
  "9:88": ["But the Rasul and those who believe with that one strive with their wealth and their souls — and those: for them are the good things, and those are the muflihin.", "আর বার্তাবাহক এবং যারা তার সাথে বিশ্বাস করেছে, তারা আগ্রহের সাথে তাদের অর্থ এবং তাদের জীবন দিয়ে সংগ্রাম করে। এরা সকল ভালো জিনিসের যোগ্য হয়েছে; এরাই জয়ী।"],
  "9:89": ["Allah has prepared for them gardens through which rivers flow, abiding therein forever. That is the great triumph.", "আল্লাহ তাদের জন্য প্রবাহিত ঝর্নাসহ বাগান প্রস্তুত করেছেন, যেখানে তারা চিরকাল বসবাস করে। এটাই সবচেয়ে বড় বিজয়।"],
  "9:90": ["And those making excuses among the desert Arabs came to be given leave, while those who lied against Allah and Allah's Rasul sat back. A painful punishment will strike those of them who disbelieve.", "আরবরা অজুহাত বানিয়েছিল, এবং তোমার কাছে এসেছিল পেছনে থেকে যাবার অনুমতি চাইতে। এটি নির্দেশ করে আল্লাহ এবং তাঁর বার্তাবাহককে তাদের প্রত্যাখ্যান- তারা পেছনে থেকে যায়। নিশ্চয়, তাদের মধ্যে যারা অবিশ্বাস করে তারা টেনে এনেছে যন্ত্রণাদায়ক শাস্তি।"],
  "9:91": ["There is no blame upon the weak, nor upon the sick, nor upon those who find nothing to spend — if they are sincere toward Allah and Allah's Rasul. There is no way against the good-doers — and Allah is forgiving, merciful.", "তারা দোষী হবে না যারা দূর্বল, অথবা অসুস্থ, অথবা উৎসর্গ করার জন্য কোনকিছু পায় না, যতক্ষণ পর্যন্ত তারা আল্লাহ ও তাঁর বার্তাবাহকের প্রতি নিবেদিত থাকে। তাদের মধ্যকার সৎকর্মশীলরা দোষী হবে না। আল্লাহ ক্ষমাকারী, পরম দয়ালু।"],
  "9:92": ["Nor upon those who come to you for mounts, and you say: \"I find nothing to mount you upon\" — and they turn away, their eyes pouring with tears, out of grief that they find nothing to spend.", "এছাড়াও তারা অব্যাহতিপ্রাপ্ত যারা তোমার কাছে আসে তোমার সাথে অন্তর্ভুক্ত হবার ইচ্ছায়, কিন্তু তুমি তাদেরকে বলো, \"তোমাদেরকে চালিয়ে নিতে আমার কিছুই করার নেই।”তারা তখন তাদের চোখে অশ্রু নিয়ে ফিরে যায়, সত্যই দু:খ পেয়ে যে তারা অবদান রাখতে সমর্থ হয়নি।"],
  "9:93": ["The blame is only upon those who ask your leave while they are rich. They were content to be with the stay-behinds, and Allah sealed their hearts — so they do not know.", "দোষ হচ্ছে তাদের যারা তোমার কাছে পেছনে থেকে যাওয়ার অনুমতি চায়, এমনকি যদিও তাদের কোন অজুহাত নেই। তারা বসে থাকাদের সাথে থাকতে পছন্দ করেছে। পরিনামে, আল্লাহ তাদের হৃদয়ে মোহর এঁটে দিয়েছেন, এবং এ কারণে, তারা কোন জ্ঞান অর্জন করে না।"],
  "9:94": ["They will make excuses to you when you return to them. Say: \"Make no excuses — we will never believe you. Allah has informed us of your news. And Allah and Allah's Rasul will see your deeds; then you will be returned to the knower of the unseen and the witnessed, and will be told what you used to do.\"", "তারা তোমার কাছে ক্ষমা চায় যখন তুমি (যুদ্ধ থেকে) তাদের কাছে ফিরে আসো। বল, “ক্ষমা চেও না; তোমাদেরকে আমরা আর বিশ্বাস করি না। আল্লাহ আমাদেরকে তোমাদের সম্পর্কে অবগত করেছেন।”আল্লাহ তোমাদের কাজ দেখবেন, এবং বার্তাবাহকও, এরপর তোমরা সকল গোপন এবং প্রকাশ্য বিষয়ের জ্ঞাতার নিকট ফিরে যাবে, এরপর তিনি তোমাদেরকে সবকিছু জানাবেন যা তোমরা করেছিলে।"],
  "9:95": ["They will swear to you by Allah when you return to them, so that you may turn away from them. So turn away from them — they are filth, and their refuge is Jahannam, as recompense for what they used to earn.", "যখন তুমি তাদের কাছে ফিরে আসো, তারা তোমার কাছে আল্লাহর নামে শপথ করবে, কারণ হয়তো তুমি তাদের উপেক্ষা করতে পারো। তাদেরকে উপেক্ষা করো। তারা দূষিত, এবং তাদের নিয়তি নরক, তাদের অর্জিত পাপের প্রতিফল হিসেবে।"],
  "9:96": ["They swear to you so that you may be pleased with them — but even if you are pleased with them, Allah is not pleased with the rebellious people.", "তারা তোমার কাছে শপথ করে, যাতে তুমি তাদেরকে ক্ষমা করে দাও। যদি তুমি তাদেরকে ক্ষমা করেও দাও, আল্লাহ এমন মন্দ লোকদের ক্ষমা করেন না।"],
  "9:97": ["The desert Arabs are more severe in disbelief and hypocrisy, and more apt not to know the limits of what Allah has sent down upon Allah's Rasul. And Allah is knowing, wise.", "আরবরা অবিশ্বাস এবং ভণ্ডামিতে নিকৃষ্টতম। এবং আল্লাহ তাঁর বার্তাবাহকের কাছে যে আইন প্রকাশ করেছেন তা উপেক্ষা করার প্রবণতা সবচেয়ে বেশি। আল্লাহ সর্বজ্ঞ, সবচেয়ে জ্ঞানী।"],
  "9:98": ["And among the desert Arabs are those who take what they spend as a penalty and wait for turns of fortune against you. The turn of evil shall be upon them — and Allah is all-hearing, knowing.", "কিছু আরব (আল্লাহর উদ্দেশে) তাদের ব্যায়কে ক্ষতি হিসেবে গন্য করে, এমনকি প্রত্যাশায় অপেক্ষা করতে থাকে যে তোমার উপর কোন বিপর্যয় আঘাত হানবে। এরাই নিকৃষ্টতম বিপর্যয় টেনে আনবে। আল্লাহ শ্রোতা, সর্বজ্ঞ।"],
  "9:99": ["And among the desert Arabs are those who believe in Allah and the Last Day, and take what they spend as means of nearness with Allah and as prayers of the Rasul. Indeed, it is a nearness for them — Allah will enter them into the mercy. Allah is forgiving, merciful.", "অন্যান্য আরবরা আল্লাহ এবং শেষ দিবসে বিশ্বাস করে, এবং তাদের ব্যয়কে আল্লাহর নৈকট্য লাভের একটি উপায় হিসেবে গন্য করে, এবং বার্তাবাহককে সমর্থনের একটি উপায় হিসেবে গন্য করে। নিশ্চয়ই, এটি তাদেরকে অধিকতর নিকটে আনবে; আল্লাহ তাদেরকে তাঁর দয়ার অন্তর্ভুক্ত করবেন। আল্লাহ ক্ষমাশীল, পরম দয়ালু।"],
  "9:100": ["And the forerunners, the first of the muhajirin and the helpers, and those who followed them with good — Allah is pleased with them, and they are pleased with Allah — and Allah has prepared for them gardens through which rivers flow, abiding therein forever. That is the great triumph.", "প্রথম অগ্রণীদল যারা দেশান্তরিত হয়েছে (মুহাজারিন), এবং সমর্থনকারীরা (আনসার) যারা তাদেরকে আশ্রয় দিয়েছিল, এবং যারা তাদেরকে সৎকর্মশীলতায় অনুসরণ করেছিল, আল্লাহ তাদের প্রতি সন্তুষ্ট, এবং তারা তাঁর প্রতি সন্তুষ্ট। তিনি তাদের জন্য প্রস্তুত করেছেন প্রবাহিত ঝর্না সহ বাগান, যেখানে তারা চিরকাল থাকবে। এটাই সর্বশ্রেষ্ঠ বিজয়।"],
  "9:101": ["And among those around you of the desert Arabs are munafiqin, and among the people of the city — obstinate in hypocrisy. You do not know them; Allah knows them. Allah will punish them twice; then they will be returned to a great punishment.", "তোমাদের চারপাশের আরবদের মধ্যে রয়েছে ভন্ডরা। আরও, শহরের অধিবাসীদের মধ্যে তারা রয়েছে, যারা ভণ্ডামিতে অভ্যস্ত। তুমি তাদের জানো না, কিন্তু আমরা তাদেরকে জানি। আমরা তাদের জন্য শাস্তি দ্বিগুন করবো, এরপর পরিশেষে তারা এক ভয়ানক শাস্তিতে পতিত হয়।"],
  "9:102": ["And others have acknowledged their sins: they mixed a salih deed and another evil. Perhaps Allah will turn in mercy toward them — Allah is forgiving, merciful.", "অন্যান্যরা আছে যারা তাদের পাপ স্বীকার করেছে; তারা ভাল কাজের সাথে মন্দ কাজ মিশিয়েছে। আল্লাহ তাদেরকে উদ্ধার করবেন, কারণ আল্লাহ ক্ষমাকারী, পরম দয়ালু।"],
  "9:103": ["Take from their wealth an alms to purify them and cleanse them thereby, and pray over them. Indeed, your prayer is a calm for them — and Allah is all-hearing, knowing.", "তাদের অর্থ থেকে দান নাও তাদেরকে পরিশুদ্ধ করতে এবং তাদেরকে পবিত্র করতে। এবং তাদেরকে উৎসাহিত করো, কারণ তোমার উৎসাহ তাদেরকে আশ্বস্ত করে। আল্লাহ শ্রোতা, সর্বজ্ঞ।"],
  "9:104": ["Do they not know that it is Allah who accepts repentance from the servants, and takes the alms, and that Allah is the ever-relenting, the merciful?", "তারা কি উপলব্ধি করে না যে আল্লাহ তাঁর উপাসনাকারীদের অনুশোচনা গ্রহন করেন, এবং দান নেন, এবং যে আল্লাহ উদ্ধারকারী, পরম দয়ালু?"],
  "9:105": ["And say: \"Act — Allah will see your deeds, and so will Allah's Rasul and the muminin. And you will be returned to the knower of the unseen and the witnessed, and will be told what you used to do.\"", "বল, “সৎকর্ম করো; আল্লাহ তোমাদের কাজ দেখবেন, এবং তাঁর বার্তাবাহক এবং বিশ্বাসীরাও। অবশেষে, তোমরা সকল গোপন এবং প্রকাশ্য বিষয়ের জ্ঞাতার নিকট ফিরে যাবে, এরপর তিনি তোমাদেরকে সবকিছু জানাবেন যা তোমরা করেছিলে।”"],
  "9:106": ["And others are deferred for the affair of Allah — either Allah will punish them or turn in mercy toward them. And Allah is knowing, wise.", "অন্যান্যরা অপেক্ষায় আছে আল্লাহর সিদ্ধান্তের জন্য; তিনি হয়তো তাদের শাস্তি দেবেন, অথবা হয়তো তিনি তাদের উদ্ধার করবেন। আল্লাহ সর্বজ্ঞ, সবচেয়ে জ্ঞানী।"],
  "9:107": ["And those who have taken a mosque in harm, in disbelief, in dividing the muminin, and as an ambush for whoever warred against Allah and Allah's Rasul before — and they will surely swear: \"We intended nothing but good.\" And Allah witnesses that they are liars.", "আর যারা মসজিদের অপব্যবহার করে অংশীদার উপাসনা চর্চা করে, বিশ্বাসীদের বিভক্ত করে, এবং তাদেরকে স্বস্তি দিয়ে যারা আল্লাহ এবং তাঁর বার্তাবাহকের বিরোধিতা করে। তারা দৃড়তার সাথে শপথ করেঃ “আমাদের উদ্দেশ্য সম্মানজনক!”আল্লাহ সাক্ষ্য দেন যে তারা মিথ্যুক।"],
  "9:108": ["Never stand in it. A mosque founded upon reverence from the first day is more worthy that you stand in it — in it are men who love to purify themselves, and Allah loves the purified.", "তুমি এমন মসজিদে কখনো প্রার্থনা করবে না। যে মসজিদ প্রথম দিন থেকেই ন্যায়পরায়ণতার ভিত্তির উপর প্রতিষ্ঠিত সে স্থান তোমার প্রার্থনার অধিক উপযুক্ত। এখানে আছে লোকেরা, যারা শুদ্ধ হতে ভালবাসে। আল্লাহ তাদেরকে ভালবাসেন যারা নিজেদের শুদ্ধ করে।"],
  "9:109": ["Then is one who founded that one's building upon reverence of Allah and good-pleasure better, or one who founded that one's building on the edge of a crumbling cliff — so it tumbles with that one into the fire of Jahannam? And Allah does not guide the unjust people.", "যে ব্যক্তি তার ইমারত আল্লাহ ভক্তি এবং তাঁর সম্মতি অর্জনের ভিত্তির উপর প্রতিষ্ঠা করে সে উত্তম, নাকি সে ব্যক্তি যে তার ইমারত একটি ক্ষয়প্রাপ্ত পর্বতগাত্রের কিনারে প্রতিষ্ঠা করে, যা তাকে নিয়ে নরকের আগুনে পতিত হয়? আল্লাহ সীমাতিক্রকারি লোকদের পথ-প্রদর্শন করেন না।"],
  "9:110": ["Their building, which they built, will not cease to be a doubt in their hearts unless their hearts are severed. And Allah is knowing, wise.", "এমন ইমারত যা তারা স্থাপন করেছে তা তাদের হৃদয়ে সন্দেহের একটি উৎস হয়ে থাকে, যতক্ষণ না তাদের হৃদয় স্থির হয়ে যায়। আল্লাহ সর্বজ্ঞ, সবথেকে জ্ঞানী।"],
  "9:111": ["Indeed, Allah has purchased from the muminin their souls and their wealth — that for them is the Garden. They fight in the way of Allah: they slay and are slain — a promise true upon Allah, in the Torah, the Gospel, and the Quran. And who is truer to the covenant than Allah? So rejoice in the deal you have made — and that is the great triumph.", "আল্লাহ স্বর্গোদ্যানের বিনিময়ে বিশ্বাসীদের কাছ থেকে তাদের জীবন এবং তাদের অর্থ কিনে নিয়েছেন। এ কারনে, তারা আল্লাহর উদ্দেশ্যে লড়াই করে, মারতে এবং মরতে সম্মত। এমনই হচ্ছে তওরাত, ইঞ্জিল, এবং কুরআনে তাঁর সত্য অঙ্গীকার– এবং কে অঙ্গীকার পূরণে আল্লাহর চেয়ে উত্তম? তোমরা এমন বিনিময়ে আনন্দ করবে। এটিই শ্রেষ্ঠ বিজয়।"],
  "9:112": ["The repentant, the worshippers, the praisers, the journeyers, the bowing, the prostrating, those who command the recognized and forbid the rejected, and the keepers of the limits of Allah — and give tidings to the muminin.", "তারা অনুশোচনাকারী, উপাসনাকারী, প্রশংসাকারী, ধ্যানকারী, অবনত হয় ও সেজদা করে, সৎকর্মশীলতার উকালতি করে এবং মন্দের নিষেধকারী, এবং আল্লাহর আইন রক্ষাকারী। এমন বিশ্বাসীদের সুসংবাদ দাও।"],
  "9:113": ["It is not for the Nabi and those who believe to ask forgiveness for the mushrikin — even if they were nearest kin — after it has become clear to them that they are companions of the Blaze.", "না নবী, না তারা যারা বিশ্বাস করে প্রতিমা উপাসকদের জন্য ক্ষমা প্রার্থনা করবে, এমনকি যদিও তারা তাদের নিকটতম আত্মীয়স্বজন হয়, যখন তারা উপলব্ধি করে যে তারা নরকের জন্য নির্ধারিত।"],
  "9:114": ["And the seeking of forgiveness by Ibrahim for his father was only about a promise he had promised him. But when it became clear to him that his father was an enemy of Allah, he disavowed him. Indeed, Ibrahim was most tender-hearted, forbearing.", "ইব্রাহিম তার পিতার জন্য ক্ষমা চেয়েছিল শুধু একারনে যে, সে তাকে এমন অঙ্গীকার দিয়েছিল। কিন্তু, যখনই সে উপলব্ধি করলো যে সে আল্লাহর শত্রু, সে তাকে ত্যাগ করলো। ইব্রাহিম ছিল অত্যন্ত দয়ালু, সহিষ্ণু।"],
  "9:115": ["And it is not for Allah to lead a people astray after guiding them, until it is made clear to them what they should be mindful of. Allah is knowing of all things.", "আল্লাহ কোন লোকদের পথভ্রষ্ট করেন না, তিনি তাদের পথ-প্রদর্শন করার পর, প্রথমে তাদের জন্য নির্দেশ না করে যে কি প্রত্যাশা করা হয়। আল্লাহ সবকিছু সম্পর্কে সম্পূর্ণ অবগত।"],
  "9:116": ["Indeed, to Allah belongs the dominion of the skies and the earth: Allah gives life and gives death — and you have, besides Allah, no protector and no helper.", "আকাশমন্ডলী এবং পৃথিবীর সার্বভৌমত্ব আল্লাহর। তিনি জীবন এবং মৃত্যু নিয়ন্ত্রন করেন। আল্লাহর পাশে প্রভু এবং মনিব হিসাবে তোমাদের অন্য কেউ নেই।"],
  "9:117": ["Allah has turned in mercy toward the Nabi, the muhajirin, and the helpers who followed the Nabi in the hour of hardship, after the hearts of a party of them had nearly swerved; then Allah turned in mercy toward them — indeed, toward them Allah is gentle in mercy, merciful.", "আল্লাহ উদ্ধার করেছেন নবীকে, এবং অভিবাসীদের (মুহাজিরিন) এবং সমর্থকদের যারা তাদের আতিথিয়তা করেছে এবং তাদেরকে আশ্রয় দিয়েছে (আনসার), যারা তাকে কঠিন সময়ে অনুসরণ করেছে। সে সময় তাদের কারো কারো হৃদয় প্রায় দোদুল্যমান ছিল। কিন্তু তিনি তাদেরকে উদ্ধার করেছিলেন, কারন তিনি তাদের প্রতি করুনাময়, পরম দয়ালু।"],
  "9:118": ["And upon the three who were left behind — until, when the earth was straitened for them for all its breadth, and their own selves were straitened for them, and they supposed there was no refuge from Allah except to Allah — then Allah turned in mercy toward them, that they might repent. Indeed, Allah is the ever-relenting, the merciful.", "আরো (ক্ষমা করা হয়েছে) সে তিনজনকে যারা পেছনে থেকে গিয়েছিল। বিস্তৃত পৃথিবী তাদের জন্য এতো সঙ্কুচিত হয়ে গিয়েছিল যে, তারা তাদের নিজেদের জন্য প্রায় সকল আশা ত্যাগ করেছিল। পরিশেষে, তারা উপলব্ধি করলো যে আল্লাহর থেকে পালানো যায় না, তাঁর দিকে ছাড়া। তিনি তখন তাদের উদ্ধার করলেন যাতে তারা অনুশোচনা করতে পারে। আল্লাহ উদ্ধারকারী, সবচেয়ে দয়াময়।"],
  "9:119": ["O you who believe, revere Allah and be with the sadiqin.", "হে তোমরা যারা বিশ্বাস করো, তোমরা আল্লাহকে ভক্তি করবে, এবং সত্যবাদীদের মধ্যে থাকবে।"],
  "9:120": ["It was not for the people of the city and those around them of the desert Arabs to stay behind the Rasul of Allah, nor to prefer their own selves over that one's self. That is because neither thirst, nor toil, nor hunger befalls them in the way of Allah, nor do they tread any treading-place that enrages the kafirin, nor reach from an enemy any reach, but it is decreed for them thereby as a salih deed. Allah does not lose the reward of the good-doers.", "না এই শহরের বাসিন্দারা, না তাদের চারদিকের আরবরা, আল্লাহর বার্তাবাহকের পেছনে থেকে যাওয়ার পথ খুঁজবে (যখন সে যুদ্ধের জন্য একত্রিত হয়)। না তারা তাদের নিজেদের বিষয়কে প্রাধান্য দেবে তাকে সমর্থন দেয়ার চেয়ে। এটা এই কারনে যে, তারা আল্লাহর উদ্দেশ্যে কোন তৃষ্ণা , অথবা কোন উদ্যোগ, অথবা ক্ষুধা, অথবা কোন একটি পদক্ষেপ নেয়া যা অবিশ্বাসীদের ক্ষুদ্ধ করে, অথবা শত্রুদের উপর কোন কষ্ট আরোপ করা- এগুলোর কোনটাই করেনা,  যার কৃতিত্ব তাদের জন্য লেখা হয় না। যারা সৎকর্ম করে তাদেরকে আল্লাহ কখনো পুরস্কৃত করতে ব্যর্থ হন না।"],
  "9:121": ["Nor do they spend any spending, small or large, nor cross any valley, but it is decreed for them — that Allah may recompense them the best of what they used to do.", "না তারা নিজের উপর কোন ব্যয় টেনে আনে, ছোট অথবা বড়, না তারা কোন উপত্যকা পার হয়, যার কৃতিত্ব তাদের জন্য লেখা না হয়। আল্লাহ অবশ্যই তাদের কাজের জন্য তাদেরকে উদারভাবে পুরস্কৃত করবেন।"],
  "9:122": ["And it is not for the muminin to go forth all together. So why should not a party from every division of them go forth, to understand the religion and to warn their people when they return to them, so that perhaps they may beware?", "যখন বিশ্বাসীরা যুদ্ধের জন্য প্রস্তুতি নেয়, তাদের সকলে নিবে না। প্রত্যেক দল থেকে কিছু লোক ধর্ম অধ্যয়নে তাদের সময় উৎসর্গ করতে সমবেত হবে। এভাবে, তারা তাদের লোকদের কাছে জ্ঞান ছড়িয়ে দিতে পারে যখন তারা ফিরে আসে, যাতে তারা ধর্মীয়ভাবে অবগত থাকতে পারে।"],
  "9:123": ["O you who believe, fight those of the kafirin who are near to you, and let them find hardness in you — and know that Allah is with the reverent.", "হে যারা তোমরা বিশ্বাস করো, তোমরা লড়াই করবে অবিশ্বাসীদের সাথে যারা তোমাদের আক্রমণ করে- যেন তারা তোমাদের কঠোরতা বুঝতে পারে-এবং জানে যে আল্লাহ সৎকর্মশীলদের সাথে আছেন।"],
  "9:124": ["And whenever a chapter is sent down, there are some of them who say: \"Which of you has this increased in faith?\" As for those who believe, it increases them in faith — and they rejoice.", "যখন কোন সুরা প্রকাশিত হতো, তাদের কেউ কেউ বলতো, “এই সুরা কি তোমাদের কারো বিশ্বাস মজবুত করেছে?” নিশ্চয়ই, এটা তাদের বিশ্বাসকে মজবুত করেছিল যারা বিশ্বাস করেছে, এবং তারা যেকোন প্রকাশনাতেই আনন্দ পায়।"],
  "9:125": ["But as for those in whose hearts is disease, it increases them in filth upon their filth — and they die while they are kafirin.", "আর তাদের জন্য যারা তাদের হৃদয়ে সন্দেহ পোষণ করতো, এটা আসলে তাদের অপবিত্রতায় অপবিত্রতা যোগ করেছিল, এবং তারা অবিশ্বাসী হিসাবে মৃত্যুবরণ করলো।"],
  "9:126": ["Do they not see that they are tried once or twice every year — yet they do not repent and do not remember?", "তারা কি খেয়াল করে না যে প্রতি বছর এক বা দু'বার তারা কঠোর পরীক্ষার সম্মুখীন হয়? এরপরও, তারা প্রতিবার অনুশোচনা করতে ব্যর্থ হয়, এবং ব্যর্থ হয় সতর্ক হতে।"],
  "9:127": ["And whenever a chapter is sent down, they look one to another: \"Does anyone see you?\" Then they turn away. Allah has turned their hearts away — because they are a people who do not understand.", "যখনি কোন সুরা প্রকাশিত হতো, তাদের কেউ কেউ একে অন্যের দিকে এমনভাবে তাকাতো যেন বলতে চায়ঃ “কেউ কি তোমাদের দেখছে?”এরপর তারা স্থান ত্যাগ করে। এভাবে, আল্লাহ তাদের হৃদয়কে বিমুখ করেন, কারন তারা এমন লোক যারা হৃদয়ঙ্গম করে না।"],
  "9:128": ["A Rasul has come to you from among yourselves — grievous to that one is whatever hardship you suffer, ardently desiring good for you, gentle in mercy and merciful toward the muminin.", "তোমাদের কাছে এসেছে তোমাদের মধ্য থেকেই একজন রসূল। তোমাদের দুঃখ-কষ্ট তার পক্ষে দুঃসহ। তিনি তোমাদের মঙ্গলকামী, মুমিনদের প্রতি স্নেহশীল, দয়াময়।"],
  "9:129": ["But if they turn away, say: \"Allah is enough for me — there is no ilah but Allah. Upon Allah I have placed my trust, and Allah is the Rabb of the great arsh.\"", "এ সত্ত্বেও যদি তারা বিমুখ হয়ে থাকে, তবে বলে দাও, আল্লাহই আমার জন্য যথেষ্ট, তিনি ব্যতীত আর কারো বন্দেগী নেই। আমি তাঁরই ভরসা করি এবং তিনিই মহান আরশের অধিপতি।"],
};
